import type { Task } from '../types';

export const PW_TASKS: Record<string, Task[]> = {

  setup: [
    { id:1, level:1, title:'Install Playwright', scenario:'A new project needs Playwright for end-to-end testing.', objective:'Run `npm init playwright@latest` in a new project folder. Accept all defaults. Verify that `playwright.config.ts`, `tests/` folder, and `package.json` scripts are created.', constraints:'Use npm init command. Inspect the generated files. List what was created.', expectedOutput:'playwright.config.ts, tests/example.spec.ts, package.json with test script. `npx playwright test` runs without error.', check:'`npm init playwright@latest` scaffolds the project. Key files: playwright.config.ts (configuration), tests/ (spec files), node_modules/@playwright/test.' },
    { id:2, level:1, title:'Install Browsers', scenario:'The CI pipeline needs all browsers installed before tests can run.', objective:'Run `npx playwright install`. Verify Chromium, Firefox, and WebKit are installed. Then install only Chromium with `npx playwright install chromium`.', constraints:'Full install first, then targeted install. Confirm with `npx playwright install --help`.', expectedOutput:'All three browsers installed. `npx playwright test --browser=chromium` succeeds.', check:'`npx playwright install` downloads browser binaries to a local cache. `--browser=chromium` limits to one browser.' },
    { id:3, level:1, title:'Run Your First Test', scenario:'The scaffolded example test must pass to confirm the installation is correct.', objective:'Run `npx playwright test`. Observe the output. Then run with `--reporter=list` for verbose output. Note how many tests ran and which browsers.', constraints:'Default run. Then with reporter flag. Note the test count.', expectedOutput:'All example tests pass. Reporter shows browser name, test name, and duration.', check:'Default reporter is "dot" (compact). `--reporter=list` shows one line per test. Tests run in all configured browsers by default.' },
    { id:4, level:1, title:'Explore playwright.config.ts', scenario:'A team lead wants to understand each configuration option before customizing it.', objective:'Open the generated `playwright.config.ts`. Identify and explain: `testDir`, `fullyParallel`, `retries`, `use.baseURL`, `use.trace`, `projects`. Change `retries` to 1 and observe the effect.', constraints:'Read the file. Explain each key option. Make one change and verify it applies.', expectedOutput:'`retries:1` causes failed tests to retry once. Other settings explained in comments.', check:'`testDir`: where to find test files. `fullyParallel`: run all tests in parallel. `use.baseURL`: default URL for `page.goto("/")`. `projects`: browser configurations.' },
    { id:5, level:1, title:'VS Code Extension Setup', scenario:'A developer wants to run and debug Playwright tests directly from VS Code.', objective:'Install the "Playwright Test for VS Code" extension. Use the Testing panel to run the example test. Set a breakpoint and use the debugger.', constraints:'Extension installation. Testing panel usage. Breakpoint debugging.', expectedOutput:'Tests appear in the VS Code Testing panel. Clicking play runs the test. Breakpoint pauses execution.', check:'Extension ID: ms-playwright.playwright. The Testing panel shows a tree of tests by file. Debug mode opens a browser and pauses at breakpoints.' },
    { id:6, level:1, title:'Headed vs Headless Mode', scenario:'During development, a developer wants to see the browser as tests run.', objective:'Run tests in headed mode: `npx playwright test --headed`. Compare to headless (default). Add `headless: false` to the config `use` section for permanent headed mode.', constraints:'CLI flag first. Then config change.', expectedOutput:'Headed: browser window appears during tests. Headless: no window (faster, for CI).', check:'Headless is the default for CI speed. Headed mode is useful during test development. `--headed` overrides the config for one run.' },
    { id:7, level:1, title:'Running a Single Test', scenario:'A developer wants to run only one specific test while fixing a bug.', objective:'Use `npx playwright test tests/example.spec.ts` to run one file. Use `--grep "has title"` to run tests matching a pattern. Use `npx playwright test -g "keyword"` shorthand.', constraints:'File filter. grep filter. Combined filter.', expectedOutput:'Only matching tests run. Count shown in output.', check:'`-g` is short for `--grep`. Pattern is a regex. Can combine: `npx playwright test login.spec.ts -g "valid user"` runs only matching tests in that file.' },
    { id:8, level:1, title:'Playwright Inspector', scenario:'A test is clicking the wrong element. Use the Playwright Inspector to debug.', objective:'Run `npx playwright test --debug` to launch the Inspector. Step through actions using the step-over button. Observe the highlighted element for each action.', constraints:'Debug flag. Use step controls. Read the selector being used.', expectedOutput:'Inspector panel shows current action, highlighted element in browser, and call stack.', check:'`--debug` opens the Playwright Inspector. Use step-over (F10) to advance one action. The blue overlay shows which element was targeted.' },
    { id:9, level:1, title:'Generate Tests with Codegen', scenario:'A tester wants to record a user flow and convert it to a test.', objective:'Run `npx playwright codegen https://playwright.dev`. Perform clicks and typing in the browser. Observe the generated test code. Copy and save it.', constraints:'Codegen command. Perform at least 3 actions. Save the output.', expectedOutput:'Generated test code with `page.goto`, `page.click`, `page.fill` calls. Selectors chosen automatically.', check:'Codegen records actions and generates Playwright test code in real time. The right panel shows the generated code. It prefers `getByRole`, `getByText` locators.' },
    { id:10, level:1, title:'View Test Reports', scenario:'After a CI run, the team reviews which tests failed.', objective:'After running tests, open the HTML report with `npx playwright show-report`. Navigate the report. Find test details, error messages, and the trace file (if trace is configured).', constraints:'Run tests first. Then show-report. Explore report sections.', expectedOutput:'HTML report shows: test list with pass/fail status, error details, screenshots, and trace links.', check:'Report saved to `playwright-report/`. `show-report` serves it on localhost. Trace shows a timeline of actions and screenshots.' },
    { id:11, level:2, title:'Multi-Browser Configuration', scenario:'Tests must run on Chrome, Firefox, and Safari (WebKit) to catch browser-specific bugs.', objective:'Configure the `projects` array in `playwright.config.ts` with three projects: `chromium`, `firefox`, `webkit`. Run all tests and verify they run in all three browsers.', constraints:'Three projects defined. Verify test count tripled.', expectedOutput:'`npx playwright test` shows 3x the tests. Each test runs in all three browsers.', check:'Projects: `{name:"chromium",use:{...devices["Desktop Chrome"]}}`. Each project creates a separate run of all tests. Test count = specs × browsers.' },
    { id:12, level:2, title:'Device Emulation Setup', scenario:'A mobile-first app must be tested on simulated iPhone and Pixel devices.', objective:'Add projects for `Mobile Chrome` and `Mobile Safari` using `devices["iPhone 13"]` and `devices["Pixel 5"]`. Run a navigation test and observe the viewport size and user agent.', constraints:'Two mobile projects. Log viewport and userAgent in a test.', expectedOutput:'Tests run in mobile viewport. `await page.evaluate(()=>navigator.userAgent)` shows mobile UA.', check:'`devices["iPhone 13"]` sets viewport, userAgent, hasTouch, deviceScaleFactor. Access device list with `import {devices} from "@playwright/test"`.' },
    { id:13, level:2, title:'Environment Variables in Config', scenario:'Tests must run against different environments (dev/staging/prod) without code changes.', objective:'Use `process.env.BASE_URL` in config: `use: {baseURL: process.env.BASE_URL || "http://localhost:3000"}`. Run with `BASE_URL=https://staging.example.com npx playwright test`.', constraints:'env var in config. Default fallback. Demonstrate with different URLs.', expectedOutput:'`page.goto("/")` navigates to the env-specified base URL. No code change needed to switch environments.', check:'`process.env.BASE_URL` reads from shell env. `|| "default"` provides a fallback. `.env` files can be loaded with `dotenv` package.' },
    { id:14, level:2, title:'Trace on Failure', scenario:'CI failures are hard to diagnose without seeing what happened. Enable traces on retry.', objective:'Set `use.trace: "on-first-retry"` in config. Create a test that fails. Run with `--retries=1`. Open the trace file in the HTML report.', constraints:'Trace on first retry. Deliberate failure. View trace.', expectedOutput:'After retry failure: trace file attached in HTML report. Trace shows actions, network, and screenshots.', check:'`"on-first-retry"`: trace starts only on the first retry attempt. `"always"`: always record. `"off"`: never. Trace files are `.zip` archives.' },
    { id:15, level:2, title:'Screenshot and Video on Failure', scenario:'The team wants screenshots of exactly what the browser showed when a test failed.', objective:'Set `use.screenshot: "only-on-failure"` and `use.video: "retain-on-failure"`. Create a failing test. View the screenshot and video in the HTML report.', constraints:'Both settings. Failing test. View artifacts.', expectedOutput:'After failure: screenshot and video attached in HTML report.', check:'`"only-on-failure"`: captures only when test fails. `"always"`: captures every test. Video: `.webm` file. Stored in `test-results/`.' },
    { id:16, level:2, title:'Test Timeout Configuration', scenario:'Slow tests on CI cause the suite to hang. Set appropriate timeouts.', objective:'Configure: `timeout: 30000` (test timeout), `use.actionTimeout: 5000` (each action), `use.navigationTimeout: 10000` (page.goto). Write a test that exceeds the action timeout and observe the error.', constraints:'All three timeout types. Observe timeout error message.', expectedOutput:'Action exceeds 5000ms → `TimeoutError: Locator.click: Timeout 5000ms exceeded`. Test fails with clear message.', check:'Three timeout levels: global test timeout, action timeout (per locator action), navigation timeout (page.goto). More specific wins.' },
    { id:17, level:2, title:'Parallel Workers Configuration', scenario:'A 200-test suite takes 10 minutes running sequentially. Speed it up with workers.', objective:'Set `workers: 4` in config. Run and observe that multiple tests run simultaneously. On CI, use `workers: "50%"` to use half the available CPUs.', constraints:'Workers count. Percentage format.', expectedOutput:'4 tests run simultaneously. Total time roughly divided by 4.', check:'`workers: 4` runs 4 test workers in parallel. `workers: "50%"` uses half available CPUs. `fullyParallel: true` also runs tests within a file in parallel.' },
    { id:18, level:2, title:'Global Setup and Teardown', scenario:'Tests need a database seeded before the suite runs and cleaned up after.', objective:'Create `global-setup.ts` exporting `async function globalSetup()`. Create `global-teardown.ts`. Register them in config: `globalSetup: "./global-setup.ts"`. Verify they run once before/after the suite.', constraints:'Both files. Register in config. Log to confirm execution order.', expectedOutput:'"global setup" logged once before any test. "global teardown" logged once after all tests.', check:'`globalSetup` runs once before all workers start. `globalTeardown` runs after all workers finish. Useful for database seeding, auth tokens.' },
    { id:19, level:2, title:'Reporter Configuration', scenario:'CI must output JUnit XML for Jenkins and also show a list in the terminal.', objective:'Configure multiple reporters: `reporter: [["list"],["junit",{outputFile:"results.xml"}],["html",{open:"never"}]]`. Run and verify all three outputs are produced.', constraints:'Three reporters. Verify output files.', expectedOutput:'Terminal shows list format. `results.xml` created. `playwright-report/index.html` created.', check:'Array format: each entry is `[reporterName]` or `[reporterName, options]`. Built-in reporters: list, dot, line, html, json, junit.' },
    { id:20, level:2, title:'Project Dependencies', scenario:'Mobile tests must run only after desktop tests pass (desktop builds the auth state that mobile reuses).', objective:'Configure project dependencies: `{name:"mobile",dependencies:["desktop"]}`. Show that `setup` project runs first, and `mobile` project can use its artifacts.', constraints:'Dependencies between projects. Setup project pattern.', expectedOutput:'`setup` project runs first and exits before `mobile` starts. `mobile` can use the saved state from `setup`.', check:'Project dependencies: Playwright ensures dependency projects complete before dependent ones start. Use with storageState for auth sharing across projects.' },
    { id:21, level:3, title:'Monorepo Setup', scenario:'A monorepo has multiple apps (web, mobile-web, admin) each needing separate Playwright configs.', objective:'Create three `playwright.config.ts` files in separate directories. Run a specific one: `npx playwright test --config=apps/web/playwright.config.ts`. Share common config via a base config file.', constraints:'Three configs. Shared base config using spread. Run specific config.', expectedOutput:'`npx playwright test --config=apps/web/playwright.config.ts` runs only web tests.', check:'`--config` flag selects the config file. Base config: `const base = require("./base.config"); module.exports = {...base, testDir:"./tests"}`.' },
    { id:22, level:3, title:'Custom Reporter', scenario:'The team needs a custom Slack notification when tests fail.', objective:'Create a class implementing the `Reporter` interface: `onTestEnd(test, result)`. If result.status is "failed", send a Slack message. Register as a reporter in config.', constraints:'Reporter interface. onTestEnd. Slack webhook (mock with console.log).', expectedOutput:'Failed test → custom reporter logs "FAILED: test.title" (simulating Slack notification).', check:'Reporter interface: `onBegin(config,suite)`, `onTestBegin(test)`, `onTestEnd(test,result)`, `onEnd(result)`. Result.status: "passed","failed","timedOut","skipped".' },
    { id:23, level:3, title:'Sharding for CI Parallelism', scenario:'A 500-test suite must be split across 5 CI machines to run in under 5 minutes.', objective:'Configure sharding: run `npx playwright test --shard=1/5`, `--shard=2/5`, etc. on different machines. Merge reports: `npx playwright merge-reports ./blob-reports --reporter=html`.', constraints:'Shard flag. Blob reporter for merging. Merge command.', expectedOutput:'Each shard runs ~100 tests. Merged report shows all 500 tests.', check:'`--shard=1/5` runs the first fifth of tests. Blob reporter outputs binary blobs. `merge-reports` combines them into a single HTML report.' },
    { id:24, level:3, title:'Docker Setup for CI', scenario:'Tests must run in a Docker container for reproducible CI results.', objective:'Use the official `mcr.microsoft.com/playwright` image. Write a `docker run` command that mounts the project and runs tests. Explain why browsers are pre-installed in this image.', constraints:'Docker command. Volume mount. Explain browser pre-installation.', expectedOutput:'`docker run -v $(pwd):/work mcr.microsoft.com/playwright npx playwright test` runs tests in Docker.', check:'Official image has all browsers pre-installed with correct system dependencies. Avoids the `npx playwright install-deps` step on Linux.' },
    { id:25, level:3, title:'GitHub Actions Integration', scenario:'Tests must run automatically on every pull request.', objective:'Write a `.github/workflows/playwright.yml` that: installs Node.js, runs `npm ci`, runs `npx playwright install --with-deps`, runs tests, and uploads the HTML report as an artifact on failure.', constraints:'Workflow YAML. Install step. Test step. Artifact upload.', expectedOutput:'PR triggers workflow. Tests run. On failure: report uploaded and downloadable from the Actions UI.', check:'`npx playwright install --with-deps` installs browsers AND system dependencies. `uses: actions/upload-artifact` for the report directory.' },
    { id:26, level:3, title:'Environment-Specific Config', scenario:'Dev, staging, and prod have different feature flags and auth requirements.', objective:'Create `playwright.dev.config.ts`, `playwright.staging.config.ts`. Each extends base config and overrides `baseURL` and `use.storageState`. Run: `npx playwright test --config=playwright.staging.config.ts`.', constraints:'Two env configs. Base config extended. Different storageState per env.', expectedOutput:'Staging config uses staging URL and staging auth token. Tests run against the correct environment.', check:'`import baseConfig from "./playwright.config"; export default {...baseConfig, use:{...baseConfig.use, baseURL:STAGING_URL}}`.' },
    { id:27, level:3, title:'Soft Assertions Setup', scenario:'A test must check 10 fields but should report all failures, not stop at the first.', objective:'Use `expect.soft()` for each field check. The test continues even if an assertion fails. At the end, the test fails if any soft assertion failed. Compare to regular `expect`.', constraints:'10 soft assertions. Mix pass and fail. Observe all are reported.', expectedOutput:'Test reports 3 failures (fields 2, 5, 7 failed) but ran all 10 checks.', check:'`expect.soft(value).toBe(expected)` records the failure but does not throw. Test fails at the end if any soft assertion failed. Regular `expect` stops immediately.' },
    { id:28, level:3, title:'Fixtures Setup', scenario:'Common test setup (create user, open page) must be shared across all tests.', objective:'Create a custom fixtures file exporting extended `test` and `expect`. Add a `userPage` fixture that creates a user and navigates to their profile page. Use in tests.', constraints:'Fixtures file. Custom fixture. Use in two different test files.', expectedOutput:'Tests using `userPage` fixture get a pre-authenticated page without duplicating setup code.', check:'`const test = base.extend<{userPage:Page}>({userPage:async({page},use)=>{...await use(page)}})`.' },
    { id:29, level:3, title:'Web Server Auto-Start', scenario:'Tests must start the dev server automatically and stop it after the suite.', objective:'Configure `webServer` in playwright.config.ts: `{command:"npm run dev", url:"http://localhost:3000", reuseExistingServer:!process.env.CI}`. Run tests and observe the server auto-starts.', constraints:'webServer config. reuseExistingServer for local dev. url health check.', expectedOutput:'`npx playwright test` starts the dev server, runs tests, then stops the server.', check:'`webServer.url`: Playwright polls this URL until 200 OK before starting tests. `reuseExistingServer:true` skips starting if already running (useful for local dev).' },
    { id:30, level:3, title:'Test Filtering and Tags', scenario:'The team runs a "smoke" subset of tests before every deploy and the full suite nightly.', objective:'Add `@smoke` tag to key tests: `test("login @smoke", ...)`. Run smoke tests: `npx playwright test --grep @smoke`. Run non-smoke: `--grep-invert @smoke`. Configure a `smoke` project.', constraints:'Tag tests. grep filter. grep-invert. Smoke project in config.', expectedOutput:'`--grep @smoke` runs only tagged tests. `--grep-invert @smoke` runs all others.', check:'Tags are part of the test title string. `--grep` accepts regex. `--grep-invert` is the inverse filter. Can also use test.describe.tags().' },
    { id:31, level:4, title:'Custom Test Parametrization', scenario:'The same checkout flow must be tested with 10 different product/payment combinations.', objective:'Use `test.describe` with a data array and `forEach` to generate parameterized tests. Each combination gets its own test title. Verify each runs independently.', constraints:'Array of {product,payment} pairs. forEach generates tests.', expectedOutput:'10 tests created, one per combination. Each has a descriptive title. All run independently.', check:'`const cases=[...]; cases.forEach(({product,payment})=>test(`checkout ${product} with ${payment}`,async({page})=>{...}))`. Each iteration creates a separate test.' },
    { id:32, level:4, title:'Cross-Origin Testing Setup', scenario:'A payment flow redirects to a third-party payment processor on a different domain.', objective:'Configure Playwright to handle cross-origin iframes and redirects. Use `page.waitForURL` to track navigation across domains. Handle the redirect back to the app.', constraints:'page.waitForURL. Cross-origin iframe access limitations. Handle redirect.', expectedOutput:'Test navigates to payment domain, interacts with payment form, returns to app domain, verifies success.', check:'Playwright handles cross-origin navigation natively. Cross-origin iframes: use `frameLocator`. Some operations restricted by browser CORS policy.' },
    { id:33, level:4, title:'Advanced Browser Launch Options', scenario:'Tests need specific browser flags: disable GPU (headless CI), ignore certificate errors (self-signed certs), add custom Chrome extensions.', objective:'Configure `launchOptions`: `{args:["--disable-gpu","--no-sandbox","--ignore-certificate-errors"]}`. For extensions: `{args:["--disable-extensions-except=path/to/ext","--load-extension=path/to/ext"]}`.', constraints:'launchOptions in use. GPU disabled. Extension loading.', expectedOutput:'Tests run with specified flags. Certificate errors ignored. Extension loaded.', check:'`use.launchOptions.args`: passed directly to the browser binary. `--no-sandbox`: required in Docker/some CI. Extensions require headed mode or specific flags.' },
    { id:34, level:4, title:'Playwright with TypeScript Path Aliases', scenario:'A large project uses `@/components/*` path aliases. Playwright must resolve them too.', objective:'Configure `tsconfig.json` paths. Add `moduleNameMapper` or use `require("@playwright/test").defineConfig` with proper path setup.', constraints:'tsconfig paths. Playwright config imports resolved correctly.', expectedOutput:'Test files can import `@/helpers/auth` and the types resolve correctly.', check:'Playwright uses its own tsconfig resolution. Set `tsConfigPath` in playwright.config.ts. Or use `require("tsconfig-paths/register")` in the config.' },
    { id:35, level:4, title:'Selective Fixture Scope', scenario:'A database connection fixture should be created once per worker, not per test, to improve speed.', objective:'Define a worker-scoped fixture: `{scope:"worker"}`. Show it is created once per worker. Compare to test-scoped (default) and create timing.', constraints:'Worker-scoped and test-scoped fixtures. Log creation time.', expectedOutput:'Worker fixture: created once, shared across all tests in the worker. Test fixture: created fresh for each test.', check:'`{scope:"worker"}`: one instance per parallel worker process. `{scope:"test"}` (default): one per test invocation. Worker fixtures cannot use `page` (which is test-scoped).' },
    { id:36, level:4, title:'Expect Extensions', scenario:'The app has a custom condition (e.g., "isLoggedIn") that needs a clean assertion.', objective:'Create a custom expect matcher: `expect.extend({toBeLoggedIn(page){...return {pass,message}}})`. Use it: `await expect(page).toBeLoggedIn()`. Show the error message on failure.', constraints:'expect.extend. Custom matcher. Async matcher (returns Promise).', expectedOutput:'`expect(page).toBeLoggedIn()` passes when logged in, fails with custom message when not.', check:'`expect.extend({async toBeLoggedIn(received){const loggedIn=await checkLoginState(received); return {pass:loggedIn,message:()=>"Expected page to be logged in"}}})`. Must be set up before use.' },
    { id:37, level:4, title:'Playwright with Docker Compose', scenario:'Tests need a running backend API and a database, all managed by Docker Compose.', objective:'Write a `docker-compose.yml` with: `app` (the web app), `db` (PostgreSQL), `playwright` (test runner). Use `depends_on` to ensure app and db start first. Configure network.', constraints:'Three services. depends_on. Playwright service runs tests.', expectedOutput:'`docker compose run playwright` starts db, app, then runs tests against the app.', check:'`depends_on: [app,db]` with `condition:service_healthy`. Healthcheck on app: `curl http://localhost:3000/health`. Playwright uses app\'s service name as baseURL.' },
    { id:38, level:4, title:'Snapshot Testing Setup', scenario:'Visual regressions must be caught by comparing screenshots pixel-by-pixel.', objective:'Use `expect(page).toHaveScreenshot("baseline.png")`. First run: creates the baseline. Subsequent runs: compare against baseline. Configure `threshold` for minor differences.', constraints:'First run creates baseline. Second run compares. Change something and see the diff.', expectedOutput:'First run: baseline saved. Second run: test passes. After DOM change: test fails with diff image.', check:'Snapshots stored in `__snapshots__` directory. `--update-snapshots` to regenerate. `toHaveScreenshot({threshold:0.1})` allows 10% pixel difference.' },
    { id:39, level:4, title:'Allure Reporter Integration', scenario:'The QA team uses Allure for test management and needs Playwright to output Allure results.', objective:'Install `allure-playwright`. Configure it as a reporter. Run tests. Generate the Allure report with `allure generate`. View the report.', constraints:'npm install. Reporter config. allure generate and open.', expectedOutput:'Allure report shows tests grouped by feature, with attachments, history, and categories.', check:'`npm i -D allure-playwright`. Config: `reporter: [["allure-playwright"]]`. Generates results to `allure-results/`. `allure generate && allure open` creates/serves the report.' },
    { id:40, level:4, title:'Cross-Browser Test Matrix', scenario:'Tests must run in 8 browser/viewport combinations (3 browsers × desktop+mobile+tablet).', objective:'Define 8 projects using `devices` and browser settings. Use `test.skip(({browserName})=>browserName==="webkit","Safari-only skip")` for browser-specific skips.', constraints:'8 projects. test.skip with condition.', expectedOutput:'8 test runs per test. Skipped tests shown as skipped (not failed). Clear browser identification in output.', check:'Conditional skip: `test.skip(({browserName})=>browserName==="webkit","reason")`. Note: this is a function, not a boolean — the function receives fixtures and returns bool.' },
    { id:41, level:5, title:'Enterprise Multi-Project CI Architecture', scenario:'A large enterprise has 50 teams each with their own test suites. Design a centralized Playwright CI system.', objective:'Design: shared base config npm package, central shard coordinator, merged reporting dashboard, team-specific projects with shared fixtures. Document the architecture and implement the base config package.', constraints:'Base config as npm package. At least 5 key architectural decisions documented.', expectedOutput:'`@company/playwright-base` package. Config: `import base from "@company/playwright-base"`. Teams extend it. Central dashboard merges all reports.', check:'Key decisions: shared baseURL per env, shared auth fixtures, common reporters, standardized project names, shared global setup.' },
    { id:42, level:5, title:'Dynamic Test Generation from API', scenario:'Test cases are stored in a database. Generate Playwright tests dynamically at runtime.', objective:'Fetch test cases from an API in `global-setup`. Write them to a JSON file. In the test file, read the JSON and generate `test()` calls with `forEach`. Handle dynamic titles and assertions.', constraints:'Fetch in global setup. Dynamic test generation from data. Type-safe.', expectedOutput:'200 test cases in DB → 200 generated tests. Each has a unique title from the data.', check:'`globalSetup`: `const cases=await fetchTestCases(); fs.writeFileSync("test-cases.json",JSON.stringify(cases))`. Test file: `import cases from "../test-cases.json"; cases.forEach(c=>test(c.title,...))`. ' },
    { id:43, level:5, title:'Playwright as a Service', scenario:'Multiple teams trigger Playwright tests via an API (webhook from GitHub) without direct access to the runner.', objective:'Build a lightweight REST API (Express) that receives test-run requests and runs `child_process.exec("npx playwright test ...")` with the specified options. Queue concurrent requests.', constraints:'Express server. child_process.exec. Queue for concurrency.', expectedOutput:'POST /run → triggers test run → returns run ID. GET /run/:id → returns status and report URL.', check:'`exec("npx playwright test --reporter=json --output-file=results/${id}.json")`. Store results keyed by run ID. Queue: max N concurrent runs.' },
    { id:44, level:5, title:'Playwright Plugin System', scenario:'The framework needs a plugin API so teams can add custom fixtures, reporters, and matchers without modifying the core config.', objective:'Build a `createPlugin({fixtures, matchers, reporter})` API. `registerPlugin(plugin)` in config extends `test` with plugin fixtures and registers the reporter.', constraints:'Plugin interface. Registration mechanism. At least 2 plugins demonstrated.', expectedOutput:'authPlugin adds `authenticatedPage` fixture. analyticsPlugin adds custom reporter. Both work together.', check:'Each plugin: `{fixtures?:{},matchers?:{},reporter?:Reporter}`. Registration: extend test with fixtures, merge matchers via expect.extend, push reporter.' },
    { id:45, level:5, title:'Self-Healing Selectors', scenario:'Tests break when developers rename CSS classes. Build a self-healing selector mechanism.', objective:'Build `resilientLocator(page, selectors[])` that tries each selector in order, caching the one that worked. On next run, try cached first. If it fails, retry others and update cache.', constraints:'Multiple selector strategies. Cache successful selector. Persistent cache.', expectedOutput:'Rename a class: test tries next selector, succeeds, updates cache. Future runs use the new selector.', check:'Selector priority: ARIA role > test-id > text > CSS class. Cache: JSON file keyed by "test:selectorGroup". On cache hit failure: retry others and update.' },
    { id:46, level:5, title:'Visual Regression System', scenario:'Build a complete visual regression testing system with baseline management and CI integration.', objective:'Design: baseline storage (S3/git), comparison with perceptual hashing, threshold configuration per page, automatic PR comments with diff images, manual approval workflow.', constraints:'Baseline management. Diff reporting. PR comment with images. Approval workflow.', expectedOutput:'PR changes login page → visual diff detected → PR comment with before/after/diff images → reviewer approves or rejects.', check:'Perceptual hash (pHash) for structural similarity. Pixel diff for detail. Store baselines in S3 with commit SHA key. GitHub API for PR comments.' },
    { id:47, level:5, title:'Performance Metrics Collection', scenario:'Tests must collect Core Web Vitals (LCP, FID, CLS) and fail if they exceed thresholds.', objective:'Use `page.evaluate` to read `performance.getEntriesByType` and the web-vitals library. Create a custom fixture `performancePage` that collects metrics after each navigation. Assert against thresholds.', constraints:'web-vitals library injected. Custom fixture. Threshold assertions.', expectedOutput:'`await expect(metrics.lcp).toBeLessThan(2500)`. Test fails if LCP exceeds 2.5s.', check:'Inject web-vitals: `await page.addScriptTag({url:"https://unpkg.com/web-vitals"})`. Collect: `await page.evaluate(()=>webVitals.getLCP(m=>m))`. Report via fixture.' },
    { id:48, level:5, title:'Cross-Team Test Orchestration', scenario:'Multiple teams\' test suites must run in a dependency order: infrastructure → auth → features.', objective:'Build a meta-orchestrator that: reads a dependency graph (YAML), topologically sorts suites, executes them in order (sequential) or in parallel (independent), collects and merges reports.', constraints:'YAML dependency graph. Topological sort. Parallel independent suites.', expectedOutput:'infrastructure tests pass → auth tests run → feature tests run in parallel.', check:'Dependency graph: `{auth: [infrastructure], featureA: [auth], featureB: [auth]}`. Topo sort: Kahn\'s algorithm. Parallel: `Promise.all` for independent groups.' },
    { id:49, level:5, title:'Zero-Flake Test Architecture', scenario:'The team has 30% flaky tests. Redesign the test architecture to eliminate flakiness.', objective:'Audit causes: (1) timing issues, (2) test isolation failures, (3) shared state, (4) network dependencies. Implement solutions: proper waits, test isolation, state reset, network mocking.', constraints:'Identify 5 flakiness patterns. Fix each with a specific Playwright technique.', expectedOutput:'30% flaky → 0% flaky after: replacing hardcoded delays with `waitForSelector`, mocking external APIs, isolating storage state per test.', check:'Flakiness causes and fixes: time→`waitFor*`. shared state→`storageState` per test. network→`route.fulfill`. race conditions→`Promise.all([navigate,waitForResponse])`. Random data→fixed seeds.' },
    { id:50, level:5, title:'Complete E2E Testing Platform', scenario:'Design and implement a complete enterprise E2E testing platform for a team of 100 engineers.', objective:'Build: (1) shared config npm package, (2) custom test runner with queue, (3) results dashboard, (4) flakiness tracker, (5) automatic baseline updates, (6) Slack/Teams notifications, (7) integration with JIRA for bug filing.', constraints:'All 7 components. Architecture diagram. Core implementation of at least 3.', expectedOutput:'Tests run → dashboard shows results → flaky tests identified → Slack notified → JIRA bug auto-filed for new failures.', check:'Core 3: shared config package (npm), results dashboard (Express+SQLite), Slack notifier (webhook). Design: each component is a separate service/package.' },
  ],

  firsttest: [
    { id:1, level:1, title:'Write Your First Test', scenario:'A developer writes a test that verifies the Playwright homepage title.', objective:'Create `tests/first.spec.ts`. Write: `test("has title", async({page})=>{ await page.goto("https://playwright.dev"); await expect(page).toHaveTitle(/Playwright/); })`. Run it.', constraints:'Single test. toHaveTitle. Run and pass.', expectedOutput:'Test passes. Output: "1 passed (1.2s)".', check:'`test` takes a name and an async function. The function receives `{page}` (and other fixtures). `await` every Playwright call.' },
    { id:2, level:1, title:'Test File Structure', scenario:'A tester learns the anatomy of a Playwright test file.', objective:'Write a test file with: one `import` statement, one `test.describe` block containing two `test` cases, and `beforeEach` that navigates to a URL.', constraints:'Import. describe. beforeEach. Two tests.', expectedOutput:'Two tests run. beforeEach navigates before each. Both tests start at the correct URL.', check:'`import {test,expect} from "@playwright/test"`. `test.describe("group",()=>{beforeEach(async({page})=>{await page.goto(url);}); test("...",async({page})=>{...});})`. ' },
    { id:3, level:1, title:'Navigating to a URL', scenario:'A test must open a specific page before interacting with it.', objective:'Use `await page.goto("https://example.com")`. Verify `page.url()` returns the expected URL. Show `page.goto` with `waitUntil` options: `"load"`, `"networkidle"`, `"domcontentloaded"`.', constraints:'goto. page.url(). Three waitUntil options.', expectedOutput:'page.url() returns "https://example.com/". Each waitUntil option changes when goto resolves.', check:'`waitUntil:"load"` (default): waits for load event. `"domcontentloaded"`: faster, DOM ready. `"networkidle"`: waits for no network activity (slow, avoid in CI).' },
    { id:4, level:1, title:'Clicking Elements', scenario:'A test clicks a "Sign In" button on the homepage.', objective:'Use `page.click("text=Sign In")` (legacy) and `page.getByRole("button",{name:"Sign In"}).click()` (modern). Show that both work. Prefer the `getByRole` approach.', constraints:'Both syntaxes. Explain why getByRole is preferred.', expectedOutput:'Both click the same button. getByRole is more resilient to class/id changes.', check:'Legacy: `page.click(selector)`. Modern: chain `locator.click()`. `getByRole` uses ARIA semantics — more stable than CSS selectors.' },
    { id:5, level:1, title:'Filling Input Fields', scenario:'A login form test fills in email and password fields.', objective:'Use `page.getByLabel("Email").fill("user@example.com")`. Use `page.getByPlaceholder("Password").fill("secret")`. Submit with `page.getByRole("button",{name:"Login"}).click()`.', constraints:'getByLabel for email. getByPlaceholder for password. Role for button.', expectedOutput:'Form fills correctly. Button click submits. Test verifies navigation after login.', check:'`fill` clears the field first, then types. Use `getByLabel` when the field has an associated `<label>` element — most accessible approach.' },
    { id:6, level:1, title:'Basic Assertions', scenario:'A test verifies the page loaded correctly.', objective:'Write assertions using `expect`: `toHaveTitle`, `toHaveURL`, `toBeVisible`, `toContainText`, `toHaveValue`. Each on an appropriate element.', constraints:'Five different assertions. One per line. All should pass.', expectedOutput:'All five assertions pass. Each checks a different aspect of the page.', check:'`expect(page).toHaveTitle(/pattern/)`. `expect(page).toHaveURL(/path/)`. `expect(locator).toBeVisible()`. `expect(locator).toContainText("text")`. `expect(input).toHaveValue("value")`.' },
    { id:7, level:1, title:'Taking Screenshots', scenario:'A test captures a screenshot for visual verification.', objective:'Use `await page.screenshot({path:"screenshots/homepage.png"})`. Capture a specific element: `await locator.screenshot({path:"button.png"})`. Show full-page screenshot option.', constraints:'Full page screenshot. Element screenshot. fullPage option.', expectedOutput:'PNG files created in screenshots/ directory. Element screenshot shows only that element.', check:'`{fullPage:true}`: captures the entire scrollable page. Element screenshot: only the element\'s bounding box. Useful for visual debugging.' },
    { id:8, level:1, title:'Waiting for Elements', scenario:'A dynamic page shows a loading spinner, then content. The test must wait for content.', objective:'Use `await page.waitForSelector(".content")` (legacy) and `await expect(page.locator(".content")).toBeVisible()` (modern). Show auto-waiting in Playwright actions.', constraints:'Both approaches. Explain auto-waiting.', expectedOutput:'Test waits for content to appear before asserting. No explicit sleep needed.', check:'Playwright auto-waits for actionability before each action (visible, stable, enabled). `expect(locator).toBeVisible()` also waits. Never use `page.waitForTimeout` (sleep).' },
    { id:9, level:1, title:'Test Hooks (before/after)', scenario:'Each test in a describe block needs a logged-in user and a clean state.', objective:'Use `beforeAll` (runs once before all tests in describe), `beforeEach` (before each), `afterEach` (after each), `afterAll` (after all). Log execution order.', constraints:'All four hooks. Log in each. Verify order.', expectedOutput:'Order: beforeAll → [beforeEach → test → afterEach] × N → afterAll.', check:'`beforeAll`: one-time setup. `afterAll`: one-time teardown. `beforeEach/afterEach`: per-test setup/teardown. Hooks are scoped to their `describe` block.' },
    { id:10, level:1, title:'Skipping and Focusing Tests', scenario:'During development, a developer runs only the test they are working on.', objective:'Use `test.only("focused test",...)` to run only that test. Use `test.skip("skipped test",...)` to skip. Use `test.fixme` for known broken tests. Run and observe output.', constraints:'One only, one skip, one fixme, one normal test.', expectedOutput:'only: runs. skip: shown as skipped. fixme: shown as skipped. normal: does NOT run (only is active).', check:'`test.only`: only this test runs in the file. `test.skip`: skipped (counted). `test.fixme`: marked as broken, skipped. Remove `.only` before committing!' },
    { id:11, level:2, title:'Page Object Model Basics', scenario:'A login flow is used in many tests. Extract it into a reusable Page Object.', objective:'Create `LoginPage` class with `goto()`, `login(email,password)`, `errorMessage()`. Use it in two tests. Show how it reduces duplication.', constraints:'Class-based POM. Three methods. Used in two tests.', expectedOutput:'Both tests use `loginPage.login(...)`. No duplicate selectors across tests.', check:'POM: class encapsulates selectors and actions for a page. Changes to the UI require updating only the POM, not every test.' },
    { id:12, level:2, title:'Handling Multiple Tabs', scenario:'Clicking a link opens a new tab. The test must interact with the new tab.', objective:'`const [newPage] = await Promise.all([context.waitForEvent("page"), page.click("a[target=_blank]")])`. Interact with `newPage`. Close it with `newPage.close()`.', constraints:'waitForEvent("page"). Promise.all pattern. Interact with new tab.', expectedOutput:'New tab opens. Test reads its title. Test closes it. Original page is still active.', check:'`context.waitForEvent("page")` must be set up BEFORE the click that opens the tab. `Promise.all` ensures both start simultaneously.' },
    { id:13, level:2, title:'Handling Dialogs (alert/confirm)', scenario:'A delete action shows a confirm dialog. The test must accept it.', objective:'`page.on("dialog", dialog=>dialog.accept())`. Trigger the delete. For confirm: `dialog.accept()`. For cancel: `dialog.dismiss()`. Read `dialog.message()`.', constraints:'Dialog listener before action. accept and dismiss. Read message.', expectedOutput:'alert: accepted. confirm accept: deletion proceeds. confirm dismiss: cancelled. dialog.message() returns the dialog text.', check:'Set up `page.on("dialog",...)` BEFORE the action that triggers the dialog. `dialog.accept(promptText)` for prompt dialogs. Handler is called once per dialog.' },
    { id:14, level:2, title:'File Upload', scenario:'A form allows users to upload a profile picture. The test uploads a file.', objective:'`await page.getByLabel("Upload").setInputFiles("path/to/image.png")`. Upload multiple: `setInputFiles(["file1.png","file2.png"])`. Clear files: `setInputFiles([])`.', constraints:'Single file. Multiple files. Clear.', expectedOutput:'File input shows the selected file name. Form submits with the file.', check:'`setInputFiles` works with `<input type="file">`. Path is relative to the project root. For drag-and-drop uploads, use `page.dispatchEvent`.' },
    { id:15, level:2, title:'Network Interception', scenario:'A test mocks an API response to test the UI in a specific state.', objective:'`await page.route("/api/users", route=>route.fulfill({json:[{id:1,name:"Alice"}]}))`. Navigate to the page. Assert the UI shows Alice.', constraints:'route.fulfill with JSON. Navigate after route setup. Assert UI.', expectedOutput:'API call intercepted. UI renders with mocked data. No real API call made.', check:'`page.route(pattern, handler)`. Handler options: `fulfill` (mock response), `abort` (simulate error), `continue` (pass through). Pattern: string, regex, or predicate.' },
    { id:16, level:2, title:'Keyboard Shortcuts', scenario:'A rich text editor supports keyboard shortcuts (Ctrl+B for bold).', objective:'`await page.keyboard.press("Control+B")`. `await page.keyboard.type("Hello World")`. `await page.keyboard.down("Shift"); await page.keyboard.press("End"); await page.keyboard.up("Shift")`.', constraints:'press shortcut. type text. Shift+End selection.', expectedOutput:'Ctrl+B triggers bold. "Hello World" typed character by character. Shift+End selects to end of line.', check:'`keyboard.press`: single key or chord. `keyboard.type`: types each character. `keyboard.down/up`: for holding modifier keys.' },
    { id:17, level:2, title:'Scroll Actions', scenario:'A long page has content below the fold that must be scrolled to.', objective:'`await page.mouse.wheel(0,500)` to scroll down 500px. `await locator.scrollIntoViewIfNeeded()`. `await page.evaluate(()=>window.scrollTo(0,document.body.scrollHeight))` to scroll to bottom.', constraints:'Three scroll methods. Show each use case.', expectedOutput:'Mouse wheel scrolls by pixels. scrollIntoViewIfNeeded brings element into view. evaluate scrolls to page bottom.', check:'`scrollIntoViewIfNeeded`: only scrolls if the element is not already visible. `mouse.wheel(deltaX,deltaY)`: simulates the scroll wheel.' },
    { id:18, level:2, title:'Hover Effects', scenario:'A dropdown menu appears only on hover. The test must hover to reveal it.', objective:'`await page.getByText("Products").hover()`. After hover, assert the dropdown `toBeVisible`. Verify menu items are clickable.', constraints:'hover then assert visibility. Click a menu item.', expectedOutput:'Hover reveals dropdown. Dropdown item is visible and clickable.', check:'`locator.hover()` moves the mouse to the center of the element. CSS `:hover` state is activated. The dropdown appears via CSS transition.' },
    { id:19, level:2, title:'Drag and Drop', scenario:'A kanban board uses drag-and-drop to move cards between columns.', objective:'`await page.dragAndDrop("#card-1","#column-2")`. Also try the manual approach: `locator.hover()`, `mouse.down()`, `mouse.move()`, `mouse.up()` for fine-grained control.', constraints:'dragAndDrop shorthand. Manual mouse approach for comparison.', expectedOutput:'Card moved to column 2. dragAndDrop is simpler but less realistic. Manual mouse is more flexible.', check:'`page.dragAndDrop(source,target)` is a convenience method. Complex drag-and-drop (HTML5) may need the manual approach with `locator.dispatchEvent("dragstart")`.' },
    { id:20, level:2, title:'Test Data Isolation', scenario:'Tests that create data must clean up after themselves to avoid affecting other tests.', objective:'In `afterEach`: delete the user/record created during the test. Show why using `test.beforeEach` to set up unique test data (with timestamps) avoids collisions when tests run in parallel.', constraints:'Unique test data (timestamp suffix). Cleanup in afterEach.', expectedOutput:'Each test creates `user_${Date.now()}`. afterEach deletes it. Tests can run in parallel without conflicting.', check:'Isolation: each test should create its own data, not share with other tests. Unique IDs prevent conflicts. Cleanup prevents data accumulation.' },
    { id:21, level:3, title:'API Testing with Playwright', scenario:'The backend API must be tested independently of the UI.', objective:'Use `request` fixture: `const res = await request.get("/api/users/1")`. Assert `res.status()===200`. `res.json()` to read body. POST: `request.post("/api/users",{data:{name:"Alice"}})`.', constraints:'GET and POST. Status assertion. JSON body assertion.', expectedOutput:'GET /api/users/1 → 200, {id:1,name:Alice}. POST /api/users → 201, {id:2,name:"Alice"}.', check:'`request` fixture is a standalone `APIRequestContext`. No browser involved. Much faster than UI tests for API verification.' },
    { id:22, level:3, title:'Authentication State Reuse', scenario:'Tests that need a logged-in user must not log in for every single test (slow).', objective:'Log in once in `global-setup.ts`. Save auth state: `await page.context().storageState({path:"auth.json"})`. In playwright.config.ts: `use.storageState:"auth.json"`. Tests start already logged in.', constraints:'global-setup logs in. storageState saved. Config uses it. Verify tests start authenticated.', expectedOutput:'Tests skip login. Auth cookies from auth.json are pre-loaded. Login page never appears.', check:'`storageState` saves cookies and localStorage. Loaded via `use.storageState` in config or in a fixture. Per-role auth: multiple storageState files.' },
    { id:23, level:3, title:'Visual Comparison Testing', scenario:'A UI change must be verified to not accidentally alter the visual appearance.', objective:'`await expect(page).toHaveScreenshot("homepage.png")`. Run twice: first creates baseline, second compares. Modify a style and see the failure.', constraints:'Baseline creation. Comparison. Deliberate failure with diff.', expectedOutput:'First run: baseline saved. Second run: pass. After CSS change: fail with diff image showing the changed area.', check:'Snapshots in `__snapshots__` next to the test file. `--update-snapshots` flag regenerates them. Threshold: `{maxDiffPixels:100}` for minor differences.' },
    { id:24, level:3, title:'Mobile Testing', scenario:'A responsive page must be verified on a mobile viewport.', objective:'`const context = await browser.newContext({...devices["iPhone 14"]})`. Navigate and assert mobile-specific elements (hamburger menu visible, desktop nav hidden).', constraints:'Device emulation. Mobile-specific assertions. Touch simulation.', expectedOutput:'Hamburger menu visible on mobile viewport. Desktop nav hidden via CSS media query.', check:'`devices["iPhone 14"]` sets: `viewport:{width:390,height:844}`, `userAgent` (mobile), `hasTouch:true`. CSS media queries respond accordingly.' },
    { id:25, level:3, title:'Custom Fixture for User Roles', scenario:'Tests for admin and regular users require different setups.', objective:'Create fixtures for `adminPage` and `userPage`. Each fixture logs in as the appropriate role. Tests declare which fixture they need.', constraints:'Two fixtures. Different auth per role. Clean separation.', expectedOutput:'`test("admin test",async({adminPage})=>{...})` starts as admin. `test("user test",async({userPage})=>{...})` starts as regular user.', check:'Fixtures are injected by Playwright based on the parameter name. Each fixture sets up its own browser context with the appropriate auth state.' },
    { id:26, level:3, title:'Intercepting and Modifying Requests', scenario:'Test the app behavior when the API returns a specific error code.', objective:'`await page.route("/api/data", route=>route.fulfill({status:500,body:"Server Error"}))`. Assert the UI shows an error message.', constraints:'route.fulfill with 500. Assert error UI. Also test 404 and network failure (abort).', expectedOutput:'API returns 500 → UI shows "Something went wrong". abort() → UI shows "Network error".', check:'`route.abort("failed")` simulates network failure. `route.fulfill({status:404})` simulates 404. `route.continue()` passes through with optional modifications.' },
    { id:27, level:3, title:'Parallel Test Execution', scenario:'A 100-test suite must run in under 2 minutes using parallel workers.', objective:'Enable `fullyParallel:true`. Ensure tests do not share state (each creates its own data). Run with `workers:4`. Verify tests run simultaneously by checking timestamps.', constraints:'fullyParallel. Isolated test data. workers config.', expectedOutput:'4 tests run simultaneously. Total time ~25% of sequential time.', check:'`fullyParallel:true`: even tests in the same file run in parallel. Tests must be fully independent. Shared state (DB, files) requires isolation or mocking.' },
    { id:28, level:3, title:'Trace Viewing for Debugging', scenario:'A CI test failure is investigated using the trace file.', objective:'Configure `use.trace:"on-first-retry"`. Write a test that fails. Open the trace: `npx playwright show-trace trace.zip`. Navigate the timeline, inspect DOM snapshots, and read network requests.', constraints:'Configure trace. Failing test. View trace timeline.', expectedOutput:'Trace shows: each action on a timeline, before/after DOM snapshots, network requests, console logs.', check:'Trace file: `.zip` containing `trace.json`, screenshots, DOM snapshots. Timeline: each action has before/after state. Network: each request/response.' },
    { id:29, level:3, title:'Database State Setup', scenario:'Tests need specific database records to exist before they run.', objective:'In `beforeEach`: use the `request` fixture to POST test data via the API. In `afterEach`: DELETE the created records. Use a unique ID per test to avoid conflicts.', constraints:'API-based setup. API-based cleanup. Unique ID per test.', expectedOutput:'Test creates user via API. Asserts the UI shows the user. afterEach deletes the user.', check:'API setup is faster than UI setup. Use `request.post("/api/users",{data:testUser})`. Store the created ID for cleanup. `afterEach` always runs, even if test fails.' },
    { id:30, level:3, title:'Cross-Browser Assertion Differences', scenario:'A test passes on Chromium but fails on Firefox due to subtle behavior differences.', objective:'Write a test that checks CSS rendering. Run on all three browsers. Identify the difference. Use `browserName` fixture to add conditional assertions.', constraints:'Run on 3 browsers. Identify difference. Conditional assertion.', expectedOutput:'Chromium: passes. Firefox: different scroll behavior. WebKit: slightly different. Conditional assertion handles the difference.', check:'`test("name",async({page,browserName})=>{ if(browserName==="firefox") expect(x).toBe(y_ff); else expect(x).toBe(y); })`. Or `test.skip(({browserName})=>...)` for unsupported.' },
    { id:31, level:4, title:'Custom Matchers for Domain Logic', scenario:'The app has business rules that need clean assertion language.', objective:'Build custom matchers: `toBeValidEmail`, `toShowSuccessState`, `toHaveItemCount(n)`. Register with `expect.extend`. Use in tests.', constraints:'Three custom matchers. async matchers for locators. Error messages.', expectedOutput:'`expect(emailInput).toBeValidEmail()` passes for valid email. Fails with custom "Expected a valid email address" message.', check:'`expect.extend({async toBeValidEmail(locator){const val=await locator.inputValue(); const valid=/.+@.+/.test(val); return {pass:valid,message:()=>"Expected a valid email address"}}})` .' },
    { id:32, level:4, title:'Test Retry Logic', scenario:'A flaky test (network dependent) should retry up to 3 times before marking as failed.', objective:'Configure `retries:3` globally. Override per-test: `test.describe.configure({retries:1})`. Show retry annotations in the report. Verify the test passes on retry.', constraints:'Global retries. Per-test override. Observe retry in report.', expectedOutput:'Test fails once, retries, passes on second attempt. Report shows "1 retry" annotation.', check:'`test.describe.configure({retries:2})` applies to all tests in the describe block. Report shows retry count. Trace is auto-attached for retried tests.' },
    { id:33, level:4, title:'Mocking Time', scenario:'A test must verify behavior that depends on the current date/time (e.g., a "time-limited offer" banner).', objective:'Use `page.clock.setFixedTime(new Date("2024-12-25"))`. Navigate to the page. Assert the Christmas offer banner is visible. Reset with `page.clock.install`.', constraints:'clock.setFixedTime. Date-dependent UI. Assert the correct state.', expectedOutput:'Clock fixed at Christmas → banner visible. Clock at non-holiday → banner hidden.', check:'`page.clock` controls `Date`, `setTimeout`, `setInterval`. `setFixedTime(date)`: freezes time. `install({time:date})`: starts at that time but allows progression.' },
    { id:34, level:4, title:'Accessibility Testing', scenario:'Every page must meet WCAG accessibility standards.', objective:'Install `@axe-core/playwright`. In a test: `const results = await new AxeBuilder({page}).analyze()`. `expect(results.violations).toHaveLength(0)`. Fix any reported violations.', constraints:'AxeBuilder. analyze. Assert zero violations.', expectedOutput:'Page with no accessibility issues: pass. Page with missing alt text: fail with violation details.', check:'`@axe-core/playwright`: Deque\'s axe-core integrated for Playwright. Violations include: missing labels, low contrast, missing alt text. Rules configurable per test.' },
    { id:35, level:4, title:'Performance Assertions', scenario:'A page must load in under 3 seconds.', objective:'`const timing = await page.evaluate(()=>JSON.stringify(window.performance.timing))`. Parse and calculate DOMContentLoaded time. Assert it is under 3000ms. Also use `page.metrics()`.', constraints:'performance.timing. DOMContentLoaded calculation. Threshold assertion.', expectedOutput:'`dcl = timing.domContentLoadedEventEnd - timing.navigationStart`. `expect(dcl).toBeLessThan(3000)`.', check:'`performance.timing`: navigation timing API. `page.metrics()`: V8 heap, node count, task duration (Chromium only). For LCP: use PerformanceObserver.' },
    { id:36, level:4, title:'GraphQL Interception', scenario:'The app uses GraphQL. Tests must mock specific GraphQL operations.', objective:'Use `page.route("/graphql", route=>{ const body=route.request().postDataJSON(); if(body.operationName==="GetUser") route.fulfill({json:{data:{user:{id:1,name:"Alice"}}}}); else route.continue(); })`.', constraints:'Route on /graphql. Check operationName. Fulfill for specific op. Continue for others.', expectedOutput:'GetUser operation → mocked response. Other operations → pass through to real API.', check:'GraphQL routes all go to one endpoint. Differentiate by `operationName` in the request body. `route.request().postDataJSON()` reads the parsed JSON body.' },
    { id:37, level:4, title:'Component Testing with Playwright', scenario:'A React component must be tested in isolation without the full app.', objective:'Use `@playwright/experimental-ct-react`. Create a test that mounts `<Button label="Click me" onClick={handler}/>`. Assert it renders and calls the handler on click.', constraints:'CT config (playwright-ct.config.ts). mount fixture. Prop passing.', expectedOutput:'Isolated button renders. Click fires the mock handler. Test passes.', check:'Component testing: mounts a component directly in the browser without a dev server. `test("renders",async({mount})=>{ const cmp=await mount(<Button.../>); await expect(cmp).toBeVisible(); })`. ' },
    { id:38, level:4, title:'Network Throttling', scenario:'A test must verify the app works correctly on a slow 3G connection.', objective:'`await page.route("**",async route=>{ await new Promise(r=>setTimeout(r,100)); await route.continue(); })`. Simulate latency. Or use CDP: `await context.setExtraHTTPHeaders(...)` with a network condition.', constraints:'Route-based latency simulation. Assert loading state visible.', expectedOutput:'With 100ms latency: loading spinner visible during requests. Page eventually loads.', check:'Route-based throttling: adds delay before each request continues. For realistic throttling: use Chrome DevTools Protocol (CDP) `Network.emulateNetworkConditions`.' },
    { id:39, level:4, title:'Locator Chaining', scenario:'A data table has rows, and each row has action buttons. Locate a button in a specific row.', objective:'Chain locators: `page.getByRole("row",{name:/Alice/}).getByRole("button",{name:"Edit"})`. Also use `.nth(2)` for positional selection. Compare approaches.', constraints:'Row locator. Chained button locator. nth selection.', expectedOutput:'`.getByRole("row",{name:/Alice/}).getByRole("button",{name:"Edit"})` finds the Edit button in Alice\'s row.', check:'Locator chaining scopes the search: find button within the row context. More specific than a global `getByRole("button",{name:"Edit"})` which might match multiple.' },
    { id:40, level:4, title:'Authenticated API Requests in Tests', scenario:'Some API endpoints require authentication. Use the saved auth token from the browser session.', objective:'Get the cookie/token from the browser context: `await page.context().storageState()`. Use it in a subsequent `request` fixture call by setting the Authorization header.', constraints:'Extract token from storageState. Use in API request.', expectedOutput:'`request.get("/api/protected",{headers:{Authorization:"Bearer "+token}})` → 200.', check:'`storageState()` returns `{cookies:[...],origins:[{origin:"...",localStorage:[...]}]}`. Extract the JWT from localStorage: `origins[0].localStorage.find(i=>i.name==="token")`.' },
    { id:41, level:5, title:'Test Generation from OpenAPI Spec', scenario:'An API has an OpenAPI 3.0 spec. Generate Playwright API tests automatically.', objective:'Parse the OpenAPI spec. For each endpoint+method combination, generate a `test` that makes the request with valid test data and asserts the expected status code.', constraints:'YAML/JSON spec parsing. Dynamic test generation. At least 5 endpoints.', expectedOutput:'spec with 20 endpoints → 20 generated tests. Each verifies status code and response schema.', check:'Use `js-yaml` to parse. Iterate paths and methods. Generate: `test(\`${method} ${path}\`,async({request})=>{const res=await request[method](path,{data:genBody(op)}); expect(res.status()).toBe(successCode);})`. ' },
    { id:42, level:5, title:'Self-Healing Test Locators', scenario:'Tests break when developers rename CSS classes. Implement self-healing.', objective:'Build a `SmartLocator` class that tries locators in priority order: `getByTestId` → `getByRole` → `getByText` → `getByCSS`. Caches the successful locator. On cache miss, retries.', constraints:'Priority order. Cache to JSON. Retry on cache failure. Update cache.', expectedOutput:'Test uses SmartLocator. Class renamed → CSS fails → text locator succeeds → cache updated.', check:'Cache key: `testFile:locatorId`. Cache value: the strategy that worked. On failure: try next strategy, update cache. Log cache hits/misses.' },
    { id:43, level:5, title:'AI-Assisted Test Maintenance', scenario:'Tests are breaking due to UI changes. Use an AI service to suggest selector fixes.', objective:'On test failure: capture a screenshot and the failing selector. POST to an AI API with the image and selector. Parse the suggested new selector. Apply it and retry the test.', constraints:'On failure hook. Screenshot capture. AI API call. Retry with suggestion.', expectedOutput:'Test fails on old selector. AI suggests new selector. Retry succeeds. Selector updated in test file.', check:'Failure hook: `onTestEnd(test,result){if(result.status==="failed") await aiSuggestFix(test)}`. AI prompt: "Given this screenshot and failing selector, suggest a new selector."' },
    { id:44, level:5, title:'E2E Test as Documentation', scenario:'Test code serves as living documentation of user flows. Make it human-readable.', objective:'Write a test using the `test.step` API to document each step: `await test.step("User logs in",async()=>{...})`. Steps appear in the trace and report. Write a complete checkout flow with 8 documented steps.', constraints:'test.step for each logical step. 8 steps minimum. Steps visible in report.', expectedOutput:'Report shows: "1. User logs in → 2. Adds product to cart → ... → 8. Receives confirmation email".', check:'`test.step(title,body)`: groups actions into a labeled step. Visible in HTML report and trace. Steps can be nested. Great for BDD-style documentation.' },
    { id:45, level:5, title:'Property-Based Testing', scenario:'Instead of fixed inputs, generate hundreds of random valid inputs and verify invariants hold.', objective:'Integrate `fast-check` with Playwright. Generate random user registration data. Verify: the app always accepts valid emails, always rejects empty names, always returns a 201 status.', constraints:'fast-check for data generation. Invariant assertions. 50+ generated inputs.', expectedOutput:'50 random valid users: all accepted. 50 random invalid inputs: all rejected with 400.', check:'`fc.assert(fc.asyncProperty(fc.emailAddress(),async email=>{const r=await request.post("/api/users",{data:{email}}); expect(r.status()).not.toBe(500);}))`. ' },
    { id:46, level:5, title:'Cross-Platform Desktop Testing', scenario:'An Electron desktop app must be E2E tested on Windows, Mac, and Linux.', objective:'Use `playwright.launch({executablePath:electronPath})`. Configure for Electron: `electronApp = await electron.launch({args:["main.js"]})`. Access windows and interact with them.', constraints:'electron.launch. window access. Cross-platform path handling.', expectedOutput:'Electron app launches. Test clicks button in the app window. Asserts window title.', check:'`import {_electron as electron} from "@playwright/test"`. `await electronApp.firstWindow()` gets the first window as a Page. Full Playwright API available.' },
    { id:47, level:5, title:'Mutation Testing for Tests', scenario:'Verify test quality by introducing mutations (bugs) in the source code and checking that tests catch them.', objective:'Use `stryker` or manual mutations: change an `===` to `!==`. Run Playwright tests. If they still pass, the mutation "survived" — indicating inadequate test coverage.', constraints:'At least 5 mutations. Run tests after each. Report survived mutations.', expectedOutput:'Mutation 1 (wrong operator): caught (test fails). Mutation 2 (missing validation): survived (test did not catch it). Add test to catch it.', check:'Mutation testing measures test QUALITY, not coverage. Surviving mutations → missing test cases. Use Stryker with playwright runner for automation.' },
    { id:48, level:5, title:'Chaos Engineering Tests', scenario:'Verify the app degrades gracefully under chaotic conditions: random network failures, slow responses, and missing resources.', objective:'Use `page.route` to randomly fail or delay requests with a configurable chaos rate. Write tests that assert graceful degradation: error messages shown, retry buttons appear, no crashes.', constraints:'Random route interception. Configurable chaos rate. Assert graceful degradation.', expectedOutput:'20% requests fail → app shows retry button. 50% delays → loading indicators shown. No JavaScript errors logged.', check:'`route.fulfill({status:503})` simulates service unavailable. `route.abort("failed")` simulates network failure. Monitor console errors: `page.on("console",msg=>if(msg.type()==="error")...)`. ' },
    { id:49, level:5, title:'Contract Testing', scenario:'Frontend and backend teams evolve APIs independently. Contract tests verify compatibility.', objective:'Write consumer contracts (what the frontend expects) as Playwright API tests. Run them against the real backend and a mock backend. Any change that breaks a contract triggers an alert.', constraints:'Consumer contract as API tests. Mock server (msw or json-server). Contract validation.', expectedOutput:'Contract: `GET /api/user/:id → {id,name,email}`. Test passes on both real and mock API. Change backend → contract test fails.', check:'Consumer contract: defines the shape of API responses the frontend expects. Provider verification: backend runs the contracts against itself. Pact is the popular tool.' },
    { id:50, level:5, title:'Full E2E Test Suite Architecture', scenario:'Design and implement a production-grade E2E test suite for a complex e-commerce app.', objective:'Build: (1) Page Object hierarchy, (2) Custom fixtures for auth/data, (3) API setup helpers, (4) Visual regression baseline, (5) 20 test scenarios covering critical paths, (6) CI/CD integration, (7) Reporting dashboard.', constraints:'All 7 components. Critical paths: login, checkout, search, admin, mobile.', expectedOutput:'Complete suite: 20 tests across 3 browsers. CI on every PR. Report published. Visual baselines managed.', check:'Architecture: pages/ (POM), fixtures/, helpers/ (API), tests/ (specs), .github/workflows/ (CI). Each layer has a single responsibility.' },
  ],

  browsers: [
    { id:1, level:1, title:'Launching Chromium', scenario:'A test needs to verify behavior specifically in Chromium.', objective:'Use `chromium.launch()` to launch the browser. Create a context. Open a page. Navigate and assert. Close the browser.', constraints:'Manual launch (not test fixture). All steps explicit.', expectedOutput:'Browser opens. Page navigates. Title asserted. Browser closed.', check:'`const browser=await chromium.launch(); const ctx=await browser.newContext(); const page=await ctx.newPage(); await page.goto(url); await browser.close()`. Always close in finally.' },
    { id:2, level:1, title:'Launching Firefox', scenario:'A cross-browser suite must verify Firefox behavior.', objective:'Launch Firefox: `await firefox.launch({headless:false})`. Navigate to a page. Log `browserType.name()`. Compare behavior with Chromium.', constraints:'Firefox launch. browserType.name(). Headed mode.', expectedOutput:'Firefox window opens. `browserType.name()` → "firefox".', check:'Import `{firefox}` from `@playwright/test`. Firefox is a separate browser engine (Gecko). Some CSS and JS behaviors differ from Chromium.' },
    { id:3, level:1, title:'Launching WebKit (Safari)', scenario:'A test must verify Safari-like behavior using WebKit.', objective:'`await webkit.launch()`. Navigate and assert. Note WebKit-specific behaviors (different scroll mechanics, form styling). Log the userAgent.', constraints:'WebKit launch. Log userAgent. Note one WebKit difference.', expectedOutput:'WebKit navigates. userAgent contains "Safari".', check:'WebKit is the browser engine behind Safari. Not identical to Safari but close. `page.evaluate(()=>navigator.userAgent)` shows "Safari" and "WebKit" in the UA string.' },
    { id:4, level:1, title:'Browser Contexts', scenario:'A test needs two independent browser sessions simultaneously (e.g., admin and user).', objective:'`const ctx1=await browser.newContext()`, `const ctx2=await browser.newContext()`. Each context has its own cookies, storage, and pages. Log in as different users in each.', constraints:'Two contexts. Different users. Verify cookies are isolated.', expectedOutput:'ctx1 has user1 cookies. ctx2 has user2 cookies. They do not share sessions.', check:'Browser contexts are like separate "incognito windows". They share no cookies, localStorage, or sessions. Each can have multiple pages. Cheaper than launching a new browser.' },
    { id:5, level:1, title:'Headed vs Headless Mode', scenario:'Development uses headed mode to see the browser; CI uses headless for speed.', objective:'`chromium.launch({headless:false})` for headed. Default (`headless:true`) for headless. Log the mode. Show the `--headed` CLI flag.', constraints:'Both modes. CLI flag.', expectedOutput:'Headed: browser window visible. Headless: no window. Tests behave identically.', check:'Headless is the default. `headless:false` opens a visible window. `--headed` CLI flag overrides the config. Slow motion: `{slowMo:1000}` adds 1s delay between actions.' },
    { id:6, level:1, title:'Slow Motion Mode', scenario:'Debugging a flaky test requires seeing actions slowly to spot the issue.', objective:'`await chromium.launch({slowMo:500})`. Run a test. Each action has a 500ms delay. Use this to visually verify what the test is doing.', constraints:'slowMo in launch options. Observe the delay.', expectedOutput:'Each action (click, fill, navigate) takes 500ms longer than usual. Easy to follow visually.', check:'`slowMo:ms` adds a delay AFTER each action. Useful for debugging. Remove before committing. Can also use Playwright Inspector (`--debug`) for step-by-step.' },
    { id:7, level:1, title:'Browser Version and Type Info', scenario:'A test utility logs which browser and version is running.', objective:'`browser.version()` returns the version string. `browser.browserType().name()` returns "chromium", "firefox", or "webkit". Log both.', constraints:'browser.version(). browser.browserType().name(). Log both.', expectedOutput:'Chromium: "120.0.6099.109". firefox: "121.0". webkit: "17.4".', check:'`browser.version()`: the specific browser version installed. `browser.browserType()`: the playwright BrowserType object (chromium/firefox/webkit).' },
    { id:8, level:1, title:'Multiple Pages in One Context', scenario:'A test must verify that opening a link in a new tab shows the correct content.', objective:'`const page1=await context.newPage()`. `const page2=await context.newPage()`. Both share cookies. Navigate each to different URLs. Switch between them.', constraints:'Two pages in same context. Shared cookies. Navigate each.', expectedOutput:'Both pages share the same session (same cookies). Each has its own URL and content.', check:'Multiple pages in one context share cookies/storage (like browser tabs in the same window). `context.pages()` returns all pages. `page.bringToFront()` focuses a page.' },
    { id:9, level:1, title:'Browser Context Options', scenario:'A test needs a specific viewport, user agent, and locale.', objective:'`browser.newContext({viewport:{width:1920,height:1080}, userAgent:"...", locale:"de-DE", timezoneId:"Europe/Berlin"})`. Verify each setting applied.', constraints:'All four options. Verify with page.evaluate.', expectedOutput:'`navigator.userAgent` matches. `navigator.language` is "de". `Intl.DateTimeFormat().resolvedOptions().timeZone` is "Europe/Berlin".', check:'Context options apply to all pages in that context. `viewport`: sets the browser window size. `locale`: affects `navigator.language` and `Intl`. `timezoneId`: affects date display.' },
    { id:10, level:1, title:'Persistent Browser Context', scenario:'A test needs to use a real user profile with existing extensions and settings.', objective:'`chromium.launchPersistentContext("/path/to/profile",{headless:false})`. The context uses the real Chrome profile. Extensions and saved passwords are available.', constraints:'Persistent context path. Headed (required for extensions). Verify profile loaded.', expectedOutput:'Browser opens with the user\'s real profile. Extensions visible. Saved passwords available.', check:'`launchPersistentContext`: uses a real browser profile directory. Required for testing Chrome Extensions. Profile path: `~/.config/google-chrome/Profile1` on Linux.' },
    { id:11, level:2, title:'Browser Context Storage State', scenario:'Save and restore a full browser context (cookies + localStorage) to reuse auth across tests.', objective:'After login: `await context.storageState({path:"state.json"})`. In next test: `browser.newContext({storageState:"state.json"})`. Verify the session is preserved.', constraints:'Save state after login. Restore in new context. Verify auth.', expectedOutput:'New context created from storageState starts already logged in without going through login flow.', check:'`storageState.json`: `{cookies:[...],origins:[{origin:"...",localStorage:[...]}]}`. Restores all cookies and localStorage. Used for auth sharing between tests.' },
    { id:12, level:2, title:'Geolocation Emulation', scenario:'A location-based feature shows different content for users in different cities.', objective:'`browser.newContext({geolocation:{latitude:51.5,longitude:-0.1},permissions:["geolocation"]})`. Navigate to a page that uses `navigator.geolocation`. Assert the location-specific content.', constraints:'geolocation option. permissions grant. Verify location-based content.', expectedOutput:'Page receives latitude:51.5, longitude:-0.1 (London). Shows "London" weather.', check:'`permissions:["geolocation"]` grants the permission without a browser prompt. `geolocation:{latitude,longitude,accuracy}`. `context.setGeolocation` to update mid-test.' },
    { id:13, level:2, title:'Dark Mode Emulation', scenario:'A test verifies the app looks correct in dark mode.', objective:'`browser.newContext({colorScheme:"dark"})`. Navigate and take a screenshot. Compare with `colorScheme:"light"`. Assert dark-mode-specific elements.', constraints:'Both color schemes. Screenshot comparison. CSS media query assertion.', expectedOutput:'Dark mode: background is dark, text is light. Light mode: background is light.', check:'`colorScheme:"dark"` emulates `@media(prefers-color-scheme:dark)`. `context.setExtraHTTPHeaders` for additional headers.' },
    { id:14, level:2, title:'Download Handling', scenario:'A test verifies that clicking "Export CSV" downloads a file.', objective:'`const [download] = await Promise.all([page.waitForEvent("download"), page.click("text=Export CSV")])`. Get path: `await download.path()`. Read and verify the file content.', constraints:'waitForEvent("download"). Promise.all with click. Read file.', expectedOutput:'Download event fires. `download.suggestedFilename()` returns "data.csv". File content verified.', check:'`page.waitForEvent("download")` must be set up BEFORE the click. `download.saveAs("path")` saves the file. `download.failure()` returns null on success, error string on failure.' },
    { id:15, level:2, title:'HTTP Authentication', scenario:'A staging environment is protected by HTTP Basic Auth.', objective:'`browser.newContext({httpCredentials:{username:"admin",password:"secret"}})`. Navigate to the protected page. Verify access without the browser auth prompt.', constraints:'httpCredentials in context. Navigate to protected page. Verify access.', expectedOutput:'Page loads without showing an auth dialog. Content is accessible.', check:'`httpCredentials` provides credentials for HTTP Basic/Digest authentication. Alternative: include credentials in the URL: `https://user:pass@example.com`.' },
    { id:16, level:2, title:'Intercept All Network Traffic', scenario:'A test must verify that no third-party analytics calls are made on a privacy-focused page.', objective:'Collect all requests: `page.on("request",req=>requests.push(req.url()))`. Navigate and interact. After the test, assert that `requests` does not contain any analytics URLs.', constraints:'page.on("request"). Collect all URLs. Assert no analytics.', expectedOutput:'`requests` collected. Filter for "google-analytics.com" or "segment.com". Assert empty.', check:'`page.on("request",cb)`: fires for every request (fetch, XHR, navigation, images). `req.url()`, `req.method()`, `req.headers()`. `page.on("response",cb)` for responses.' },
    { id:17, level:2, title:'Service Worker Interaction', scenario:'A PWA registers a service worker. Tests must bypass or interact with it.', objective:'`browser.newContext({serviceWorkers:"block"})` to disable service workers (for clean tests). Or wait for the SW: `await context.waitForEvent("serviceworker")`. Interact with it.', constraints:'serviceWorkers:"block" option. Also show waitForEvent approach.', expectedOutput:'Blocked: SW never registers, tests always hit the network. Waiting: SW registers, test can interact.', check:'`serviceWorkers:"block"` prevents SW registration — useful when SW caching interferes with tests. `context.serviceWorkers()` returns registered workers.' },
    { id:18, level:2, title:'HAR Recording', scenario:'Capture all network traffic for a user flow and save it as a HAR file for analysis.', objective:'`await context.routeFromHAR("recording.har", {update:true})` to record. Navigate and interact. The HAR file captures all requests/responses. Then play it back with `update:false`.', constraints:'Record mode. Navigate. Playback mode.', expectedOutput:'HAR file created. On playback: all requests served from HAR file. No real network calls.', check:'HAR (HTTP Archive): standard format for network traffic. Record: `{update:true}` makes real requests and saves them. Playback: `{update:false}` serves from the HAR file.' },
    { id:19, level:2, title:'Browser-Specific Test Logic', scenario:'A CSS animation works differently in Firefox. Test must adapt.', objective:'Use `browserName` fixture in tests. `test.skip(({browserName})=>browserName==="webkit","webkit does not support X")`. Or conditional assertion: `if(browserName==="firefox") expect(x).toBe(y2)`.', constraints:'browserName fixture. skip for one browser. Conditional assertion.', expectedOutput:'WebKit: test skipped with reason. Firefox: alternate assertion used. Chromium: standard assertion.', check:'`browserName` fixture: "chromium","firefox","webkit". `test.skip(condition, reason)`: when condition is true, test is skipped. Conditional assertion handles known differences.' },
    { id:20, level:2, title:'Context Permissions', scenario:'A test must grant camera, microphone, and notification permissions to avoid browser prompts.', objective:'`browser.newContext({permissions:["camera","microphone","notifications"]})`. Navigate to a page that requests these. Verify no browser prompt appears.', constraints:'All three permissions. Navigate to requesting page. Verify no prompt.', expectedOutput:'Page requests camera → no browser dialog. Permission is pre-granted.', check:'`permissions` in context options pre-grants permissions. `context.grantPermissions(["geolocation"],{origin:"https://example.com"})` to grant mid-test.' },
    { id:21, level:3, title:'Browser Context Isolation Verification', scenario:'Prove that two browser contexts cannot access each other\'s cookies.', objective:'Context 1: login as Alice. Context 2: login as Bob. Read cookies from each context. Assert they are completely separate. Verify page from ctx1 sees Alice, page from ctx2 sees Bob.', constraints:'Two contexts. Two users. Verify complete isolation.', expectedOutput:'ctx1.cookies() contains Alice\'s session. ctx2.cookies() contains Bob\'s session. No overlap.', check:'Contexts are isolated. `context.cookies()` returns all cookies for that context. They share no state with other contexts.' },
    { id:22, level:3, title:'CDP (Chrome DevTools Protocol) Access', scenario:'A test needs access to Chrome-specific APIs not exposed by Playwright (e.g., memory info, coverage).', objective:'`const client = await page.context().newCDPSession(page)`. `await client.send("Performance.enable")`. `const metrics = await client.send("Performance.getMetrics")`. Log JS heap size.', constraints:'newCDPSession. Performance.enable. Performance.getMetrics.', expectedOutput:'`metrics.metrics.find(m=>m.name==="JSHeapUsedSize").value` logs heap usage.', check:'CDP is Chromium-only. `newCDPSession(page)`: creates a CDP session for the page. `client.send(method,params)` calls any CDP method. Used for: network throttling, coverage, heap profiling.' },
    { id:23, level:3, title:'JavaScript Coverage Collection', scenario:'A test framework collects JavaScript code coverage to identify untested code.', objective:'Start coverage: `await page.coverage.startJSCoverage()`. Interact with the page. Stop: `const coverage = await page.coverage.stopJSCoverage()`. Log which lines were executed.', constraints:'Chromium only. Start before actions. Stop and parse.', expectedOutput:'Coverage report: each script file, which lines were hit, and coverage percentage.', check:'`page.coverage.startJSCoverage()`: Chromium only. Returns per-script coverage: `{url,text,ranges:[{start,end}]}`. Use istanbul to report HTML.' },
    { id:24, level:3, title:'Emulating Offline Mode', scenario:'A PWA must show cached content when the user goes offline.', objective:'Set the context offline: `await context.setOffline(true)`. Navigate and assert the offline page is shown (or cached content). `context.setOffline(false)` to go back online.', constraints:'setOffline(true). Navigate and assert. setOffline(false).', expectedOutput:'Offline: SW serves cached page. `No internet` message shown. Online: real page loads.', check:'`context.setOffline(true)` simulates no network. All requests fail. Service worker can still serve cached responses. Test the offline fallback behavior.' },
    { id:25, level:3, title:'Request Interception and Modification', scenario:'Tests must modify request headers to simulate different authentication tokens.', objective:'`await page.route("/api/**", async route=>{ const headers={...route.request().headers(),"Authorization":"Bearer test-token"}; await route.continue({headers}); })`. Assert the API accepts the modified request.', constraints:'Intercept and modify headers. Continue with new headers.', expectedOutput:'API call with modified Authorization header. Backend accepts the test token.', check:'`route.continue({headers,method,postData,url})`: continues the request with modifications. Can change any aspect of the outgoing request.' },
    { id:26, level:3, title:'Context Events', scenario:'A monitoring system logs all page creation and close events in a context.', objective:'`context.on("page",page=>log("new page:"+page.url()))`. `context.on("close",()=>log("context closed"))`. Observe events as pages open and close.', constraints:'page event. close event. Log in each.', expectedOutput:'"new page: about:blank" when page is created. "context closed" when context is closed.', check:'Context events: `"page"` (new page created), `"close"` (context closing), `"backgroundpage"` (Chrome extension background). Page events: `"load"`,`"console"`,`"dialog"`,`"request"`,`"response"`.' },
    { id:27, level:3, title:'Timezone and Locale Testing', scenario:'An e-commerce site displays prices and dates differently per locale. Test all locales.', objective:'Test with `locale:"ja-JP"` and `timezoneId:"Asia/Tokyo"`. Navigate to a date picker and a price display. Assert Japanese formatting (¥, yyyy年mm月dd日).', constraints:'locale and timezoneId in context. Verify formatting in UI.', expectedOutput:'Price shows ¥1,234. Date shows 2024年1月15日. Timezone offset is JST (+9).', check:'`locale` affects: `navigator.language`, `Intl` APIs, date/number formatting. `timezoneId` affects: `new Date()` display, date pickers. Set on context, applies to all pages.' },
    { id:28, level:3, title:'Browser Extension Testing', scenario:'A Chrome extension modifies web pages. Test the modification.', objective:'Load the extension: `chromium.launchPersistentContext(profilePath,{args:["--load-extension=./extension","--disable-extensions-except=./extension"],headless:false})`. Navigate and assert the extension\'s modification.', constraints:'Extension loading. launchPersistentContext. Assert modification.', expectedOutput:'Page loaded with extension. Extension\'s UI injection visible in page.', check:'Extensions require: `launchPersistentContext` (not `launch`), `headless:false` (or Chrome headless new mode), `--load-extension` and `--disable-extensions-except` flags.' },
    { id:29, level:3, title:'Proxy Configuration', scenario:'Tests must route traffic through a corporate proxy or a mitmproxy for inspection.', objective:'`browser.newContext({proxy:{server:"http://proxy:8080",username:"user",password:"pass"}})`. Verify requests are routed through the proxy by checking proxy logs.', constraints:'proxy in context. Credentials. Verify routing.', expectedOutput:'All browser requests visible in proxy logs. HTTPS traffic proxied via CONNECT method.', check:'`proxy.server`: the proxy URL. `proxy.bypass`: comma-separated hostnames to bypass. `proxy.username/password`: for authenticated proxies.' },
    { id:30, level:3, title:'Multiple Browser Types in One Suite', scenario:'Run the same tests on Chromium, Firefox, and WebKit using the projects API.', objective:'Configure three projects in playwright.config.ts. Each uses a different browser. Write one test file — it runs 3 times, once per browser. Handle browser-specific differences with `browserName`.', constraints:'Three projects. One test file. browserName-based conditional.', expectedOutput:'Test count = 1 spec × 3 browsers = 3 tests. Each labeled with its browser.', check:'Projects: `[{name:"cr",use:{...devices["Desktop Chrome"]}},{name:"ff",use:{...devices["Desktop Firefox"]}},{name:"wk",use:{...devices["Desktop Safari"]}}]`.' },
    { id:31, level:4, title:'Browser Pool Management', scenario:'A test orchestrator manages a pool of browser instances to avoid launch overhead.', objective:'Build `BrowserPool(size, browserType)` with `acquire()` and `release(browser)`. Pre-launch `size` browsers. Tests check out a browser, use it, and return it.', constraints:'Pre-launched pool. acquire/release. Queue when exhausted.', expectedOutput:'5 browsers pre-launched. 10 concurrent tests: first 5 get browsers immediately. Others queue. Each browser reused 2 times.', check:'Pool: array of available browsers. `acquire()`: if available, pop and return; else queue a resolver. `release(b)`: if waiters, resolve next; else push back to pool.' },
    { id:32, level:4, title:'Persistent Context with Extensions', scenario:'Test a Chrome extension that modifies page content and adds a toolbar.', objective:'Load the extension via persistent context. Verify the extension toolbar is visible on all pages. Interact with extension popup via `page.goto("chrome-extension://ID/popup.html")`.', constraints:'Extension ID discovery. Toolbar assertion. Popup navigation.', expectedOutput:'Extension toolbar visible. Popup page opens and is interactive.', check:'Get extension ID: `const worker=await context.waitForEvent("serviceworker"); const id=worker.url().split("//")[1].split("/")[0]`. Navigate to `chrome-extension://${id}/popup.html`.' },
    { id:33, level:4, title:'Browser Context Templates', scenario:'Tests that need pre-configured contexts (auth, locale, device) should use context templates.', objective:'Build `createContext(template, browser)` where templates are named configs. Templates: `"admin"`, `"mobile-user"`, `"guest"`. Each template sets viewport, locale, storageState, and permissions.', constraints:'Template registry. Three named templates. createContext factory.', expectedOutput:'`createContext("admin",browser)` returns a context pre-configured with admin auth and desktop viewport.', check:'Template: `{storageState:"...",viewport:{...},locale:"...",permissions:[...]}`. Factory: `browser.newContext(templates[name])`. Extend with overrides: `{...templates[name],...overrides}`.' },
    { id:34, level:4, title:'Real Mobile Device Testing via BrowserStack', scenario:'Tests must run on real iOS and Android devices via BrowserStack.', objective:'Connect to BrowserStack remote: `chromium.connect("wss://cdp.browserstack.com/playwright?caps=...")`. Run tests. Show the caps format for different real devices.', constraints:'Remote connection URL. Capabilities for iOS Safari.', expectedOutput:'Test runs on a real iPhone in BrowserStack. Video recording available in their dashboard.', check:'`browser.connect(wsEndpoint)`: connects to a remote Playwright server. BrowserStack, LambdaTest, Sauce Labs all expose Playwright-compatible endpoints.' },
    { id:35, level:4, title:'Network Condition Emulation', scenario:'Tests verify slow-network behavior: spinner appears, optimistic updates shown.', objective:'Use CDP for network throttling: `await client.send("Network.emulateNetworkConditions",{offline:false,downloadThroughput:50*1024/8,uploadThroughput:10*1024/8,latency:200})`. Test on "Slow 3G".', constraints:'CDP session. Network.emulateNetworkConditions. Slow 3G simulation.', expectedOutput:'Page loads slowly. Loading spinner visible. DOMContentLoaded takes >1s.', check:'CDP download/uploadThroughput in bytes/s. Slow 3G: download=50KB/s, upload=10KB/s, latency=200ms. `Network.emulateNetworkConditions` is Chromium-only.' },
    { id:36, level:4, title:'Context-Level Route Handlers', scenario:'A test suite needs all contexts to mock analytics — globally, not per-test.', objective:'`context.route("**/*.{png,jpg}", route=>route.abort())` — blocks all images in the context. All pages in this context are affected. Compare to page-level routes.', constraints:'Context-level route. Page-level route. Show scoping difference.', expectedOutput:'Context route: all pages in context block images. Page route: only that page is affected.', check:'`context.route`: applies to all pages in the context. `page.route`: applies to that specific page only. Context routes are checked before page routes.' },
    { id:37, level:4, title:'Browser Type Feature Detection', scenario:'A test helper conditionally uses a feature only available in Chromium.', objective:'`const isCr = browserType.name()==="chromium"`. Use this flag to conditionally call CDP (`if(isCr) await cdpSession.send(...)`) or collect coverage (`if(isCr) await page.coverage.startJSCoverage()`).', constraints:'Feature detection via browserType.name. Conditional CDP and coverage.', expectedOutput:'On Chromium: CDP and coverage work. On Firefox/WebKit: those blocks skipped gracefully.', check:'`browser.browserType()` returns the BrowserType. `.name()` is "chromium","firefox","webkit". Some features (CDP, coverage, extensions) are Chromium-only.' },
    { id:38, level:4, title:'WebRTC Testing', scenario:'A video conferencing app uses WebRTC. Test the connection setup and media streams.', objective:'Grant `camera` and `microphone` permissions. Emulate fake media: `--use-fake-ui-for-media-stream --use-fake-device-for-media-stream` launch args. Assert video stream is active.', constraints:'Permissions. Fake media launch args. Assert stream active.', expectedOutput:'getUserMedia succeeds with fake camera/mic. Video element shows a test pattern. Connection established.', check:'Fake media args: `--use-fake-ui-for-media-stream` (no dialog), `--use-fake-device-for-media-stream` (fake camera input). WebRTC tests require these to work in CI.' },
    { id:39, level:4, title:'Multiple Browser Sessions', scenario:'A real-time collaboration test needs two users interacting simultaneously.', objective:'Launch two browser contexts (or two browsers). Log in as different users. User A sends a message. Assert User B\'s browser receives it in real time.', constraints:'Two parallel page objects. Simultaneous actions. Real-time assertion.', expectedOutput:'User A types message → User B\'s page shows message within 1 second.', check:'Run both browsers in the same test: `const [page1,page2]=[await ctx1.newPage(),await ctx2.newPage()]`. Make assertions on page2 after actions on page1. `expect(page2.locator(".message")).toContainText("Hello")`.' },
    { id:40, level:4, title:'Browser Memory Leak Detection', scenario:'Navigating between pages should not increase memory unboundedly.', objective:'Use CDP `Performance.getMetrics` to read `JSHeapUsedSize` before and after 10 page navigations. Assert memory does not grow by more than 10MB.', constraints:'CDP Performance metrics. 10 navigations. Memory growth assertion.', expectedOutput:'Heap after 10 navs ≤ heap at start + 10MB. Memory leak → heap grows linearly.', check:'`await client.send("HeapProfiler.collectGarbage")` before measuring. `JSHeapUsedSize` metric. Growth > threshold → possible leak. Run multiple GC cycles for accurate measurement.' },
    { id:41, level:5, title:'Custom Browser Build', scenario:'A security testing suite needs a custom Chromium build with specific patches.', objective:'Configure Playwright to use a custom Chromium binary: `chromium.launch({executablePath:"/path/to/custom-chrome"})`. Verify the custom build is used via `browser.version()`.', constraints:'Custom executablePath. Version verification. Explain use case.', expectedOutput:'`browser.version()` shows the custom build version. Tests run on the patched browser.', check:'`executablePath` overrides the Playwright-downloaded browser. Use for: (1) specific version pinning, (2) custom patches, (3) enterprise browser builds.' },
    { id:42, level:5, title:'Browser Fleet Management', scenario:'An enterprise runs Playwright tests across 100 remote browser instances.', objective:'Build a `BrowserFleet` class that manages remote Playwright server connections. Load balance across instances. Health check and remove unhealthy instances. Queue overflow requests.', constraints:'Remote connect. Health check. Load balancing. Queue.', expectedOutput:'100 concurrent test requests: distributed across 10 remote servers. Unhealthy server: requests rerouted.', check:'`browser.connect(wsUrl)`: connects to remote Playwright server. Health check: `browser.isConnected()`. LB: round-robin or least-loaded. Queue: Redis-based job queue.' },
    { id:43, level:5, title:'Browser Context State Machine', scenario:'A context transitions through states (guest→authenticated→2FA→authorized). Model this as a state machine.', objective:'Build `ContextStateMachine` with: `transition(context,event)` that moves the context through auth states. Each transition modifies the context\'s storageState.', constraints:'States: guest, authenticated, 2fa_pending, authorized. Events: login, submit2fa, logout.', expectedOutput:'Transition from guest→authenticated: login credentials entered. authenticated→2fa_pending: 2FA required. 2fa_pending→authorized: code entered.', check:'State machine guards invalid transitions. Each state has an `enter` action (what to do with the context). Transitions are async.' },
    { id:44, level:5, title:'Cross-Browser Performance Benchmarking', scenario:'Compare JavaScript execution performance across Chromium, Firefox, and WebKit.', objective:'Run a JavaScript benchmark (Fibonacci, DOM operations) in all three browsers. Collect timing via `page.evaluate(()=>performance.now())`. Compare and report results.', constraints:'Same benchmark in all 3 browsers. Collect timing. Statistical comparison.', expectedOutput:'Chromium: 45ms. Firefox: 52ms. WebKit: 48ms. Report with winner and percentage differences.', check:'Run benchmark N times (e.g., 10) in each browser. Take the median. `performance.now()` before and after. Report: `{chromium:{median,p95},firefox:{...},webkit:{...}}`.' },
    { id:45, level:5, title:'Browser Automation as a Microservice', scenario:'A company deploys Playwright as a stateless microservice: receive a URL, return a screenshot and metadata.', objective:'Build an Express server with `POST /screenshot` endpoint. Request body: `{url, options}`. Response: `{screenshot:base64, title, loadTime, statusCode}`. Manage browser lifecycle efficiently.', constraints:'Long-lived browser (reuse). Per-request context (isolation). Timeout handling.', expectedOutput:'POST {url:"https://example.com"} → {screenshot:"data:image/png;base64,...",title:"Example",loadTime:523}.', check:'Long-lived browser: `const browser = await chromium.launch()` once. Per-request: `const ctx=await browser.newContext(); const page=await ctx.newPage(); try{...}finally{await ctx.close()}`.' },
    { id:46, level:5, title:'Distributed Browser Grid', scenario:'Build a distributed Playwright grid: a coordinator sends tests to worker nodes, each running browser instances.', objective:'Design: coordinator (Express API), workers (Playwright + WebSocket server), test runner (connects to coordinator). Implement: job queue, worker registration, result collection.', constraints:'Coordinator API. Worker WebSocket. Job queue. Result collection.', expectedOutput:'10 worker nodes. 100 test jobs dispatched. Results aggregated. Report generated.', check:'Coordinator: job queue (Redis), worker registry (Map). Worker: connect to coordinator, claim jobs, run with Playwright, post results. Similar to Playwright Grid concept.' },
    { id:47, level:5, title:'Real-Time Test Monitoring Dashboard', scenario:'A live dashboard shows test execution across all browser instances in real time.', objective:'Build a WebSocket server. Custom Playwright reporter sends events (test start/end, screenshots) over WebSocket. Dashboard (HTML page) shows live test status, browser type, and screenshots.', constraints:'WebSocket server. Custom reporter. HTML dashboard.', expectedOutput:'Dashboard updates in real time as tests run. Shows: browser type, test name, status, latest screenshot.', check:'Reporter: `onTestBegin`: `ws.send({type:"test:start",name,browser})`. `onTestEnd`: `ws.send({type:"test:end",status,screenshot})`. Dashboard: `WebSocket` client, update DOM.' },
    { id:48, level:5, title:'AI-Powered Browser Automation', scenario:'Use an LLM to generate Playwright actions from natural language instructions.', objective:'Build `AIBrowser(page)` with `do(instruction)` method. `instruction` is natural language ("click the login button"). Post to an LLM API with the page\'s DOM. Parse the returned Playwright code and execute it.', constraints:'DOM serialization. LLM API call. Code execution via eval (sandboxed).', expectedOutput:'`aiBrowser.do("click the submit button")` → LLM returns `page.click("#submit")` → executes.', check:'DOM: `page.content()` or a simplified DOM snapshot. LLM prompt: "Given this DOM, write Playwright code to: <instruction>". Execute: Function constructor (not raw eval) for slight isolation.' },
    { id:49, level:5, title:'Browser Automation Ethics and Security', scenario:'A penetration testing firm uses Playwright for authorized security assessments.', objective:'Build a controlled automation framework with: (1) target allowlist, (2) rate limiting, (3) audit logging, (4) automatic PII detection/masking in screenshots. All tests require explicit authorization.', constraints:'Allowlist check before navigation. Rate limiter. Audit log. PII masking.', expectedOutput:'Navigation to non-allowlisted domain → error thrown. Rapid requests → rate limited. All actions logged. Screenshots with email addresses blurred.', check:'Allowlist: `if(!allowed.includes(new URL(url).hostname)) throw new Error("Not authorized")`. PII detection: regex for email/SSN. Masking: canvas-based screenshot filter.' },
    { id:50, level:5, title:'Full Browser Automation Platform', scenario:'Build a complete browser automation platform: scheduling, execution, result storage, and replay.', objective:'Build: (1) Test scheduler (cron-based), (2) Browser pool executor, (3) Result store (SQLite), (4) Failure replay (save and re-run), (5) Analytics dashboard. All components integrated.', constraints:'5 components integrated. Scheduler triggers executor. Results stored. Dashboard reads from store.', expectedOutput:'Scheduled tests run every hour. Results stored. Dashboard shows pass/fail trends. Failed tests can be replayed.', check:'Scheduler: node-cron. Executor: browser pool (size=4). Store: SQLite with `test_runs` and `test_results` tables. Replay: save storageState + test file + config.' },
  ],

  navigation: [
    { id:1, level:1, title:'Basic page.goto', scenario:'A test navigates to the homepage and verifies the title.', objective:'`await page.goto("https://example.com")`. Assert `toHaveTitle("Example Domain")`. Use `toHaveURL` to verify the final URL after any redirects.', constraints:'goto. toHaveTitle. toHaveURL.', expectedOutput:'Page loads. Title matches. URL is the final (post-redirect) URL.', check:'`page.goto` returns a Response object. `response.status()` gives the HTTP status code. `page.url()` returns the current URL after all redirects.' },
    { id:2, level:1, title:'Navigation waitUntil Options', scenario:'An SPA renders content after JavaScript execution. The default "load" event fires too early.', objective:'Compare: `waitUntil:"load"` (default), `"domcontentloaded"` (faster), `"networkidle"` (waits for no requests). Use each and observe when goto resolves.', constraints:'All three waitUntil values. Log resolution time.', expectedOutput:'domcontentloaded resolves fastest. networkidle resolves slowest. load is between.', check:'`"load"`: waits for the load event (DOM + resources). `"domcontentloaded"`: DOM only. `"networkidle"`: no network requests for 500ms. For SPAs, prefer waiting for a specific element over "networkidle".' },
    { id:3, level:1, title:'Browser History Navigation', scenario:'A test verifies the browser back button returns to the previous page.', objective:'Navigate to page1, then page2. `await page.goBack()`. Assert you are on page1. `await page.goForward()`. Assert you are on page2. `page.goBack()` returns null if no history.', constraints:'Two pages. goBack. goForward. Check return value.', expectedOutput:'After goBack: URL is page1. After goForward: URL is page2.', check:'`page.goBack()` and `page.goForward()` return a Response or null. They respect the browser\'s navigation history (like pressing the back/forward button).' },
    { id:4, level:1, title:'Reloading a Page', scenario:'A test verifies that refreshing the page persists the correct state.', objective:'`await page.reload()`. After reload, verify the page has the same content (e.g., form values are persisted in the URL, or a session cookie keeps the user logged in).', constraints:'reload after state change. Verify persistence.', expectedOutput:'Reload: page loads fresh. Session cookie keeps user logged in. URL params preserved.', check:'`page.reload()` sends a fresh request for the current URL. Like pressing F5. `{waitUntil:"networkidle"}` option available.' },
    { id:5, level:1, title:'Waiting for Navigation After Click', scenario:'Clicking a link causes a full-page navigation. Wait for it to complete.', objective:'`await Promise.all([page.waitForNavigation(), page.click("a.nav-link")])`. Or the modern approach: `await page.click("a.nav-link"); await page.waitForURL("**/about")`.', constraints:'Both patterns. Old waitForNavigation and new waitForURL.', expectedOutput:'Click triggers navigation. Test waits for the new URL. Page content updated.', check:'Legacy: `Promise.all([waitForNavigation(),click()])` — both must start simultaneously. Modern: `waitForURL(pattern)` after the action. For SPAs: use `waitForURL` or `waitForSelector`.' },
    { id:6, level:1, title:'Handling Redirects', scenario:'A login redirect takes the user from /login to /dashboard.', objective:'`await page.goto("/login")`. After login action, `await page.waitForURL("**/dashboard")`. Assert the final URL. Check the redirect HTTP status (301/302).', constraints:'waitForURL for the destination. Verify URL. Check response status.', expectedOutput:'After login: URL changes to /dashboard. `page.url()` returns the dashboard URL.', check:'`waitForURL(pattern)`: waits until `page.url()` matches the pattern. Pattern can be a string (glob), regex, or predicate. Resolves immediately if already matching.' },
    { id:7, level:1, title:'Page Load State', scenario:'A test must wait until the page is fully loaded before making assertions.', objective:'`await page.waitForLoadState("load")`. Also `"domcontentloaded"` and `"networkidle"`. Show that after `page.goto`, the page is already at "load" state by default.', constraints:'Three load states. Show post-goto state.', expectedOutput:'After goto("load"): calling waitForLoadState("load") resolves immediately. waitForLoadState("networkidle") may wait additional time.', check:'`page.waitForLoadState`: waits for the specified state to be reached. If already past that state, resolves immediately. Useful after tab-switches or popups.' },
    { id:8, level:1, title:'URL Patterns and Assertions', scenario:'A test verifies navigation after form submission goes to the correct URL.', objective:'`await expect(page).toHaveURL("https://example.com/success")`. Use glob: `toHaveURL("**/success*")`. Use regex: `toHaveURL(/\/success/)`. Use predicate: `toHaveURL(url=>url.includes("success"))`.', constraints:'All four URL patterns. One that passes, one that fails.', expectedOutput:'Exact match: strict. Glob: flexible. Regex: powerful. Predicate: most flexible.', check:'`toHaveURL` auto-waits for the URL to match (up to timeout). String is exact match. Glob: `*` matches any characters except `/`, `**` matches across `/`.' },
    { id:9, level:1, title:'Frame Navigation', scenario:'An app embeds content in an iframe. The test must navigate within the frame.', objective:'`const frame = page.frame({name:"content"})`. Or `page.frame({url:/.*/})`. `await frame.goto("...")`. Assert content within the frame.', constraints:'Frame selection by name and URL. frame.goto. Assert inside frame.', expectedOutput:'Frame navigates to a new URL within the frame. Outer page unchanged.', check:'`page.frame({name})`: finds frame by name attribute. `page.frame({url})`: by URL. `page.frames()`: all frames. `frameLocator("iframe")` is preferred for interacting with frame content.' },
    { id:10, level:1, title:'Navigating to File URLs', scenario:'A test must verify a locally generated HTML file.', objective:'Navigate to a local file: `await page.goto("file:///path/to/file.html")`. Assert content. Useful for testing HTML email templates or generated reports.', constraints:'file:// URL. Absolute path. Assert content.', expectedOutput:'Local HTML file renders in the browser. Assertions on its content pass.', check:'`file://` URLs work in Playwright. Windows: `file:///C:/path/to/file.html`. Generate test HTML: `const html="<h1>Test</h1>"; await page.setContent(html)` is often easier.' },
    { id:11, level:2, title:'SPA Navigation (Hash Routing)', scenario:'An SPA uses hash-based routing (#/users, #/settings). Test navigation between views.', objective:'Navigate to `/#/users`. Assert the users view renders. Click a settings link. `waitForURL("**/#/settings")`. Assert settings view.', constraints:'Hash URL. waitForURL with hash. Assert view change.', expectedOutput:'`page.url()` ends with `#/users`. Click settings: URL becomes `#/settings`. Content changes.', check:'Hash navigation does not trigger a network request — it\'s client-side. `waitForURL` handles hash changes. `page.waitForURL("**#/settings")` waits for the hash to change.' },
    { id:12, level:2, title:'History API Navigation', scenario:'A modern SPA uses pushState/replaceState. Test navigation and back/forward.', objective:'Interact with a pushState-based SPA. Navigate forward through 3 views. Use `page.goBack()` twice. Verify URLs and content at each point.', constraints:'pushState SPA. Three views. goBack twice. Verify URLs.', expectedOutput:'Forward: view1→view2→view3. goBack: view3→view2→view1.', check:'pushState navigation: URL changes but no page reload. `page.waitForURL` detects pushState changes. `page.goBack()` triggers popstate event in the SPA.' },
    { id:13, level:2, title:'Network Request Waiting', scenario:'A dashboard makes multiple API calls on load. Wait for all to complete before asserting.', objective:'`await page.waitForResponse("/api/users")`. Or use request predicate: `await page.waitForResponse(res=>res.url().includes("/api")&&res.status()===200)`. Use `Promise.all` for multiple responses.', constraints:'waitForResponse. Predicate form. Promise.all for multiple.', expectedOutput:'Navigation triggers API calls. Test waits for specific response(s) before asserting.', check:'`page.waitForResponse(urlOrPredicate)` resolves with the Response object. Must be set up BEFORE the action that triggers the request. `res.json()` to read the body.' },
    { id:14, level:2, title:'Popup Window Navigation', scenario:'Clicking a button opens a popup window (not a tab). The test must interact with the popup.', objective:'`const [popup] = await Promise.all([page.waitForEvent("popup"), page.click(".open-popup")])`. Navigate within the popup. Assert content. Close popup.', constraints:'waitForEvent("popup"). Interact with popup page. Close.', expectedOutput:'Popup opens. Test reads its content. Test closes it. Main page unaffected.', check:'`popup` event fires for windows opened via `window.open()`. `page.waitForEvent("popup")` vs `context.waitForEvent("page")` for tabs. Popup is a Page object.' },
    { id:15, level:2, title:'Multi-Step Form Navigation', scenario:'A wizard form has 4 steps. Test the complete flow, verifying each step.', objective:'Step 1: fill and click Next. Verify step 2 URL/content. Fill and Next. Continue through all 4 steps. Assert the confirmation page.', constraints:'Four steps. waitForURL or waitForSelector after each Next.', expectedOutput:'Each Next click navigates to the next step. Final step: confirmation shown.', check:'After each Next: `await page.waitForURL("**/step-2")` or `await expect(page.getByText("Step 2 of 4")).toBeVisible()`. Don\'t rely on sleep.' },
    { id:16, level:2, title:'Scroll and Navigate Pattern', scenario:'A long list has pagination via infinite scroll. Test loading more content.', objective:'Scroll to the bottom: `await page.evaluate(()=>window.scrollTo(0,document.body.scrollHeight))`. Wait for new content: `await expect(page.locator(".item")).toHaveCount(40)`. Repeat.', constraints:'Scroll to bottom. waitForCount. Repeat until expected count.', expectedOutput:'Initial: 20 items. After first scroll: 40 items. After second: 60 items.', check:'After scroll, wait for the new content to load: `toHaveCount(newCount)` auto-waits. Do not use `sleep`. Repeat until reaching the desired count.' },
    { id:17, level:2, title:'Timeout Handling for Navigation', scenario:'A slow page must be handled gracefully with a custom timeout.', objective:'`await page.goto(url,{timeout:10000})` — fail if page does not load in 10s. Catch the `TimeoutError`. Also `page.setDefaultNavigationTimeout(15000)` to set globally.', constraints:'Custom timeout on goto. Catch TimeoutError. setDefaultNavigationTimeout.', expectedOutput:'Page loads in <10s: success. Slow page: TimeoutError caught. Error message logged.', check:'Navigation timeout default: 30000ms. `{timeout:0}`: disable timeout. `setDefaultNavigationTimeout` applies to all navigations. `setDefaultTimeout` applies to all (actions + navigation).' },
    { id:18, level:2, title:'Conditional Navigation', scenario:'A test must handle a conditional popup that sometimes appears on navigation.', objective:'After goto: check if a cookie consent banner is visible. If visible, click "Accept". Then proceed with the test. Use `locator.isVisible()` for the conditional check.', constraints:'isVisible check. Conditional click. Proceed regardless.', expectedOutput:'Banner present: clicked Accept. Banner absent: skipped. Test continues in both cases.', check:'`await locator.isVisible()` does NOT auto-wait — resolves immediately with true/false. Use it for conditional logic. Do not `await expect(locator).toBeVisible()` (throws if not visible).' },
    { id:19, level:2, title:'Navigation in a New Context', scenario:'Admin and user flows must be tested simultaneously by navigating in two separate contexts.', objective:'`const adminCtx = await browser.newContext({storageState:"admin.json"})`. `const userCtx = await browser.newContext({storageState:"user.json"})`. Navigate both to the same page. Assert different content per role.', constraints:'Two contexts. Different auth. Same URL. Different assertions.', expectedOutput:'Admin page: shows "Admin Dashboard". User page: shows "Welcome, User".', check:'Parallel navigation: `await Promise.all([adminPage.goto(url),userPage.goto(url)])`. Contexts are fully independent. Roles enforced by different storageState files.' },
    { id:20, level:2, title:'Anchor Link Navigation', scenario:'A documentation page uses anchor links (#section-2). Verify they scroll to the correct section.', objective:'Navigate to `page.goto("/docs#section-2")`. Assert the correct section is in the viewport. Or click an anchor link and assert `page.url()` includes the hash.', constraints:'Hash in goto URL. Verify viewport position or URL hash.', expectedOutput:'Page scrolls to #section-2. `page.url()` ends with "#section-2". Section heading is visible.', check:'`getBoundingClientRect().top` should be near 0 for the element to be at the top of the viewport. `page.evaluate(()=>document.querySelector("#section-2").getBoundingClientRect().top)`.' },
    { id:21, level:3, title:'Navigation Tracing', scenario:'Instrument all page navigations to track performance and errors.', objective:'Listen to `page.on("framenavigated",frame=>log(frame.url(),frame.name()))`. Also `page.on("load")` and `page.on("domcontentloaded")`. Build a navigation log.', constraints:'Three events. Build log. Verify navigation sequence.', expectedOutput:'Navigation log: [{url:"/",event:"domcontentloaded",ms:123},{url:"/",event:"load",ms:456}].', check:'`framenavigated`: fires for every frame (including iframes). `frame.name()`: frame name or "" for main. `frame.isDetached()`: check if frame is still attached.' },
    { id:22, level:3, title:'Route-Based Navigation Mocking', scenario:'Test navigation to a page that does not exist in the dev environment by mocking it.', objective:'`await page.route("/preview/**", route=>route.fulfill({body:previewHTML}))`. Navigate to `/preview/article-123`. Assert the mocked content renders.', constraints:'route.fulfill for entire page. Navigate to mocked URL. Assert.', expectedOutput:'Navigation to /preview/article-123: route handler serves the mocked HTML. No actual server needed.', check:'`route.fulfill({body:html,contentType:"text/html",status:200})`: serves a full HTML page. Can mock any URL. Useful for testing with data that doesn\'t exist in dev.' },
    { id:23, level:3, title:'Navigation and Auth Token Refresh', scenario:'The auth token expires during a test. The app should silently refresh and continue navigating.', objective:'Intercept the 401 response. Mock the token refresh. Verify the original request is retried with the new token. Navigation continues without error.', constraints:'Intercept 401. Mock refresh. Verify retry.', expectedOutput:'Request returns 401 → app calls /refresh → gets new token → retries original request with new token → 200.', check:'`page.route("/api/**", async route=>{ const res=await route.fetch(); if(res.status()===401){/* mock refresh */} else route.fulfill({response:res}); })`.' },
    { id:24, level:3, title:'Deep Link Testing', scenario:'Push notifications link directly to specific app sections (deep links). Test each link.', objective:'Test 10 deep link URLs. Each should navigate to the correct section with the correct data. Use `page.goto(deepLink)` and assert the correct content without going through the normal navigation.', constraints:'10 deep links. Direct goto each. Assert correct section and data.', expectedOutput:'Deep link `/products/123/reviews` → product review section shows. Product ID 123 loaded.', check:'Deep links test the URL-to-state mapping directly. Each test: `goto(url)`, `expect(locator).toBeVisible()`, `expect(locator).toContainText(expectedData)`.' },
    { id:25, level:3, title:'Navigation with Authentication Challenges', scenario:'Some pages redirect to login if unauthenticated. Test the redirect and return navigation.', objective:'Navigate to a protected page without auth. Assert redirect to /login. Log in. Assert redirect back to the original page (via ?returnUrl parameter).', constraints:'Unauthenticated access. Login redirect. Return URL. Verify return.', expectedOutput:'Access /dashboard → redirect to /login?returnUrl=/dashboard → login → redirect to /dashboard.', check:'`page.waitForURL("**/login**")` after navigating to protected page. After login: `page.waitForURL("**/dashboard")`. The `returnUrl` parameter is the key.' },
    { id:26, level:3, title:'Progressive Enhancement Navigation', scenario:'A server-rendered page works without JS (forms submit via POST, links via GET). With JS, it becomes an SPA.', objective:'Disable JavaScript: `browser.newContext({javaScriptEnabled:false})`. Navigate and interact via native form submissions. Assert the server-rendered responses. Compare to JS-enabled behavior.', constraints:'javaScriptEnabled:false. Form submit navigation. Compare.', expectedOutput:'Without JS: form submission reloads the page via GET/POST. With JS: SPA handles it client-side.', check:'`javaScriptEnabled:false`: disables JavaScript. Tests the HTML/CSS-only experience. Links and forms work via native browser behavior (full page reloads).' },
    { id:27, level:3, title:'AJAX Navigation Patterns', scenario:'A table filters via AJAX — the URL updates (via pushState) but the page does not reload.', objective:'Enter search term. `waitForResponse("/api/search?q=...")` and `waitForURL("**?q=...")`. Assert results updated. Back button restores previous search results.', constraints:'waitForResponse and waitForURL simultaneously. Back button test.', expectedOutput:'Search triggers AJAX. URL updates. Results update. goBack restores previous search.', check:'`Promise.all([page.waitForResponse(pred),page.waitForURL(pat),page.fill(input,term)])` — start all three simultaneously, then await the Promise.all.' },
    { id:28, level:3, title:'Navigation Retry Logic', scenario:'A test must retry navigation if the page fails to load (flaky in CI).', objective:'Write `retryNavigation(page, url, maxAttempts)` that calls `page.goto(url)`, catches navigation errors, and retries with exponential backoff.', constraints:'Retry on navigation failure. Exponential backoff. Max attempts.', expectedOutput:'Navigation fails twice → retries → succeeds on third attempt.', check:'`try{ await page.goto(url) }catch(e){ if(attempt<max){ await sleep(delay*2**attempt); return retry(); } throw e; }`.' },
    { id:29, level:3, title:'Navigation Benchmarking', scenario:'Measure page navigation performance across 10 different pages.', objective:'For each URL: record `Date.now()` before `page.goto`. After goto, use `page.evaluate(()=>performance.timing.loadEventEnd - performance.timing.navigationStart)`. Compare developer timing vs browser timing.', constraints:'10 URLs. Date.now timing. performance.timing. Comparison.', expectedOutput:'Array of {url, devMs, browserMs}. Browser timing is more accurate (includes TCP, DNS).', check:'`performance.timing.navigationStart`: epoch timestamp of navigation start. `loadEventEnd - navigationStart`: total load time. More accurate than JS Date.now surrounding goto.' },
    { id:30, level:3, title:'Cross-Origin Navigation', scenario:'An app redirects to a payment processor (different domain) and back.', objective:'Navigate to the payment page (cross-origin). Interact with the payment form. Monitor for the redirect back. `waitForURL` for the return URL.', constraints:'Cross-origin goto. waitForURL for return. Assert success page.', expectedOutput:'Payment form filled. Submit → redirect to merchant site → success page shown.', check:'Cross-origin navigation: Playwright handles it transparently. `page.waitForURL("**/payment/success")` waits for the redirect back. No special configuration needed.' },
    { id:31, level:4, title:'Navigation State Persistence Testing', scenario:'Critical user journeys must survive page refreshes without losing state.', objective:'Complete step 3 of a 5-step wizard. Refresh the page. Assert the wizard resumes at step 3 (state persisted in localStorage or URL params).', constraints:'Multi-step state. Refresh. Verify persistence mechanism.', expectedOutput:'Before refresh: step 3 shown. After `page.reload()`: step 3 still shown. State read from localStorage.', check:'Read localStorage: `page.evaluate(()=>localStorage.getItem("wizardStep"))`. After reload: same value. Tests the persistence layer, not just the UI.' },
    { id:32, level:4, title:'Navigation Waterfall Analysis', scenario:'A performance tool identifies which resources during navigation are blocking the page load.', objective:'Capture all `response` events during `page.goto`. Calculate: time-to-first-byte, time for each resource type (JS, CSS, images). Identify the longest chain.', constraints:'Response event listener. Resource type classification. Waterfall analysis.', expectedOutput:'Waterfall: [{url:"...",type:"document",ms:120},{url:"app.js",type:"script",ms:350},...].', check:'`page.on("response",res=>{const type=res.request().resourceType(); timings.push({url:res.url(),type,ms:Date.now()-start})})`. Resource types: "document","script","stylesheet","image","fetch","xhr".' },
    { id:33, level:4, title:'URL Parameter Testing', scenario:'An e-commerce search page uses URL parameters for filters. Test all combinations.', objective:'Test 20 URL combinations of search params: `?category=electronics&sort=price&min=100&max=500`. For each: navigate, assert the correct filters are applied in the UI and correct items shown.', constraints:'20 URLs. Parameterized test. URL params mapped to UI state.', expectedOutput:'URL with category=electronics → electronics tab active. sort=price → items sorted by price.', check:'Parameterized test: `const params = [{...},...]; params.forEach(p=>test(`search ${JSON.stringify(p)}`,async({page})=>{await page.goto("?"+new URLSearchParams(p).toString());...}))`. ' },
    { id:34, level:4, title:'Navigation Error Handling', scenario:'A test gracefully handles 404s, 500s, and network failures during navigation.', objective:'`route.fulfill({status:404})` to simulate 404. `route.abort("failed")` for network error. `route.fulfill({status:500})` for server error. Assert the app shows correct error pages.', constraints:'Three error types. Assert error UI for each. graceful.', expectedOutput:'404 → "Page not found" UI. 500 → "Something went wrong" UI. Network error → "Check your connection" UI.', check:'Mock the main document route, not API calls. `route` matches the document request when `resourceType()==="document"`. Assert the error page content.' },
    { id:35, level:4, title:'Frame Hierarchy Navigation', scenario:'A complex app has nested iframes. Navigate and assert within deeply nested frames.', objective:'Find the main iframe. Within it, find a nested iframe. Use `frameLocator("iframe").frameLocator("iframe")` to chain. Navigate within the innermost frame. Assert content.', constraints:'frameLocator chaining. Two levels deep. Assert in innermost.', expectedOutput:'`page.frameLocator("#outer").frameLocator("#inner").getByText("Content").toBeVisible()`.', check:'`frameLocator(selector)` returns a FrameLocator. Can be chained for nested frames. Preferred over `frame()` for interactions. `frame()` for navigation.' },
    { id:36, level:4, title:'Service Worker Controlled Navigation', scenario:'A PWA uses a service worker to serve cached pages. Verify cache-first behavior.', objective:'First visit: page loads from network (SW caches it). Simulate offline: `context.setOffline(true)`. Second visit: page loads from SW cache. Assert content is the same.', constraints:'First visit online. setOffline. Second visit cached. Compare.', expectedOutput:'Offline navigation succeeds. Content matches the online version. Network requests blocked but page renders.', check:'SW must be registered and active before going offline. `context.waitForEvent("serviceworker")` ensures SW is ready. `setOffline(true)` blocks network.' },
    { id:37, level:4, title:'Preload and Prefetch Testing', scenario:'A page prefetches the next article. Test that the prefetched navigation is instant.', objective:'Navigate to article list. Hover a link (triggers prefetch). Time the navigation to that article. Assert it loads faster than a non-prefetched article.', constraints:'Hover to trigger prefetch. Time navigation. Compare times.', expectedOutput:'Prefetched: 50ms navigation. Non-prefetched: 300ms. Prefetching measurably improves speed.', check:'Monitor network: `page.on("request",r=>if(r.headers()["purpose"]==="prefetch") log("prefetching:"+r.url()))`. Time: `const t=Date.now(); await page.goto(url); expect(Date.now()-t).toBeLessThan(100)`.' },
    { id:38, level:4, title:'Multi-Tab Navigation Coordination', scenario:'A banking app opens statements in new tabs. Test the coordination between the main tab and the statement tab.', objective:'Main tab: click "View Statement" → opens new tab with the statement. Interact with statement tab. Close it. Assert main tab still shows the correct state.', constraints:'New tab open. Interact. Close. Assert main.', expectedOutput:'Statement tab opens with correct data. Close: main tab still on account page with correct balance.', check:'`const [stmt] = await Promise.all([ctx.waitForEvent("page"), mainPage.click(".view-stmt")])`. After close: `await stmt.close()`. Assert on `mainPage` (unaffected).' },
    { id:39, level:4, title:'Navigation with Custom Headers', scenario:'All test requests must include a custom header for tracking.', objective:'`await page.setExtraHTTPHeaders({"X-Test-Session":"playwright-123"})`. Navigate. Verify via a mocked route that the header is present on all requests.', constraints:'setExtraHTTPHeaders. Verify in route handler.', expectedOutput:'All requests include X-Test-Session header. Route handler can read it and respond accordingly.', check:'`page.setExtraHTTPHeaders` sets headers on all HTTP requests from the page. `route.request().headers()` in the route handler allows verification.' },
    { id:40, level:4, title:'Navigation Performance Budget', scenario:'Pages must load in under 2 seconds. Fail tests that exceed the budget.', objective:'Measure navigation timing. Assert `domContentLoaded < 1000ms` and `loadComplete < 2000ms`. Add to all tests via a custom fixture.', constraints:'performance.timing. Two assertions. Custom fixture for reuse.', expectedOutput:'Fast page: both assertions pass. Slow page: test fails with "Expected loadComplete < 2000ms, got 3200ms".', check:'`const timing = await page.evaluate(()=>({dcl:performance.timing.domContentLoadedEventEnd - performance.timing.navigationStart,load:performance.timing.loadEventEnd-performance.timing.navigationStart}))`. Assert both.' },
    { id:41, level:5, title:'Full Navigation Testing Framework', scenario:'Build a reusable framework for testing navigation flows in large SPAs.', objective:'Build: `NavigationFlow` class that records visited pages, expected URL patterns, and required content assertions. Execute the flow and report mismatches.', constraints:'Flow builder API. URL pattern matching. Content assertions. Report.', expectedOutput:'`new NavigationFlow().step("/login",/Welcome/).step("/dashboard",/Overview/).execute(page)`. Pass or fail with detailed report.', check:'Each step: `goto(url)`, `waitForURL(pattern)`, `expect(locator).toContainText(expectedText)`. Flow: chain of steps executed sequentially.' },
    { id:42, level:5, title:'Navigation Chaos Testing', scenario:'Randomly interrupt navigations (network failure, slow response) and verify graceful degradation.', objective:'Build `chaosNavigation(page, urls, chaosRate)` that navigates each URL but randomly (chaosRate) aborts or delays requests. Assert the app never crashes.', constraints:'Random chaos. Assert no uncaught JS errors. Assert user-facing error messages.', expectedOutput:'30% chaos rate: some navigations fail gracefully. App shows error messages. No console errors logged.', check:'`page.on("pageerror",e=>errors.push(e))`. After chaos navigations: `expect(errors).toHaveLength(0)`. Use `route` to inject random failures.' },
    { id:43, level:5, title:'Navigation Graph Testing', scenario:'Verify that all pages in the app are reachable and return 200 without broken links.', objective:'Start from the homepage. Extract all links. Navigate to each. Record status codes. Recursively follow links up to depth 3. Report broken links.', constraints:'BFS/DFS link crawler. Status code collection. Depth limit.', expectedOutput:'100 pages crawled. 3 broken links found: {url, statusCode, foundOn}.', check:'Extract links: `page.$$eval("a[href]",els=>els.map(el=>el.href))`. Filter to same origin. Deduplicate. Record status via `page.goto` response. Report failures.' },
    { id:44, level:5, title:'Navigation API Testing', scenario:'The Navigation API (modern browser) must be tested for correct behavior in SPAs.', objective:'Test `window.navigation.navigate(url)`, `navigation.back()`, `navigation.currentEntry.url`. Assert navigation events fire correctly.', constraints:'Navigation API events. currentEntry. back/forward.', expectedOutput:'navigate() → navigatesuccess event fires → currentEntry.url updated → content rendered.', check:'`page.evaluate(()=>window.navigation.navigate("/new-url"))`. Listen: `navigation.addEventListener("navigatesuccess",...)`. Only Chromium supports Navigation API currently.' },
    { id:45, level:5, title:'Navigation Testing for Micro-Frontends', scenario:'A micro-frontend app composes multiple independently deployed apps. Navigation crosses app boundaries.', objective:'Test: navigate from App A (localhost:3001) to App B (localhost:3002) via the shell app (localhost:3000). Assert state is preserved across the boundary.', constraints:'Three origins. Shell-mediated navigation. State preservation.', expectedOutput:'Navigate App A→B: URL changes, App B renders, user session preserved (shared cookie).', check:'Micro-frontends: separate deployments, shared auth. Navigation: shell intercepts, loads App B into the shell. Test: navigate via shell links, assert App B content.' },
    { id:46, level:5, title:'Navigation Accessibility Testing', scenario:'All navigation must be keyboard-accessible and screen-reader-friendly.', objective:'Test: Tab to nav links. Enter navigates. Focus moves correctly after navigation. `aria-current="page"` on active link. `aria-live` announces page changes.', constraints:'Keyboard navigation only. aria-current assertion. aria-live check.', expectedOutput:'Tab through nav links. Enter on each: page navigates. Active link has aria-current="page". Live region announces "Navigated to About".', check:'`page.keyboard.press("Tab")` through links. `page.keyboard.press("Enter")` to activate. Assert `aria-current`: `expect(link).toHaveAttribute("aria-current","page")`.' },
    { id:47, level:5, title:'Navigation Replay and Record', scenario:'Record a real user navigation session and replay it exactly in tests.', objective:'Build a recorder: intercept navigations, clicks, and form fills. Save to JSON. Build a replayer: read JSON, execute each action with Playwright.', constraints:'Recorder instruments the page. Replayer is a Playwright test. Round-trip.', expectedOutput:'Record: user navigates 5 pages, fills 2 forms. Replay: identical sequence executed by Playwright.', check:'Recorder: `window.addEventListener("click",e=>record({type:"click",selector:getSelector(e.target)}))`. Navigation: `navigation.addEventListener("navigate",e=>record({type:"goto",url:e.destination.url}))`. Replayer: execute each action.' },
    { id:48, level:5, title:'Navigation Security Testing', scenario:'The app must not leak sensitive data in URLs or allow open redirects.', objective:'Test: (1) Sensitive data not in URL after login. (2) Open redirect: `?returnUrl=https://evil.com` does not redirect to an external domain. (3) `Referer` header does not include sensitive URL params.', constraints:'Three security checks. Assert URL, redirect destination, and headers.', expectedOutput:'(1) /dashboard URL has no token. (2) returnUrl=evil.com → redirect to home, not evil.com. (3) Referer does not include session token.', check:'Open redirect: navigate with malicious returnUrl, assert `page.url()` is the safe destination (not evil.com). Referer: `route.request().headers()["referer"]` in a route handler.' },
    { id:49, level:5, title:'Navigation Orchestration', scenario:'A test orchestrates navigation across multiple browser instances in a defined sequence.', objective:'Instance 1 navigates to page A. Instance 2 navigates to page A. Instance 1 performs action. Assert Instance 2 reflects the change in real time.', constraints:'Two instances. Sequential coordination. Real-time assertion.', expectedOutput:'Instance 1 creates a record. Instance 2 (on the same page) sees the record appear within 1 second.', check:'Use a shared coordination mechanism (API call or WebSocket). Instance 1: `await createRecord()`. Instance 2: `await expect(locator).toBeVisible({timeout:2000})`. The `timeout` allows real-time propagation.' },
    { id:50, level:5, title:'Full Navigation Test Suite', scenario:'Build a complete navigation test suite for a complex SPA with authentication, deep links, back/forward, and error pages.', objective:'Cover: (1) All main routes, (2) Auth-protected routes (redirect to login), (3) Deep link entry points, (4) Back/forward history, (5) Error pages (404, 500), (6) Cross-origin navigation, (7) Offline navigation.', constraints:'All 7 coverage areas. Page Object for navigation helper. Shared test data.', expectedOutput:'40 tests covering all navigation scenarios. 100% of defined routes covered.', check:'Navigation test pyramid: (1) URL→content mapping, (2) Guard redirects, (3) History, (4) Error states, (5) Performance budget. One fixture: `navigatorFixture` with helpers.' },
  ],

  locators: [
    { id:1, level:1, title:'getByRole Locator', scenario:'A test clicks a button using its accessible role.', objective:'`page.getByRole("button",{name:"Submit"})`. Also use: `getByRole("link",{name:"Home"})`, `getByRole("heading",{level:2})`, `getByRole("checkbox",{name:"Agree"})`.', constraints:'Four role types. Name and level options.', expectedOutput:'Each locator finds the correct element. Click works. Assertion passes.', check:'`getByRole` uses ARIA roles and accessible names. Most resilient to HTML changes. Name: from aria-label, aria-labelledby, or text content. Prefer over CSS selectors.' },
    { id:2, level:1, title:'getByText Locator', scenario:'A test finds an element by its visible text content.', objective:'`page.getByText("Welcome back")` — exact match. `page.getByText("Welcome",{exact:false})` — partial. `page.getByText(/welcome/i)` — regex case-insensitive.', constraints:'Exact string. Partial (exact:false). Regex.', expectedOutput:'Exact: only elements with exactly "Welcome back". Partial: any containing "Welcome". Regex: case-insensitive.', check:'`getByText` matches text content. `exact:true` (default): full match. `exact:false`: contains. Regex: tested against full text. Multiple matches → assertion needed to narrow.' },
    { id:3, level:1, title:'getByLabel Locator', scenario:'A test fills a form field by its label text.', objective:'`page.getByLabel("Email address").fill("user@example.com")`. Works with `<label for="id">`, `aria-label`, and `aria-labelledby`.', constraints:'Three label types: for attribute, aria-label, aria-labelledby.', expectedOutput:'All three label patterns find the correct input element.', check:'`getByLabel("Email")` finds an input whose `<label>` text is "Email", or whose `aria-label="Email"`. The most semantic way to find form inputs.' },
    { id:4, level:1, title:'getByPlaceholder Locator', scenario:'A search input has no label but has a meaningful placeholder.', objective:'`page.getByPlaceholder("Search products...")`. Fill it. Assert the value. Also show that `getByLabel` is preferred when a label exists.', constraints:'Placeholder locator. Fill. Assert value.', expectedOutput:'Input with placeholder="Search products..." found. Filled. `toHaveValue` passes.', check:'`getByPlaceholder` finds inputs by their `placeholder` attribute. Useful when no label exists. Prefer `getByLabel` when there is an associated label.' },
    { id:5, level:1, title:'getByAltText Locator', scenario:'A test verifies an image is displayed correctly.', objective:'`page.getByAltText("Company logo")`. Assert `toBeVisible()`. Also assert `toHaveAttribute("src",/logo\\.png/)`.', constraints:'getByAltText. toBeVisible. toHaveAttribute.', expectedOutput:'Image with alt="Company logo" found. Visible. src attribute verified.', check:'`getByAltText` finds elements by their `alt` attribute. Primarily for `<img>` tags. Also works for `<area>` and `<input type="image">`.' },
    { id:6, level:1, title:'getByTitle Locator', scenario:'An icon button has a title attribute describing its action.', objective:'`page.getByTitle("Close dialog")`. Click it. Assert the dialog is gone.', constraints:'getByTitle. Click. Assert dialog gone.', expectedOutput:'Element with title="Close dialog" found. Click closes the dialog.', check:'`getByTitle` finds elements by their `title` attribute. Less common than other locators — prefer `getByRole` or `getByLabel` when available.' },
    { id:7, level:1, title:'getByTestId Locator', scenario:'A test uses data-testid attributes added by developers specifically for testing.', objective:'`page.getByTestId("submit-button")`. HTML: `<button data-testid="submit-button">`. Discuss when to use vs avoid test IDs.', constraints:'getByTestId usage. HTML with data-testid. When to prefer over role.', expectedOutput:'Element with data-testid="submit-button" found. Click works.', check:'Test IDs: stable across text/class changes. Downside: must be added to HTML (maintenance burden). Use when `getByRole` is not specific enough. Configure: `testIdAttribute:"data-cy"` in config.' },
    { id:8, level:1, title:'CSS Selector Locator', scenario:'A legacy test uses CSS selectors. Understand when they are acceptable.', objective:'`page.locator(".nav-link.active")`. `page.locator("#user-menu")`. `page.locator("[data-status=active]")`. Discuss: CSS selectors are fragile. Prefer semantic locators.', constraints:'Three CSS patterns: class, id, attribute. Show fragility.', expectedOutput:'CSS locators work. Show that renaming a class breaks the test.', check:'`page.locator(selector)` accepts CSS selectors, XPath, and text pseudo. CSS: fragile to class renames. Prefer `getByRole` or `data-testid`. Use CSS only for complex structural queries.' },
    { id:9, level:1, title:'XPath Locator', scenario:'A test must select an element using XPath when no semantic locator works.', objective:'`page.locator("//button[contains(text(),\'Submit\')]")`. `page.locator("xpath=//table//tr[3]/td[2]")`. Discuss: XPath is verbose and fragile. Use as last resort.', constraints:'Two XPath examples. Show when XPath is needed.', expectedOutput:'XPath locators work. Table cell at row 3, col 2 found.', check:'`xpath=` prefix for explicit XPath. `//` shorthand also works. XPath can traverse up the DOM (parent::) unlike CSS. But it\'s slow and brittle.' },
    { id:10, level:1, title:'Locator Chaining and Filtering', scenario:'A table has multiple Edit buttons, one per row. Target only Alice\'s row.', objective:'`page.getByRole("row",{name:/Alice/}).getByRole("button",{name:"Edit"})`. Chain locators to narrow scope. Also filter: `page.getByRole("listitem").filter({hasText:"Alice"}).getByRole("button")`.', constraints:'Row-scoped button. filter({hasText}). Chaining.', expectedOutput:'Only Alice\'s Edit button found. No ambiguity.', check:'Chaining: the second `getByRole` searches within the first. `filter({hasText})`: narrows a locator to items containing text. `filter({has:locator})`: narrows by child locator.' },
    { id:11, level:2, title:'Locator Filtering Techniques', scenario:'A list has 20 items. Filter to only those with "Sale" badge.', objective:'`page.getByRole("listitem").filter({has:page.getByText("Sale")})`. Count: `await filteredItems.count()`. Assert each has the Sale badge.', constraints:'filter with has locator. count(). all() iteration.', expectedOutput:'Only items with "Sale" badge selected. count() returns correct number.', check:'`filter({has:locator})`: keeps only list items that contain the given locator. `locator.all()` returns an array of locator snapshots for iteration.' },
    { id:12, level:2, title:'Nth Locator Selection', scenario:'A carousel has 5 slides. Test the third slide.', objective:'`page.getByRole("img").nth(2)` — zero-indexed. `page.getByRole("img").first()`. `page.getByRole("img").last()`. Show all three.', constraints:'nth. first. last. Zero-indexing.', expectedOutput:'nth(0) = first, nth(2) = third, last() = fifth.', check:'`nth(n)`: zero-indexed. `first()` = `nth(0)`. `last()` = `nth(-1)` equivalent. Use sparingly — positional selectors are fragile if items are reordered.' },
    { id:13, level:2, title:'Locator Assertions', scenario:'A test verifies multiple properties of a locator.', objective:'`expect(locator).toBeVisible()`. `toBeEnabled()`. `toBeChecked()`. `toHaveText("...")`. `toHaveAttribute("href",/.+/)`. `toHaveClass(/active/)`. Show each.', constraints:'Six assertions. Each on an appropriate element.', expectedOutput:'All six assertions pass. Each verifies a different property.', check:'All locator assertions auto-wait up to the timeout. `toBeVisible`: element is visible in the viewport. `toBeEnabled`: not disabled. `toBeChecked`: checkbox/radio is checked.' },
    { id:14, level:2, title:'Locator Visibility and Existence', scenario:'A test must handle elements that may or may not exist on the page.', objective:'`await locator.isVisible()` — resolves immediately, no wait. `await locator.count()` — 0 if absent. Compare to `expect(locator).toBeVisible()` (auto-waits). Use `{timeout:0}` to check without waiting.', constraints:'isVisible for condition check. count for existence. expect for assertion.', expectedOutput:'`isVisible()`: instant true/false. `count()`: 0 or more. `expect().toBeVisible({timeout:0})`: no wait.', check:'`isVisible` and `count` do NOT wait. `expect(locator).toBeVisible()` waits up to timeout. Use `isVisible` for conditionals: `if(await locator.isVisible()) await locator.click()`.' },
    { id:15, level:2, title:'Dynamic Locators', scenario:'A list renders items with dynamic IDs. Build locators that work regardless of the ID.', objective:'Avoid `#item-12345`. Use: `page.getByRole("listitem").filter({hasText:"Apple"})`. Or: `page.locator("[data-product-name=Apple]")`. Or: `page.getByRole("row").nth(0)`.', constraints:'Three dynamic-safe approaches. Explain why dynamic IDs are bad.', expectedOutput:'Tests work even after a database reset that changes IDs.', check:'Dynamic IDs change across environments and data resets. Stable alternatives: role+name, data-testid, visible text, stable data attributes.' },
    { id:16, level:2, title:'Within-Frame Locators', scenario:'An embedded payment form is inside an iframe. Locate inputs within it.', objective:'`const frame = page.frameLocator("#payment-iframe")`. `await frame.getByLabel("Card Number").fill("4111111111111111")`. `await frame.getByRole("button",{name:"Pay"}).click()`.', constraints:'frameLocator. getByLabel within frame. Click within frame.', expectedOutput:'Card number input inside iframe found and filled. Pay button clicked inside iframe.', check:'`frameLocator(selector)` returns a FrameLocator. All locator methods work within it. Automatically handles cross-origin iframes with Playwright\'s special handling.' },
    { id:17, level:2, title:'Shadow DOM Locators', scenario:'A web component uses Shadow DOM. Locate elements within the shadow root.', objective:'`page.locator("my-component >> css=.button")`. Or using `locator("my-component").locator(".button")`. Show that `>>` pierces shadow DOM.', constraints:'Two shadow DOM locator approaches. Verify found.', expectedOutput:'Element inside shadow root found and interacted with.', check:'Playwright automatically pierces shadow DOM for `getByRole`, `getByText`, and other semantic locators. CSS with `>>` explicitly pierces. `locator` chaining also works.' },
    { id:18, level:2, title:'Locator Reusability', scenario:'The same "Add to Cart" button appears on every product card. Create a reusable function.', objective:'Write `addToCart(page, productName)` that: finds the product card by name, then clicks the Add to Cart button within that card. Reuse in 5 tests.', constraints:'Helper function. Scoped locator. Used in 5 tests.', expectedOutput:'`addToCart(page,"iPhone 15")` finds the iPhone 15 card and clicks its Add to Cart button.', check:'`const card = page.getByRole("article").filter({hasText:productName})`. `await card.getByRole("button",{name:"Add to Cart"}).click()`. Reusable and scoped.' },
    { id:19, level:2, title:'Text Selector Patterns', scenario:'A test verifies the exact vs partial text matching behavior.', objective:'`getByText("Add")` — matches elements with exactly "Add". `getByText("Add",{exact:false})` — matches "Add to Cart" too. `getByText(/add/i)` — case-insensitive.', constraints:'All three. Show which elements match each.', expectedOutput:'Exact "Add": only the standalone "Add" button. Partial: all containing "Add". Regex /add/i: all case-insensitive.', check:'Default `exact:true` prevents accidental matches. Use `exact:false` or regex when you need partial matching. Multiple matches → use `.nth()` or `.filter()` to narrow.' },
    { id:20, level:2, title:'Accessible Name Computation', scenario:'A test uses getByRole but needs to understand how the accessible name is computed.', objective:'Show how accessible name is computed for a button: (1) aria-label, (2) aria-labelledby, (3) button text content. Build examples of each and verify getByRole finds them all with the same name.', constraints:'Three name computation methods. getByRole for each.', expectedOutput:'All three buttons found by `getByRole("button",{name:"Close"})` despite having different HTML.', check:'Accessible name algorithm (accname-1.1): aria-labelledby > aria-label > title > text content. Playwright follows this. Test your app\'s accessibility by using these locators.' },
    { id:21, level:3, title:'Custom Locator Factory', scenario:'The team needs a `getByDataQa` helper for `data-qa` attributes (non-standard).', objective:'Extend `page` with a custom `getByDataQa(value)` method. `page.getByDataQa("submit-btn")` returns `page.locator("[data-qa="+value+"]")`.', constraints:'Custom method on Page (via fixture or class). Used in tests.', expectedOutput:'`page.getByDataQa("submit-btn")` finds `<button data-qa="submit-btn">`.', check:'Add via fixture: extend the Page type. Or use a helper function: `const getByDataQa=(page,val)=>page.locator(\`[data-qa="${val}"]\`)`. Or configure `testIdAttribute:"data-qa"`.' },
    { id:22, level:3, title:'Locator Combining Strategies', scenario:'A navigation link must be found using BOTH role and href attribute.', objective:'`page.getByRole("link",{name:"Products"}).and(page.locator("[href*=products]"))`. The `.and()` method narrows to elements matching both.', constraints:'getByRole. .and() with locator. Verify narrowing.', expectedOutput:'Link with role=link, name="Products", AND href containing "products" found. Other links excluded.', check:'`.and(locator)`: returns elements matching both the original locator AND the given locator. Useful for adding specificity without full CSS.' },
    { id:23, level:3, title:'Locator vs ElementHandle', scenario:'Understand when to use Locator (recommended) vs ElementHandle (legacy).', objective:'Show: `const handle = await page.$(selector)` (ElementHandle). `const locator = page.locator(selector)`. ElementHandles go stale after navigation. Locators always resolve fresh.', constraints:'Both APIs. Show stale ElementHandle after navigation. Locator stays valid.', expectedOutput:'ElementHandle: stale after reload, throws. Locator: still valid after reload, resolves fresh.', check:'ElementHandle: a snapshot of an element at a point in time. Can go stale. Locator: a lazy query, re-evaluated on each action. Always use Locators. ElementHandle is legacy.' },
    { id:24, level:3, title:'Locator Snapshot Testing', scenario:'Verify that a locator always matches exactly one element (no duplicates, no missing).', objective:'`await expect(locator).toHaveCount(1)` — exactly one match. `await expect(locator).not.toHaveCount(0)` — at least one. Use `.count()` for conditional logic.', constraints:'toHaveCount assertions. count() for conditional.', expectedOutput:'`toHaveCount(1)`: passes for single match, fails for 0 or 2+. `count()`: returns number for conditional logic.', check:'`expect(locator).toHaveCount(n)` auto-waits for count to match n. Use before interacting to ensure no ambiguity. `.count()` does not wait — use for conditions.' },
    { id:25, level:3, title:'Scoped Locators in Loops', scenario:'A product list has 10 items. Extract each item\'s name and price.', objective:'`const items = page.getByRole("listitem")`. `const count = await items.count()`. Loop: `for(let i=0;i<count;i++){const item=items.nth(i); const name=await item.getByTestId("name").textContent(); ...}`.', constraints:'Loop over locator. nth in loop. textContent per item.', expectedOutput:'Array of {name,price} extracted from all list items.', check:'`items.nth(i)` inside a loop re-queries for index i. `textContent()` returns the inner text. Consider `items.all()` for array-based iteration.' },
    { id:26, level:3, title:'Locator in Page Object Model', scenario:'A LoginPage Page Object encapsulates all locators.', objective:'`class LoginPage { emailInput = ()=>this.page.getByLabel("Email"); passwordInput = ()=>this.page.getByLabel("Password"); submitBtn = ()=>this.page.getByRole("button",{name:"Login"}); }`.', constraints:'POM with locator methods. Used in test. Locators as methods (lazy).', expectedOutput:'`loginPage.emailInput().fill("user@example.com")`. Clean, readable. Locator re-evaluated each time.', check:'Locators as methods (not properties): `emailInput = () => page.getByLabel("Email")`. This ensures re-evaluation. Store `page` reference in constructor.' },
    { id:27, level:3, title:'Locator Performance', scenario:'A test has 100 locator operations. Minimize unnecessary queries.', objective:'Show: locators are lazy (no query until action). `locator.count()` triggers a query. Avoid calling `.count()` in a loop — prefer `locator.all()` once. Profile query count.', constraints:'Lazy evaluation demonstration. all() vs count()+nth(). Profile.', expectedOutput:'`all()` triggers one query. `count()+nth(i)` in loop: N+1 queries. `all()` is more efficient.', check:'`locator.all()`: returns an array of Locator objects in one query. `locator.nth(i)` in a loop: one query per iteration. For reading data from many elements: use `$$eval` or `locator.all()`.' },
    { id:28, level:3, title:'Locator for Data Tables', scenario:'A complex data table has sortable columns, paginated rows, and clickable cells.', objective:'Locate: specific cell by row/col, sort button for a column, all rows on the current page. Use: `getByRole("row").nth(n)`, `getByRole("columnheader",{name:"Price"})`.', constraints:'Row selection. Cell in row. Column header. Pagination controls.', expectedOutput:'Row 3, Col 2 cell located. Clicking "Price" header sorts. Pagination shows page 2.', check:'Table structure: `getByRole("table")`, `getByRole("row")`, `getByRole("cell")`, `getByRole("columnheader")`. Chain them for specific cells.' },
    { id:29, level:3, title:'Locator for Form Arrays', scenario:'A form allows adding multiple phone numbers. Each row has input + delete button.', objective:'Locate the second phone row: `page.getByTestId("phone-row").nth(1)`. Delete button: `phoneRow.getByRole("button",{name:"Delete"})`. Add new: `page.getByRole("button",{name:"Add phone"}).click()`.', constraints:'Dynamic form rows. nth for index. Scoped delete button.', expectedOutput:'Second phone row found. Delete removes it. Add creates a new row.', check:'`getByTestId("phone-row")` finds all phone rows. `.nth(1)` is the second. Scoped `getByRole` on that row finds only that row\'s delete button.' },
    { id:30, level:3, title:'Locator Stability in SPAs', scenario:'An SPA re-renders components. Locators must survive re-renders.', objective:'Get a locator. Trigger a re-render (state change). Assert the locator still works. Show that Locators automatically handle re-renders.', constraints:'Locator before re-render. Trigger state change. Locator after.', expectedOutput:'After re-render: locator still resolves correctly. No stale reference errors.', check:'Locators are lazy — they query the current DOM on each action. After a re-render: the locator re-queries and finds the new DOM node. Unlike ElementHandles, they do not go stale.' },
    { id:31, level:4, title:'Locator-Based Visual Diffing', scenario:'Capture individual component screenshots using locators and diff them.', objective:'`const card = page.getByTestId("product-card").nth(0)`. `await card.screenshot({path:"card.png"})`. Compare with baseline. Assert no visual regression in just this component.', constraints:'Locator screenshot. Baseline comparison. Component-level.', expectedOutput:'Card screenshot matches baseline. Change card style → visual diff detected.', check:'`locator.screenshot()`: takes a screenshot of the element\'s bounding box only. Useful for component-level visual regression. `expect(locator).toHaveScreenshot("card.png")` is cleaner.' },
    { id:32, level:4, title:'Locator for Canvas Elements', scenario:'A chart rendered in `<canvas>` needs interaction testing.', objective:'`page.locator("canvas")`. Assert visibility. For pixel-level: `page.evaluate(()=>canvas.getContext("2d").getImageData(...))`. Simulate click at coordinates: `locator.click({position:{x:100,y:50}})`.', constraints:'Canvas locator. Pixel verification. Coordinate click.', expectedOutput:'Canvas visible. Click at (100,50) triggers chart interaction. Pixel at position verified.', check:'Canvas cannot be locator-queried for content — it is a bitmap. For chart testing: click at specific coordinates, then read data from the app state or API.' },
    { id:33, level:4, title:'Accessibility Tree Locators', scenario:'Test the app\'s ARIA tree to verify correct accessibility structure.', objective:'Use `page.accessibility.snapshot()` to get the accessibility tree. Find the submit button in the tree. Verify its role, name, and enabled state.', constraints:'accessibility.snapshot(). Tree traversal. Find button.', expectedOutput:'`snapshot.children.find(n=>n.role==="button"&&n.name==="Submit")` → found and enabled.', check:'`page.accessibility.snapshot()` returns a JSON tree of accessibility nodes. Useful for verifying complex ARIA structures without Playwright-specific selectors.' },
    { id:34, level:4, title:'Locator for Infinite Scroll Lists', scenario:'A 1000-item infinite scroll list requires finding a specific item by scrolling to it.', objective:'Implement `findItem(page, text)`: scroll incrementally, check if the item exists in the current viewport, stop when found.', constraints:'Incremental scroll. Viewport check. Return locator when found.', expectedOutput:'findItem(page,"Item #750") scrolls until the item is visible and returns its locator.', check:'`const item=page.getByText(text); await item.scrollIntoViewIfNeeded(); return item`. If item is not in DOM (virtualized list): scroll loop + check `item.count()>0`.' },
    { id:35, level:4, title:'Locator Retry Behavior', scenario:'An element appears after a 2-second animation. The locator must wait for it.', objective:'`await expect(page.getByText("Success")).toBeVisible()` — waits up to timeout (default 5s). Verify the auto-wait behavior. Show `{timeout:2000}` override.', constraints:'Delayed element. Default auto-wait. Custom timeout.', expectedOutput:'Element appears at 1.5s. Test passes (within default 5s timeout). `{timeout:2000}` would fail.', check:'All `expect(locator).toBe*()` assertions auto-wait. Actions (`click`,`fill`) also auto-wait for actionability. `{timeout:n}` per assertion. Global: `testTimeout` or `expect.setTimeout`.' },
    { id:36, level:4, title:'Multiple Element State Checking', scenario:'All items in a list must be in the "active" state. Check all at once.', objective:'`await expect(page.getByRole("listitem")).toHaveClass(/active/,{each:true})`. Also: `toHaveText(["Item 1","Item 2","Item 3"])` to verify all text at once.', constraints:'each:true for class check. Array form of toHaveText.', expectedOutput:'`toHaveClass(/active/,{each:true})`: all items have the active class. `toHaveText(arr)`: all items match in order.', check:'`{each:true}`: applies the assertion to every element in the locator. `toHaveText(arr)`: matches one-to-one with the locator\'s elements in order. Order matters.' },
    { id:37, level:4, title:'Context Menu Locator', scenario:'A right-click context menu appears and must be interacted with.', objective:'`await page.getByRole("listitem").nth(0).click({button:"right"})`. `await page.getByRole("menuitem",{name:"Delete"}).click()`. Assert item deleted.', constraints:'Right click. Context menu appears. Click menu item.', expectedOutput:'Right click → context menu appears. "Delete" clicked → item removed from list.', check:'`click({button:"right"})`: right-click. Context menu: a `role="menu"` element with `role="menuitem"` children. `getByRole("menuitem",{name:"Delete"})` finds the delete option.' },
    { id:38, level:4, title:'Locator for PDF Viewer', scenario:'An embedded PDF viewer must be verified to show the correct document.', objective:'`page.frameLocator("#pdf-viewer")`. Get title text. Assert page count. Interact with navigation buttons (Next Page, Prev Page).', constraints:'PDF iframe. frameLocator. Title and page count assertions.', expectedOutput:'PDF title visible. Page count shown. Next Page button click advances the PDF.', check:'PDF viewers (PDF.js) use iframes. `frameLocator` accesses them. Content depends on the viewer library. For basic verification: title and page count via text locators.' },
    { id:39, level:4, title:'Lazy Loaded Image Verification', scenario:'Images below the fold are lazy-loaded. Verify they load when scrolled into view.', objective:'Find image with `data-lazy="true"`. `scrollIntoViewIfNeeded()`. Wait for `src` to be set (not empty). Assert `naturalWidth > 0` (actually loaded).', constraints:'scrollIntoViewIfNeeded. Wait for src. naturalWidth assertion.', expectedOutput:'Before scroll: src empty. After scroll: src set. naturalWidth > 0.', check:'`await locator.scrollIntoViewIfNeeded()`. `await expect(img).toHaveAttribute("src",/.+/)`. `const loaded = await img.evaluate(el=>el.naturalWidth>0); expect(loaded).toBe(true)`.' },
    { id:40, level:4, title:'Locator for Dynamic Table Sorting', scenario:'Clicking a column header sorts the table. Verify the sort order.', objective:'Click "Price" header. `await expect(rows.first()).toContainText("$9.99")` (cheapest). Click "Price" again for descending. `await expect(rows.first()).toContainText("$999")`.', constraints:'Click header. Verify first row. Click again. Verify again.', expectedOutput:'Ascending: first row has lowest price. Descending: first row has highest price.', check:'Extract all cell values: `await rows.allTextContents()`. Assert sorted order. Or just check first/last element for min/max.' },
    { id:41, level:5, title:'Locator Analysis Tool', scenario:'Build a tool that analyzes all locators in a test file and reports fragile ones.', objective:'Parse test files with AST. Find all `page.locator()` calls with CSS class or ID selectors. Flag them as fragile. Suggest `getByRole` or `getByTestId` alternatives.', constraints:'AST parsing. Fragile selector detection. Suggestion engine.', expectedOutput:'Report: [{file, line, selector, fragility, suggestion}]. CSS class selectors flagged. getByRole suggested.', check:'Use `@babel/parser` or `ts-morph` to parse. Find `CallExpression` with callee matching `page.locator`. Check the argument for class/id patterns. Suggest alternative.' },
    { id:42, level:5, title:'Locator Registry', scenario:'A large test suite has 500 locators. Centralize them for easy maintenance.', objective:'Build a `LocatorRegistry` that maps logical names to locator factories. `registry.get("loginButton")(page)` returns the login button locator. Update one entry to update all tests.', constraints:'Registry pattern. Factory functions. TypeScript typed keys.', expectedOutput:'`registry.get("submitButton")(page)` returns `page.getByRole("button",{name:"Submit"})`. Change once in registry → all tests updated.', check:'`const registry = {submitButton:(page)=>page.getByRole("button",{name:"Submit"})}`. TypeScript: key type from `keyof typeof registry`. `get(key)` returns the factory.' },
    { id:43, level:5, title:'AI-Assisted Locator Generation', scenario:'When a locator fails, use an AI service to suggest a new one from the current page DOM.', objective:'On locator failure: serialize the DOM (HTML), send to an LLM with the failing selector and the intent. Parse the response for a new selector. Retry the action.', constraints:'On failure hook. DOM serialization. LLM suggestion. Retry.', expectedOutput:'Locator `[data-id="old"]` fails. AI analyzes DOM. Suggests `getByRole("button",{name:"Submit"})`. Test retries and passes.', check:'DOM: `page.content()` or `page.evaluate(()=>document.body.innerHTML)`. Prompt: "Given this DOM, suggest a Playwright locator for: [element description]". Parse response for code.' },
    { id:44, level:5, title:'Locator-Based A/B Testing', scenario:'The app serves two variants (A/B). Tests must work with both without knowing which variant is active.', objective:'Build `resilientLocator(page, variants[])` that tries each variant locator. Returns the first that resolves within a short timeout.', constraints:'Multiple variant selectors. Try each. Return first success.', expectedOutput:'Variant A button: `getByRole("button",{name:"Buy Now"})`. Variant B: `getByRole("button",{name:"Add to Cart"})`. `resilientLocator` finds whichever is present.', check:'`for(const loc of variants){ if(await loc.isVisible()) return loc; }`. Or `Promise.race` with timeout on each. Log which variant was found.' },
    { id:45, level:5, title:'Locator Performance Profiling', scenario:'Slow locator resolution is making tests flaky. Profile which locators take the longest.', objective:'Wrap all locator actions with timing. `const t=Date.now(); await locator.click(); log("click took",Date.now()-t,"ms")`. Build a report of slow locators.', constraints:'Timing wrapper. Report slow locators. Threshold.', expectedOutput:'Locator timing report: [{selector,action,ms}]. Locators > 500ms flagged.', check:'Proxy the Locator class to wrap all methods with timing. Or use a helper: `const timedClick=async(loc,label)=>{const t=Date.now();await loc.click();if(Date.now()-t>500)log("slow:",label)}`.' },
    { id:46, level:5, title:'Semantic Locator Migration Tool', scenario:'A test suite has 2000 CSS class selectors. Migrate them all to semantic locators.', objective:'Build a codemod (using jscodeshift) that finds `page.locator(".class-name")` and replaces with `getByTestId` or `getByRole` based on a mapping file.', constraints:'jscodeshift codemod. Mapping file. Before/after examples.', expectedOutput:'`page.locator(".submit-btn")` → `page.getByRole("button",{name:"Submit"})` based on mapping entry.', check:'Mapping: `{".submit-btn": {type:"role",role:"button",name:"Submit"}}`. Codemod: find CallExpression, match against mapping, replace with the correct `getBy*` call.' },
    { id:47, level:5, title:'Cross-Framework Locator Compatibility', scenario:'Tests must work against React, Angular, and Vue versions of the same component.', objective:'Test the same user flow against three framework implementations. Locators must find elements regardless of framework-generated attributes. Use semantic locators exclusively.', constraints:'Three apps. Same test file. Semantic locators only.', expectedOutput:'Same test file passes on React app, Angular app, and Vue app. No framework-specific selectors.', check:'Semantic locators (getByRole, getByLabel, getByText) are framework-agnostic. They query the rendered DOM using ARIA semantics, not framework internals.' },
    { id:48, level:5, title:'Locator Security Audit', scenario:'Tests inadvertently expose sensitive data through selectors (e.g., SSN in data attributes).', objective:'Build a locator auditor that scans page HTML for sensitive patterns (SSN, credit card, email) in data attributes and selectors used in tests.', constraints:'HTML scan. Regex for sensitive patterns. Report.', expectedOutput:'Found `data-user-ssn="123-45-6789"` in the DOM. Test locators using this attribute flagged.', check:'`await page.evaluate(()=>document.querySelectorAll("[data-user-ssn],[data-card-number]").length)`. Flag in report. Also scan test files for hardcoded sensitive values in selectors.' },
    { id:49, level:5, title:'Intelligent Locator with Fallback Chain', scenario:'Build a production-grade locator system that survives UI redesigns.', objective:'`SmartLocator` tries, in order: (1) data-testid, (2) aria-label, (3) role+name, (4) text, (5) CSS as last resort. Caches the successful strategy per test per element.', constraints:'5-tier priority. Cache per element. Fallback chain.', expectedOutput:'First run: finds by role (testid missing). Caches strategy. Future runs: use cached strategy first.', check:'`for(const strategy of strategies){ const loc=strategy(page); if(await loc.count()>0) return {loc,strategy}; }`. Cache: `Map<elementId,strategyIndex>`. Persist cache to JSON between runs.' },
    { id:50, level:5, title:'Full Locator Strategy Framework', scenario:'Build a comprehensive locator strategy framework for a large engineering organization.', objective:'Build: (1) Priority-based locator resolution, (2) Locator registry with types, (3) Custom matchers for domain types, (4) Migration tool for legacy selectors, (5) Performance monitoring, (6) A/B test support.', constraints:'All 6 components. Documentation. Integration examples.', expectedOutput:'Framework published as npm package. Teams import and use it. Locator failures reduced by 80%.', check:'Core: `LocatorStrategy` interface. `LocatorResolver` tries strategies in order. `LocatorRegistry` maps names to strategies. `LocatorMonitor` tracks performance. Export all.' },
  ],

  actions: [
    { id:1, level:1, title:'Click Actions', scenario:'A test clicks various UI elements.', objective:'`locator.click()`. `locator.click({button:"right"})`. `locator.click({modifiers:["Shift"]})`. `locator.dblclick()`. `locator.click({position:{x:10,y:5}})`.', constraints:'Five click variants. Each on an appropriate element.', expectedOutput:'Left click, right click, shift-click, double-click, and coordinate click all work.', check:'`{button:"right"}`: right mouse button. `{modifiers:["Shift","Control"]}`: modifier keys. `{position:{x,y}}`: relative to element top-left. `dblclick()`: double-click.' },
    { id:2, level:1, title:'Type and Fill', scenario:'A form requires different input strategies for different fields.', objective:'`locator.fill("text")` — replaces entire value. `locator.type("text")` — types character by character (triggers keydown/keypress/keyup). `locator.pressSequentially("text")` — like type but slower.', constraints:'fill vs type vs pressSequentially. Show input event differences.', expectedOutput:'fill: value replaced instantly. type: one character at a time with keyboard events.', check:'`fill`: fastest, fires input event. `type`/`pressSequentially`: simulates real typing, fires keyboard events. Use `type` for apps that process keystrokes (e.g., autocomplete).' },
    { id:3, level:1, title:'Keyboard Actions', scenario:'A test navigates a modal with keyboard shortcuts.', objective:'`page.keyboard.press("Escape")`. `page.keyboard.press("Tab")`. `page.keyboard.press("Enter")`. `page.keyboard.type("Hello World")`. `page.keyboard.press("Control+A")` select all.', constraints:'Five keyboard actions. Mix of press and type.', expectedOutput:'Escape closes modal. Tab shifts focus. Enter submits. Type fills. Ctrl+A selects.', check:'`keyboard.press(key)`: presses and releases. Use `+` for chords: `"Control+A"`. `keyboard.type(text)`: types each character. `keyboard.down/up`: for holding keys.' },
    { id:4, level:1, title:'Mouse Actions', scenario:'A drawing canvas requires precise mouse control.', objective:'`page.mouse.move(100,100)`. `page.mouse.down()`. `page.mouse.move(200,200)`. `page.mouse.up()` — draws a line. `page.mouse.wheel(0,300)` — scroll.', constraints:'move, down, move, up for drag. wheel for scroll.', expectedOutput:'Drawing: line from (100,100) to (200,200). Scroll: page scrolls by 300px.', check:'`mouse.move`: moves cursor. `mouse.down`: presses button. `mouse.up`: releases. This sequence simulates drag-and-drop. `mouse.wheel(dx,dy)`: mouse wheel scroll.' },
    { id:5, level:1, title:'Select Dropdown', scenario:'A test selects an option from a <select> dropdown.', objective:'`locator.selectOption("value")`. `locator.selectOption({label:"United States"})`. `locator.selectOption({index:2})`. Multiple: `locator.selectOption(["a","b"])`.', constraints:'Value, label, and index selection. Multiple selection.', expectedOutput:'Option selected by value, label, and index. Multiple selection selects all specified.', check:'`selectOption` works on `<select>` elements. `{label}`: visible text. `{value}`: the value attribute. `{index}`: zero-indexed position. Multiple: multi-select elements.' },
    { id:6, level:1, title:'Checkbox and Radio', scenario:'A settings form has checkboxes and radio buttons.', objective:'`checkbox.check()`. `checkbox.uncheck()`. `expect(checkbox).toBeChecked()`. For radio: `radio.check()`. Note: radio groups auto-deselect others.', constraints:'Check/uncheck. Verify state. Radio group behavior.', expectedOutput:'Checkbox: checked/unchecked verified. Radio: one selected, others deselected.', check:'`check()`: sets to checked. `uncheck()`: sets to unchecked. Both are idempotent — safe to call even if already in that state. Radio: `check()` selects this option and deselects others.' },
    { id:7, level:1, title:'Focus and Blur', scenario:'A form validates on blur. The test must trigger the blur event.', objective:'`locator.focus()`. Type invalid input. `locator.blur()`. Assert the validation message appears.', constraints:'focus. Invalid input. blur. Assert validation.', expectedOutput:'After focus: field active. After blur: validation message appears.', check:'`locator.focus()`: focuses the element (keyboard/click focus). `locator.blur()`: removes focus. Many forms validate `onblur`. `blur()` triggers this.' },
    { id:8, level:1, title:'Hover Actions', scenario:'A tooltip appears on hover. The test must hover to see the tooltip.', objective:'`locator.hover()`. Wait for tooltip: `await expect(tooltip).toBeVisible()`. Move away: `page.mouse.move(0,0)`. Assert tooltip hidden.', constraints:'hover. Assert tooltip. Move away. Assert hidden.', expectedOutput:'Hover: tooltip visible. Move away: tooltip hidden.', check:'`locator.hover()` moves the mouse to the element\'s center. CSS `:hover` state activates. For nested hover menus: `hover()` on the parent, then click the submenu item.' },
    { id:9, level:1, title:'Tap Action (Touch)', scenario:'A mobile UI uses tap (touch) instead of click.', objective:'`locator.tap()`. Requires `hasTouch:true` in the browser context. Show that `tap` fires touch events (`touchstart`, `touchend`) not mouse events.', constraints:'Context with hasTouch:true. tap() action. Touch vs mouse events.', expectedOutput:'tap() fires touchstart and touchend. Mouse events not fired. Mobile UI responds correctly.', check:'`browser.newContext({hasTouch:true})` enables touch. `locator.tap()` fires touch events. Some mobile UIs only respond to touch events, not mouse events.' },
    { id:10, level:1, title:'Action Actionability Checks', scenario:'Understand why Playwright waits before executing an action.', objective:'Show that `click()` auto-waits for: (1) visible, (2) stable (not animating), (3) enabled, (4) not obscured, (5) receives pointer events. Force-click with `{force:true}` bypasses these checks.', constraints:'Normal click with wait. {force:true} bypasses. Show each condition.', expectedOutput:'Normal click: waits for all 5 conditions. Force click: executes immediately regardless.', check:'Actionability: Playwright ensures elements are ready before acting. `{force:true}`: bypasses all checks. Use `force` only when you intentionally need to bypass (e.g., testing covered elements).' },
    { id:11, level:2, title:'Form Submission Patterns', scenario:'A checkout form has multi-step validation. Test the complete submission flow.', objective:'Fill all fields. Click Submit. Wait for navigation (or success message). Use `Promise.all([page.waitForNavigation(),form.submit()])` for form submit.', constraints:'Fill multiple fields. Submit. waitForNavigation or waitForURL.', expectedOutput:'Form filled. Submitted. navigates to /confirmation. Success message shown.', check:'`form.submit()` or `button.click()`. `waitForURL` is cleaner than `waitForNavigation`. After submission: assert the response (success page or API call).' },
    { id:12, level:2, title:'File Upload with Drag and Drop', scenario:'A file upload zone accepts files via drag and drop (not just input click).', objective:'`const dataTransfer = await page.evaluateHandle(()=>new DataTransfer())`. `await page.dispatchEvent(".drop-zone","drop",{dataTransfer})`. Or use `setInputFiles` if there\'s an underlying input.', constraints:'DataTransfer approach for drag-drop. setInputFiles for hidden input.', expectedOutput:'File dropped in zone. File listed as uploaded.', check:'Real drag-and-drop: `DataTransfer` API. `page.dispatchEvent(selector,"dragover",{dataTransfer})` then `"drop"`. For `<input type="file">` behind a drop zone: `setInputFiles` is simpler.' },
    { id:13, level:2, title:'Copy and Paste Actions', scenario:'A test verifies copy-paste works in a rich text editor.', objective:'Select all text: `Ctrl+A`. Copy: `Ctrl+C`. Focus a different input. Paste: `Ctrl+V`. Assert the pasted content.', constraints:'Keyboard shortcuts for copy-paste. Verify pasted content.', expectedOutput:'Text selected → copied → pasted in target input → content matches.', check:'`page.keyboard.press("Control+A")`, `"Control+C"`, `"Control+V"`. Some browsers require clipboard permissions. Alternative: `page.evaluate(()=>navigator.clipboard.writeText("..."))`.' },
    { id:14, level:2, title:'Drag and Drop Between Elements', scenario:'A kanban board uses HTML5 drag-and-drop. Move a card between columns.', objective:'Try `page.dragAndDrop(".card","#column-2")`. If HTML5 D&D events are needed: dispatch `dragstart`, `dragenter`, `dragover`, `drop` events manually.', constraints:'dragAndDrop shorthand. Manual event dispatch for HTML5 D&D.', expectedOutput:'Card moved to column 2 via dragAndDrop or manual event dispatch.', check:'`page.dragAndDrop` simulates pointer-based drag. HTML5 D&D uses different events. If dragAndDrop fails: `page.dispatchEvent(source,"dragstart"); page.dispatchEvent(target,"drop")`.' },
    { id:15, level:2, title:'Multi-Step Action Sequences', scenario:'An autocomplete search requires: click input → type → wait for dropdown → click option.', objective:'`await input.click()`. `await input.type("new y",{delay:100})`. `await page.waitForSelector(".autocomplete-dropdown")`. `await page.getByRole("option",{name:"New York"}).click()`.', constraints:'Click → type → wait → click option. delay for typing.', expectedOutput:'Autocomplete suggestions appear. "New York" selected. Input shows "New York".', check:'`{delay:100}`: 100ms between keystrokes. Simulates slower typing for autocomplete. Without delay: too fast for the debounced search to trigger.' },
    { id:16, level:2, title:'Action Timeouts', scenario:'A slow action (loading button) must be given a longer timeout.', objective:'`await locator.click({timeout:10000})` — override per-action. `page.setDefaultActionTimeout(15000)` — set globally. Observe the TimeoutError message.', constraints:'Per-action timeout. Global action timeout. TimeoutError.', expectedOutput:'Action exceeds timeout → `TimeoutError: Locator.click: Timeout 10000ms exceeded`.', check:'Action timeout default: 30s (or `actionTimeout` in config). Per-action: `{timeout:ms}`. `setDefaultActionTimeout`: overrides for all future actions on this page.' },
    { id:17, level:2, title:'Waiting for Actions to Complete', scenario:'A button triggers an async operation. Wait for the operation to finish, not just the click.', objective:'`await Promise.all([page.waitForResponse("/api/submit"), submitButton.click()])`. Assert the response status. Assert the UI update after the response.', constraints:'waitForResponse with click. Assert response. Assert UI.', expectedOutput:'Click → API call made → response 200 → UI shows success.', check:'`Promise.all([waitForResponse(url), click()])`: starts the wait BEFORE the click (which triggers the request). Without Promise.all: the request might complete before waitForResponse is set up.' },
    { id:18, level:2, title:'Scroll Into View Before Action', scenario:'A button is below the fold and not clickable until scrolled to.', objective:'`await locator.scrollIntoViewIfNeeded()`. Then `locator.click()`. Or: Playwright auto-scrolls before actions — but explain when manual scroll is needed.', constraints:'scrollIntoViewIfNeeded. When Playwright auto-scrolls.', expectedOutput:'Manual scrollIntoView brings element into view. Playwright auto-scrolls for visible elements.', check:'Playwright auto-scrolls before click if the element is outside the viewport. Manual `scrollIntoViewIfNeeded` is needed for: (1) confirming the element is visible, (2) before assertions.' },
    { id:19, level:2, title:'Frame Actions', scenario:'A payment form inside an iframe must be filled and submitted.', objective:'`const frame = page.frameLocator("#payment-frame")`. `await frame.getByLabel("Card Number").fill("4111111111111111")`. `await frame.getByRole("button",{name:"Submit"}).click()`.', constraints:'frameLocator. fill inside frame. click inside frame.', expectedOutput:'Card number filled in iframe. Submit clicked in iframe.', check:'`frameLocator(selector)` returns a FrameLocator. All `getBy*` methods work on it. Actions are scoped to the frame content.' },
    { id:20, level:2, title:'Conditional Actions', scenario:'A cookie banner appears only on first visit. Handle it conditionally.', objective:'`const banner = page.getByRole("dialog",{name:/cookie/i})`. `if(await banner.isVisible()){ await page.getByRole("button",{name:"Accept"}).click(); }`. Then continue the test.', constraints:'isVisible check. Conditional click. Non-blocking.', expectedOutput:'If banner present: accepted. If not: skipped. Test continues in both cases.', check:'`isVisible()` resolves immediately (no waiting). Use for conditional flow. `expect(locator).toBeVisible()` auto-waits — use for assertions, not conditionals.' },
    { id:21, level:3, title:'Gesture Simulation', scenario:'A mobile map requires pinch-to-zoom gesture.', objective:'Simulate pinch zoom: two touch points starting close together and moving apart. Use `page.touchscreen.tap`, or dispatch `touchstart`, `touchmove`, `touchend` events with two touches.', constraints:'Two touch points. Starting close, moving apart.', expectedOutput:'Map zooms in when pinch-spread gesture is simulated.', check:'No built-in pinch API in Playwright. Manual: `page.evaluate(el=>{dispatchTouchEvent(el,"touchstart",[t1,t2]);...})`. Or use Chrome DevTools Protocol `Input.synthesizePinchGesture` (Chromium only).' },
    { id:22, level:3, title:'Rich Text Editor Actions', scenario:'A WYSIWYG editor (e.g., Quill) requires specific keyboard sequences to apply formatting.', objective:'Focus the editor. Type text. Select it (Ctrl+A). Apply bold (Ctrl+B). Verify `<strong>` in the editor HTML.', constraints:'Focus editor. Type. Select all. Bold shortcut. Verify HTML.', expectedOutput:'Editor shows bolded text. HTML contains `<strong>` tag.', check:'Rich text editors use contenteditable divs. `focus()` → `type()` → `keyboard.press("Control+A")` → `keyboard.press("Control+B")`. Verify: `evaluate(()=>editor.innerHTML)`.' },
    { id:23, level:3, title:'Slider and Range Input', scenario:'A price filter uses an HTML range slider.', objective:'`const slider = page.locator("input[type=range]")`. Set value programmatically: `await slider.fill("75")`. Or drag: `mouse.move(x,y), mouse.down(), mouse.move(targetX,y), mouse.up()`. Assert value.', constraints:'fill approach. Manual drag approach.', expectedOutput:'Slider value set to 75. Price filter updates accordingly.', check:'`fill(value)` on range input sets the value but may not fire the `input` event. If the app listens to `input` event: dispatch it manually via `evaluate`. Or use mouse drag.' },
    { id:24, level:3, title:'Date Picker Interaction', scenario:'A booking form has a custom date picker. Select a future date.', objective:'Click the date input. Navigate to the next month. Click the 15th. Assert the input value contains the selected date.', constraints:'Click input to open picker. Navigate months. Click day.', expectedOutput:'Date picker opens. Next month shown. 15th clicked. Input shows the date.', check:'Custom date pickers vary by library. General approach: `click input`, `click "Next Month"`, `click "15"`. Verify: `getByRole("textbox").inputValue()` or assertion.' },
    { id:25, level:3, title:'Infinite Scroll Actions', scenario:'A social feed uses infinite scroll. Scroll to the bottom to load more posts.', objective:'`await page.evaluate(()=>window.scrollTo(0,document.body.scrollHeight))`. Wait for new content: `await expect(page.getByRole("article")).toHaveCount(moreThanBefore)`. Repeat.', constraints:'Scroll to bottom. Wait for count increase. Repeat 3 times.', expectedOutput:'Initial: 10 posts. After scroll 1: 20. After scroll 2: 30.', check:'After scroll: wait for the new items to load. `toHaveCount(n)` auto-waits. Do not hardcode the count — read the initial count first.' },
    { id:26, level:3, title:'Complex Keyboard Navigation', scenario:'A data grid is navigable via arrow keys. Test full keyboard accessibility.', objective:'Focus first cell. Arrow right: next cell. Arrow down: row below. Tab: next interactive element. Enter: edit mode. Escape: cancel edit.', constraints:'Arrow keys in grid. Tab. Enter/Escape for edit mode.', expectedOutput:'Arrow navigation moves focus correctly. Edit mode activates with Enter. Escape cancels.', check:'`keyboard.press("ArrowRight")`, `"ArrowDown"`. Track `document.activeElement` via `evaluate` to verify focus. `keyboard.press("Enter")` activates edit. `"Escape"` cancels.' },
    { id:27, level:3, title:'Action Retry with Custom Conditions', scenario:'A button is intermittently disabled for 2 seconds (rate limiting). Retry the click.', objective:'Write `retryClick(locator, maxAttempts)`: try `locator.click()`. Catch `ElementNotEnabledError`. Wait 1s. Retry. Up to `maxAttempts` times.', constraints:'Catch specific error. Retry loop. Max attempts.', expectedOutput:'Button disabled for 2s. retryClick tries once (disabled), waits 1s, tries again (enabled) → click succeeds.', check:'Catch `Error` and check message for "Element is not enabled". `await locator.waitFor({state:"enabled"})` is cleaner: auto-waits for the enabled state.' },
    { id:28, level:3, title:'Visual Feedback After Actions', scenario:'After clicking Submit, a loading spinner appears, then a success toast.', objective:'Click Submit. Assert spinner visible. `await expect(spinner).toBeHidden()`. Assert toast `"Success!"` visible. Assert toast disappears after 3s.', constraints:'Three state assertions: loading, success, gone.', expectedOutput:'Submit → spinner → spinner gone → toast → toast gone.', check:'`toBeHidden()` is the opposite of `toBeVisible()`. Both auto-wait. For disappearing elements: `await expect(locator).toBeHidden({timeout:5000})`.' },
    { id:29, level:3, title:'Action Recording and Playback', scenario:'Record a sequence of actions and replay them for regression testing.', objective:'Record: intercept all Playwright actions (click, fill) via a proxy. Save to JSON. Replay: read JSON, execute each action via Playwright.', constraints:'Action recording proxy. JSON save. Replay execution.', expectedOutput:'Record: [{type:"fill",selector:"#email",value:"a@b.com"},{type:"click",selector:"#submit"}]. Replay: executes identical sequence.', check:'Recorder wraps the Page object. Proxy intercepts method calls, logs them, and calls through. Replayer: `for(const a of actions) await execute(page,a)`.' },
    { id:30, level:3, title:'Simulating Real User Behavior', scenario:'Tests that simulate real users (with delays and mouse moves) catch timing bugs that instant actions miss.', objective:'Add realistic delays: `type({delay:80})`. Add random mouse movement before clicking. Use `slowMo` in launch options. Compare: fast automation vs simulated-human speed.', constraints:'Realistic typing delay. Mouse movement. slowMo comparison.', expectedOutput:'Realistic: autocomplete triggers. Instant: autocomplete does not trigger (too fast for debounce).', check:'`{delay:80}`: 80ms between keystrokes (average typing speed). `mouse.move` before click: triggers hover states. Realistic simulation catches issues with debounce, hover states, and focus handling.' },
    { id:31, level:4, title:'Action Composition', scenario:'Build reusable action helpers for common workflows.', objective:'`async function login(page,email,password){ await page.getByLabel("Email").fill(email); await page.getByLabel("Password").fill(password); await page.getByRole("button",{name:"Login"}).click(); await page.waitForURL("**/dashboard"); }`. Reuse in 10 tests.', constraints:'Action helper function. Used in 10 tests via fixture.', expectedOutput:'All tests call `login(page,email,password)` and land on the dashboard.', check:'Action helpers are plain async functions. Fixtures can wrap them: `login:async({page},use)=>{ await use((e,p)=>loginFn(page,e,p)); }`. DRY principle.' },
    { id:32, level:4, title:'Atomic Multi-Action Transactions', scenario:'A payment form submission must be atomic: all actions complete, or roll back.', objective:'Write `fillPaymentForm(page, card)`. If any action fails, catch and re-navigate to a clean state. Ensure the test state is always clean after a failure.', constraints:'All fields filled atomically. Failure → clean state.', expectedOutput:'fillPaymentForm succeeds: all fields filled. fillPaymentForm fails mid-way: page navigated to clean state.', check:'`try{ all actions }catch(e){ await page.goto("/checkout"); throw e; }`. afterEach also resets: ensures cleanliness regardless.' },
    { id:33, level:4, title:'Action Performance Measurement', scenario:'Verify that each UI action responds within a performance budget.', objective:'Wrap actions with `Date.now()`. Assert each takes under 300ms. Build a `timedAction(label,fn)` helper.', constraints:'Timing wrapper. Threshold. Report slow actions.', expectedOutput:'timedAction("click submit",()=>btn.click()). If >300ms: log warning. If >1000ms: fail test.', check:'`const start=Date.now(); await fn(); const ms=Date.now()-start; if(ms>300) log("slow:"+label+" "+ms+"ms")`. Fail: `expect(ms).toBeLessThan(budget)`.' },
    { id:34, level:4, title:'Complex Drag-and-Drop Sequences', scenario:'A kanban board allows sorting within a column by dragging.', objective:'Move card from position 1 to position 3 in the same column. Requires: hover card, mouse down, move to position 3, mouse up. Verify the order.', constraints:'Within-column sort. hover → down → move → up. Verify order.', expectedOutput:'Card at position 3. Other cards shifted. Order verified.', check:'`mouse.move` to card center. `mouse.down()`. Slowly `mouse.move` to target position (multiple intermediate moves). `mouse.up()`. Verify: `column.locator(".card").allTextContents()` matches expected order.' },
    { id:35, level:4, title:'Clipboard API Actions', scenario:'A "Copy Link" button copies the current URL to the clipboard. Verify it.', objective:'Grant clipboard permission. Click "Copy Link". Read clipboard: `page.evaluate(()=>navigator.clipboard.readText())`. Assert it matches the page URL.', constraints:'Clipboard permission. Click. readText. Assert.', expectedOutput:'clipboard.readText() returns the page URL after clicking "Copy Link".', check:'Permissions: `context.grantPermissions(["clipboard-read","clipboard-write"])`. `navigator.clipboard.readText()` returns a Promise. Wrap in `page.evaluate(async()=>await navigator.clipboard.readText())`.' },
    { id:36, level:4, title:'Touch Gesture Testing', scenario:'A mobile carousel swipes between slides with touch gestures.', objective:'`page.touchscreen.tap(x,y)`. Simulate swipe: `touchscreen.tap` at x=300, drag to x=100 (left swipe). Verify slide changed.', constraints:'touchscreen.tap. Swipe simulation. Slide assertion.', expectedOutput:'Left swipe: next slide shown. Right swipe: previous slide shown.', check:'`page.touchscreen.tap(x,y)`: single tap. Swipe: touch events `touchstart → touchmove → touchend` with changing coordinates. Use `page.evaluate` with dispatchEvent for precise control.' },
    { id:37, level:4, title:'Actions in Service Workers', scenario:'A service worker intercepts background sync. Test the sync action.', objective:'Trigger background sync: `page.evaluate(()=>navigator.serviceWorker.ready.then(sw=>sw.sync.register("sync-messages")))`. Verify the sync event was processed (check API call or UI update).', constraints:'Service worker sync registration. Verify processing.', expectedOutput:'Background sync registered. Service worker processes it. API call made or UI updated.', check:'Service worker testing: `context.waitForEvent("serviceworker")` to get the SW. Sync: register tag, then verify the SW `sync` event fired via intercepted API calls.' },
    { id:38, level:4, title:'Parallel Actions in One Test', scenario:'Multiple independent UI sections can be filled in parallel to speed up the test.', objective:'Fill three independent form sections in parallel: `await Promise.all([fillPersonalInfo(), fillAddressInfo(), fillPaymentInfo()])`. Each is a helper that fills its section.', constraints:'Three async helpers. Promise.all for parallel execution.', expectedOutput:'All three sections filled. Total time = max(section1, section2, section3) instead of sum.', check:'Only parallelize when sections are truly independent (no scroll conflicts, no shared state). Verify all three filled correctly after Promise.all resolves.' },
    { id:39, level:4, title:'Action Event Verification', scenario:'Verify that a click action fires the correct JavaScript events in the correct order.', objective:'`page.on("console",msg=>log(msg.text()))`. In the page, listen to click events and log them. Verify the event log matches expected: mousedown → mouseup → click.', constraints:'Console message capture. Event order verification.', expectedOutput:'Console log: ["mousedown","mouseup","click"] in that order.', check:'Inject event listeners via `page.evaluate`: `el.addEventListener("mousedown",()=>console.log("mousedown"))`. Then `locator.click()`. Read console messages: `page.on("console",...)`. ' },
    { id:40, level:4, title:'Action Batching', scenario:'Reduce round-trip latency by batching multiple read actions.', objective:'Instead of: `const t=await title.textContent(); const u=await url.textContent(); const p=await price.textContent()`. Use: `const [t,u,p]=await Promise.all([title.textContent(),url.textContent(),price.textContent()])`.', constraints:'Sequential vs parallel textContent. Timing comparison.', expectedOutput:'Parallel: ~1x latency. Sequential: ~3x latency. Use Promise.all for independent reads.', check:'`locator.textContent()`, `inputValue()`, `isVisible()` etc. are I/O operations. Parallelizing with `Promise.all` reduces wall-clock time in remote browser tests.' },
    { id:41, level:5, title:'Action Orchestration Engine', scenario:'Build an action orchestrator that runs test steps with dependency resolution.', objective:'Define steps as `{name, deps:[], fn:async(results)=>{}}`. Orchestrator runs steps in dependency order (toposort). Passes results of dependency steps to dependent steps.', constraints:'Topological sort. Dependency injection. Parallel independent steps.', expectedOutput:'Step A and B (no deps) run in parallel. Step C (deps:A,B) runs after both with their results.', check:'Toposort: Kahn\'s algorithm. `Promise.all` for independent steps. `fn(results)` receives `{A:resultA, B:resultB}` for step C.' },
    { id:42, level:5, title:'Visual Action Testing', scenario:'Capture before/after screenshots of each significant action for visual documentation.', objective:'Wrap each action in a screenshot capture: before and after. Compile into a step-by-step visual guide of the test flow.', constraints:'Before/after screenshot per action. Compile to HTML report.', expectedOutput:'10-step test → 20 screenshots. HTML page shows the before/after for each step.', check:'Proxy the action methods. `screenshot` before and after each. Store: `{step, before: buffer, after: buffer}`. Compile: HTML with img tags in sequence.' },
    { id:43, level:5, title:'Action Model for DSL', scenario:'Build a domain-specific language for test actions that non-technical testers can write.', objective:'DSL: `"click button Submit"`, `"fill input Email with user@example.com"`, `"assert text Dashboard visible"`. Parser maps to Playwright actions.', constraints:'Three action types: click, fill, assert. Parser. Playwright execution.', expectedOutput:'`execute(page, "click button Submit")` → `page.getByRole("button",{name:"Submit"}).click()`.', check:'Parser: regex or PEG grammar. `"click (role) (name)"`, `"fill (label) with (value)"`, `"assert text (text) (visible|hidden)"`. Map each to Playwright call.' },
    { id:44, level:5, title:'Action Replay from Production Events', scenario:'Production click events (from analytics) are replayed as Playwright tests to reproduce bugs.', objective:'Collect analytics events: `{type:"click",selector:".buy-btn",timestamp}`. Build a replayer that executes them in order with correct timing.', constraints:'Analytics event format. Timing preservation. Replay in Playwright.', expectedOutput:'Production click sequence replayed. Bug reproduced in test environment.', check:'Selector from analytics: use `data-analytics-id` attributes. Timing: `await sleep(event.timestamp - previousTimestamp)`. Replay: `page.locator("[data-analytics-id="+id+"]").click()`.' },
    { id:45, level:5, title:'Fault-Tolerant Action Sequences', scenario:'A test suite must complete even when individual actions fail (resilient mode).', objective:'Build `resilientSequence(steps)` that executes each step, catches failures, logs them, and continues. At the end, fails the test if any step failed.', constraints:'Catch per step. Continue on failure. Fail at end.', expectedOutput:'Step 3 of 10 fails. Steps 4-10 continue. Test fails at the end with "3 of 10 steps failed: [step3 error]".', check:'`const failures=[]; for(const s of steps){try{await s()}catch(e){failures.push({step:s.name,error:e});}}. if(failures.length) throw new Error(...)`. ' },
    { id:46, level:5, title:'AI-Guided Action Recovery', scenario:'When an action fails, use an AI service to analyze the screenshot and suggest a recovery action.', objective:'On action failure: screenshot → send to AI with "what went wrong and what should I do next?" → parse suggestion → execute recovery → retry original action.', constraints:'Failure detection. Screenshot. AI API. Recovery execution. Retry.', expectedOutput:'Click fails (element moved). AI: "click at new position (200,300)". Recovery click succeeds. Test continues.', check:'Recovery: `mouse.click(x,y)` or `locator.click()` with new coordinates from AI. AI prompt: "Given this screenshot where clicking [selector] failed, what action should be taken?".' },
    { id:47, level:5, title:'Cross-Device Action Normalization', scenario:'The same actions must work on desktop (mouse), mobile (touch), and keyboard navigation.', objective:'Build `universalClick(page,context,locator)` that: (1) if desktop context → `locator.click()`, (2) if mobile context → `locator.tap()`, (3) if keyboard mode → `locator.focus()` + `keyboard.press("Enter")`.', constraints:'Three interaction modes. Context detection. Normalization.', expectedOutput:'Desktop: click fires. Mobile: tap fires. Keyboard: Enter activates.', check:'Context detection: `context._options.hasTouch` (mobile), or check userAgent. Keyboard mode: use `isMobile` flag set in test config.' },
    { id:48, level:5, title:'Action Dependency Graph', scenario:'Complex test setup with 20 actions must be optimized by running independent actions in parallel.', objective:'Define actions with `{name, deps, fn}`. Build a graph. Topological sort. Run parallel groups. Total time = sum of critical path, not sum of all actions.', constraints:'Graph definition. Topological sort. Parallel execution. Critical path.', expectedOutput:'20 actions with 4 parallel groups: total time = sum of critical path (5 actions in sequence).', check:'Toposort produces levels: level 0 (no deps), level 1 (deps at level 0), etc. `Promise.all` for each level. Total time = sum of each level\'s max duration.' },
    { id:49, level:5, title:'Accessibility-First Action Testing', scenario:'All actions must be performable via keyboard alone (WCAG 2.1 Level AA).', objective:'Write a test that performs the entire checkout flow using only keyboard actions (Tab, Enter, Space, Arrow keys). No mouse or touch actions.', constraints:'Keyboard only. Tab navigation. ARIA pattern compliance.', expectedOutput:'Complete checkout via keyboard: Tab to fields, type values, Tab to Submit, Enter to submit. No mouse used.', check:'`page.keyboard.press("Tab")` to advance focus. `keyboard.type(value)` to fill. `keyboard.press("Enter")` to submit. Verify `document.activeElement` moves correctly.' },
    { id:50, level:5, title:'Full Action Testing Framework', scenario:'Build a complete action testing framework for an enterprise application.', objective:'Build: (1) Action library (click,fill,select,upload,drag), (2) Recovery strategies, (3) Performance budgets per action, (4) Accessibility verification, (5) Cross-device support, (6) Action recording and replay.', constraints:'All 6 components. Composable API. Documentation.', expectedOutput:'`const actions = new ActionFramework(page). actions.click("Submit"). actions.fill("Email","a@b.com"). actions.assertPerformance()`.', check:'Core class wraps Playwright actions. Each method: timing, accessibility check, error recovery. Chain pattern for readability. Plugin: `actions.use(performancePlugin)`.' },
  ],

  assertions: [
    { id:1, level:1, title:'toBeVisible and toBeHidden', scenario:'A modal dialog appears after clicking a button and hides after clicking Close.', objective:'`await expect(modal).toBeVisible()` after open click. `await expect(modal).toBeHidden()` after close click. Both auto-wait.', constraints:'Both assertions. Verify auto-waiting behavior.', expectedOutput:'Modal visible after open. Hidden after close. Both auto-wait without explicit sleep.', check:'`toBeVisible()`: element is visible in the DOM and not hidden by CSS. `toBeHidden()`: element is hidden (display:none, visibility:hidden, or opacity:0) or not in DOM.' },
    { id:2, level:1, title:'toHaveText and toContainText', scenario:'A product page must show the correct product name and description.', objective:'`expect(heading).toHaveText("MacBook Pro 16")` — exact match. `expect(desc).toContainText("M3 chip")` — partial match. `toHaveText(/MacBook/)` — regex.', constraints:'Exact, partial, and regex. All three on appropriate elements.', expectedOutput:'Exact: full text must match. Partial: substring match. Regex: pattern match.', check:'`toHaveText`: full text content must match (normalizes whitespace). `toContainText`: text must be a substring. Both auto-wait. Regex: tested against the full text.' },
    { id:3, level:1, title:'toHaveValue', scenario:'After filling a form field, verify the value is correctly set.', objective:'Fill an input. `expect(input).toHaveValue("user@example.com")`. Fill a select. `expect(select).toHaveValue("us")`. Check a checkbox. `expect(checkbox).toHaveValue("on")`.', constraints:'Text input, select, and checkbox value assertions.', expectedOutput:'Each assertion verifies the current value of its element type.', check:'`toHaveValue`: works on inputs, textareas, and selects. For checkboxes: value is "on" when checked, depends on the value attribute.' },
    { id:4, level:1, title:'toHaveAttribute', scenario:'A link must have the correct href and an image must have an alt attribute.', objective:'`expect(link).toHaveAttribute("href","https://example.com")`. `expect(img).toHaveAttribute("alt",/logo/)`. `expect(btn).toHaveAttribute("disabled")` — just presence.', constraints:'Exact value, regex value, presence check.', expectedOutput:'href exact match. alt regex match. disabled attribute present (value doesn\'t matter).', check:'`toHaveAttribute("name")`: checks presence. `toHaveAttribute("name","value")`: checks value. `toHaveAttribute("name",/regex/)`: regex match.' },
    { id:5, level:1, title:'toHaveClass and toHaveCSS', scenario:'An active tab must have the "active" CSS class and the correct background color.', objective:'`expect(tab).toHaveClass(/active/)`. `expect(tab).toHaveCSS("background-color","rgb(0,120,255)")`. Show that toHaveCSS reads computed styles.', constraints:'Class assertion with regex. CSS property assertion.', expectedOutput:'Tab has "active" class. Background color matches (in rgb format).', check:'`toHaveClass(regex)`: tests if the element has any class matching. `toHaveCSS(prop,value)`: reads getComputedStyle. Colors are in rgb() format in computed styles.' },
    { id:6, level:1, title:'toBeChecked and toBeEnabled', scenario:'A submit button must be enabled only after all required fields are filled.', objective:'Before filling: `expect(submitBtn).toBeDisabled()`. Fill required fields. `expect(submitBtn).toBeEnabled()`. For checkbox: `expect(cb).toBeChecked()`.', constraints:'toBeDisabled. toBeEnabled. toBeChecked.', expectedOutput:'Button disabled initially. After filling: enabled. Checkbox checked after click.', check:'`toBeEnabled()`: element is not disabled. `toBeDisabled()`: element has `disabled` attribute. `toBeChecked()`: checkbox or radio is checked.' },
    { id:7, level:1, title:'toHaveURL and toHaveTitle', scenario:'After login, verify the page navigated to the dashboard with the correct title.', objective:'`expect(page).toHaveURL("https://app.example.com/dashboard")`. `expect(page).toHaveTitle(/Dashboard/)`. Both auto-wait for the URL/title to match.', constraints:'Exact URL. Regex title.', expectedOutput:'URL matches after navigation. Title matches.', check:'`toHaveURL`: string (exact), regex, or glob pattern. `toHaveTitle`: string or regex. Both are on `page`, not a locator. Both auto-wait.' },
    { id:8, level:1, title:'toHaveCount', scenario:'After adding 3 items to a cart, verify the cart badge shows 3.', objective:'Add 3 items. `expect(cartItems).toHaveCount(3)`. Also: `expect(locator).not.toHaveCount(0)` — ensure at least one item.', constraints:'toHaveCount with exact number. not modifier.', expectedOutput:'`toHaveCount(3)`: auto-waits until count reaches 3. not.toHaveCount(0): passes if ≥1.', check:'`toHaveCount(n)` auto-waits for the locator to match exactly n elements. Use for: verifying list length, table row count, error message count.' },
    { id:9, level:1, title:'Negation with not', scenario:'After deleting an item, verify it no longer appears in the list.', objective:'Delete item. `expect(page.getByText("Deleted Item")).not.toBeVisible()`. `expect(locator).not.toHaveText("Error")`. Show negation of any assertion.', constraints:'not modifier. Two negated assertions.', expectedOutput:'Deleted item not visible. No error text shown.', check:'`.not` inverts any assertion. `not.toBeVisible()`: waits until element is hidden or not in DOM. `not.toHaveText("Error")`: waits until the text does not match.' },
    { id:10, level:1, title:'Soft Assertions', scenario:'A checkout flow has 10 fields to verify. Report all failures, not just the first.', objective:'`expect.soft(locator).toHaveText("value")` for each field. Test continues after failures. At the end, the test fails if any soft assertion failed.', constraints:'10 soft assertions. Mix pass and fail. All evaluated.', expectedOutput:'3 fields with wrong values: all 3 reported. Test does not stop at the first failure.', check:'`expect.soft()` records failures without throwing. Test fails at the end if any soft assertions failed. The test function continues executing after a soft failure.' },
    { id:11, level:2, title:'Custom Assertion Messages', scenario:'A failing assertion must show a clear business-context message, not just "expected X to be Y".', objective:'`expect(price,{message:"Product price should be discounted"}).toHaveText("$9.99")`. The custom message appears in the failure output.', constraints:'Custom message on three assertions. View failure output.', expectedOutput:'Failure: "Product price should be discounted: Expected \"$19.99\" to equal \"$9.99\"".', check:'`expect(locator, {message:"custom"}).toBe*()`: the message prefixes the error. Essential for test readability when the locator context is unclear.' },
    { id:12, level:2, title:'toMatchSnapshot (Text)', scenario:'A JSON API response must match a stored snapshot to detect unintended changes.', objective:'`expect(responseBody).toMatchSnapshot("api-response.json")`. First run: creates snapshot. Subsequent: compares. Use `--update-snapshots` to regenerate.', constraints:'Text snapshot. First run creates. Second run compares. Deliberate change.', expectedOutput:'First run: "api-response.json" created. Second run: pass. Change body → fail with diff.', check:'`toMatchSnapshot(name)`: for strings and buffers. Snapshots stored in `__snapshots__`. `--update-snapshots` flag. Different from `toHaveScreenshot` (which is for images).' },
    { id:13, level:2, title:'toHaveScreenshot (Visual Assertion)', scenario:'A UI component must not visually regress between deployments.', objective:'`expect(component).toHaveScreenshot("card.png",{maxDiffPixels:50})`. First run creates baseline. Change CSS → fails with diff image. View diff in HTML report.', constraints:'First run baseline. Second run compare. Threshold option.', expectedOutput:'First: baseline saved. Match: pass. After CSS change: fail with diff image shown in report.', check:'`toHaveScreenshot`: visual assertion. `maxDiffPixels`: allowed pixel difference. `threshold`: ratio 0-1. Diff image shows changed area highlighted.' },
    { id:14, level:2, title:'API Response Assertions', scenario:'A REST API endpoint must return the correct status code and body structure.', objective:'`const res = await request.get("/api/users/1")`. `expect(res.status()).toBe(200)`. `expect(await res.json()).toMatchObject({id:1,name:expect.stringContaining("Alice")})`.', constraints:'Status assertion. JSON body assertion with toMatchObject.', expectedOutput:'Status 200. Body has id:1 and name containing "Alice".', check:'`toMatchObject({key:expect.any(String)})`: flexible matching. `expect.any(String/Number/Boolean)`: type checks. `expect.stringContaining("Alice")`: substring match in jest-style.' },
    { id:15, level:2, title:'Array Assertions', scenario:'An API returns an array of products. Verify the array structure.', objective:'`expect(products).toHaveLength(10)`. `expect(products).toContain("expected item")`. `expect(products).toEqual(expect.arrayContaining(["item1","item2"]))`.', constraints:'Length, contains, arrayContaining.', expectedOutput:'Length 10. Contains specific item. Array contains at least these items (order-independent).', check:'`arrayContaining(arr)`: the actual array must contain all items in arr (can have more). Order doesn\'t matter. `toContain`: single item check.' },
    { id:16, level:2, title:'toBeOK for API Responses', scenario:'An API response should have a 2xx status code (success).', objective:'`expect(response).toBeOK()`. This asserts `response.ok()` is true (status 200-299). Compare to `toBe(200)` for exact status.', constraints:'toBeOK assertion. Compare to status(200).', expectedOutput:'2xx responses: toBeOK passes. 3xx, 4xx, 5xx: toBeOK fails. `toBe(201)` fails for 200.', check:'`toBeOK()`: passes for any 2xx response. `response.ok()`: returns true for 2xx. Use `toBeOK` for general success, `toBe(201)` for exact code.' },
    { id:17, level:2, title:'Polling Assertions', scenario:'A background job completes asynchronously. Poll until the result appears.', objective:'`await expect.poll(async()=>{ const res=await request.get("/api/job/status"); return (await res.json()).status; },{timeout:30000}).toBe("completed")`.', constraints:'expect.poll. Async polling function. Timeout.', expectedOutput:'Job completes after 10s. expect.poll retries every 100ms until "completed" or timeout.', check:'`expect.poll(fn,{timeout,intervals})`: calls `fn` repeatedly until the assertion passes or times out. `intervals`: delays between retries (default: exponential backoff). For long-running async processes.' },
    { id:18, level:2, title:'Conditional Assertions', scenario:'A test must handle two valid states: item deleted (not visible) OR item grayed out (disabled).', objective:'`const isDeleted = !await item.isVisible(); const isGrayed = await item.isDisabled(); expect(isDeleted || isGrayed).toBeTruthy()`.', constraints:'isVisible and isDisabled for conditions. toBeTruthy assertion.', expectedOutput:'If deleted: assertion passes. If grayed: assertion passes. If still active: assertion fails.', check:'Non-assertive queries: `isVisible()`, `isEnabled()`, `isChecked()` for conditional logic. Combine with JavaScript boolean operations. Then assert the combined result.' },
    { id:19, level:2, title:'Accessibility Assertions', scenario:'A button must be keyboard-accessible and have a proper accessible name.', objective:'`expect(button).toHaveAttribute("role","button")`. `expect(button).toHaveAttribute("aria-label","Close dialog")`. Tab to the button and assert focus: `expect(button).toBeFocused()`.', constraints:'Role attribute. aria-label. toBeFocused.', expectedOutput:'Button has correct role. aria-label set. After Tab: button is focused.', check:'`toBeFocused()`: element is the current `document.activeElement`. Use `keyboard.press("Tab")` to move focus. Essential for keyboard accessibility testing.' },
    { id:20, level:2, title:'toHaveValues (Multi-Select)', scenario:'A multi-select dropdown has three options selected.', objective:'`expect(multiSelect).toHaveValues(["us","ca","mx"])`. Show how to set multiple values and verify them.', constraints:'Set multiple values. toHaveValues assertion.', expectedOutput:'Three countries selected. `toHaveValues(["us","ca","mx"])` passes.', check:'`toHaveValues` for multi-select inputs. `selectOption(["val1","val2"])` selects multiple. `toHaveValues` checks the array of selected values.' },
    { id:21, level:3, title:'Custom Expect Matchers', scenario:'The app has domain-specific state that needs clean assertion language.', objective:'Create: `toShowLoadingState`, `toHaveItemInCart(productId)`, `toBeLoggedIn`. Each is an async matcher using `expect.extend`.', constraints:'Three matchers. All async. Error messages.', expectedOutput:'`expect(page).toBeLoggedIn()` passes when session exists. Fails with "Expected page to be in logged-in state".', check:'`expect.extend({async toBeLoggedIn(page){const loggedIn=await checkAuth(page); return {pass:loggedIn,message:()=>"Expected page to be logged in"}}})`. Must return `{pass,message}`.' },
    { id:22, level:3, title:'Assertion Retry Configuration', scenario:'A slow API causes assertions to time out. Configure custom timeouts per assertion.', objective:'`expect(locator,{timeout:15000}).toBeVisible()`. `test.describe.configure({timeout:60000})` for slow test groups. `expect.configure({timeout:10000})` for global override.', constraints:'Per-assertion timeout. describe timeout. Global timeout.', expectedOutput:'Slow assertion succeeds with custom timeout. Passes before the default 5000ms.', check:'`{timeout:ms}` on `expect()`: overrides for this assertion only. `expect.configure({timeout:ms})`: sets default for all assertions in the file. Higher levels: `testTimeout`.' },
    { id:23, level:3, title:'toHaveScreenshot Advanced', scenario:'A full-page screenshot comparison with masking of dynamic content (timestamps, ads).', objective:'`expect(page).toHaveScreenshot("page.png",{mask:[page.locator(".timestamp"),page.locator(".ad")]})`. Dynamic areas are masked with a colored box before comparison.', constraints:'Full page. Two masked locators.', expectedOutput:'Timestamps and ads masked (pink box in screenshot). Comparison succeeds despite dynamic content.', check:'`mask: [locator1,locator2]`: masks the locators\' bounding boxes with a solid color (#FF00FF by default). `maskColor:"#00FF00"` to change. Use for dynamic content.' },
    { id:24, level:3, title:'expect.poll vs waitForSelector', scenario:'Compare two approaches for waiting for async conditions.', objective:'Method 1: `await expect.poll(()=>getStatus()).toBe("ready")`. Method 2: `await page.waitForSelector(".status-ready")`. Method 3: `await expect(status).toHaveText("ready")`. Compare timing and use cases.', constraints:'All three approaches. Timing comparison. Use case explanation.', expectedOutput:'All three work. `expect(locator)` is cleanest for DOM state. `expect.poll` is best for non-DOM state (API calls, database).', check:'`expect.poll`: for non-DOM state (API, computed values). `waitForSelector`: DOM element state. `expect(locator).toBeVisible()`: cleanest for DOM visibility.' },
    { id:25, level:3, title:'Multiple Tab Assertions', scenario:'A link opens a new tab. Verify the new tab has the correct URL and title.', objective:'`const [newPage] = await Promise.all([context.waitForEvent("page"),page.click("a[target=_blank]")])`. `expect(newPage).toHaveURL(/expected/)`. `expect(newPage).toHaveTitle("Expected Title")`.', constraints:'New tab assertion. URL and title.', expectedOutput:'New tab URL matches. Title matches. Main page unchanged.', check:'`newPage` is a Page object. All page assertions work: `toHaveURL`, `toHaveTitle`, `locator` assertions. `await newPage.waitForLoadState()` if content is not yet loaded.' },
    { id:26, level:3, title:'Assert Network Requests', scenario:'Clicking a button must trigger a specific API call. Verify it was made.', objective:'`const requestPromise = page.waitForRequest(req=>req.url().includes("/api/checkout")&&req.method()==="POST")`. Click checkout. `const request = await requestPromise`. `expect(request.postDataJSON()).toMatchObject({productId:123})`.', constraints:'waitForRequest before action. Inspect request body.', expectedOutput:'Checkout click triggers POST /api/checkout. Body has productId:123.', check:'`page.waitForRequest(predicate)`: resolves with the matching Request object. `request.postDataJSON()`: parses request body as JSON. `request.headers()`: request headers.' },
    { id:27, level:3, title:'Assert Cookies', scenario:'After login, verify the auth cookie is set correctly.', objective:'`const cookies = await context.cookies()`. `const authCookie = cookies.find(c=>c.name==="session")`. `expect(authCookie).toBeDefined()`. `expect(authCookie.httpOnly).toBe(true)`. `expect(authCookie.secure).toBe(true)`.', constraints:'Read cookies. Find by name. Assert properties.', expectedOutput:'Session cookie exists. It is httpOnly and secure.', check:'`context.cookies([url])`: all cookies for the context. Cookie properties: name, value, domain, path, expires, httpOnly, secure, sameSite. Security assertions: httpOnly, secure.' },
    { id:28, level:3, title:'Assert Local Storage', scenario:'After a settings change, verify the preference is persisted in localStorage.', objective:'`const theme = await page.evaluate(()=>localStorage.getItem("theme"))`. `expect(theme).toBe("dark")`. Or clear: `page.evaluate(()=>localStorage.clear())`.', constraints:'Read localStorage via evaluate. Assert value.', expectedOutput:'localStorage.theme is "dark" after enabling dark mode.', check:'`page.evaluate`: runs in the browser context. `localStorage.getItem`, `setItem`, `removeItem`, `clear`. localStorage persists within a browser context session.' },
    { id:29, level:3, title:'Performance Assertions', scenario:'A page must load within performance budgets.', objective:'`const metrics = await page.evaluate(()=>JSON.parse(JSON.stringify(window.performance.timing)))`. Calculate and assert: FCP < 2000ms, DCL < 1500ms, load < 3000ms.', constraints:'performance.timing. Three metric assertions.', expectedOutput:'FCP: 800ms (< 2000: pass). DCL: 1200ms (< 1500: pass). Load: 2400ms (< 3000: pass).', check:'`FCP = timing.domContentLoadedEventEnd - timing.navigationStart`. Not FCP (First Contentful Paint) — that requires PerformanceObserver. This is DOMContentLoaded timing.' },
    { id:30, level:3, title:'Grouped Assertions with test.step', scenario:'Organize related assertions into named groups for better reporting.', objective:'`await test.step("verify product details",async()=>{ expect(title).toHaveText(...); expect(price).toHaveText(...); expect(img).toBeVisible(); })`. Steps appear in the HTML report.', constraints:'Three assertions per step. Two steps total.', expectedOutput:'HTML report shows: "verify product details" → pass/fail. "verify cart state" → pass/fail.', check:'`test.step(name,fn)`: groups test steps. Steps are visible in the HTML report and trace. Steps can be nested. Great for organizing long tests.' },
    { id:31, level:4, title:'Snapshot-Based API Testing', scenario:'All API endpoints must not regress between deployments.', objective:'For each endpoint: make the request, save the response as a snapshot. On subsequent runs: compare. Use `--update-snapshots` when intentional changes are made.', constraints:'10 endpoints. Snapshot per endpoint. Update workflow.', expectedOutput:'Snapshot mismatches catch unintended API changes. `--update-snapshots` updates for intentional changes.', check:'`toMatchSnapshot("endpoint-name.json")`: snapshot stored in `__snapshots__`. Compare JSON structure. Dynamic fields (timestamps, IDs): mask or normalize before snapshot.' },
    { id:32, level:4, title:'Cross-Browser Assertion Differences', scenario:'A date formatting assertion fails on Firefox because the format differs.', objective:'Detect browser-specific differences in assertions. Use `browserName` fixture to have conditional expected values. Or normalize before assertion.', constraints:'browserName fixture. Conditional expected values. Or normalization.', expectedOutput:'Chromium: "Jan 15, 2024". Firefox: "January 15, 2024". Conditional assertion handles both.', check:'`const expected = browserName==="chromium" ? "Jan 15, 2024" : "January 15, 2024"`. Or normalize: `text.replace(/January/,"Jan")` before asserting.' },
    { id:33, level:4, title:'Database State Assertions', scenario:'After a form submission, verify the data was saved to the database.', objective:'Submit form. Then use the `request` fixture to call `GET /api/users/1`. Assert the API response matches the submitted data.', constraints:'Form submit. API call to verify. Assert response matches form data.', expectedOutput:'Submitted email "test@example.com". GET /api/users/1 → {email:"test@example.com"}. Match.', check:'Testing the full stack: UI action → API → database. The API call verifies the data was actually persisted. UI-only verification only tests the front-end state.' },
    { id:34, level:4, title:'Flaky Assertion Detection', scenario:'An assertion sometimes passes and sometimes fails. Identify if it\'s a timing issue.', objective:'Run the assertion 10 times in a loop. Count passes and failures. If inconsistent, it\'s flaky. Fix: add proper wait condition before the assertion.', constraints:'Loop 10 times. Count results. Identify flakiness.', expectedOutput:'5/10 passes: flaky (add waitForSelector). 10/10 passes: stable. 0/10 passes: consistently failing.', check:'`let passes=0; for(let i=0;i<10;i++){try{await expect(loc).toHaveText(...)；passes++;}catch{}}`. Flaky: add `await expect(loc).toBeVisible()` before the assertion.' },
    { id:35, level:4, title:'Assert Redirect Chains', scenario:'A URL shortener redirects through multiple hops. Verify the full redirect chain.', objective:'Intercept all responses: `page.on("response",res=>log(res.status(),res.url()))`. Navigate to the short URL. Log and assert: 301 → 302 → 200 (final destination).', constraints:'Response event listener. Log all. Assert chain.', expectedOutput:'Response log: [{status:301,url:"/s/abc"},{status:302,url:"/intermediate"},{status:200,url:"/final"}].', check:'`page.on("response",res=>{if([301,302,303,307,308].includes(res.status())) log(res)})`. Playwright follows redirects automatically, but the events still fire.' },
    { id:36, level:4, title:'Visual Regression with Masking', scenario:'A dashboard has live charts with random data. Visual regression must ignore the chart area.', objective:'Mask the chart: `toHaveScreenshot({mask:[page.locator(".chart")]})`. The masked area shows a solid color box. Compare only the static UI elements.', constraints:'Multiple masks. Verify static vs dynamic separation.', expectedOutput:'Chart area masked. Layout, navigation, and text compared. Changes to layout detected. Chart changes ignored.', check:'Combine with `maxDiffPixels` for minor acceptable differences. `maskColor:"rgba(0,0,0,0)"` for transparent masking.' },
    { id:37, level:4, title:'toHaveScreenshot With Animation', scenario:'A page with CSS animations causes visual regression failures because screenshots capture mid-animation state.', objective:'Wait for animations to complete before screenshot: `await page.evaluate(()=>document.getAnimations().forEach(a=>a.finish()))`. Then take the screenshot.', constraints:'Finish all animations. Then screenshot.', expectedOutput:'Screenshot always captures the final animation state. No mid-animation differences.', check:'`document.getAnimations()`: all active CSS animations and transitions. `.finish()`: jumps to end state. Alternative: `page.clock.fastForward(ms)` to advance time past the animation.' },
    { id:38, level:4, title:'Assertion in Concurrent Tests', scenario:'Concurrent tests must not interfere with each other\'s assertions.', objective:'Run two tests in parallel. Each creates its own user. Each verifies its own data. Show that `expect` assertions are scoped to the test that created the locator.', constraints:'Parallel tests. Independent data. No cross-contamination.', expectedOutput:'Test 1 creates user1, verifies user1 data. Test 2 creates user2, verifies user2 data. No cross-interference.', check:'Each test gets its own Page and BrowserContext. Assertions are scoped to the page. No global state in assertions. Test data must be unique (use timestamps or UUIDs).' },
    { id:39, level:4, title:'Chained Assertion Pipeline', scenario:'A complex object must pass a chain of assertions, where each narrows the expected state.', objective:'Build a fluent assertion chain: `assertUser(user).hasName("Alice").hasEmail("alice@example.com").isActive().hasRole("admin")`. Each method calls `expect` internally.', constraints:'Fluent builder pattern. Assertions per method. Throw on first failure.', expectedOutput:'`assertUser(user).hasName("Alice")` fails if name is not "Alice". Chain stops at first failure.', check:'`class UserAssertion { constructor(user){this.user=user;} hasName(n){expect(this.user.name).toBe(n);return this;} ... }`. Return `this` for chaining.' },
    { id:40, level:4, title:'toHaveAccessibilityTree', scenario:'A modal must have the correct ARIA structure for screen readers.', objective:'`await page.accessibility.snapshot({root:modal})`. Assert the tree: modal has role="dialog", title matches, contains button with name="Close".', constraints:'accessibility.snapshot with root. Tree structure assertion.', expectedOutput:'`snapshot.role === "dialog"`. `snapshot.name === "Settings"`. `snapshot.children.find(c=>c.role==="button"&&c.name==="Close")` exists.', check:'`accessibility.snapshot({root:locator})`: snapshot of the subtree rooted at the element. Useful for verifying ARIA structure of complex widgets.' },
    { id:41, level:5, title:'Assertion Framework Extension', scenario:'Build a domain-specific assertion framework for an e-commerce application.', objective:'Build: `assertProduct`, `assertCart`, `assertOrder`, `assertUser` — each with domain-specific methods. Integrate with `expect.extend` for Playwright-native syntax.', constraints:'Four domain assertors. Each with 5+ methods. expect.extend integration.', expectedOutput:'`expect(productLocator).toBeInStock()`. `expect(cartLocator).toHaveItemCount(3)`. All work natively with Playwright assertions.', check:'`expect.extend({async toBeInStock(locator){const badge=locator.getByTestId("stock"); return {pass:await badge.toHaveText(/in stock/i),message:()=>"Expected product to be in stock"}}})`. ' },
    { id:42, level:5, title:'Probabilistic Assertion', scenario:'A flaky network sometimes adds 50-200ms. Assertion must handle the range.', objective:'`expect(responseTime).toBeGreaterThan(50)`. `expect(responseTime).toBeLessThan(500)`. Or use `toBeCloseTo(150,50)` — custom matcher for "within 50ms of 150".', constraints:'Range assertion. Custom toBeCloseTo with tolerance.', expectedOutput:'Response time in 50-500ms: both assertions pass. Outside range: fail.', check:'Custom: `expect.extend({toBeCloseTo(received,target,tolerance){const pass=Math.abs(received-target)<=tolerance; return {pass,message:()=>`Expected ${received} to be within ${tolerance} of ${target}`}}})`. ' },
    { id:43, level:5, title:'Structural Assertion System', scenario:'A complex API response with nested objects must be structurally validated.', objective:'Build `assertStructure(actual, schema)` that validates: required fields exist, types match, nested objects validated recursively, arrays have correct element types.', constraints:'Recursive validation. Type checking. Required vs optional fields.', expectedOutput:'Missing field: error. Wrong type: error. All correct: pass.', check:'Schema: `{id:{type:"number",required:true},name:{type:"string"},items:{type:"array",items:{type:"string"}}}`. Recursive: for each key in schema, validate the actual value.' },
    { id:44, level:5, title:'Continuous Assertion Monitoring', scenario:'During a long-running test, continuously assert an invariant holds (e.g., no error messages appear).', objective:'While executing other actions, continuously check: `await expect(errorBanner).not.toBeVisible()`. Use `expect.poll` or a background loop.', constraints:'Background assertion. Does not block main test flow. Reports if condition violated.', expectedOutput:'Error banner appears at step 7: "Invariant violated at step 7: Error banner became visible".', check:'Background loop: `const monitor = setInterval(async()=>{if(await errorBanner.isVisible()) fail("error appeared");},500)`. Cleanup in afterEach: `clearInterval(monitor)`.' },
    { id:45, level:5, title:'Regression Test Builder', scenario:'On each PR, automatically generate assertions from the current page state to create regression tests.', objective:'`captureBaseline(page)` — records text content of all visible elements, URLs, and screenshots. `generateRegression(baseline)` — outputs a Playwright test file that asserts each baseline value.', constraints:'Baseline capture. Test generation. Runnable generated test.', expectedOutput:'Capture baseline. Generated test file has: toHaveText for each visible element, toHaveURL for navigation, toHaveScreenshot for visuals.', check:'Capture: `page.$$eval("*",els=>els.filter(el=>el.offsetParent).map(el=>({selector:el.dataset.testid,text:el.textContent})))`. Generate: template literal test file.' },
    { id:46, level:5, title:'Assertion Time Travel', scenario:'A test must assert that a specific state existed at a particular time during the test execution.', objective:'Record state after each action. Assert that state recorded at step 3 was `{count:2}`. Use Playwright trace to replay and verify historical state.', constraints:'State recording after each action. Historical assertion.', expectedOutput:'State log: [{step:1,state:{count:0}},{step:2,state:{count:1}},...]. Assert step 3 state.', check:'State log: push state after each action. Assert: `expect(stateLog[2].state.count).toBe(2)`. Trace: use Playwright trace to view DOM at any step visually.' },
    { id:47, level:5, title:'Invariant Testing System', scenario:'Critical business rules must never be violated, regardless of the test flow.', objective:'Build `InvariantChecker` that registers invariants (assertions that must always hold). Before each test action, check all invariants. Report violations immediately.', constraints:'Invariant registry. Pre-action check. Immediate failure on violation.', expectedOutput:'Invariant: "cart total must equal sum of item prices". Any action that violates this → immediate failure.', check:'After each action: `for(const inv of invariants) { await inv.check(page); }`. Invariant: `async(page)=>{const total=await getTotal(); const sum=await getSum(); expect(total).toBeCloseTo(sum,2)}`.' },
    { id:48, level:5, title:'Multi-Layer Assertion Strategy', scenario:'A test must verify: UI layer, API layer, and database layer all agree.', objective:'After a purchase: (1) UI: confirm page shows "Order #123". (2) API: `GET /api/orders/123` returns 200 with correct data. (3) DB: `SELECT * FROM orders WHERE id=123` returns a row.', constraints:'Three layers. All must pass. Report which layer failed.', expectedOutput:'All three pass: test passes. UI correct but API wrong: "API layer failed: expected order 123 not found".', check:'Layer assertions: `await test.step("UI layer",()=>{...}). await test.step("API layer",()=>{...}). await test.step("DB layer",()=>{...})`. Steps appear in report.' },
    { id:49, level:5, title:'Assertion Coverage Analyzer', scenario:'Identify which UI elements are never asserted in the test suite.', objective:'Instrument the Page to track all `locator` calls that had assertions. After the suite runs, compare against all interactive elements on the pages. Report uncovered elements.', constraints:'Track assertion calls. Compare to all elements. Report gaps.', expectedOutput:'30% of interactive elements (buttons, inputs) are never asserted. Report: {element, page, reason}.', check:'Intercept `expect(locator)` calls: proxy the expect function, log the locator. After suite: crawl app, enumerate interactive elements, compare. Gap = element never in assertion log.' },
    { id:50, level:5, title:'Full Assertion Framework', scenario:'Build a complete, production-grade assertion framework for a large application.', objective:'Build: (1) Domain matchers, (2) Structural validation, (3) Performance assertions, (4) Accessibility assertions, (5) Visual regression, (6) API contract validation, (7) Cross-layer verification.', constraints:'All 7 components. Documented. Importable npm package.', expectedOutput:'`import {expectProduct,expectAPI,expectA11y} from "@company/playwright-assertions"`. All matchers integrated with Playwright\'s expect.', check:'Package structure: matchers/ (domain), validators/ (structural), reporters/ (custom output). `setup.ts` calls `expect.extend(allMatchers)`. Export all from index.ts.' },
  ],

  config: [
    { id:1, level:1, title:'Basic Config Structure', scenario:'A team sets up playwright.config.ts for a new project.', objective:'Create a config with: `testDir`, `timeout`, `retries`, `use.baseURL`, `use.screenshot`, `use.video`, `use.trace`. Explain each option.', constraints:'Seven key options. Explain each.', expectedOutput:'Config runs tests, uses the base URL, and captures screenshots on failure.', check:'`testDir:"./tests"`. `timeout:30000`. `retries:0`. `use.baseURL:"http://localhost:3000"`. `use.screenshot:"only-on-failure"`. `use.video:"retain-on-failure"`. `use.trace:"on-first-retry"`.' },
    { id:2, level:1, title:'Test Directory Configuration', scenario:'Tests are organized in different directories by feature.', objective:'Set `testDir:"./e2e"`. Set `testMatch:["**/*.spec.ts","**/*.test.ts"]`. Set `testIgnore:["**/node_modules/**"]`. Run and verify only matching files are picked up.', constraints:'testDir. testMatch. testIgnore.', expectedOutput:'Only .spec.ts and .test.ts in ./e2e/ are run. node_modules ignored.', check:'`testMatch`: glob patterns. `testIgnore`: patterns to exclude. `testDir`: root directory for test discovery.' },
    { id:3, level:1, title:'Browser Projects', scenario:'Tests must run on three browsers.', objective:'Configure `projects`: chromium, firefox, webkit. Each project uses `devices["Desktop Chrome/Firefox/Safari"]`. Run and observe 3x test count.', constraints:'Three browser projects. devices import.', expectedOutput:'`npx playwright test` shows 3x the single-browser count. Each labeled with browser name.', check:'`import {defineConfig,devices} from "@playwright/test"`. Projects: `[{name:"cr",use:{...devices["Desktop Chrome"]}},...]`. Test count = specs × projects.' },
    { id:4, level:1, title:'Reporter Configuration', scenario:'CI needs JUnit XML output. Development needs a list view.', objective:'Configure reporters: `[["list"],["junit",{outputFile:"junit.xml"}],["html",{open:"never"}]]`. Run and verify all three outputs.', constraints:'Three reporters. Verify each output.', expectedOutput:'Terminal: list format. junit.xml created. playwright-report/ created.', check:'Array of reporters. Each is `[name]` or `[name,options]`. Built-in: list,dot,line,html,json,junit,blob. `open:"never"` prevents auto-opening the HTML report.' },
    { id:5, level:1, title:'Test Timeouts', scenario:'The default 30s timeout is too long for some fast tests and too short for some slow ones.', objective:'Set global `timeout:10000`. Override in describe: `test.describe.configure({timeout:60000})`. Override per-test: `test("slow test",{timeout:60000},async({page})=>{...})`.', constraints:'Global timeout. describe-level. Per-test.', expectedOutput:'Global: 10s. Describe: 60s for all tests in that describe. Per-test: 60s for just that test.', check:'Priority: per-test > describe.configure > global config. `timeout:0` disables timeout. `use.actionTimeout` for individual action timeout.' },
    { id:6, level:1, title:'Retry Configuration', scenario:'CI tests flake occasionally. Configure retries to reduce false failures.', objective:'Set `retries: process.env.CI ? 2 : 0`. On CI: tests retry twice. Locally: no retries. Verify retry count in report.', constraints:'CI-conditional retries. Observe retry behavior.', expectedOutput:'CI: failed test retried twice. Report shows retry count. Locally: no retries.', check:'`retries:2`: retry 2 times (total 3 attempts). `process.env.CI`: set by most CI systems. `test.describe.configure({retries:1})`: override per describe.' },
    { id:7, level:1, title:'Workers Configuration', scenario:'The test suite is slow. Speed it up with parallel workers.', objective:'Set `workers: process.env.CI ? 2 : "50%"`. On CI: 2 workers. Locally: 50% of available CPUs. Observe parallel execution.', constraints:'CI-conditional workers. Percentage format.', expectedOutput:'CI: 2 parallel workers. Local: half of CPUs. Tests run simultaneously.', check:'`workers:"50%"`: half the available CPU cores. `workers:4`: fixed count. `fullyParallel:true`: also parallelizes within files. Default: 1 worker per file.' },
    { id:8, level:1, title:'Base URL Configuration', scenario:'Tests should work against dev, staging, and prod by changing only the BASE_URL env var.', objective:'`use.baseURL: process.env.BASE_URL || "http://localhost:3000"`. `page.goto("/login")` becomes relative. Run with `BASE_URL=https://staging.example.com`.', constraints:'baseURL with env var. Relative goto. Env var override.', expectedOutput:'`page.goto("/login")` → navigates to `BASE_URL + /login`. Change env var to change target.', check:'`baseURL` makes `page.goto(path)` relative. `page.goto("http://other.com")` is still absolute. Useful: all tests use relative paths, env controls the environment.' },
    { id:9, level:1, title:'Screenshot and Video Config', scenario:'CI must save screenshots on failure and videos for retried tests.', objective:'`use.screenshot:"only-on-failure"`. `use.video:"retain-on-failure"`. `use.videosPath:"test-videos/"`. Run a failing test and locate the artifacts.', constraints:'Both options. Custom video path. Locate artifacts.', expectedOutput:'Failing test: screenshot saved. Retried test that fails: video saved. Both in HTML report.', check:'Screenshot options: "off","on","only-on-failure","retain-on-failure". Video options: "off","on","retain-on-failure","on-first-retry". Default paths: test-results/.' },
    { id:10, level:1, title:'Trace Configuration', scenario:'Debugging CI failures requires a full action trace.', objective:'`use.trace:"on-first-retry"`. Trigger a retry. Open trace: `npx playwright show-trace`. Explain trace contents.', constraints:'Trace on retry. Show trace. Explain timeline.', expectedOutput:'Trace opens showing: action timeline, before/after screenshots, network requests, console logs.', check:'Trace options: "off","on","retain-on-failure","on-first-retry","on-all-retries". The trace is a `.zip` file containing `trace.json` and screenshots.' },
    { id:11, level:2, title:'Device Emulation Config', scenario:'A mobile-first app must be tested on iPhone and Pixel.', objective:'Add projects: `{name:"iPhone",use:{...devices["iPhone 14"]}}`, `{name:"Pixel",use:{...devices["Pixel 7"]}}`. Write a test and run on both.', constraints:'Two mobile projects. Verify viewport and userAgent.', expectedOutput:'iPhone: viewport 390×844, mobile UA. Pixel: viewport 412×915, mobile UA.', check:'`devices["iPhone 14"]`: `{viewport:{width:390,height:844},userAgent:"...",isMobile:true,hasTouch:true,deviceScaleFactor:3}`. Access with `import {devices} from "@playwright/test"`.' },
    { id:12, level:2, title:'Global Setup and Teardown', scenario:'Tests need a seeded database before the suite and cleanup after.', objective:'Create `global-setup.ts` and `global-teardown.ts`. Register in config. Verify they run once per suite (not per test).', constraints:'Both files. Register. Log execution order.', expectedOutput:'"global setup" once at start. All tests run. "global teardown" once at end.', check:'`globalSetup:"./global-setup"`. `globalTeardown:"./global-teardown"`. Run before all workers start / after all workers finish. Different from `beforeAll` (per worker).' },
    { id:13, level:2, title:'Web Server Config', scenario:'Tests should auto-start the dev server before running.', objective:'`webServer:{command:"npm run dev",url:"http://localhost:3000",reuseExistingServer:!process.env.CI}`. Tests start only after the server responds.', constraints:'webServer config. reuseExistingServer. Timeout option.', expectedOutput:'Server starts before tests. Tests run. Server stops after.', check:'`url`: Playwright polls this URL until it returns 200. `reuseExistingServer:true`: skips start if already running. `timeout:120000`: max wait for server start.' },
    { id:14, level:2, title:'Project Dependencies', scenario:'A "setup" project creates auth state. Main tests depend on it.', objective:'`projects:[{name:"setup",testMatch:"**/setup/*.ts"},{name:"tests",dependencies:["setup"],use:{storageState:"auth.json"}}]`. Run and observe setup runs first.', constraints:'Setup project. Main project with dependency. storageState.', expectedOutput:'Setup project runs, creates auth.json. Main tests run with auth already loaded.', check:'`dependencies:["setup"]`: main project waits for all "setup" project tests to complete first. Combined with `storageState` for pre-authenticated tests.' },
    { id:15, level:2, title:'Output Directory Config', scenario:'All test artifacts must be saved in a specific directory.', objective:'`outputDir:"./test-results"`. `use.videosPath:"./test-results/videos"`. `reporter:[["html",{outputFolder:"./test-results/report"}]]`. Run and verify all artifacts are in the correct directory.', constraints:'outputDir. videosPath. report outputFolder.', expectedOutput:'All artifacts in ./test-results/. Report in ./test-results/report/. Videos in ./test-results/videos/.', check:'`outputDir`: where individual test attachments go. Separate from reporter output. Clean between runs with `npx playwright test --clean-output`.' },
    { id:16, level:2, title:'Custom Fixtures in Config', scenario:'A base URL and authentication token needed by all tests should be in fixtures.', objective:'Define fixtures in a fixtures file. Import the extended `test` in all test files. Show how config `use` properties integrate with fixtures.', constraints:'Custom fixture. Extended test. Config integration.', expectedOutput:'All tests automatically have access to the `authToken` fixture without importing it explicitly.', check:'Custom `test` from a fixtures file is the test function for all tests. Import it instead of `@playwright/test`. The extended test includes all custom fixtures.' },
    { id:17, level:2, title:'Metadata in Config', scenario:'Test reports should include project name, version, and environment metadata.', objective:'Add custom metadata: in the config or via a custom reporter that reads from the config. Show metadata in the HTML report.', constraints:'Custom metadata. Custom reporter or report annotation.', expectedOutput:'HTML report shows: "Project: My App v2.1.3 | Environment: staging".', check:'`metadata:{appVersion:"2.1.3",environment:"staging"}` in config. Custom reporter: reads `config.metadata` in `onBegin(config,suite)` and includes in the report output.' },
    { id:18, level:2, title:'Grep and GrepInvert in Config', scenario:'The smoke test project should only run @smoke tagged tests.', objective:'`projects:[{name:"smoke",grep:/@smoke/},{name:"full",grepInvert:/@smoke/}]`. Smoke project runs only tagged tests. Full project runs all others.', constraints:'Two projects. grep and grepInvert.', expectedOutput:'Smoke project: only @smoke tests. Full project: all tests without @smoke tag.', check:'`grep:/@smoke/` in a project applies globally to all tests in that project. Combined with `grepInvert` in another project: separates smoke from full suite.' },
    { id:19, level:2, title:'Expect Config', scenario:'The default assertion timeout of 5s is too short for slow staging environments.', objective:'`expect:{timeout:10000}` in config. All assertions wait up to 10s. Override per assertion with `{timeout:2000}` for fast assertions.', constraints:'Global expect timeout. Per-assertion override.', expectedOutput:'All assertions timeout after 10s by default. Fast assertion overridden to 2s.', check:'`expect.timeout` in config sets the default for all `expect(locator).toBe*()` calls. Does not affect `page.waitForSelector` (that uses `page.waitForTimeout`).' },
    { id:20, level:2, title:'Forbid Only in CI', scenario:'A developer accidentally committed `test.only`. CI should fail immediately.', objective:'`forbidOnly: !!process.env.CI`. When `CI=true` and a test has `.only`, the run fails immediately with an error message.', constraints:'forbidOnly config. CI env var. Verify failure message.', expectedOutput:'CI with `test.only` in code: immediate failure with "forbidOnly found: [file:line]". Locally: `test.only` works normally.', check:'`forbidOnly:true`: run fails if any `test.only` or `describe.only` is found. Standard practice to prevent accidentally running only one test in CI.' },
    { id:21, level:3, title:'Multi-Environment Config', scenario:'The same test suite runs against dev, staging, and prod with different configs.', objective:'Create `playwright.dev.config.ts`, `playwright.staging.config.ts`, `playwright.prod.config.ts`. Each extends a base config and overrides env-specific values.', constraints:'Base config. Three env configs. Run specific: --config flag.', expectedOutput:'`npx playwright test --config=playwright.staging.config.ts` runs against staging URL with staging auth.', check:'Base config: shared options. Env config: `import baseConfig from "./playwright.config"; export default {...baseConfig,use:{...baseConfig.use,baseURL:STAGING_URL}}`.' },
    { id:22, level:3, title:'Dynamic Config Generation', scenario:'A config must dynamically read from a remote config service to get environment settings.', objective:'`global-setup.ts` fetches config from API: `const cfg = await fetchConfig()`. Writes to `config.json`. `playwright.config.ts` reads `config.json` synchronously.', constraints:'Async setup writes config. Sync config reads it. Config used in test.', expectedOutput:'Config fetched from API. Tests use the fetched baseURL.', check:'`globalSetup` can do async work before the config is used by tests. Write to a JSON file. Config reads it: `const {baseURL}=require("./config.json")`.' },
    { id:23, level:3, title:'Config for Microservices Testing', scenario:'An e-commerce app has 5 microservices, each with its own tests. One config orchestrates all.', objective:'One root `playwright.config.ts` defines 5 projects, each with a different `testDir` pointing to a service\'s tests. Run all: `npx playwright test`. Run one: `--project=checkout`.', constraints:'Five projects. Different testDirs. Run all and single.', expectedOutput:'Root config runs tests for all 5 services. `--project=checkout` runs only checkout service tests.', check:'Each project: `{name:"checkout",testDir:"./services/checkout/e2e",use:{baseURL:"http://checkout:3003"}}`. Separate base URLs per service.' },
    { id:24, level:3, title:'Config Validation', scenario:'A misconfigured playwright.config.ts causes confusing errors at runtime. Validate the config early.', objective:'Build a `validateConfig(config)` function that checks: required fields present, valid browser names in projects, valid paths exist. Run in global setup.', constraints:'Validation function. Check required fields, browser names, paths.', expectedOutput:'Missing `testDir`: error at startup. Invalid browser: error at startup. Config errors caught early.', check:'Valid browser names: "chromium","firefox","webkit". Check: `Object.keys(config.use?.browserName||{}).filter(...)`. Path check: `fs.existsSync(config.testDir)`.' },
    { id:25, level:3, title:'Config for Visual Regression Baseline', scenario:'The visual regression baseline changes per branch. Configure baselines per environment.', objective:'`toHaveScreenshot({snapshotPath:"baselines/"+process.env.BRANCH})`. Different branches use different baseline directories. Update baselines: `--update-snapshots`.', constraints:'BRANCH-dependent snapshot path. Update workflow.', expectedOutput:'Feature branch: uses its own baseline directory. main: uses main baseline.', check:'`snapshotPathTemplate: "{snapshotDir}/{testFilePath}/{arg}-{projectName}-{platform}{ext}"`. Customize to include branch: `{snapshotDir}/{BRANCH}/{testFileName}/{arg}{ext}`.' },
    { id:26, level:3, title:'Config for Performance Testing', scenario:'A performance test project runs with specific settings to measure page load times accurately.', objective:'Create a "performance" project with: `{retries:0, workers:1, use:{video:"off",screenshot:"off",trace:"off"}}`. Disabling all artifacts reduces measurement noise.', constraints:'Performance project. All artifacts off. Serial execution.', expectedOutput:'Performance tests run with no overhead from video/screenshot/trace. Timing measurements are accurate.', check:'`workers:1`: serial execution for consistent timing. Artifacts off: no overhead. `retries:0`: no retries (a performance test should not retry). Clean environment each time.' },
    { id:27, level:3, title:'Test Tag Configuration', scenario:'Configure tag-based test filtering with projects for smoke, regression, and performance.', objective:'Three projects: smoke (`grep:/@smoke/`), regression (`grepInvert:/@smoke/`), performance (`grep:/@perf/`). Each CI stage runs a different project.', constraints:'Three tagged projects. Different CI stages.', expectedOutput:'Smoke (< 2min): PR gates. Regression (< 30min): merge gates. Performance (< 10min): nightly.', check:'Tags in test names: `test("login @smoke @perf",...)`. `grep` is a regex. `/@smoke|@perf/` matches either tag. Use `test.describe.tags()` API in newer Playwright versions.' },
    { id:28, level:3, title:'Config Inheritance with Defaults', scenario:'All projects share default settings but can override specific ones.', objective:'Set `use.locale:"en-US"` and `use.timezoneId:"America/New_York"` globally. One project overrides: `use.locale:"de-DE"`. Other projects inherit the global defaults.', constraints:'Global use settings. One project override.', expectedOutput:'German project: de-DE locale. All others: en-US. Both use America/New_York timezone (inherited).', check:'Project `use` is merged with global `use`. Deep merge: project value wins for specified keys. Unspecified keys inherit the global value.' },
    { id:29, level:3, title:'Config for API Testing', scenario:'A separate project runs only API tests (no browser).', objective:'`{name:"api",testDir:"./api-tests",use:{baseURL:"http://api.example.com"}}`. API tests use the `request` fixture without creating a browser.', constraints:'API-only project. request fixture. No browser.', expectedOutput:'API project: tests use `request` fixture. No browser launched. Much faster than UI tests.', check:'API tests: `import {test,expect} from "@playwright/test"`. Use `request` fixture only. No `page` fixture = no browser. Great for REST API testing.' },
    { id:30, level:3, title:'Secrets Management in Config', scenario:'API keys and passwords must not be hardcoded in playwright.config.ts.', objective:'Use environment variables: `use.httpCredentials:{username:process.env.API_USER!,password:process.env.API_PASS!}`. Load from `.env` file using `dotenv` in a separate config loader.', constraints:'Env vars for secrets. dotenv loading. Never hardcode.', expectedOutput:'Secrets from env vars. `.env` loaded. Config file has no secrets.', check:'`dotenv` must be loaded before `playwright.config.ts` is evaluated. Add `require("dotenv/config")` at the top. Or use a `global-setup` that loads env vars first.' },
    { id:31, level:4, title:'Config as Code with TypeScript', scenario:'Generate the playwright config programmatically from a YAML/JSON config file.', objective:'Read `test-config.yaml` (list of environments and browser combinations). Generate the `PlaywrightConfig` object from it. Output as `playwright.config.ts`.', constraints:'YAML parsing. Config generation. Type-safe output.', expectedOutput:'YAML with 5 environments × 3 browsers → 15 generated projects. Type-safe config object.', check:'`import {defineConfig,devices} from "@playwright/test"`. `defineConfig()` provides type safety. Generate: `environments.flatMap(env=>browsers.map(b=>({name:env+"-"+b,use:{...devices[b],baseURL:env.url}})))`.' },
    { id:32, level:4, title:'Config for Flakiness Detection', scenario:'Run each test 10 times to detect flakiness. Report any test that fails intermittently.', objective:'`--repeat-each=10` CLI flag or `repeatEach:10` in config. Count failures. A test that fails 1/10 times is flaky.', constraints:'repeatEach. Count pass/fail per test. Identify flaky.', expectedOutput:'Test runs 10 times. 9 passes, 1 fail: marked as flaky in report.', check:'`repeatEach:10` in config or `--repeat-each=10` CLI. Each test runs N times independently. A failing repetition counts as a test failure. Use to catch timing-sensitive bugs.' },
    { id:33, level:4, title:'Config Plugins', scenario:'Build a reusable config plugin that adds retry logic, custom reporters, and environment setup.', objective:'Create `playwrightPlugin({retries,reporter,env})` that returns config additions. Merge into the main config: `{...baseConfig,...plugin({retries:2})}`.', constraints:'Plugin function. Three configurable options. Merge pattern.', expectedOutput:'`plugin({retries:2,reporter:"slack",env:"staging"})` returns config additions. Base config merges them.', check:'Plugin: `(opts)=>({retries:opts.retries,reporter:[[...reporters[opts.reporter]]],use:{baseURL:environments[opts.env]}})`. Merge: spread both objects, deep-merge `use` and `reporter`.' },
    { id:34, level:4, title:'Config for Cross-Region Testing', scenario:'An app has different data per region. Test each region independently.', objective:'Four region projects: `us-east`, `eu-west`, `ap-southeast`, `us-west`. Each uses a different `baseURL` and `storageState` (region-specific auth).', constraints:'Four region projects. Different baseURL and storageState per region.', expectedOutput:'`--project=eu-west` runs tests against the EU endpoint with EU auth state.', check:'Region storageState: generated in global-setup per region (login to each regional endpoint). Config: each project specifies its URL and its storageState file.' },
    { id:35, level:4, title:'Config Linting', scenario:'A misconfigured or deprecated option in playwright.config.ts should be caught by a linter.', objective:'Write a `lintConfig(config)` function that checks: deprecated options (e.g., `testRunner`), conflicting options (e.g., `headless:false` with `workers:8`), missing recommended options.', constraints:'Check deprecated. Check conflicts. Check missing recommended.', expectedOutput:'`workers:8` with `headless:false`: warning "Running many headed workers may cause issues". `retries:0` in CI: warning "Consider retries > 0 in CI".', check:'Lint rules: array of `{check:fn,message,severity:"warn"|"error"}`. Report all warnings and errors. Fail config loading on errors.' },
    { id:36, level:4, title:'Dynamic Worker Count', scenario:'Worker count should scale with the number of test files to avoid over-provisioning.', objective:'In config: `workers: Math.min(await countTestFiles(), os.cpus().length)`. Dynamically count test files and set workers accordingly.', constraints:'Dynamic worker count. File counting. CPU count cap.', expectedOutput:'5 test files, 8 CPUs: workers=5. 20 test files, 8 CPUs: workers=8.', check:'`const files = await glob("**/*.spec.ts",{cwd:testDir}); const workers = Math.min(files.length, os.cpus().length)`. But config is synchronous — calculate in global-setup and set env var.' },
    { id:37, level:4, title:'Config for A/B Test Coverage', scenario:'An A/B test serves two variants. Both must be tested. Config generates two projects.', objective:'`projects: variants.flatMap(v=>[{name:v.name+"_cr",use:{...devices["Desktop Chrome"],...v.setup}},{name:v.name+"_ff",use:{...devices["Desktop Firefox"],...v.setup}}])`. Dynamic project generation.', constraints:'flatMap for project generation. Two browsers per variant.', expectedOutput:'2 variants × 2 browsers = 4 projects. Each variant has its setup applied.', check:'Variant setup: `{extraHTTPHeaders:{"X-Variant":v.id}}` or `storageState` with variant cookie. Dynamic project names: `"variantA_cr"`, `"variantA_ff"`, etc.' },
    { id:38, level:4, title:'Config Hot Reloading', scenario:'During development, config changes should be picked up without restarting the test runner.', objective:'Use `watch` mode: `npx playwright test --ui` or `npx playwright test --watch`. Config changes are detected and the runner restarts.', constraints:'Watch mode. Config change detection. Restart behavior.', expectedOutput:'Edit config: test runner detects change, reloads config, reruns tests with new settings.', check:'`--ui` mode: Playwright UI with live reloading. `--watch` mode: non-interactive live reloading. Config changes: config file is re-evaluated. Some changes require restart.' },
    { id:39, level:4, title:'Config for Monorepo', scenario:'A monorepo has 10 apps each with their own e2e tests. One root config orchestrates all.', objective:'Root config: 10 projects, each with `testDir`, `baseURL`, and a matching setup project. Run all: `npx playwright test`. Run one app: `--project=app-name`.', constraints:'10 projects. Different testDirs. Setup projects.', expectedOutput:'Root run: 10 apps tested in parallel. `--project=billing` tests only the billing app.', check:'Read app list from `apps/*/package.json`. Generate projects dynamically. Setup project per app: `{name:"billing-setup",testMatch:"**/billing/setup.spec.ts"}`. Dependency: billing depends on billing-setup.' },
    { id:40, level:4, title:'Config Audit Trail', scenario:'Track which config options have been changed from defaults and why.', objective:'Build a `ConfigAudit` that compares the current config against Playwright defaults. Report deviations with the reason (from a separate reasons.json file).', constraints:'Default config comparison. Deviation report. Reason documentation.', expectedOutput:'Report: {option:"retries",default:0,actual:2,reason:"CI flakiness reduction"}.', check:'Default config: `{timeout:30000,retries:0,workers:1,...}`. Compare: `Object.keys(defaults).filter(k=>config[k]!==defaults[k]).map(k=>({option:k,...}))`. Reasons: separate JSON.' },
    { id:41, level:5, title:'Config as a Service', scenario:'A central config service provides Playwright config for all teams.', objective:'Build an Express API: `GET /config?team=checkout&env=staging`. Returns a playwright config JSON. Teams include it in their config with `fetch`.', constraints:'Config API. Team and env parameters. JSON response.', expectedOutput:'Checkout team staging config: their testDir, staging baseURL, staging storageState, their reporters.', check:'Config API: `configs[team][env]`. Response: `{use:{baseURL,storageState},projects:[...],reporters:[...]}`. Teams: `const remoteConfig=await fetchConfig();export default {...remoteConfig,...localOverrides}`.' },
    { id:42, level:5, title:'Self-Optimizing Config', scenario:'Config automatically adjusts workers and timeouts based on historical test performance.', objective:'Analyze test duration history (from previous runs). Set `workers` to maximize parallelism without exceeding a target duration. Set `timeout` to p95 of historical duration + 20%.', constraints:'History analysis. Worker optimization. Timeout optimization.', expectedOutput:'History: 5s avg, 12s p95. Timeout: 15s. Workers: 4 (all tests complete in < 2min).', check:'Read history: `sqlite3 test-history.db "SELECT * FROM runs"`. Calculate p95 duration. Set `timeout = p95 * 1.2`. Set `workers = Math.ceil(totalDuration / targetDuration)`.' },
    { id:43, level:5, title:'Config for Chaos Testing', scenario:'A chaos project randomly injects failures (network delays, service errors) during tests.', objective:'Create a "chaos" project with a custom setup that uses `page.route` to randomly delay or fail requests. Chaos rate configurable via env var.', constraints:'Chaos project. route-based failures. Configurable rate.', expectedOutput:'CHAOS_RATE=0.3: 30% of requests delayed or failed. Tests verify app degrades gracefully.', check:'Chaos setup fixture: `test.extend({page:async({page},use)=>{await page.route("**",route=>chaos(route,chaosRate)); await use(page);}})`. chaos: random delay or abort.' },
    { id:44, level:5, title:'Config Version Control Strategy', scenario:'Config changes must be reviewed, tested, and rolled back easily.', objective:'Design a config versioning strategy: separate config from code, version it with git tags, validate before applying, roll back with `git checkout`. Document the workflow.', constraints:'Separation of concerns. Validation before apply. Rollback procedure.', expectedOutput:'Config in separate repository. PR for config changes. Validation CI. Rollback: `git checkout v2.3.1 -- playwright.config.ts`.', check:'Separation: `playwright.config.ts` (structure) vs `test-config.json` (values). Config PR: runs a validation workflow. Rollback: git tag per stable config version.' },
    { id:45, level:5, title:'Config for Compliance Testing', scenario:'A healthcare app must prove HIPAA compliance. Config generates compliance test projects.', objective:'Generate projects for each compliance requirement: `authentication`, `authorization`, `audit_logging`, `encryption`. Each project has specific tags and reporters.', constraints:'Compliance project generation. Specific reporters per project. Tag filtering.', expectedOutput:'Compliance run: 4 projects, each testing specific requirements. Output: audit report per requirement.', check:'Compliance project: `{name:"authentication",grep:/@auth-compliance/,reporter:[["html",{outputFolder:"./compliance/auth"}],["junit",{outputFile:"./compliance/auth/junit.xml"}]]}`. ' },
    { id:46, level:5, title:'Multi-Tenant Config', scenario:'A SaaS product has 50 customer tenants. Each must be tested with tenant-specific config.', objective:'Generate 50 projects (one per tenant) from a tenant list. Each uses the tenant\'s subdomain as baseURL and its auth state file.', constraints:'Dynamic project generation from tenant list. Per-tenant auth state.', expectedOutput:'`--project=tenant-abc` runs tests against `https://abc.saas.com` with abc\'s auth.', check:'Tenant list: from API or JSON file. Global setup: log in to each tenant, save `storageState`. Config: `tenants.map(t=>({name:"tenant-"+t.id,use:{baseURL:"https://"+t.subdomain+".saas.com",storageState:"auth-"+t.id+".json"}}))`. ' },
    { id:47, level:5, title:'Config for Blue-Green Deployment Testing', scenario:'During a blue-green deployment, run tests against both environments and compare results.', objective:'Two projects: `blue` (current prod URL) and `green` (new deployment URL). Run both. Compare results — any test that passes on blue but fails on green is a regression.', constraints:'Two deployment projects. Result comparison. Regression detection.', expectedOutput:'Blue: all pass. Green: 3 failures. Report: "Regressions found in green: [test names]". Block deploy.', check:'Run both projects. Compare JSON reports. `greenFails.filter(t=>!blueFails.includes(t.title))` = regressions. Alert and block deployment if regressions found.' },
    { id:48, level:5, title:'Config Federation', scenario:'Each team owns their Playwright config. A central CI system merges them and runs the full suite.', objective:'Teams publish their config to a registry. CI fetches all configs. Merges projects, reporters, and settings (with conflict resolution). Runs the unified config.', constraints:'Config registry. Merge algorithm. Conflict resolution.', expectedOutput:'5 team configs → 1 merged config. 50 projects. All run in CI.', check:'Merge: projects are additive (union). Reporters: union (deduplicate by type). Conflicting `use` settings: central config wins. `timeout`: take max across configs.' },
    { id:49, level:5, title:'Config-Driven Test Matrix', scenario:'Generate a test matrix from a config: all combinations of (browsers × environments × locales × devices).', objective:'Matrix config: `{browsers:["chromium","firefox"],environments:["dev","staging"],locales:["en-US","de-DE"],devices:["Desktop","Mobile"]}`. Generate all 16 combinations as projects.', constraints:'Cartesian product of all dimensions. 16 projects. Run subsets with --project.', expectedOutput:'16 projects: `chromium-dev-en-Desktop`, `firefox-staging-de-Mobile`, etc. Each runs all tests.', check:'Cartesian product: `browsers.flatMap(b=>environments.flatMap(e=>locales.flatMap(l=>devices.map(d=>({name:b+"-"+e+"-"+l+"-"+d,use:{...}})))))`. 2×2×2×2=16 projects.' },
    { id:50, level:5, title:'Full Config Management System', scenario:'Build a complete configuration management system for a large organization\'s Playwright suites.', objective:'Build: (1) Config schema validation, (2) Environment-aware config, (3) Team-specific overrides, (4) Dynamic project generation, (5) Config auditing, (6) Version control integration, (7) Config API service.', constraints:'All 7 components. Documentation. CI integration.', expectedOutput:'Teams define their config in YAML. Config service validates and serves it. CI fetches and runs. Audit trail tracks all changes.', check:'Core: JSON Schema for validation. Service: Express API with YAML config source. CI: `npx playwright test --config=$(curl config-service/config?team=X)`. Audit: git-based.' },
  ],

  fixtures: [
    { id:1, level:1, title:'Built-in Fixtures', scenario:'A test uses built-in Playwright fixtures.', objective:'Write a test using: `page` (current page), `context` (browser context), `browser` (browser instance), `request` (API context), `browserName` (current browser name).', constraints:'All five built-in fixtures. Log each one\'s type.', expectedOutput:'page: Page object. context: BrowserContext. browser: Browser. request: APIRequestContext. browserName: "chromium".', check:'Built-in fixtures are injected by Playwright based on parameter names. `page`: new page per test. `context`: new context per test. `browser`: shared per worker. `request`: standalone API context.' },
    { id:2, level:1, title:'Custom Fixture Basics', scenario:'A logged-in page must be available to tests without repeating login code.', objective:'`const test = base.extend<{loggedInPage:Page}>({loggedInPage: async({page},use)=>{ await page.goto("/login"); await page.fill("#email","user@example.com"); await page.fill("#password","secret"); await page.click("text=Login"); await use(page); }})`. Use in a test.', constraints:'Extend base test. Async fixture. use() function.', expectedOutput:'Test using `loggedInPage` fixture starts already logged in.', check:'`base.extend<Types>({fixtureName: async({page},use)=>{ setup(); await use(value); teardown(); }})`. The `use(value)` provides the fixture to the test. Code after `use()` is teardown.' },
    { id:3, level:1, title:'Fixture Teardown', scenario:'A fixture that creates a database record must delete it after the test.', objective:'In the fixture: `const user = await createUser()`. `await use(user)`. After use: `await deleteUser(user.id)`. Even if the test fails, teardown runs.', constraints:'Create before use. Delete after use. Teardown always runs.', expectedOutput:'Test runs. After test (pass or fail): user deleted.', check:'Code after `await use(value)` in a fixture is teardown. It ALWAYS runs, even if the test or an earlier fixture fails. Works like `afterEach`.' },
    { id:4, level:1, title:'Fixture Composition', scenario:'A "user page" fixture needs both a "user" fixture and a "page" fixture.', objective:'`user` fixture: creates a test user. `userPage` fixture: needs `user` and `page` as parameters. Navigates to the user\'s profile. `userPage` is a composed fixture.', constraints:'Two fixtures. Composition via parameters. Use in test.', expectedOutput:'`userPage` fixture provides a page navigated to the user\'s profile.', check:'`base.extend({user:async({request},use)=>{...}, userPage:async({page,user},use)=>{await page.goto("/users/"+user.id); await use(page);}})`. Fixtures can depend on other custom fixtures.' },
    { id:5, level:1, title:'Fixture Overriding', scenario:'A test needs to override the default `page` fixture to add a custom base URL.', objective:'`base.extend({page: async({page},use)=>{ await page.goto("/"); await use(page); }})`. The overridden page fixture navigates to "/" before giving it to the test.', constraints:'Override built-in fixture. Extend behavior.', expectedOutput:'Tests using the overridden `page` fixture start at "/" automatically.', check:'Built-in fixtures can be overridden by extending `test` with a fixture of the same name. The original fixture is available as a parameter.' },
    { id:6, level:1, title:'Fixture Scoping', scenario:'A database connection should be created once per worker (not per test) to save time.', objective:'`base.extend({dbConnection: [{scope:"worker"}, async({},use)=>{ const db=await connectDB(); await use(db); await db.close(); }]})`. Show it is created once per worker process.', constraints:'Worker scope. Verify creation count.', expectedOutput:'4 tests in one worker: dbConnection created once. Closed once after all 4 tests.', check:'`{scope:"worker"}`: fixture created once per parallel worker. `{scope:"test"}` (default): once per test. Worker fixtures cannot use test-scoped fixtures like `page`.' },
    { id:7, level:1, title:'Fixture Value Types', scenario:'A fixture can provide any value type: objects, functions, primitives.', objective:'Create fixtures for: a string (`testUserId`), a plain object (`testUser`), an async function (`createUser`). Show each used in a test.', constraints:'String fixture. Object fixture. Function fixture.', expectedOutput:'`testUserId` provides "test-123". `testUser` provides `{id:"test-123",email:"..."}`. `createUser` provides a factory function.', check:'Fixtures can return any value. Primitive: `async({},use)=>use("test-value")`. Object: `use({key:"value"})`. Function: `use(async(name)=>createUser(name))`.' },
    { id:8, level:1, title:'Automatic Fixtures', scenario:'A fixture that should run for every test (like logging) without being explicitly declared.', objective:'`base.extend({autoLog: [async({page},use)=>{ log("test start"); await use(); log("test end"); },{auto:true}]})`. The fixture runs for every test without being in the test parameters.', constraints:'auto:true. Runs without declaration. Log output.', expectedOutput:'"test start" logged before every test. "test end" logged after every test.', check:'`{auto:true}`: fixture runs automatically for every test in the scope. No need to declare it in the test function parameters. Useful for global logging, cleanup, or state verification.' },
    { id:9, level:1, title:'Fixtures File Organization', scenario:'A project has many fixtures. Organize them in separate files.', objective:'Create `fixtures/auth.ts` (auth fixtures), `fixtures/data.ts` (data fixtures). Each exports an extended `test`. Merge: `const test = authTest.extend(dataFixtures)`.', constraints:'Two fixture files. Merge pattern.', expectedOutput:'Tests import the merged `test` and have access to all fixtures from both files.', check:'`const authTest = base.extend(authFixtures)`. `const test = authTest.extend(dataFixtures)`. Export `test` and `expect`. Tests import from the merged fixture file.' },
    { id:10, level:1, title:'Using Fixtures in beforeEach', scenario:'A fixture needs to set up state that isn\'t a fixture itself.', objective:'In `beforeEach({page})=>{ await page.goto("/dashboard") }`. Compare to a fixture that navigates. Show when `beforeEach` is better vs a fixture.', constraints:'beforeEach usage. Fixture usage. When to use each.', expectedOutput:'beforeEach: simpler for one-time setup. Fixture: reusable across tests and files.', check:'`beforeEach`: scoped to the describe block, cannot be reused across files. Fixture: reusable, composable, scoped to the test. Use fixtures for complex, reusable setup.' },
    { id:11, level:2, title:'Auth Fixture with Storage State', scenario:'All tests need a logged-in session. Use storageState to avoid logging in every test.', objective:'Auth fixture: load storageState from file if it exists. If not, log in and save it. Context created with storageState.', constraints:'Check if state file exists. Log in if not. Load if exists.', expectedOutput:'First run: logs in, saves state. Subsequent runs: loads state, skips login. Much faster.', check:'`if(!fs.existsSync("auth.json")){ await login(page); await context.storageState({path:"auth.json"}); }`. Context: `base.extend({context:async({browser},use)=>{ const ctx=await browser.newContext({storageState:"auth.json"}); ...}})`. ' },
    { id:12, level:2, title:'Multi-Role Fixtures', scenario:'Tests for admin, user, and guest roles need separate fixtures.', objective:'Create `adminTest`, `userTest`, `guestTest` — each extended from base with different auth. Compose them: `test = adminTest.extend(userFixtures)` for tests needing both.', constraints:'Three role fixtures. Composition for multi-role tests.', expectedOutput:'Admin test: has admin page. User test: has user page. Composed: has both.', check:'Role fixture: load role-specific storageState. Composed: extend with both. Test: `test("admin sees user",async({adminPage,userPage})=>{...})` has both fixtures.' },
    { id:13, level:2, title:'Database Fixture', scenario:'Each test needs its own database records, cleaned up after.', objective:'Fixture `testDb`: wraps a database client. Creates test data in `beforeEach` logic. Cleans up in teardown. Provides the client.', constraints:'Database client. Test data creation. Cleanup.', expectedOutput:'Test runs with fresh data. After test: data deleted.', check:'`testDb` fixture: `async({},use)=>{ const db=await connect(); const data=await seed(db); await use({db,data}); await cleanup(db,data); await db.close(); }`. Worker scope for the connection.' },
    { id:14, level:2, title:'API Client Fixture', scenario:'Tests that interact with the API need an authenticated client.', objective:'`apiClient` fixture: creates a `request` context with auth headers. Returns helper methods: `getUser(id)`, `createUser(data)`, `deleteUser(id)`.', constraints:'Extended request context. Helper methods. Auth headers.', expectedOutput:'`apiClient.createUser({name:"Alice"})` makes an authenticated POST request.', check:'`async({request},use)=>{ const client=new APIClient(request,authToken); await use(client); }`. APIClient wraps request with auth headers and provides semantic methods.' },
    { id:15, level:2, title:'Page Object Fixture', scenario:'Page Objects should be available as fixtures for clean test code.', objective:'`loginPage` fixture: `async({page},use)=>{ await use(new LoginPage(page)); }`. `dashboardPage` fixture: `async({page},use)=>{ await use(new DashboardPage(page)); }`. Use in tests.', constraints:'Two POM fixtures. Used in test. Clean syntax.', expectedOutput:'`test("login",async({loginPage,dashboardPage})=>{ await loginPage.login(email,password); await expect(dashboardPage.welcomeMessage).toBeVisible(); })`.', check:'POM fixtures: instantiate the Page Object with the `page` fixture. Tests get clean, semantic interfaces. No `new LoginPage(page)` boilerplate in tests.' },
    { id:16, level:2, title:'Mock Server Fixture', scenario:'Tests need an API mock server that starts and stops with the test.', objective:'Fixture `mockServer`: starts a mock HTTP server (using `msw` or `express`). Provides the base URL. Stops the server after the test.', constraints:'Server start in fixture. URL provided. Stop in teardown.', expectedOutput:'Test navigates to the mock server URL. API calls intercepted by mock. Server stopped after.', check:'`async({},use)=>{ const server=await startMockServer(); await use({url:server.url,mock:server.mock}); await server.close(); }`. Worker scope: one server per worker. Test scope: new server per test.' },
    { id:17, level:2, title:'Browser-Specific Fixtures', scenario:'Some fixtures are only needed for Chromium (e.g., CDP session).', objective:'`cdpSession` fixture: `async({page,browserName},use)=>{ if(browserName!=="chromium"){await use(null);return;} const cdp=await page.context().newCDPSession(page); await use(cdp); }`. Use in tests that need CDP.', constraints:'browserName check. Null for non-Chromium. CDP for Chromium.', expectedOutput:'On Chromium: cdpSession is a CDPSession. On Firefox: null. Test skips CDP operations when null.', check:'`if(browserName!=="chromium"){await use(null);return;}`: provides null for non-Chromium browsers. Test guards: `if(!cdpSession) test.skip()` or conditional logic.' },
    { id:18, level:2, title:'Environment Fixture', scenario:'Tests need to know which environment they are running against.', objective:'`environment` fixture: `async({},use)=>{ await use(process.env.ENV||"dev"); }`. Tests use it to conditionally skip or adjust behavior.', constraints:'Env var fixture. Used for conditional skip.', expectedOutput:'`test.skip(environment==="prod","Skip in prod")`. `if(environment==="staging") expect slower timeout.`', check:'Environment fixture provides the current environment name. Tests can skip for certain environments, adjust assertions, or use environment-specific data.' },
    { id:19, level:2, title:'Fixture Timeout Override', scenario:'A slow fixture (DB connection) needs a longer timeout than the default.', objective:'`base.extend({slowFixture: [async({},use)=>{ await slowSetup(); await use(result); },{timeout:30000}]})`. The fixture has its own 30s timeout.', constraints:'Fixture-level timeout. Slow setup.', expectedOutput:'slowFixture setup takes 15s: succeeds (< 30s timeout). Takes 35s: fails with fixture timeout.', check:'`[fixtureFn, {timeout:ms}]`: array form with options. `timeout`: how long the fixture function can run before timing out. Separate from test timeout.' },
    { id:20, level:2, title:'Parameterized Fixtures', scenario:'The same tests must run with two different configurations.', objective:'`base.extend({config: [{scope:"test"}, async({},use)=>{ for(const cfg of configs){await use(cfg);} }]})`. Using `for...of use(value)`: the test runs once for each value.', constraints:'Multiple use() calls. Test runs twice.', expectedOutput:'Test runs twice: once with config A, once with config B. Results separate in report.', check:'Calling `use(value)` multiple times in a fixture causes the test to run once per value. The test title includes the fixture value as a suffix.' },
    { id:21, level:3, title:'Fixture Dependency Graph', scenario:'Multiple fixtures with complex dependencies. Ensure they initialize in the correct order.', objective:'`a` fixture depends on nothing. `b` depends on `a`. `c` depends on `b`. `d` depends on both `a` and `c`. Show initialization order.', constraints:'4 fixtures with dependencies. Log initialization order.', expectedOutput:'Order: a → b → c → d. Teardown order: d → c → b → a (reverse).', check:'Playwright topologically sorts fixtures. Teardown is in reverse initialization order. Fixture code after `use()` runs on teardown (post-test).' },
    { id:22, level:3, title:'Worker Fixture with Shared Resources', scenario:'An in-memory cache should be shared across all tests in a worker to avoid redundant setup.', objective:'Worker-scoped fixture: `{scope:"worker"}`. Initialize once per worker. Tests read from the shared cache.', constraints:'Worker scope. Shared between tests in worker. Closed after all.', expectedOutput:'Cache initialized once at worker start. 10 tests in the worker read from the same cache. Cache closed at worker end.', check:'Worker scope: created when the worker starts, destroyed when it stops. All tests in the worker share the same instance. Must be initialized with `{scope:"worker"}`.' },
    { id:23, level:3, title:'Fixture for Feature Flags', scenario:'Tests must run with specific feature flags enabled or disabled.', objective:'`featureFlags` fixture: reads flags from env or config. Provides a `setFlag(name,value)` method. After the test: reset all flags.', constraints:'Read flags. setFlag method. Reset on teardown.', expectedOutput:'`test("new UI",async({featureFlags})=>{ featureFlags.set("newUI",true); ...verify new UI... })`. After test: flag reset.', check:'Feature flags: stored in localStorage or cookies. Fixture sets them before the test and resets after. `setFlag`: `await page.evaluate(([n,v])=>localStorage.setItem("ff_"+n,v),[name,value])`.' },
    { id:24, level:3, title:'Time Control Fixture', scenario:'Tests involving time-dependent behavior need to control the clock.', objective:'`clock` fixture: wraps `page.clock`. `clock.setDate("2024-12-25")` fixes time for the test. Automatically restores real time after the test.', constraints:'page.clock wrapper. setDate method. Auto-restore.', expectedOutput:'Clock set to Dec 25. UI shows Christmas promotions. After test: clock restored.', check:'`page.clock.setFixedTime(date)` fixes the clock. Fixture wraps this with auto-restore in teardown: `await page.clock.restore()` (or re-navigate to reset).' },
    { id:25, level:3, title:'Network Mock Fixture', scenario:'All tests need specific API endpoints mocked, with per-test overriding capability.', objective:'Base fixture: mocks common endpoints. Per-test: override specific mock with `test.use({mockData:{users:[...]}})`. Fixture reads `mockData` and applies mocks.', constraints:'Base mocks. test.use override. Dynamic mock application.', expectedOutput:'All tests use base mocks. One test overrides the users mock with custom data.', check:'`test.use({mockData:{users:[{id:1,name:"Custom"}]}})`: sets a fixture value for a specific test. Fixture reads it: `async({page,mockData},use)=>{ await applyMocks(page,mockData); }`. ' },
    { id:26, level:3, title:'Fixture for Observability', scenario:'Every test must log its start, end, duration, and any errors.', objective:'`observability` auto fixture: logs test start (`test.info().title`). After test: logs duration and result status (`test.info().status`).', constraints:'auto:true. test.info() usage. Log timing.', expectedOutput:'Every test logs: "start: test name", "end: test name, duration: 1.2s, status: passed".', check:'`test.info()`: available inside fixtures and tests. `.title`: test name. `.status`: "passed","failed","skipped". `.duration`: after the test completes. `{auto:true}`: runs for all tests.' },
    { id:27, level:3, title:'Global Setup as Fixture', scenario:'Global setup logic that should be accessible within tests (not just globally).', objective:'Convert `globalSetup.ts` logic to a worker-scoped fixture. This allows tests to receive the setup result directly, rather than reading from a file.', constraints:'Worker scope. Convert globalSetup to fixture. Tests receive result.', expectedOutput:'Tests get `config` fixture with values from the (formerly global) setup. No file I/O needed.', check:'Tradeoff: `globalSetup` runs once total. Worker fixture runs once per worker. If multiple workers, worker fixture runs multiple times. Use worker fixture for per-worker setup.' },
    { id:28, level:3, title:'Conditional Fixture Setup', scenario:'A fixture should set up a real browser session in CI and use a cached state locally.', objective:'`authFixture`: check `process.env.CI`. In CI: always log in fresh. Locally: use cached `auth.json` if it exists.', constraints:'CI vs local logic. File existence check. Conditional setup.', expectedOutput:'CI: login runs for every worker. Local: login runs once (file created), subsequent runs use cache.', check:'`if(process.env.CI||!fs.existsSync("auth.json")){ ...login... }else{ context=browser.newContext({storageState:"auth.json"}) }`. CI always fresh; local uses cache.' },
    { id:29, level:3, title:'Fixture Isolation Verification', scenario:'Tests must not share state through fixtures. Verify isolation.', objective:'Worker fixture: creates a counter. Each test increments. Verify counter resets between workers. Test fixture: creates a counter. Verify it resets between tests.', constraints:'Worker vs test scope. Counter reset verification.', expectedOutput:'Test-scope counter: 1 for every test. Worker-scope counter: accumulates within worker, resets between workers.', check:'Test isolation: each test gets a fresh test-scoped fixture. Worker isolation: each worker process gets a fresh worker-scoped fixture. Counter test proves this.' },
    { id:30, level:3, title:'Fixture for Test Data Factory', scenario:'Tests need varied, realistic test data that is unique per test.', objective:'`testDataFactory` fixture: wraps Faker.js. Provides `createUser()`, `createProduct()`, `createOrder()`. Each call returns unique data.', constraints:'Faker.js integration. Three factory methods. Unique per call.', expectedOutput:'`createUser()` returns {name:"Alice Jones",email:"ajones_1234@test.com"}. Next call: different unique data.', check:'`faker.person.fullName()`, `faker.internet.email()`. Seed with `faker.seed(Math.random())` for different data per test. Or seed with test index for reproducible data.' },
    { id:31, level:4, title:'Fixture Performance Profiling', scenario:'Slow fixtures are extending test setup time. Profile them.', objective:'Wrap each fixture with timing: log start time, end time, and duration. Identify fixtures taking > 500ms. Add to a slow fixture report.', constraints:'Timing wrapper. 500ms threshold. Report.', expectedOutput:'Fixture report: [{name:"authFixture",ms:1200},{name:"dbFixture",ms:300}]. authFixture flagged as slow.', check:'Wrap fixture in proxy or timing code: `const start=Date.now(); await originalFixture(args,use); const ms=Date.now()-start; if(ms>500) log("slow fixture:",name,ms+"ms")`.' },
    { id:32, level:4, title:'Fixture Retry', scenario:'A fixture that connects to a remote service may fail on first try. Retry it.', objective:'`base.extend({remoteService: async({},use)=>{ let service; for(let i=0;i<3;i++){ try{service=await connect();break;}catch{await sleep(1000);} } await use(service); }})`.', constraints:'Retry loop in fixture. Exponential backoff.', expectedOutput:'Connection fails twice → retries → succeeds on third try. Fixture provides the connected service.', check:'Fixture retry is manual (no built-in retry). Loop with try/catch. After max retries: throw the last error. This aborts the test (and teardown runs).' },
    { id:33, level:4, title:'Fixture Communication', scenario:'Fixtures need to share state with each other that is not known at fixture definition time.', objective:'`messages` fixture: a shared array. Multiple fixtures push messages to it. Test reads all messages from `messages`.', constraints:'Shared state between fixtures. Array passed through.', expectedOutput:'authFixture pushes "logged in". apiFixture pushes "API ready". Test reads: ["logged in","API ready"].', check:'`messages` fixture: `async({},use)=>{ const msgs=[]; await use(msgs); }`. Other fixtures: `async({messages},use)=>{ messages.push("info"); ...await use(result); }`. Test: `messages[0]==="logged in"`.' },
    { id:34, level:4, title:'Fixture for Test Environment Reset', scenario:'Some tests corrupt shared state. Reset the environment after each test.', objective:'Auto fixture: after each test, reset known shared state (localStorage, cookies, server-side data). Verify the next test starts clean.', constraints:'auto:true. Reset after test (in teardown). Verify clean state.', expectedOutput:'After each test: localStorage cleared, auth cookie cleared, server data reset.', check:'Teardown in auto fixture (after use()): `await page.evaluate(()=>localStorage.clear())`. Cookie clear: `await context.clearCookies()`. Server: API call to reset endpoint. ' },
    { id:35, level:4, title:'Fixture Versioning', scenario:'A fixture API change must not break existing tests. Version the fixture.', objective:'Provide `userFixtureV1` (old) and `userFixtureV2` (new, richer data). Both available. Tests migrate from V1 to V2 gradually.', constraints:'Two versions. Both available. Gradual migration.', expectedOutput:'Old tests use userFixtureV1. New tests use userFixtureV2. Both work.', check:'`base.extend({userV1:...,userV2:...})`. Tests import and use the version they need. Deprecate V1 by adding a console.warn in the fixture. Remove after all tests migrated.' },
    { id:36, level:4, title:'Fixture as Middleware', scenario:'All API calls within a test must be authenticated. A middleware fixture intercepts all requests.', objective:'`authMiddleware` auto fixture: intercepts all fetch calls and adds the auth header. Tests make API calls without managing auth explicitly.', constraints:'auto:true. page.route for auth injection.', expectedOutput:'All API calls from the page have the Authorization header. Tests are not aware of auth.', check:'`await page.route("/api/**",async route=>{ const headers={...route.request().headers(),"Authorization":"Bearer "+token}; await route.continue({headers}); })`. Auto fixture for all tests.' },
    { id:37, level:4, title:'Cross-Worker Fixture Coordination', scenario:'Worker 1 must complete a setup task before Worker 2 can start its tests.', objective:'Use a file-based lock (or server-sent events) for cross-worker coordination. Worker 1 acquires lock, does setup, releases. Worker 2 waits for the lock.', constraints:'Cross-worker coordination. File-based or API-based lock.', expectedOutput:'Worker 1: acquires lock, does setup, releases. Worker 2: waits for lock, then starts.', check:'File-based: Worker 1 creates `setup.lock`. Worker 2 polls for `setup.lock` removal. Release: delete the lock file. Race condition: use atomic file operations (`rename`).' },
    { id:38, level:4, title:'Fixture Inheritance', scenario:'A `basePage` fixture sets up common page functionality. Child fixtures extend it.', objective:'`basePage` fixture: sets up language, timezone, dismisses cookie banner. `productPage`, `checkoutPage` extend `basePage` and navigate to their specific URL.', constraints:'Base fixture. Two extending fixtures.', expectedOutput:'productPage: `basePage` setup + navigate to /products. checkoutPage: `basePage` setup + navigate to /checkout.', check:'Chain: `const productTest = test.extend({productPage:async({basePage},use)=>{await basePage.goto("/products"); await use(basePage); }})`. `basePage` is a fixture that returns the page after common setup.' },
    { id:39, level:4, title:'Fixture Context Injection', scenario:'Tests must receive the full context of their execution environment.', objective:'`testContext` fixture: provides `{testTitle, browserName, env, startTime, worker}`. Auto fixture that logs this context for every test.', constraints:'All five properties. auto:true. Log at start.', expectedOutput:'Every test logs: "Running: [title] on [browser] in [env], worker [n], started at [time]".', check:'`async({browserName},use,testInfo)=>{ const ctx={testTitle:testInfo.title,browserName,env:process.env.ENV,worker:testInfo.workerIndex,startTime:Date.now()}; await use(ctx); }`. `testInfo` is the third param.' },
    { id:40, level:4, title:'Fixture Documentation Generator', scenario:'Generate documentation for all custom fixtures from their source code.', objective:'Parse fixture files with AST. For each fixture: extract name, parameters (dependencies), scope, and JSDoc comment. Generate markdown documentation.', constraints:'AST parsing. JSDoc extraction. Markdown output.', expectedOutput:'`authFixture` | Scope: test | Deps: page, request | Description: Provides authenticated page...', check:'Parse with `ts-morph`. Find `extend()` calls. For each fixture in the object literal: extract name, async function params, JSDoc comment above. Generate table row.' },
    { id:41, level:5, title:'Fixture Framework Design', scenario:'Design a composable fixture framework for a complex application domain.', objective:'Build: (1) Core fixtures (auth, api, db), (2) Domain fixtures (user, product, order), (3) Composition helpers (extendAll, merge), (4) Auto-documentation, (5) Scope management.', constraints:'All 5 components. Documentation. Example usage.', expectedOutput:'`import {productTest} from "@company/fixtures"`. `productTest` has: auth, api, db, product fixtures all composed.', check:'Core: base fixtures. Domain: compose core. Helpers: `merge(...tests)` for combining. Documentation: JSDoc + generator. Scope: worker for connections, test for data.' },
    { id:42, level:5, title:'Fixture Hot Reload', scenario:'During development, fixture changes should be picked up without restarting the runner.', objective:'Build a fixture loader that watches the fixtures directory for changes and reloads them. Use dynamic imports with cache busting.', constraints:'File watcher. Dynamic import with cache bust. Reload behavior.', expectedOutput:'Edit authFixture.ts → runner detects change → fixtures reloaded → next test uses new fixture.', check:'Watcher: `fs.watch("./fixtures",async()=>{ await reloadFixtures(); })`. Cache bust: `import("./fixtures/auth.ts?v="+Date.now())`. Limitation: worker-scoped fixtures cannot reload mid-run.' },
    { id:43, level:5, title:'Fixture Testing Framework', scenario:'Write tests for your fixtures to verify they work correctly.', objective:'Build a test harness for fixtures: `testFixture(fixtureName,testFn)`. Runs the fixture in isolation, providing mock dependencies. Asserts fixture output.', constraints:'Fixture test harness. Mock dependencies. Assert output.', expectedOutput:'`testFixture("authFixture",async(value)=>{ expect(value.cookies).toContain("session=..."); })`. authFixture tested in isolation.', check:'Harness: create a minimal Playwright browser. Provide mock dependencies (page, request). Run the fixture function. Assert the provided value. Teardown after test.' },
    { id:44, level:5, title:'Distributed Fixtures', scenario:'Fixtures that require network resources should be distributed across workers efficiently.', objective:'Build a `FixturePool` that assigns resources (auth tokens, DB connections) from a central pool to workers. Worker requests from pool. Returns to pool after use.', constraints:'Central pool server. Worker client. Pool exhaustion handling.', expectedOutput:'10 workers, 5 auth tokens in pool. First 5 workers get tokens immediately. Others queue. On release: queued workers get tokens.', check:'Pool server: Express API, `GET /claim` and `POST /release`. Worker fixture: `GET /claim` to get resource, `POST /release` on teardown. Queue on exhaustion.' },
    { id:45, level:5, title:'Fixture Observability Platform', scenario:'Monitor fixture performance, usage, and failures across the entire test suite.', objective:'Build a fixture monitoring platform: (1) Usage tracking per fixture, (2) Duration histogram, (3) Failure rate, (4) Dependency graph visualization, (5) Real-time dashboard.', constraints:'All 5 components. Dashboard accessible during test run.', expectedOutput:'Dashboard shows: authFixture used 200 times, avg 1.2s, 2 failures. dbFixture: 200 times, avg 0.3s, 0 failures.', check:'Tracking: auto fixture wraps others with timing/error tracking. Metrics: `{count,totalMs,failures}`. Dashboard: Express + WebSocket for real-time. Dependency graph: parse fixture dependencies.' },
    { id:46, level:5, title:'Fixture Code Generation', scenario:'Generate fixture boilerplate from a specification file.', objective:'Spec: `{name:"productFixture",scope:"test",deps:["page","apiClient"],provides:{product:ProductType}}`. Generator: outputs TypeScript fixture code.', constraints:'Spec format. Generator. TypeScript output.', expectedOutput:'Generated `productFixture.ts` with correct types, deps, and boilerplate.', check:'Generator template: `export const ${name}=base.extend<{${name}:${type}}>({${name}:async({${deps.join(",")}},use)=>{ /* TODO */ await use(result); }})`. Fill in from spec.' },
    { id:47, level:5, title:'Fixture Security Audit', scenario:'Fixtures must not expose sensitive data (tokens, passwords) in logs or screenshots.', objective:'Build a `SecureFixture` wrapper that: masks sensitive values in logs, clears sensitive data from the page after teardown, ensures no secrets in screenshots.', constraints:'Log masking. Page cleanup. Screenshot check.', expectedOutput:'Test screenshots: no tokens visible. Logs: secrets replaced with "***". Post-test: page cleared.', check:'Log masking: override `console.log` in the fixture to replace known secret patterns with "***". Page cleanup: `page.evaluate(()=>localStorage.clear())`. Screenshot: run axe-style scan for visible secrets.' },
    { id:48, level:5, title:'Cross-Platform Fixtures', scenario:'The same fixtures must work on Windows, Linux, and macOS in CI.', objective:'Build cross-platform fixtures: path helpers (no hardcoded separators), temp directory (uses `os.tmpdir()`), file comparison (normalizes line endings).', constraints:'path.join for all paths. os.tmpdir(). Line ending normalization.', expectedOutput:'Fixture works on all three platforms. File paths use correct separators. Line endings normalized.', check:'`path.join(__dirname,"fixtures","auth.json")` instead of `__dirname+"/fixtures/auth.json"`. `os.tmpdir()` for temp files. `content.replace(/\\r\\n/g,"\\n")` for line ending normalization.' },
    { id:49, level:5, title:'Fixture Dependency Injection Container', scenario:'Build a DI container for Playwright fixtures that supports lazy initialization and singleton patterns.', objective:'`Container` class: `register(name,factory)`. `resolve(name)`: lazy initialization. `singleton(name,factory)`: one instance per container. `scoped(name,factory)`: one per test.', constraints:'Lazy init. Singleton. Scoped. Integrate with Playwright test.extend.', expectedOutput:'`container.register("db",()=>connectDB())`. `container.resolve("db")`: lazy connection. Second resolve: same instance (singleton).', check:'DI container maps names to factories. Singleton: cache after first create. Scoped: create fresh per test. Integrate: `base.extend({container:async({},use)=>{ const c=new Container(); await use(c); await c.dispose(); }})`. ' },
    { id:50, level:5, title:'Full Fixture Ecosystem', scenario:'Build a complete fixture ecosystem for a large-scale testing organization.', objective:'Build: (1) Fixture library (auth, db, api, data, mocks), (2) DI container integration, (3) Performance monitoring, (4) Security audit, (5) Documentation generator, (6) Code generator, (7) Testing framework for fixtures.', constraints:'All 7 components. Published npm packages.', expectedOutput:'`@company/playwright-fixtures`: imports all. Each fixture documented. Generated on spec change. Monitored in production.', check:'Monorepo structure: `packages/fixtures/*` for each domain. `packages/tools/*` for generator, monitor, security-audit. CI: validate, test, publish on change.' },
  ],

  api: [
    { id:1, level:1, title:'First API Request', scenario:'Make a GET request to a REST API and verify the response.', objective:'`const response = await request.get("https://jsonplaceholder.typicode.com/posts/1")`. `expect(response.status()).toBe(200)`. `const body = await response.json()`. `expect(body.id).toBe(1)`.', constraints:'GET request. Status check. JSON body.', expectedOutput:'Status 200. Body: {id:1,title:"...",body:"...",userId:1}.', check:'`request` fixture: APIRequestContext. `response.status()`: HTTP status code. `response.json()`: parses body as JSON. `response.text()`: raw text. `response.headers()`: header map.' },
    { id:2, level:1, title:'POST Request', scenario:'Create a new resource via POST and verify the response.', objective:'`const response = await request.post("https://jsonplaceholder.typicode.com/posts",{data:{title:"New Post",body:"Content",userId:1}})`. `expect(response.status()).toBe(201)`.', constraints:'POST with JSON body. Status 201.', expectedOutput:'Status 201. Response body contains the created resource with an assigned id.', check:'`{data:object}`: serialized as JSON with `Content-Type:application/json`. `{form:object}`: sends as form-encoded. `{multipart:object}`: multipart/form-data.' },
    { id:3, level:1, title:'PUT and PATCH Requests', scenario:'Update a resource with PUT (full update) and PATCH (partial update).', objective:'PUT: `request.put("/posts/1",{data:{...fullObject}})`. PATCH: `request.patch("/posts/1",{data:{title:"Updated"}})`. Verify response and changed fields.', constraints:'Both verbs. Different bodies.', expectedOutput:'PUT: full object replaced. PATCH: only title changed.', check:'`request.put(url,{data})`. `request.patch(url,{data})`. `request.delete(url)`. All take the same options object. `response.ok()`: true for 2xx.' },
    { id:4, level:1, title:'DELETE Request', scenario:'Delete a resource and verify it no longer exists.', objective:'`const del = await request.delete("/posts/1")`. `expect(del.status()).toBe(200)`. Then: `const get = await request.get("/posts/1")`. `expect(get.status()).toBe(404)`.', constraints:'DELETE. Verify 404 after delete.', expectedOutput:'DELETE returns 200. Subsequent GET returns 404.', check:'`request.delete(url)`. After deletion: resource returns 404. Note: jsonplaceholder simulates this — it doesn\'t actually delete, but returns 200.' },
    { id:5, level:1, title:'Query Parameters', scenario:'Search an API using query parameters.', objective:'`request.get("/posts",{params:{userId:1}})`. Resulting URL: `/posts?userId=1`. `expect(posts.every(p=>p.userId===1)).toBe(true)`.', constraints:'params object. Verify URL-encoded query string.', expectedOutput:'GET /posts?userId=1 returns only posts with userId=1.', check:'`{params:object}`: encoded as URL query parameters. `{params:{"q":"search term","page":2}}` → `?q=search+term&page=2`. Handles encoding automatically.' },
    { id:6, level:1, title:'Request Headers', scenario:'An API requires a custom authentication header.', objective:'`request.get("/secure-data",{headers:{"Authorization":"Bearer token123","X-Api-Version":"2"}})`. Verify the header is sent by inspecting the request.', constraints:'Custom headers. Two headers.', expectedOutput:'Request sent with Authorization and X-Api-Version headers.', check:'`{headers:object}`: merged with default headers. Common headers: `Authorization`, `Content-Type`, `Accept`. `request.dispose()` to free resources.' },
    { id:7, level:1, title:'Response Headers', scenario:'Verify the API returns the correct content-type header.', objective:'`const response = await request.get("/api/data")`. `const contentType = response.headers()["content-type"]`. `expect(contentType).toContain("application/json")`.', constraints:'Read response headers. Assert content-type.', expectedOutput:'Content-Type header contains "application/json".', check:'`response.headers()`: returns a plain object with all response headers (lowercased names). `response.headersArray()`: array of {name,value} pairs.' },
    { id:8, level:1, title:'Text and Buffer Responses', scenario:'An API returns plain text and another returns binary data.', objective:'Text: `await response.text()`. Binary: `await response.body()` — returns a Buffer. For image: write buffer to file and verify.', constraints:'text() for text. body() for binary.', expectedOutput:'Text response: string. Binary response: Buffer. Buffer written to file.', check:'`response.text()`: UTF-8 string. `response.json()`: parsed JSON. `response.body()`: raw Buffer. `response.ok()`: boolean. `response.statusText()`: "OK","Not Found",etc.' },
    { id:9, level:1, title:'Request Context from Config', scenario:'All API tests target the same base URL with the same headers.', objective:'In config: `use:{baseURL:"https://api.example.com",extraHTTPHeaders:{"Authorization":"Bearer token"}}`. Tests use `request.get("/users")` (relative URL).', constraints:'Config-based baseURL. extraHTTPHeaders.', expectedOutput:'All requests use the base URL. All requests have the auth header.', check:'`request` fixture respects `use.baseURL` and `use.extraHTTPHeaders` from config. `extraHTTPHeaders` applies to all requests. `ignoreHTTPSErrors` for self-signed certs.' },
    { id:10, level:1, title:'toBeOK Assertion', scenario:'Verify an API response is successful (2xx) without checking the exact code.', objective:'`expect(response).toBeOK()`. For any 2xx. Combine with `response.json()` to check the body.', constraints:'toBeOK assertion. 2xx responses.', expectedOutput:'200: pass. 201: pass. 400: fail. 404: fail.', check:'`toBeOK()`: shorthand for `expect(response.ok()).toBe(true)`. `response.ok()`: `status >= 200 && status < 300`. Readable assertion for success-checking.' },
    { id:11, level:2, title:'API Context Initialization', scenario:'Create a standalone API context with custom options (not tied to a browser).', objective:'`const apiContext = await request.newContext({baseURL:"https://api.example.com",extraHTTPHeaders:{Authorization:"Bearer token"}})`. Use and dispose.', constraints:'newContext. Custom options. Dispose.', expectedOutput:'apiContext makes authenticated requests to the base URL. Dispose: `apiContext.dispose()`.', check:'`request.newContext(options)`: creates a new APIRequestContext. Use for test-specific contexts. Always `dispose()` when done to free resources (connections, cookies).' },
    { id:12, level:2, title:'Cookie Handling in API', scenario:'An API uses cookie-based authentication. Set a cookie before making requests.', objective:'Set cookie: `await apiContext.storageState()` after login via API. Or set manually in headers. Verify cookie-protected endpoints.', constraints:'Cookie-based auth. storageState.', expectedOutput:'After login API call: cookie saved. Protected endpoint: accessible with the cookie.', check:'APIRequestContext maintains a cookie jar. Cookies set by API responses are stored. `storageState()`: export cookies. `newContext({storageState})`: import cookies.' },
    { id:13, level:2, title:'Form Data Requests', scenario:'Upload a form submission via API test.', objective:'`request.post("/upload",{multipart:{file:{name:"test.pdf",mimeType:"application/pdf",buffer:Buffer.from("...")}},name:"Test File"}})`. Verify file received.', constraints:'multipart form data. File upload via API.', expectedOutput:'POST with multipart/form-data. File field and text field.', check:'`{multipart:{fieldName:{name,mimeType,buffer}}}`: file upload. `{form:{key:value}}`: `application/x-www-form-urlencoded`. `{data:{...}}`: JSON body.' },
    { id:14, level:2, title:'API Response Validation', scenario:'Validate the full structure of an API response against a schema.', objective:'`const user = await response.json()`. `expect(user).toMatchObject({id:expect.any(Number),name:expect.any(String),email:expect.stringMatching(/@/)})`.', constraints:'toMatchObject. expect.any. expect.stringMatching.', expectedOutput:'User object matches schema: id is a number, name is a string, email has @.', check:'`toMatchObject`: partial matching. `expect.any(Type)`: type check. `expect.stringMatching(regex)`: regex match. `expect.arrayContaining([...])`: subset matching for arrays.' },
    { id:15, level:2, title:'Pagination Testing', scenario:'An API returns paginated results. Verify all pages.', objective:'Fetch page 1 with `?page=1&limit=10`. Verify 10 items. Fetch page 2. Verify continuation. Fetch last page. Verify fewer items (or 0 on empty).', constraints:'Three page requests. Verify item count per page.', expectedOutput:'Page 1: 10 items. Page 2: 10 items. Page 3: 5 items (end).', check:'Pagination pattern: `response.json().data` for items. `response.json().total` for total count. Calculate pages: `Math.ceil(total/limit)`. Verify last page has remaining items.' },
    { id:16, level:2, title:'Error Response Handling', scenario:'Test that the API returns correct error responses for bad requests.', objective:'POST with missing required field. `expect(response.status()).toBe(400)`. `expect(body.error).toContain("name is required")`. Also test 401 (no auth), 403 (forbidden), 404 (not found).', constraints:'4xx error codes. Error body assertion.', expectedOutput:'400: validation error message. 401: unauthorized message. 403: forbidden message. 404: not found message.', check:'Test negative cases: missing fields, invalid values, wrong auth, non-existent resources. These are as important as happy-path testing.' },
    { id:17, level:2, title:'API Authentication Flows', scenario:'Test login and logout via API, using the session for subsequent requests.', objective:'POST /login → get token. Use token in `Authorization: Bearer`. POST /logout → token invalidated. Next request with old token → 401.', constraints:'Login. Authenticated request. Logout. Verify 401 after logout.', expectedOutput:'Login: 200 + token. Authenticated: 200. Logout: 200. Post-logout: 401.', check:'Token-based auth flow. Store token from login response. Use in subsequent requests. Verify invalidation after logout.' },
    { id:18, level:2, title:'GraphQL API Testing', scenario:'Test a GraphQL endpoint using POST requests.', objective:'`request.post("/graphql",{data:{query:"query{users{id name email}}"}})`. `expect(body.data.users).toBeTruthy()`. `expect(body.errors).toBeUndefined()`.', constraints:'GraphQL POST. Query in body. Check data and errors.', expectedOutput:'Query returns data.users array. No errors field.', check:'GraphQL: always POST. Body: `{query:"...",variables:{...}}`. Response: `{data:{...}}` on success, `{errors:[...]}` on failure. Note: status is always 200 even for errors.' },
    { id:19, level:2, title:'API Response Time', scenario:'Verify API response times are within acceptable limits.', objective:'Record `Date.now()` before request. Make request. Record after. `const duration = Date.now() - start`. `expect(duration).toBeLessThan(2000)`.', constraints:'Timing. Assert < 2000ms.', expectedOutput:'API responds in < 2s: pass. > 2s: fail with duration shown.', check:'Simple timing: `Date.now()` before and after. More accurate: Performance API. Caveat: network conditions affect timing. Use in controlled environments or as soft assertions.' },
    { id:20, level:2, title:'Chained API Requests', scenario:'Create a post, update it, read it, then delete it.', objective:'POST → get id. PUT using id. GET to verify update. DELETE using id. GET to verify deletion (expect 404).', constraints:'Four requests in sequence. Each depends on the previous.', expectedOutput:'Post created (201). Updated (200). Read: updated values (200). Deleted (200). Get: 404.', check:'CRUD sequence. Each request uses the result from the previous. `id = createResponse.json().id`. Use `await` for sequential execution.' },
    { id:21, level:3, title:'API Client Factory', scenario:'Build a reusable API client class for clean test code.', objective:'`class APIClient { constructor(request,baseURL,token) {}. async getUser(id){...}. async createUser(data){...}. async deleteUser(id){...}. }`. Use in tests.', constraints:'Class with three methods. Error handling. Return typed objects.', expectedOutput:'`const client = new APIClient(request,BASE_URL,token)`. `client.getUser(1)` returns a User object.', check:'Factory pattern: encapsulates request logic. Handles auth, base URL, error responses. Returns domain objects, not raw responses. Throws on 4xx/5xx.' },
    { id:22, level:3, title:'API Mocking with Route Interception', scenario:'Intercept and mock API calls made by the browser UI.', objective:'`page.route("/api/users",route=>route.fulfill({json:[{id:1,name:"Mock User"}]}))`. Navigate to the users page. UI shows "Mock User".', constraints:'page.route. fulfill with JSON. Verify UI uses mocked data.', expectedOutput:'Real API not called. UI renders "Mock User" from the mock.', check:'`route.fulfill({json,status,headers})`: intercepts and responds with mock data. `route.continue()`: passes through to real server. `route.abort()`: simulates network failure.' },
    { id:23, level:3, title:'Response Body Transformation', scenario:'The API returns dates as timestamps. Tests need them as ISO strings.', objective:'After `response.json()`: transform the body before assertions. `const normalized = {...body, createdAt: new Date(body.createdAt).toISOString()}`. Assert the normalized body.', constraints:'Transformation before assertion. Date normalization.', expectedOutput:'Timestamp 1705363200000 → "2024-01-16T00:00:00.000Z". Assert ISO string.', check:'Normalization pattern: `const normalize = body => ({...body, dates: body.dates.map(d=>new Date(d).toISOString())})`. Assert normalized data. Useful for unstable data formats.' },
    { id:24, level:3, title:'Concurrent API Requests', scenario:'Test an endpoint under concurrent load by making parallel requests.', objective:'`const responses = await Promise.all(Array.from({length:10},(_,i)=>request.get("/api/item/"+i)))`. `responses.forEach(r=>expect(r.ok()).toBe(true))`.', constraints:'10 concurrent requests. All must succeed.', expectedOutput:'10 parallel requests. All return 200. Check rate limiting behavior.', check:'`Promise.all`: runs requests in parallel. Checks rate limiting (429). Checks concurrency handling. Not a load test — use k6 or Artillery for that.' },
    { id:25, level:3, title:'API Contract Testing', scenario:'Verify the API response matches the documented contract (OpenAPI spec).', objective:'Load the OpenAPI spec. Make a request. Validate the response body against the spec using `ajv`. Report any schema violations.', constraints:'Load OpenAPI spec. ajv validation. Report violations.', expectedOutput:'Response missing field "email": "data must have required property email". Extra field: no error (additionalProperties not set).', check:'`ajv.validate(schema,data)`: validate against JSON Schema. OpenAPI uses JSON Schema for body schemas. Validate status codes, headers, and body. Run on every response.' },
    { id:26, level:3, title:'OAuth2 API Testing', scenario:'Test APIs that use OAuth2 client credentials flow.', objective:'POST to `/oauth/token` with client_id and client_secret. Get access_token. Use token for subsequent API calls. Verify token expiry handling.', constraints:'Client credentials flow. Token storage. Use token.', expectedOutput:'Token received from /oauth/token. API calls succeed with Bearer token. Expired token → 401.', check:'Client credentials: `POST /oauth/token` with `grant_type=client_credentials&client_id=X&client_secret=Y`. Response: `{access_token,token_type,expires_in}`. Use in Authorization header.' },
    { id:27, level:3, title:'API Rate Limit Testing', scenario:'Verify the API enforces rate limits.', objective:'Make requests in a tight loop. Eventually get 429. `expect(rateLimitedResponse.status()).toBe(429)`. Check `Retry-After` header.', constraints:'Loop until 429. Check Retry-After header.', expectedOutput:'After N requests: 429 status. Retry-After header: 60 (seconds).', check:'Rate limit: `Retry-After` or `X-RateLimit-Reset` header. `const retryAfter = parseInt(response.headers()["retry-after"])`. Test: verify 429 behavior, not trigger production limits.' },
    { id:28, level:3, title:'Webhook Testing', scenario:'Your app sends a webhook. Test that it is sent correctly.', objective:'Start a local HTTP server (webhook receiver). Register its URL with the API. Trigger the event. Verify the webhook was received with correct payload.', constraints:'Local receiver. Register URL. Trigger. Verify payload.', expectedOutput:'Event triggered → webhook received. Payload: {event:"user.created",data:{id:1,...}}.', check:'Webhook receiver: `http.createServer` or `express`. Start on a free port. Register the URL via API. Trigger the event. Assert on the received request body.' },
    { id:29, level:3, title:'API Retry Logic', scenario:'An API call may fail transiently. Implement retry with exponential backoff.', objective:'`async function fetchWithRetry(url, maxRetries=3) { for(let i=0;i<maxRetries;i++){const r=await request.get(url);if(r.ok())return r;await sleep(Math.pow(2,i)*1000);} throw new Error("Failed after retries"); }`. Use in tests.', constraints:'Retry loop. Exponential backoff. Max retries.', expectedOutput:'First two requests fail (503). Third succeeds. Total time: ~3s (1+2=3s backoff).', check:'Exponential backoff: `2^i * baseDelay`. 1s, 2s, 4s, 8s. Jitter: add `Math.random()*500` to avoid thundering herd. Max 3 retries by default.' },
    { id:30, level:3, title:'API Versioning', scenario:'Two API versions are live. Test both and verify backward compatibility.', objective:'`request.get("/api/v1/users/1")` and `request.get("/api/v2/users/1")`. V1: `{id,name}`. V2: `{id,firstName,lastName,email}`. Assert both return the same `id`.', constraints:'Two version endpoints. Different schemas. Compatibility check.', expectedOutput:'V1: basic user. V2: extended user. Same id in both. V2 is a superset of V1.', check:'API versioning tests: ensure old clients still work (V1 compatible), new clients use V2 features. Regression: V2 should not break V1 contracts.' },
    { id:31, level:4, title:'API Test Data Lifecycle', scenario:'Each API test must create, use, and clean up its own data.', objective:'Fixture: `async({request},use)=>{ const user=await createUser(request); await use(user); await deleteUser(request,user.id); }`. Test: uses the fixture user. Cleanup: always runs.', constraints:'Fixture-based lifecycle. Create in setup. Delete in teardown. Always clean.', expectedOutput:'User created before test. Test runs. User deleted after (even if test fails).', check:'Fixture teardown (after use()): always runs. Pattern: `const entity=await create(); try{await use(entity);}finally{await delete(entity.id)}`. Or: just put cleanup after use().' },
    { id:32, level:4, title:'API Test Reporting', scenario:'Enhance the HTML report with API call details.', objective:'Custom reporter: `onTestEnd`: log all API calls made during the test (URL, status, duration). Attach to the test report.', constraints:'Custom reporter. Log API calls. Attach to report.', expectedOutput:'HTML report shows API call log per test: "GET /users/1 → 200 in 120ms".', check:'Intercept via `page.on("request")` and `page.on("response")`. Collect in array. In `afterEach`: attach to report with `testInfo.attach("api-calls",{body:JSON.stringify(calls)})`. ' },
    { id:33, level:4, title:'API Idempotency Testing', scenario:'PUT and DELETE operations must be idempotent (calling twice has the same effect as once).', objective:'PUT twice with the same data: same result both times. DELETE twice: second returns 404 (not an error either). Verify no side effects.', constraints:'PUT idempotency. DELETE idempotency. Verify no duplicates.', expectedOutput:'PUT ×2: resource unchanged (same values). DELETE ×2: 200 then 404 (or 200 both times if designed that way).', check:'Idempotency: `PUT` same body → same state. `DELETE` → resource gone, repeated delete → still gone (404). `POST` is NOT idempotent (creates duplicates). Test these properties explicitly.' },
    { id:34, level:4, title:'API Contract Snapshot Testing', scenario:'Catch unintended API changes by snapshotting responses.', objective:'GET /api/users/1 → save response as a snapshot. Next run: compare. If the response changes: fail with diff. Use `--update-snapshots` for intentional changes.', constraints:'Response snapshot. Compare. Update workflow.', expectedOutput:'First run: snapshot created. Change email → fail. `--update-snapshots` → snapshot updated.', check:'`expect(JSON.stringify(body,null,2)).toMatchSnapshot("user-1.json")`. Mask dynamic fields first: `delete body.updatedAt`. Snapshot stored in `__snapshots__`.' },
    { id:35, level:4, title:'API Load Testing Helper', scenario:'From within Playwright, run a lightweight load check against an endpoint.', objective:'Make 50 sequential requests. Measure: min, max, p50, p90, p99 response times. Assert p99 < 2000ms.', constraints:'50 sequential requests. Percentile calculation. Assert p99.', expectedOutput:'p50: 120ms. p90: 350ms. p99: 800ms. All within budget.', check:'Not a real load test (no concurrency). Pattern: `const times=[];for(let i=0;i<50;i++){const t=Date.now();await request.get(url);times.push(Date.now()-t);}`. Sort times. p99: `times[Math.ceil(times.length*0.99)-1]`.' },
    { id:36, level:4, title:'Multipart API Testing', scenario:'An API accepts file uploads and form fields in the same request.', objective:'`request.post("/upload",{multipart:{file:{name:"data.csv",mimeType:"text/csv",buffer:Buffer.from("a,b,c\n1,2,3")},title:"My CSV"}})`. Verify upload response.', constraints:'File + form fields in one request. Assert upload success.', expectedOutput:'POST multipart: file uploaded, title stored. Response: {fileId:"abc", title:"My CSV"}.', check:'`multipart`: each field is either a string (for text fields) or `{name,mimeType,buffer}` for files. Content-Type is automatically set to `multipart/form-data; boundary=...`.' },
    { id:37, level:4, title:'API Dependency Injection in Tests', scenario:'API clients should be injectable and replaceable for testing.', objective:'Create an `APIClientInterface`. In tests: inject the real client. In integration tests: inject a mock client that returns canned responses. Toggle with env var.', constraints:'Interface. Real implementation. Mock implementation. Toggle.', expectedOutput:'Unit mode: mock client used. Integration mode: real client used. Same test code for both.', check:'Pattern: `const client = process.env.MOCK ? new MockAPIClient() : new RealAPIClient(request)`. Interface: `getUser(id):Promise<User>`. Same API, different implementations.' },
    { id:38, level:4, title:'API Security Testing', scenario:'Test for common API security issues.', objective:'(1) SQL injection: POST with `title:""; DROP TABLE posts;--"`. (2) XSS: POST with `name:"<script>alert(1)</script>"`. (3) IDOR: GET /users/2 when logged in as user 1. (4) Mass assignment: POST with `{role:"admin"}`.', constraints:'Four security tests. Assert rejections.', expectedOutput:'SQL injection: rejected (400 or sanitized). XSS: escaped in response. IDOR: 403. Mass assignment: role not changed.', check:'Security testing via API: send malicious inputs, verify they are rejected or sanitized. IDOR: expect 403, not the other user\'s data. These are important negative tests.' },
    { id:39, level:4, title:'API Caching Testing', scenario:'Verify the API implements HTTP caching correctly.', objective:'First request: no Cache-Control response header. Second request: `If-None-Match` header with ETag. Expected: 304 Not Modified. Verify cache header presence.', constraints:'ETag caching. If-None-Match. Assert 304.', expectedOutput:'First request: ETag header in response. Second request with ETag: 304 Not Modified. Body empty.', check:'ETag flow: 1) GET → response has `ETag:"abc"`. 2) GET with `If-None-Match:"abc"` → if unchanged: 304 (no body). `Cache-Control: max-age=3600`. Test: verify headers, verify 304 behavior.' },
    { id:40, level:4, title:'API Integration Test Harness', scenario:'Build a complete API integration test harness.', objective:'Build: `APITestHarness` with: `setup()` (start server), `teardown()` (stop server), `seed()` (test data), `clean()` (cleanup), `client()` (authenticated client). Use in tests.', constraints:'All five methods. Fixture integration.', expectedOutput:'`const harness = new APITestHarness()`. `harness.setup()`. `const user = harness.seed().user()`. `harness.client().getUser(user.id)`.', check:'Harness encapsulates all test infrastructure. `seed()`: returns a builder for test data. `clean()`: removes seeded data. `client()`: returns configured API client.' },
    { id:41, level:5, title:'API Test Generator', scenario:'Automatically generate API tests from an OpenAPI specification.', objective:'Read OpenAPI spec. For each endpoint: generate a happy-path test (correct params → 2xx) and a validation test (missing required param → 4xx). Output runnable test files.', constraints:'OpenAPI parsing. Two test types per endpoint. Runnable output.', expectedOutput:'GET /users/{id}: happy path (existing id → 200) and error (non-existent id → 404). Generated file has both tests.', check:'OpenAPI endpoints: `paths.forEach((path,methods.forEach(method)))`. For each: extract required params, example values. Generate: `test("GET /users/{id} happy path",...)`. Template-based output.' },
    { id:42, level:5, title:'API Fuzzing', scenario:'Send random/malformed inputs to the API to find unexpected behavior.', objective:'For each string parameter: test with empty string, very long string, special chars, SQL injection, XSS, null bytes. For numbers: negative, zero, MAX_INT. Assert no 500 errors.', constraints:'Multiple fuzz vectors. All parameters. No 500s.', expectedOutput:'500 on `id=<null byte>`: bug found. All others: 400 or 200. Report: {parameter,vector,status}.', check:'Fuzz vectors: `["","a".repeat(10000),"<script>","\'; DROP TABLE--","\\x00","-1","0","2147483647"]`. Assert: `expect(response.status()).not.toBe(500)`. Log all non-2xx for investigation.' },
    { id:43, level:5, title:'Consumer-Driven Contract Testing', scenario:'A consumer and provider agree on an API contract. Verify both sides honor it.', objective:'Consumer: defines expected interactions (pact). Provider: verifies it can fulfill the pact. Use Pact library with Playwright for the verification step.', constraints:'Consumer pact definition. Provider verification. Publish pact.', expectedOutput:'Consumer pact: expects GET /users/1 → 200 with {id:1,name}. Provider verification: confirms it returns this.', check:'Pact flow: 1) Consumer writes pact (expected request/response pairs). 2) Pact broker stores it. 3) Provider runs pact verifier against its real API. 4) Fail if mismatch.' },
    { id:44, level:5, title:'API Test Mutation Coverage', scenario:'Are the API tests actually verifying behavior, or just checking status codes?', objective:'Run mutation testing: change a field in the API response. Check if any test fails. If no test fails: tests are not covering that field.', constraints:'Mutation: change one field. Check test failure. Report coverage gaps.', expectedOutput:'No test checks `user.email`: change email → no test fails → coverage gap.', check:'Mutation testing approach: intercept API response, alter one field, re-run tests. `route.fulfill({json:{...original, email:"mutated"}})`. If tests pass: gap. Systematic: mutate each field.' },
    { id:45, level:5, title:'API Test Flakiness Elimination', scenario:'An API test is flaky because it depends on database state from previous tests.', objective:'(1) Diagnose: run test in isolation and in suite. (2) Identify shared state. (3) Fix: create isolated test data per test. (4) Verify: run 10 times, all pass.', constraints:'Isolation via fixture. Run 10 times. All pass.', expectedOutput:'Before: 7/10 pass. After fixture isolation: 10/10 pass.', check:'Flakiness cause: shared database state. Fix: use unique identifiers per test (timestamp-based), clean up in teardown. Verify with `--repeat-each=10`.' },
    { id:46, level:5, title:'API Performance Budget', scenario:'API endpoints must meet performance budgets. Alert if they are exceeded.', objective:'For each endpoint: measure p50, p95, p99. Compare to budget. Report violations. Fail CI if p99 exceeds budget.', constraints:'All endpoints. Percentile calculation. Budget comparison. CI failure.', expectedOutput:'/users/1 budget: p99<500ms. Actual p99: 800ms. CI failure with report.', check:'Budget config: `{"/users/{id}":{p99:500},"/products":{p99:300}}`. Run N requests per endpoint. Calculate percentiles. Alert: Slack/email. Fail CI: exit non-zero on violation.' },
    { id:47, level:5, title:'Multi-Tenant API Testing', scenario:'A SaaS API must isolate data between tenants.', objective:'Create two tenants. Each creates a resource. Verify tenant A cannot access tenant B\'s resources (403). Verify tenant A\'s list only shows tenant A\'s data.', constraints:'Two tenants. Cross-tenant access: 403. List isolation.', expectedOutput:'Tenant A creates resource. Tenant B GET: 403. Tenant A list: only A\'s resources.', check:'Tenant isolation tests: the most critical multi-tenant security test. Use unique tenant credentials. List endpoint: verify response count and IDs belong to the requesting tenant only.' },
    { id:48, level:5, title:'API Documentation Testing', scenario:'Verify that the API documentation examples actually work.', objective:'Extract code examples from API documentation (markdown or OpenAPI). Run each example as an actual request. Verify it matches the documented response.', constraints:'Doc example extraction. Run each. Compare to documented response.', expectedOutput:'Doc example: "GET /users/1 → {id:1,name:\"Alice\"}". Actual: {id:1,name:"Alice"}. Match.', check:'Extract examples: parse markdown code blocks or OpenAPI `examples`. Run: make the actual request. Compare: `toMatchObject(documentedResponse)`. Catch doc drift.' },
    { id:49, level:5, title:'API Test Orchestration', scenario:'A complex business flow requires coordinating multiple API calls across services.', objective:'Order flow: 1) Auth service → token. 2) Inventory service → check stock. 3) Payment service → charge. 4) Order service → create order. 5) Notification service → confirm. Each step depends on the previous.', constraints:'5 service calls. Sequential. Error handling at each step.', expectedOutput:'All 5 succeed → order created. Payment fails → order not created. Inventory 0 → payment not attempted.', check:'Sequential orchestration: `const token=await auth()`. `const stock=await inventory(token)`. `if(!stock) return fail("No stock")`. `const payment=await charge(token)`. etc. Test each failure path.' },
    { id:50, level:5, title:'Full API Testing Framework', scenario:'Build a complete API testing framework for an enterprise application.', objective:'Build: (1) API client with auth, retry, logging. (2) Contract testing (OpenAPI validation). (3) Test data factory. (4) Performance measurement. (5) Security scan. (6) Mutation coverage. (7) Reporting dashboard.', constraints:'All 7 components. Composable. Documented.', expectedOutput:'`import {APITest} from "@company/api-test"`. `APITest.get("/users/1").expectStatus(200).validateContract().measurePerformance().run()`.', check:'Fluent builder pattern: each method returns `this` for chaining. Runs execute all registered checks. Contract: ajv. Performance: timing wrapper. Security: fuzz vectors. Report: HTML.' },
  ],

  network: [
    { id:1, level:1, title:'Listen to Network Requests', scenario:'Log all network requests made during a page navigation.', objective:'`page.on("request",req=>console.log(req.method(),req.url()))`. `page.goto("/")`. Observe all requests logged.', constraints:'Request event. Log method and URL. Navigate.', expectedOutput:'GET https://example.com/, GET https://example.com/style.css, GET https://example.com/app.js, ...', check:'`page.on("request",callback)`: fires for every request (documents, XHR, fetch, images, etc.). `req.method()`: GET/POST/etc. `req.url()`: full URL. `req.headers()`: request headers.' },
    { id:2, level:1, title:'Listen to Network Responses', scenario:'Log all responses and their status codes during navigation.', objective:'`page.on("response",res=>console.log(res.status(),res.url()))`. `page.goto("/")`. Log all responses.', constraints:'Response event. Log status and URL.', expectedOutput:'200 https://example.com/, 200 https://example.com/style.css, 404 https://example.com/missing.png, ...', check:'`page.on("response",callback)`: fires when a response is received. `res.status()`: HTTP status. `res.url()`: request URL. `res.headers()`: response headers. `res.ok()`: 2xx.' },
    { id:3, level:1, title:'Wait for Network Request', scenario:'A button triggers an API call. Wait for the request before asserting.', objective:'`const requestPromise = page.waitForRequest("**/api/products")`. `page.click("button")`. `const req = await requestPromise`. `expect(req.method()).toBe("GET")`.', constraints:'waitForRequest before click. Assert after.', expectedOutput:'Click triggers GET /api/products. req.method() is "GET".', check:'`waitForRequest(url|predicate)`: returns a promise that resolves with the matching Request. Must be called BEFORE the action that triggers the request (to avoid race conditions).' },
    { id:4, level:1, title:'Wait for Network Response', scenario:'Wait for the API response before asserting the UI.', objective:'`const responsePromise = page.waitForResponse("**/api/products")`. `page.click("Load Products")`. `const response = await responsePromise`. `expect(response.status()).toBe(200)`.', constraints:'waitForResponse before click. Assert response.', expectedOutput:'Load Products click → GET /api/products → 200. Response available.', check:'`waitForResponse(url|predicate)`: resolves with the Response. Predicate: `res=>res.url().includes("/api/products")&&res.status()===200`. Set up before the action.' },
    { id:5, level:1, title:'Block Requests', scenario:'Block third-party analytics scripts to speed up tests.', objective:'`await page.route("**/*analytics*",route=>route.abort())`. `page.goto("/")`. Verify analytics script is not loaded.', constraints:'route.abort. Glob pattern. Verify blocked.', expectedOutput:'Analytics script request: aborted. Page loads without analytics.', check:'`route.abort()`: simulates a network failure (ERR_FAILED). `route.abort("blockedbyclient")`: browser-initiated block. Blocks third-party scripts, ads, analytics — speeds up tests.' },
    { id:6, level:1, title:'Mock API Response', scenario:'Replace a real API response with mock data.', objective:'`page.route("/api/users",route=>route.fulfill({status:200,contentType:"application/json",body:JSON.stringify([{id:1,name:"Mock User"}])}))`. Navigate to users page. UI shows "Mock User".', constraints:'route.fulfill. JSON body. Verify UI.', expectedOutput:'Real API not called. UI shows "Mock User" from mock.', check:'`route.fulfill({status,headers,contentType,body,json,path})`. `json` shorthand: `route.fulfill({json:[{id:1}]})` — sets Content-Type automatically.' },
    { id:7, level:1, title:'Modify Request Headers', scenario:'Add an auth header to all API requests.', objective:'`page.route("/api/**",route=>route.continue({headers:{...route.request().headers(),"Authorization":"Bearer test-token"}}))`. All API requests get the auth header.', constraints:'route.continue with modified headers. All /api/ requests.', expectedOutput:'Every /api/ request includes Authorization: Bearer test-token.', check:'`route.continue({headers,method,postData,url})`: continues with modifications. `{...route.request().headers(),...newHeaders}`: merge original headers with additions. Not replacing.' },
    { id:8, level:1, title:'Intercept and Log XHR', scenario:'Log only XHR and Fetch requests (not static assets).', objective:'`page.on("request",req=>{ if(req.resourceType()==="xhr"||req.resourceType()==="fetch"){ log(req.url()); } })`.', constraints:'resourceType filter. Log XHR and Fetch.', expectedOutput:'Only XHR and Fetch requests logged. Images, CSS, JS not logged.', check:'`req.resourceType()`: "document","stylesheet","image","media","font","script","texttrack","xhr","fetch","eventsource","websocket","manifest","other". Filter for API calls: "xhr" and "fetch".' },
    { id:9, level:1, title:'Wait for Page Load States', scenario:'Verify the page is fully loaded before making assertions.', objective:'`page.goto("/dashboard")`. Options: `await page.waitForLoadState("domcontentloaded")`, `"load"`, `"networkidle"`. Explain each.', constraints:'All three load states. Explain differences.', expectedOutput:'DOMContentLoaded: DOM parsed (no images/CSS). load: all resources. networkidle: no requests for 500ms.', check:'`domcontentloaded`: DOM is ready. `load`: everything including images. `networkidle`: no requests in flight for 500ms. For SPAs: use `networkidle` or wait for a specific element.' },
    { id:10, level:1, title:'Request Failure Detection', scenario:'Detect any failed network requests during a test.', objective:'`const failures=[]`. `page.on("requestfailed",req=>failures.push({url:req.url(),reason:req.failure()?.errorText}))`. After page actions: `expect(failures).toHaveLength(0)`.', constraints:'requestfailed event. Log failures. Assert none.', expectedOutput:'No 404/network errors: failures is empty. Missing resource: failures has one entry.', check:'`page.on("requestfailed",req)`: fires for aborted or failed requests. `req.failure()`: `{errorText:string}` like "net::ERR_CONNECTION_REFUSED". Not 4xx responses (those are responses, not failures).' },
    { id:11, level:2, title:'Route Pattern Matching', scenario:'Different route patterns intercept different requests.', objective:'Exact URL: `page.route("https://api.example.com/users",...)`. Glob: `page.route("**/api/**",...)`. Regex: `page.route(/\\/(api|graphql)\\//,...)`. Show each.', constraints:'Exact, glob, and regex patterns.', expectedOutput:'Exact: only that URL. Glob: all /api/ paths. Regex: /api/ or /graphql/ paths.', check:'Pattern types: string (exact), glob (with * and **), RegExp. `**/`: matches any number of path segments. `*`: matches within a segment. Last registered route wins (LIFO order).' },
    { id:12, level:2, title:'Modify Response Body', scenario:'Intercept a response and modify the body before it reaches the page.', objective:'`page.route("/api/products",async route=>{ const response=await route.fetch(); const json=await response.json(); json.push({id:999,name:"Injected"}); route.fulfill({response,json}); })`.', constraints:'route.fetch. Modify body. Fulfill with modified.', expectedOutput:'Original products + injected product. UI shows the injected item.', check:'`route.fetch()`: makes the real request and returns the response. Modify it, then `route.fulfill({response,json})`: use the original response for headers/status, override the body.' },
    { id:13, level:2, title:'Simulate Network Errors', scenario:'Test how the app handles network failures.', objective:'`page.route("/api/critical",route=>route.abort("failed"))`. Navigate. Verify the app shows an error message.', constraints:'route.abort. Error message verification.', expectedOutput:'API call aborted → app shows "Network Error. Please retry."', check:'Error strings: "failed","aborted","timedout","connectionreset","connectionrefused","connectionclosed","namenotresolved","internetdisconnected","addressunreachable","blockedbyclient","blockedbyresponse".' },
    { id:14, level:2, title:'Simulate Slow Networks', scenario:'Test app behavior on slow network connections.', objective:'Use `page.route` to delay responses: `setTimeout(()=>route.continue(),2000)` — 2s delay. Verify loading spinner appears and disappears after response.', constraints:'Delayed route.continue. Loading spinner check.', expectedOutput:'API call delayed 2s. Spinner visible during delay. Spinner hidden after response.', check:'Slow network simulation: `route.fulfill({...response,delay:2000})` or manually: `await new Promise(r=>setTimeout(r,2000)); await route.continue()`. Check: `page.waitForSelector(".spinner")`.' },
    { id:15, level:2, title:'Network Conditions Emulation', scenario:'Test the app on a 3G-like connection.', objective:'`const session=await page.context().newCDPSession(page)`. `session.send("Network.emulateNetworkConditions",{offline:false,downloadThroughput:1500000/8,uploadThroughput:750000/8,latency:100})`.', constraints:'CDP session. Throttle to 3G. Measure page load.', expectedOutput:'Page load time increases significantly. Perceived as a 3G connection.', check:'CDPSession: Chromium only. `Network.emulateNetworkConditions`: downloadThroughput/uploadThroughput in bytes/sec. `latency` in ms. Fast 3G: ~1.5Mbps down, ~750Kbps up, 40ms latency.' },
    { id:16, level:2, title:'Intercept WebSocket', scenario:'A real-time chat app uses WebSockets. Intercept and log WebSocket messages.', objective:'`page.on("websocket",ws=>{ ws.on("framereceived",f=>log("recv",f.payload)). ws.on("framesent",f=>log("sent",f.payload)) })`.', constraints:'WebSocket event. framereceived and framesent.', expectedOutput:'WebSocket messages logged: "recv: {type:message,content:Hello}"', check:'`page.on("websocket",ws)`: fires when a new WebSocket is created. `ws.url()`: WebSocket URL. `ws.on("framereceived")`: server→browser. `ws.on("framesent")`: browser→server.' },
    { id:17, level:2, title:'API Call Counting', scenario:'Verify an action triggers exactly one API call, not multiple.', objective:'Count: `let count=0; page.on("request",req=>{ if(req.url().includes("/api/search")) count++; })`. Type in search box. `expect(count).toBe(1)` (debounced).', constraints:'Request counter. Assert exact count.', expectedOutput:'Debounced search: exactly 1 API call per input pause.', check:'Counter pattern: increment on matching request. After action: assert count. Useful for: verifying debounce/throttle, preventing duplicate calls, checking caching.' },
    { id:18, level:2, title:'Response Caching Verification', scenario:'Verify the browser correctly caches API responses.', objective:'First navigation: count API calls. Second navigation to same page: count API calls. Verify second navigation makes fewer (or zero) calls due to caching.', constraints:'Cache-Control headers. Count requests. Compare.', expectedOutput:'First nav: 5 API calls. Second nav: 0 (all cached). Cache-Control: max-age=3600.', check:'Caching: depends on response `Cache-Control` headers and browser cache. Hard refresh (`Ctrl+F5`) bypasses cache. `page.reload({waitUntil:"networkidle"})` may use cache.' },
    { id:19, level:2, title:'Request Body Inspection', scenario:'Verify the correct data is sent in a POST request body.', objective:'`const requestPromise = page.waitForRequest(req=>req.url().includes("/api/order")&&req.method()==="POST")`. Submit order form. `const postData = (await requestPromise).postDataJSON()`. `expect(postData).toMatchObject({items:[{id:1,qty:2}]})`.', constraints:'waitForRequest with predicate. postDataJSON.', expectedOutput:'POST /api/order body has items array with correct product and quantity.', check:'`req.postData()`: raw string. `req.postDataJSON()`: parsed JSON. `req.postDataBuffer()`: Buffer. Check body for: correct data, no sensitive data leakage, proper serialization.' },
    { id:20, level:2, title:'Response Size Monitoring', scenario:'Monitor response sizes to detect unexpected large payloads.', objective:'`page.on("response",async res=>{ const body=await res.body(); if(body.length>100000) log("Large response",res.url(),body.length,"bytes"); })`.', constraints:'Response event. Body size check. 100KB threshold.', expectedOutput:'Large API response detected: /api/export → 2.3MB. Alert logged.', check:'`res.body()`: downloads the full response body as Buffer. `.length`: byte count. Alert: log and fail if over budget. Note: calling `res.body()` for every response may slow tests.' },
    { id:21, level:3, title:'Route Handler Priority', scenario:'Multiple route handlers match the same request. Understand priority.', objective:'Register two routes for `"**/api/users"`. First: returns mock A. Second: returns mock B. Which one wins? Add `await page.unroute("**/api/users",handler1)` to remove specific handler.', constraints:'Two handlers. Priority explanation. unroute.', expectedOutput:'LIFO: last-registered handler wins. Unroute removes specific handler.', check:'Routes are LIFO (stack). Last registered = first matched. `page.unroute(pattern)`: remove all handlers for pattern. `page.unroute(pattern,handler)`: remove specific handler. `page.unrouteAll()`: remove all.' },
    { id:22, level:3, title:'Stateful Route Mocking', scenario:'An API returns different data depending on whether a user is logged in.', objective:'`let loggedIn=false`. `page.route("/api/profile",route=>{ route.fulfill({json:loggedIn?{name:"Alice"}:{error:"unauthorized"},status:loggedIn?200:401}); })`. Test login → verify profile.', constraints:'Stateful mock. State changes with test actions.', expectedOutput:'Before login: 401. After login (set loggedIn=true): 200 with profile data.', check:'Stateful mocks: use a variable in the route handler that changes over time. Simulate: (1) initial state, (2) action, (3) changed state. Useful for multi-step flow testing.' },
    { id:23, level:3, title:'Network Traffic Recording', scenario:'Record all network traffic during a test for replay or analysis.', objective:'`const har=[]`. Collect all request/response pairs (URL, method, status, timing, body). After test: write to `test.har`. Analyze with HAR viewer.', constraints:'Collect request and response. Write HAR file. Analyze.', expectedOutput:'HAR file with all requests. Viewable in Chrome DevTools or online HAR viewer.', check:'HAR format: `{log:{entries:[{request:{method,url,headers},response:{status,headers,content}}]}}`. Playwright has built-in HAR recording: `context.routeFromHAR` and `recordHar` option.' },
    { id:24, level:3, title:'Replay from HAR', scenario:'Replay network traffic from a previously recorded HAR file.', objective:'Record: `const context=await browser.newContext({recordHar:{path:"test.har"}})`. `await context.close()` — saves the HAR. Replay: `context.routeFromHAR("test.har")`. Run tests offline.', constraints:'Record HAR. Close context. Replay HAR. Offline test.', expectedOutput:'Replay mode: no real network requests. All responses from HAR. Tests pass offline.', check:'`recordHar`: options: `{path,content:"embed"|"attach"|"omit",mode:"full"|"minimal"}`. `routeFromHAR`: replays requests that match. Not-found: `route.continue()` by default.' },
    { id:25, level:3, title:'Service Worker Interception', scenario:'A PWA uses a Service Worker for caching. Verify Service Worker intercepts requests.', objective:'Navigate to the PWA. Force reload (bypass SW): `page.goto(url,{serviceWorkers:"block"})`. Compare response with/without SW.', constraints:'serviceWorkers block. Compare with/without.', expectedOutput:'With SW: responses from cache. Without SW (block): responses from network.', check:'`page.goto(url,{serviceWorkers:"block"})`: prevents Service Workers from intercepting requests. Compare: SW serving cached response (200 from cache) vs network (200 from server).' },
    { id:26, level:3, title:'Assert No Sensitive Data in Requests', scenario:'Verify that passwords and tokens are not sent in plaintext in request URLs.', objective:'`page.on("request",req=>{ const url=req.url(); expect(url).not.toContain("password"); expect(url).not.toContain("token"); })`. Run login flow.', constraints:'Request event. URL inspection. Sensitive data check.', expectedOutput:'Login POST: credentials in body (not URL). No sensitive data in URL query params.', check:'Sensitive data in URLs: logged in server access logs, referrer headers, browser history. Always POST credentials in body. Check: `req.url()` and `req.postData()` for sensitive patterns.' },
    { id:27, level:3, title:'CORS Testing', scenario:'Verify the API correctly handles cross-origin requests.', objective:'Make a cross-origin request from the page: `fetch("https://api.otherdomain.com/data")`. Check the browser console for CORS errors. Verify `Access-Control-Allow-Origin` header.', constraints:'Cross-origin fetch. Console error check. Response header.', expectedOutput:'Correct CORS: `Access-Control-Allow-Origin: https://yourdomain.com`. No console CORS errors.', check:'CORS response header: `Access-Control-Allow-Origin`. Preflight: OPTIONS request → 204. CORS error: `page.on("console",msg=>{ if(msg.type()==="error"&&msg.text().includes("CORS")) fail() })`. ' },
    { id:28, level:3, title:'Proxy Configuration', scenario:'All requests must go through a corporate proxy for logging.', objective:'`const browser = await chromium.launch({proxy:{server:"http://proxy:8080",username:"user",password:"pass"}})`. Verify requests go through the proxy.', constraints:'Proxy config. Auth credentials. Verify via proxy logs.', expectedOutput:'All requests routed through proxy:8080. Proxy logs show test traffic.', check:'`proxy.server`: `"http://..."` or `"socks5://..."`. `proxy.bypass`: comma-separated domains to bypass. `proxy.username`/`proxy.password`: proxy auth. Can also be set per-context.' },
    { id:29, level:3, title:'Network Interception in Fixtures', scenario:'Build a reusable network mock fixture.', objective:'`networkMocks` fixture: registers common route mocks. Provides `addMock(pattern,response)` and `removeMock(pattern)`. Auto-cleans up all mocks after the test.', constraints:'Fixture. addMock. removeMock. Auto-cleanup.', expectedOutput:'`networkMocks.addMock("/api/users",[{id:1}])`. All tests using this fixture have it mocked.', check:'Fixture: collect all registered patterns. Teardown: `for(const p of patterns) await page.unroute(p)`. Provides a clean API: `addMock(pattern,json,status)` → calls `page.route(...)`.' },
    { id:30, level:3, title:'Offline Mode Testing', scenario:'Test that the app works correctly in offline mode.', objective:'`await context.setOffline(true)`. Navigate. Verify offline page/message. `await context.setOffline(false)`. Verify app recovers.', constraints:'setOffline true and false. Offline message. Recovery.', expectedOutput:'Offline: "You are offline. Some features unavailable." Online: app restored.', check:'`context.setOffline(true)`: all network requests fail. `context.setOffline(false)`: restored. Test: PWA offline mode, graceful degradation, sync after reconnect.' },
    { id:31, level:4, title:'Request/Response Modification Pipeline', scenario:'Build a flexible pipeline that transforms all API requests and responses.', objective:'`RequestPipeline` class: `addRequestTransform(fn)`, `addResponseTransform(fn)`. Each fn receives and returns the request/response. Apply all transforms via `page.route`.', constraints:'Pipeline class. Two transforms. Apply via route.', expectedOutput:'Request transform: add auth header. Response transform: add metadata field. Both applied automatically.', check:'Pipeline: `for(const transform of this.requestTransforms) request=await transform(request)`. Route: intercept, transform request, fetch, transform response, fulfill. Composable and reusable.' },
    { id:32, level:4, title:'Network Traffic Analysis', scenario:'Analyze the network traffic of a page to identify performance issues.', objective:'Record all requests (size, timing, type). Calculate: total payload size, number of requests, breakdown by type (XHR vs static assets). Generate report.', constraints:'Collect all requests. Size and timing. Report by type.', expectedOutput:'Report: 45 requests (12 XHR, 33 assets). Total: 2.4MB. Slowest: /api/dashboard (1.2s).', check:'Collect: `page.on("response",async res=>{const body=await res.body();report.push({url:res.url(),size:body.length,type:res.request().resourceType()})})`. Sort by size and timing.' },
    { id:33, level:4, title:'API Response Streaming', scenario:'An API streams large CSV data. Test that the streaming works correctly.', objective:'Make a streaming request. Collect chunks. Verify the data is complete and correctly streamed.', constraints:'Streaming response. Chunk collection. Complete data.', expectedOutput:'10,000 row CSV: received in chunks. Total size matches expected. Data complete.', check:'Playwright API testing: `response.body()` waits for the full response. For streaming: use the browser\'s `fetch` API via `page.evaluate`: `const reader=response.body.getReader()`. Collect chunks.' },
    { id:34, level:4, title:'Network Mock Server', scenario:'Build a mock server that Playwright tests can configure at runtime.', objective:'Start an Express server in global setup. Tests: `mockServer.when("GET","/api/users").return(200,[{id:1}])`. After test: reset mocks.', constraints:'Mock server. when/return API. Per-test reset.', expectedOutput:'Test 1: GET /api/users → [{id:1}]. Test 2 reset: GET /api/users → 404 (no mock).', check:'Express + in-memory route table. `when(method,path)` registers a mock. `return(status,body)` sets the response. Tests configure mocks per-test. `reset()` clears all mocks.' },
    { id:35, level:4, title:'HTTP/2 and HTTP/3 Testing', scenario:'Verify the app works with HTTP/2 and HTTP/3.', objective:'Check `response.headers()["version"]` or use CDP to inspect protocol. Verify HTTP/2 multiplexing does not cause issues.', constraints:'Protocol version check. HTTP/2 multiplexing.', expectedOutput:'API responses use HTTP/2. Multiple requests multiplexed on one connection.', check:'HTTP/2: check `server: h2` or CDP `Network.getResponseBody` with `protocol:"h2"`. Playwright uses Chrome which supports HTTP/2. HTTP/3 (QUIC): requires specific Chrome flags.' },
    { id:36, level:4, title:'Certificate Pinning Bypass', scenario:'Test an app that has strict certificate pinning (for security testing).', objective:'Use `ignoreHTTPSErrors:true` in browser launch or context. Verify self-signed certificate pages load. Note the security implications.', constraints:'ignoreHTTPSErrors. Self-signed cert. Security note.', expectedOutput:'With ignoreHTTPSErrors: self-signed cert accepted. Without: ERR_CERT_AUTHORITY_INVALID.', check:'`{ignoreHTTPSErrors:true}`: browser accepts any certificate. Use only in test environments. For corporate CA: install the cert in the browser\'s trust store. Never use in production.' },
    { id:37, level:4, title:'Request Deduplication Testing', scenario:'An API client should deduplicate identical concurrent requests.', objective:'Make 3 identical concurrent requests. Verify only 1 hits the server. The other 2 receive the same response from the dedup cache.', constraints:'3 concurrent requests. Count server hits (1). Same response.', expectedOutput:'3 requests from browser → 1 hits server → all 3 receive same response.', check:'Test dedup: `let serverHits=0; await page.route("/api/data",route=>{serverHits++;route.fulfill({json:{count:serverHits}})})`. Trigger 3 concurrent requests. `expect(serverHits).toBe(1)` if dedup works.' },
    { id:38, level:4, title:'API Gateway Testing', scenario:'Test routing, rate limiting, and auth enforcement at the API gateway layer.', objective:'Test: (1) routing (different services behind one gateway). (2) rate limiting (429 after N requests). (3) auth enforcement (401 without token). (4) CORS at gateway level.', constraints:'Four gateway concerns. Each tested independently.', expectedOutput:'Routing: /api/users → user-service. Rate limit: 429 on request 101. Auth: 401 without token. CORS: correct headers.', check:'Gateway testing: test the gateway separately from individual services. Focus on: routing correctness, rate limit behavior, auth propagation, CORS configuration.' },
    { id:39, level:4, title:'Network Timing Assertions', scenario:'Assert that API calls complete within expected timing windows.', objective:'Start timing before action. Wait for response. Calculate duration. Assert per-endpoint budgets.', constraints:'Per-endpoint budgets. Timing assertion.', expectedOutput:'GET /users: 150ms (budget 500ms: pass). POST /orders: 450ms (budget 300ms: fail).', check:'Timing: record before action, `page.waitForResponse` resolves after response. Budget: `{"/users":500,"/orders":300}`. Fail if exceeded. Alert: consider p95, not single measurements.' },
    { id:40, level:4, title:'DNS Resolution Testing', scenario:'Verify the app resolves DNS correctly and handles DNS failures gracefully.', objective:'Block DNS: `context.setOffline(true)` or use a mock DNS that returns NXDOMAIN. Navigate. Verify app shows a helpful DNS error message.', constraints:'DNS failure simulation. Error message check.', expectedOutput:'DNS failure: app shows "Cannot connect to the server. Check your internet connection."', check:'DNS failures: `setOffline(true)` causes all requests to fail, similar to DNS failure. Or use `--host-resolver-rules` Chrome flag: `--host-resolver-rules="MAP example.com 127.0.0.1"`. Test graceful handling.' },
    { id:41, level:5, title:'Full Network Traffic Assertion', scenario:'Assert the complete set of network requests made during a user journey.', objective:'Record all requests during a checkout flow. Assert: (1) no unexpected third-party calls. (2) all expected API calls made. (3) no duplicate calls. (4) correct order.', constraints:'All four assertions. Checkout flow.', expectedOutput:'Unexpected call to analytics.io: fail. Missing POST /api/orders: fail. Duplicate GET /cart: fail. Wrong order: fail.', check:'Collect all requests. Compare to expected list. Order check: `requests.map(r=>r.url())` matches expected sequence. Unexpected: filter by domain. Duplicates: check for repeated URLs.' },
    { id:42, level:5, title:'Network Security Scanner', scenario:'Scan all network traffic during test execution for security issues.', objective:'Check all requests: (1) sensitive data in URLs. (2) missing security headers. (3) mixed content (HTTP in HTTPS). (4) cookies without secure/httpOnly flags. Report findings.', constraints:'All four checks. Report per finding.', expectedOutput:'Finding: "POST /login sends password in URL". Finding: "Response missing X-Frame-Options header".', check:'Automated security checks in tests. Run as an additional check layer: `page.on("request",req=>securityCheck(req))`. Report in afterEach. Fail if critical findings.' },
    { id:43, level:5, title:'Chaos Network Testing', scenario:'Randomly inject network failures to test app resilience.', objective:'Build a chaos router: with probability P, fail a request; with probability Q, delay it; otherwise pass through. Verify app handles failures gracefully.', constraints:'Probabilistic failures. Probabilistic delays. Graceful handling.', expectedOutput:'P=0.3: 30% of requests fail. Q=0.3: 30% delayed. App shows retries and eventual success or graceful error.', check:'`Math.random()` based chaos: `if(Math.random()<P){route.abort()}else if(Math.random()<Q){delay().then(()=>route.continue())}else{route.continue()}`. Test specific scenarios with fixed seed.' },
    { id:44, level:5, title:'Network Performance Budget CI', scenario:'In CI, fail the build if any network performance budget is exceeded.', objective:'Measure: total bytes, number of requests, p99 response time. Compare to budgets. Output JUnit XML with pass/fail. Fail CI on violation.', constraints:'All three metrics. Budget config. JUnit output. CI failure.', expectedOutput:'Budget exceeded: JUnit shows failure. CI pipeline fails. Report: which budget exceeded.', check:'Budget config: `{totalBytes:1000000,requestCount:50,p99Ms:2000}`. Collect during test. Compare in afterAll. JUnit: `<testcase name="network budget" classname="performance"><failure>total bytes exceeded</failure></testcase>`.' },
    { id:45, level:5, title:'Network Mock as Contract', scenario:'Network mocks serve as living contracts between frontend and backend teams.', objective:'Frontend team defines mocks (expected API shape). Backend team generates mocks from their OpenAPI spec. Compare the two. Differences = contract violations.', constraints:'Two mock sources. Comparison algorithm. Violation report.', expectedOutput:'Frontend expects {id,name}. Backend returns {id,firstName,lastName}. Violation: "name" vs "firstName/lastName".', check:'Comparison: parse both mocks as JSON schemas. Use ajv or custom comparison. Report field-by-field differences. Run in CI to catch contract drift between teams.' },
    { id:46, level:5, title:'Network Test Isolation', scenario:'Tests that run in parallel must not share network state.', objective:'Verify that mocking a route in test A does not affect test B (running in parallel). Each test has its own page and context.', constraints:'Parallel tests. Independent mocks. Verify isolation.', expectedOutput:'Test A mocks /api/users → mock response. Test B simultaneously: /api/users → real response. No cross-contamination.', check:'`page.route` is scoped to the page (and context). Parallel tests use different pages. Worker isolation: different page instances. `context.route` is scoped to context (same worker). ' },
    { id:47, level:5, title:'Real-Time Network Dashboard', scenario:'Build a live dashboard showing network activity during test execution.', objective:'WebSocket server: receives request/response events from tests. Dashboard: displays active requests, response times, error rates. Updates in real-time.', constraints:'WebSocket server. Real-time events. Dashboard.', expectedOutput:'During test run: dashboard shows live request stream. Error rate spike: red alert. P99 breach: warning.', check:'Architecture: tests emit events via `ws.send()`. Dashboard: `ws.on("message")` updates state. Chart: request/s over time. Alert: threshold violations. Clean up on test end.' },
    { id:48, level:5, title:'API Contract Drift Detection', scenario:'Detect when the real API response no longer matches the mock used in tests.', objective:'Run tests with mocks. Also run against the real API. Compare all responses. Report any differences. Schedule daily.', constraints:'Mock run. Real run. Comparison. Daily schedule.', expectedOutput:'Mock: {id:1,name:"Alice"}. Real: {id:1,firstName:"Alice",lastName:"Smith"}. Drift detected: "name" missing in real, "firstName"/"lastName" added.', check:'Two-run comparison: run tests with `route.fulfill`, capture mock responses. Run tests without routes, capture real responses. Compare field by field. Alert on drift.' },
    { id:49, level:5, title:'Network Observability Platform', scenario:'Build a comprehensive network observability platform for Playwright tests.', objective:'Platform: (1) Request/response logging. (2) Performance metrics (timing, size). (3) Error detection. (4) Security scanning. (5) Contract validation. (6) Reporting dashboard.', constraints:'All 6 components. Integrated with Playwright test lifecycle.', expectedOutput:'After each test: report with all 6 dimensions. Dashboard: aggregated across suite.', check:'Integration: auto fixture initializes the platform. `page.on("request")` and `page.on("response")` feed all components. afterEach: report. afterAll: aggregate. Dashboard: Express + Chart.js.' },
    { id:50, level:5, title:'Full Network Testing Framework', scenario:'Build a production-grade network testing framework.', objective:'Build: (1) Mock server with stateful routing. (2) HAR recording and replay. (3) Network chaos injection. (4) Performance budget enforcement. (5) Security scanning. (6) Contract drift detection. (7) Real-time monitoring dashboard.', constraints:'All 7 components. npm package. CI integration.', expectedOutput:'`import {NetworkTest} from "@company/network-test"`. `NetworkTest.mock().chaos().budget().security().run()`.', check:'Fluent builder: each component is optional, activated by method call. Core: page.route pipeline. HAR: context option. Dashboard: Express server. CI: exit code based on violations.' },
  ],

  visual: [
    { id:1, level:1, title:'First Visual Snapshot', scenario:'Take a screenshot of the homepage and save it as a baseline.', objective:'`await expect(page).toHaveScreenshot("homepage.png")`. First run: saves the baseline. Second run: compares against the baseline. Explore the `playwright-snapshots` directory.', constraints:'toHaveScreenshot. First and second run. Snapshot directory.', expectedOutput:'First run: "homepage.png" created. Second run: comparison passes with no pixel difference.', check:'Snapshots stored in `__snapshots__/{testFileName}/{testTitle}/{snapshotName}` by default. First run with `--update-snapshots` or fresh run (no existing snapshot) creates the baseline.' },
    { id:2, level:1, title:'Element Screenshot', scenario:'Take a screenshot of only a specific UI component.', objective:'`const card = page.getByTestId("product-card")`. `await expect(card).toHaveScreenshot("card.png")`. Only the card is captured (clipped to its bounding box).', constraints:'Locator screenshot. Specific component. Clipped.', expectedOutput:'Snapshot captures only the product card, not the full page. Background clipped.', check:'`expect(locator).toHaveScreenshot(name)`: captures the bounding box of the element. Full page: `expect(page).toHaveScreenshot(name)`. Both are pixel-by-pixel comparisons.' },
    { id:3, level:1, title:'Screenshot with Threshold', scenario:'Minor antialiasing differences cause the comparison to fail. Allow a small pixel difference.', objective:'`expect(page).toHaveScreenshot("page.png",{maxDiffPixels:100})`. Up to 100 pixels can differ without failing.', constraints:'maxDiffPixels option. Explain threshold.', expectedOutput:'99 pixel difference: pass. 101 pixel difference: fail.', check:'`maxDiffPixels`: absolute pixel count. `threshold`: 0-1 ratio of different pixels to total pixels. `maxDiffPixelRatio`: 0-1 ratio version. Use the least permissive threshold that avoids flakiness.' },
    { id:4, level:1, title:'Masking Dynamic Content', scenario:'A timestamp updates every second. Mask it to prevent comparison failures.', objective:'`expect(page).toHaveScreenshot("page.png",{mask:[page.locator(".timestamp")]})`. The timestamp area is replaced with a solid box before comparison.', constraints:'mask option. Dynamic content. Colored box.', expectedOutput:'Timestamp area: solid pink box in screenshot. Comparison ignores this area.', check:'`mask:[locator1,locator2]`: masks the bounding boxes with `#FF00FF` by default. `maskColor:"#00FF00"`: change mask color. Multiple masks: pass an array.' },
    { id:5, level:1, title:'Updating Snapshots', scenario:'A deliberate UI change causes snapshots to fail. Update the baselines.', objective:'Change a button color in CSS. Run tests. Get failures. Run with `--update-snapshots`. Verify new snapshots are saved.', constraints:'Deliberate change. Run fails. Update. Rerun passes.', expectedOutput:'Without update: fail with diff image. `--update-snapshots`: new baseline saved. Rerun: pass.', check:'`npx playwright test --update-snapshots`: updates all failing snapshots. `--update-snapshots=changed`: only updates actually different ones. Review diffs before committing updated snapshots.' },
    { id:6, level:1, title:'Screenshot in Failure', scenario:'When a test fails, automatically capture a screenshot for debugging.', objective:'Configure `use.screenshot:"only-on-failure"`. Run a failing test. Locate the screenshot in `test-results/`. Open the HTML report to see it inline.', constraints:'Config-based failure screenshot. Locate artifact.', expectedOutput:'Failing test: screenshot at `test-results/.../test-failed.png`. Visible in HTML report.', check:'`use.screenshot:"only-on-failure"`: captures the page state at the moment of failure. `"retain-on-failure"`: captures on test failure or retry. Screenshots appear in HTML report.' },
    { id:7, level:1, title:'Full Page Screenshot', scenario:'Take a screenshot of an entire long page, including below-the-fold content.', objective:'`expect(page).toHaveScreenshot("full-page.png",{fullPage:true})`. The screenshot captures the entire scrollable page.', constraints:'fullPage:true. Verify full page captured.', expectedOutput:'Screenshot height much taller than viewport. All content visible.', check:'`fullPage:true`: scrolls and stitches to capture the entire page. Default: viewport only. Note: sticky headers may appear multiple times in full-page screenshots.' },
    { id:8, level:1, title:'Clip Screenshot', scenario:'Take a screenshot of a specific region of the page (not a locator).', objective:'`expect(page).toHaveScreenshot("hero.png",{clip:{x:0,y:0,width:1280,height:400}})`. Captures only the hero section.', constraints:'clip option. x,y,width,height.', expectedOutput:'Screenshot: only the first 400px height of the page (hero section).', check:'`clip:{x,y,width,height}`: pixel coordinates relative to the viewport. For element screenshots without a locator: calculate the bounding box from `element.boundingBox()`. ' },
    { id:9, level:1, title:'Screenshot Comparison Report', scenario:'Review what changed between the current and baseline screenshots.', objective:'Run tests with one changed component. Open the HTML report. Navigate to the failing visual test. View the three-panel diff (baseline, actual, diff highlighted).', constraints:'Failing visual test. HTML report. Three panels.', expectedOutput:'HTML report shows: left panel (baseline), middle panel (actual), right panel (pink diff overlay).', check:'HTML report: `npx playwright show-report`. Visual diff view: three panels. Diff: changed pixels highlighted. Download diff image for review. `--reporter=html` in config.' },
    { id:10, level:1, title:'Multi-Browser Visual Testing', scenario:'Verify the UI looks the same across Chromium, Firefox, and WebKit.', objective:'Three projects (chromium, firefox, webkit). Each has its own snapshot directory. Snapshots are per-browser. Run all three and compare across browsers.', constraints:'Three browser projects. Per-browser snapshots.', expectedOutput:'Chromium: chromium-specific snapshot. Firefox: its own. WebKit: its own. Cross-browser differences are expected and handled.', check:'Snapshots are suffixed by project name: `button-chromium.png`, `button-firefox.png`. Cross-browser comparison: not built-in — compare snapshots manually or write a custom script.' },
    { id:11, level:2, title:'Dark Mode Visual Testing', scenario:'Verify the UI is correct in both light and dark mode.', objective:'Test with light mode: `page.emulateMedia({colorScheme:"light"})`. Take screenshot. Test with dark mode: `page.emulateMedia({colorScheme:"dark"})`. Take screenshot. Compare both baselines.', constraints:'emulateMedia. Two color schemes. Two snapshots.', expectedOutput:'light-mode.png: white background. dark-mode.png: dark background. Both saved as separate baselines.', check:'`page.emulateMedia({colorScheme:"light"|"dark"})`: changes the CSS `prefers-color-scheme` media query. `media:"print"`: print styles. Combine with `@media (prefers-color-scheme: dark) { ... }` CSS.' },
    { id:12, level:2, title:'Responsive Visual Testing', scenario:'Verify the UI is correct at mobile, tablet, and desktop breakpoints.', objective:'Three viewport sizes: `{width:375,height:812}` (mobile), `{width:768,height:1024}` (tablet), `{width:1280,height:800}` (desktop). Take screenshot at each.', constraints:'Three viewports. Three snapshots.', expectedOutput:'Mobile: stacked layout. Tablet: two-column. Desktop: full width.', check:'`page.setViewportSize({width,height})` or `browser.newContext({viewport:{width,height}})`. Project-level: `use:{viewport:{width,height}}`. Device presets: `devices["iPhone 14"]`.' },
    { id:13, level:2, title:'Animation Handling', scenario:'CSS animations cause visual test flakiness because screenshots capture mid-animation states.', objective:'Approach 1: `page.emulateMedia({reducedMotion:"reduce"})` — disables animations via CSS. Approach 2: `page.evaluate(()=>document.getAnimations().forEach(a=>a.finish()))` — complete animations.', constraints:'Two approaches. Verify snapshot is stable.', expectedOutput:'With animation disabled/finished: same screenshot every run. Without: 30% of runs fail.', check:'`reducedMotion:"reduce"`: respects `prefers-reduced-motion` CSS media query. Animations with `@media (prefers-reduced-motion:reduce)` will be disabled/slowed. `a.finish()`: jumps to end state.' },
    { id:14, level:2, title:'Snapshot Configuration', scenario:'Configure where snapshots are stored and how they are named.', objective:'Config: `snapshotDir:"./snapshots"`, `snapshotPathTemplate:"{snapshotDir}/{platform}/{projectName}/{testFileName}/{arg}{ext}"`. Explore the resulting directory structure.', constraints:'snapshotDir. snapshotPathTemplate. Directory exploration.', expectedOutput:'linux/chromium/login.spec.ts/login-page.png. Organized by platform, project, and file.', check:'`snapshotPathTemplate` tokens: `{snapshotDir}`, `{platform}` (linux/win32/darwin), `{projectName}`, `{testFilePath}`, `{testFileName}`, `{testTitle}`, `{arg}`, `{ext}`. Customize for your CI structure.' },
    { id:15, level:2, title:'Visual Testing with Fixtures', scenario:'Each test in a group needs to verify its starting state visually before taking actions.', objective:'`visualBaseline` fixture: takes a screenshot and saves it. All tests in the group call this fixture before their assertions. Ensures visual baseline per test.', constraints:'Fixture that takes screenshot. Used in multiple tests.', expectedOutput:'Each test: baseline screenshot saved before actions. Post-action screenshot compared to it.', check:'Custom fixture: `async({page},use)=>{await use(async(name)=>{await expect(page).toHaveScreenshot(name)})}`. Tests call `await visualBaseline("test-start.png")` to verify initial state.' },
    { id:16, level:2, title:'Component-Level Visual Testing', scenario:'A design system has 50 components. Test each component visually in isolation.', objective:'For each component: navigate to the Storybook story. Take a screenshot. Compare to baseline. Run all 50 as a suite.', constraints:'Storybook stories. 50 components. 50 baselines.', expectedOutput:'50 snapshots. Changes to Button → button.png fails. Other components unaffected.', check:'Pattern: `for(const story of stories) { await page.goto(storyUrl(story)); await expect(page).toHaveScreenshot(story.id+".png"); }`. Or: one test per component. Storybook: visual testing friendly.' },
    { id:17, level:2, title:'Visual Regression on CI', scenario:'Visual regressions must be caught on every PR without manual review.', objective:'CI workflow: run visual tests. On failure: upload diff images as artifacts. Block PR merge on failure. Show diff images in PR comment.', constraints:'CI failure on regression. Diff image artifacts. PR comment.', expectedOutput:'PR changes button color → visual test fails → CI blocks merge → diff image in PR comment.', check:'Upload artifacts: `actions/upload-artifact@v3`. PR comment: `gh pr comment`. Diff images: located in `test-results/` after failure. Block merge: required status checks.' },
    { id:18, level:2, title:'Cross-OS Snapshot Differences', scenario:'Snapshots taken on macOS look different from those taken on Linux (font rendering).', objective:'Use Docker to run visual tests on a consistent OS (Linux). Configure CI to use the same Docker image. Explain why cross-OS differences occur.', constraints:'Docker-based testing. OS consistency. Explain differences.', expectedOutput:'macOS snapshot vs Linux: different font anti-aliasing. Solution: always use Linux in CI.', check:'Font rendering differs by OS (ClearType/macOS subpixel/Linux FreeType). Solution: run ALL visual tests in a Docker container with a fixed Linux image. Never compare macOS and Linux snapshots.' },
    { id:19, level:2, title:'Screenshot in Custom Reporter', scenario:'A custom reporter that attaches baseline and actual screenshots to the test report.', objective:'`onTestEnd`: read the baseline and actual screenshots. Attach both to the report. Show them side by side.', constraints:'Custom reporter. Read snapshot files. Attach to report.', expectedOutput:'Report shows: baseline image and actual image side-by-side for each visual test.', check:'`testInfo.attachments`: array of `{name,contentType,path|body}`. Reporter `onTestEnd(test,result)`: `result.attachments` for existing attachments. Custom reporter can add more.' },
    { id:20, level:2, title:'Visual Testing After Interaction', scenario:'Verify the UI looks correct after a user interaction (e.g., modal open).', objective:'Open a modal. Wait for transition to complete. Take screenshot. Close modal. Take another screenshot. Compare both to their baselines.', constraints:'Two interaction states. Two snapshots.', expectedOutput:'modal-open.png: modal visible and styled correctly. modal-closed.png: modal gone.', check:'Before screenshot: wait for animation to complete (`page.waitForFunction(()=>!document.querySelector(".modal.animating")`). Or: `page.emulateMedia({reducedMotion:"reduce"})` to disable animations.' },
    { id:21, level:3, title:'Pixelwise Diff Analysis', scenario:'A visual test failed. Analyze which area changed and why.', objective:'Open the diff image. Identify the changed area (e.g., button padding changed). Find the corresponding CSS change. Correlate with the git diff.', constraints:'Diff analysis. Area identification. CSS correlation.', expectedOutput:'Diff shows changed pixels in the top-right corner. Git diff: `padding-right: 8px` → `padding-right: 12px`. Cause identified.', check:'Diff image: colored pixels show changes. Hot areas: lots of changes. Cold areas: no changes. Correlation: `git log --oneline` + `git diff HEAD~1` to find CSS changes.' },
    { id:22, level:3, title:'Visual Testing with Dynamic Data', scenario:'A product listing page shows prices that change. Mask them during visual testing.', objective:'Mask all price elements: `mask:[page.locator(".price")]`. Take screenshot. Prices show as solid boxes. Layout comparison works without price interference.', constraints:'Dynamic price masking. Layout-only comparison.', expectedOutput:'Screenshot: prices replaced with pink boxes. Layout, spacing, fonts compared. Price changes ignored.', check:'Mask strategy: mask all dynamic content (prices, dates, user names, badges). Only static structure (layout, spacing, colors, fonts) compared. Catch layout regressions, not data changes.' },
    { id:23, level:3, title:'Visual Baseline Management', scenario:'The baseline snapshots are outdated. Workflow for safely updating them.', objective:'(1) Review the current diff (what changed). (2) Accept if intentional. (3) `--update-snapshots`. (4) Commit new baselines. (5) Document why they changed.', constraints:'Diff review. Update command. Commit workflow.', expectedOutput:'Review: 3 snapshots changed. Accepted: button redesign. Rejected: unintended text shift. Updated: 3. Committed with message "visual: update button snapshots after redesign".', check:'Workflow: never blindly `--update-snapshots`. Review each diff. Accept only intentional changes. Reject regressions. Commit baselines in the same PR as the UI change.' },
    { id:24, level:3, title:'Visual Testing for Print Styles', scenario:'A report page must look correct when printed.', objective:'`page.emulateMedia({media:"print"})`. Take screenshot. Compare to print-style baseline. Verify: page breaks, print-only elements, hidden navigation.', constraints:'media:"print". Print screenshot. Verify print-only content.', expectedOutput:'Print mode: navigation hidden, print-only content visible, correct fonts.', check:'`page.emulateMedia({media:"print"})`: applies `@media print` CSS. Print-specific: `display:none` for nav, different fonts, page breaks. Screenshot shows print layout.' },
    { id:25, level:3, title:'Visual Testing Optimization', scenario:'50 visual tests take 10 minutes. Optimize to under 5 minutes.', objective:'Optimization strategies: (1) Parallel workers. (2) Reuse browser context. (3) Only screenshot changed areas. (4) Skip screenshots for unrelated tests. (5) Use lighter viewport.', constraints:'All five strategies. Measure before and after.', expectedOutput:'Before: 10 min. After: 4 min. Each optimization: documented time saving.', check:'Parallelism: biggest gain. Reuse context: saves browser launch time. Smaller viewport: faster screenshot. Selective testing: only run visual tests for changed components (requires dependency analysis).' },
    { id:26, level:3, title:'Visual Testing for Accessibility', scenario:'Verify that the UI color contrast meets WCAG AA standards.', objective:'Use `page.evaluate` to run an axe-core accessibility check. Verify no contrast violations. Also use toHaveScreenshot with a special configuration that highlights contrast issues.', constraints:'axe-core. Contrast check. toHaveScreenshot.', expectedOutput:'axe: 0 contrast violations. Visual: no highlighted elements.', check:'axe-core: `const results=await new AxeBuilder({page}).analyze()`. `expect(results.violations).toHaveLength(0)`. For contrast: `runOnly:{rules:["color-contrast"]}`. ' },
    { id:27, level:3, title:'Visual Testing with Storybook', scenario:'Run visual tests against Storybook stories automatically.', objective:'Script: fetch the Storybook story list from `/story-book/stories.json`. For each story: navigate to `/iframe.html?id={storyId}`. Take screenshot. Compare to baseline.', constraints:'Storybook story list. Per-story screenshot. Baselines.', expectedOutput:'50 stories × 1 screenshot each = 50 baselines. Changed story → visual test fails.', check:'Storybook `stories.json`: `{stories:{storyId:{name,title,kind}}}`. Navigate: `/iframe.html?id={storyId}&viewMode=story`. Wait for: `.story-is-rendered` or similar Storybook indicator.' },
    { id:28, level:3, title:'Incremental Visual Testing', scenario:'Only run visual tests for stories/components that have changed in the current PR.', objective:'`git diff --name-only HEAD origin/main`: get changed files. Map to component stories. Run visual tests only for those components.', constraints:'git diff. File-to-component mapping. Selective test run.', expectedOutput:'PR changes Button.tsx → run only Button visual tests. 2 tests instead of 50.', check:'Mapping: `Button.tsx` → `Button.stories.ts` → story IDs. `--grep` to run specific tests. Alternative: Playwright `testNamePattern` CLI flag. This is "impacted visual testing".' },
    { id:29, level:3, title:'Visual Regression Email Report', scenario:'Send a visual regression report via email after the nightly run.', objective:'Collect failed visual tests. Attach diff images. Send email via SendGrid API. Include: test name, baseline, actual, diff.', constraints:'Collect failures. Attach images. Send email.', expectedOutput:'Email: "3 visual regressions found: [button], [header], [footer]. Diffs attached."', check:'After run: custom reporter collects failures. `onEnd(result)`: if any failures, send email. Embed diff images as base64 or link to CI artifacts. Use SendGrid or similar.' },
    { id:30, level:3, title:'Visual Testing in Monorepo', scenario:'A monorepo has 10 packages, each with their own visual snapshots.', objective:'Each package has its own snapshot directory. CI: run visual tests per package. Root config: 10 projects, each with its own `snapshotDir`.', constraints:'10 projects. Per-package snapshotDir. Independent baselines.', expectedOutput:'Package-a changes → only package-a visual tests fail. Package-b unaffected.', check:'Per-package config: `projects:[{name:"pkg-a",testDir:"packages/pkg-a/e2e",snapshotDir:"packages/pkg-a/__snapshots__"},{...}]`. Independent baselines prevent cross-package interference.' },
    { id:31, level:4, title:'Pixel-Perfect Visual Testing', scenario:'Design team requires pixel-perfect comparison with zero tolerance.', objective:'`toHaveScreenshot({maxDiffPixels:0})`. Any pixel difference fails. Workflow: run on design-approved screenshots. Fail-fast on any change.', constraints:'Zero tolerance. Fail on any pixel. Workflow.', expectedOutput:'1 pixel difference: fail with diff image showing the single changed pixel.', check:'Zero tolerance: `maxDiffPixels:0` or `threshold:0`. Very strict — fails on anti-aliasing. Use with care. Only appropriate for pixel-perfect design systems, not general apps.' },
    { id:32, level:4, title:'Visual Testing with AI Assistance', scenario:'Use AI to classify visual changes as "intentional" or "regression".', objective:'On failure: send the diff image to a vision AI model. Classify: is this a regression or an intentional change? If regression: fail. If intentional: prompt to update baseline.', constraints:'AI classification. Diff image input. Pass/fail decision.', expectedOutput:'AI: "Button padding changed by 4px — likely intentional (matches design spec). Update baseline? [Y/N]"', check:'Vision AI: send base64-encoded diff image to GPT-4o or Claude vision API. Prompt: "Is this a UI regression or an intentional design change?" Parse response for classification.' },
    { id:33, level:4, title:'Visual Testing with Feature Flags', scenario:'A feature flag changes the UI. Visual tests must cover both states.', objective:'Two test variants: with flag ON and with flag OFF. Each has its own snapshot. Toggle the flag via cookie/localStorage before the screenshot.', constraints:'Two flag states. Two snapshots. Flag toggle.', expectedOutput:'flag-on.png: new UI. flag-off.png: old UI. Both baselines maintained.', check:'Flag toggle: `page.addInitScript(()=>localStorage.setItem("feature_new_ui","true"))`. Or cookie: `context.addCookies([{name:"ff",value:"1",...}])`. Two tests: one per state.' },
    { id:34, level:4, title:'Visual Testing Performance', scenario:'Visual tests are slow due to PNG compression. Optimize screenshot performance.', objective:'(1) Use JPEG: `toHaveScreenshot({animations:"disabled"})`. (2) Reduce viewport. (3) Use element screenshots instead of full page. Measure impact on test duration.', constraints:'Three optimizations. Measure duration.', expectedOutput:'Full page PNG: 5s per test. Element JPEG: 0.8s per test. 6x improvement.', check:'PNG vs JPEG: Playwright uses PNG by default. JPEG not supported for `toHaveScreenshot`. Optimization: element screenshots (smaller area), disabled animations (faster capture), reduced viewport.' },
    { id:35, level:4, title:'Visual Testing for Emails', scenario:'Email templates must render correctly in email clients.', objective:'Render the email template in the browser. Take a screenshot. Compare to baseline. Use `page.setContent(htmlTemplate)` to load the HTML directly.', constraints:'page.setContent. Email HTML. Screenshot baseline.', expectedOutput:'Email template rendered in browser. Screenshot saved. Changes to template → visual regression.', check:'`page.setContent(html)`: loads raw HTML. Useful for email templates, generated HTML. Email-specific CSS: `style` tags, inline styles. No JavaScript in email.' },
    { id:36, level:4, title:'Visual Testing Flakiness Sources', scenario:'Identify and fix all sources of visual test flakiness.', objective:'Flakiness sources: (1) animations. (2) dynamic content. (3) fonts. (4) OS rendering. (5) timing. For each: identify, demonstrate, and fix.', constraints:'All 5 sources. Demonstrate flakiness. Fix each.', expectedOutput:'Before fix: 3/10 runs fail. After fixes: 10/10 pass.', check:'Fixes: (1) `reducedMotion:"reduce"`. (2) mask dynamic. (3) use web fonts, wait for `fonts.ready`. (4) Docker. (5) wait for network idle and animations. Run 10x to verify.' },
    { id:37, level:4, title:'Visual Testing with CDN-Served Assets', scenario:'Images and fonts are served from a CDN. Visual tests fail intermittently when CDN is slow.', objective:'Wait for all images to load: `page.waitForLoadState("networkidle")`. Or: `page.evaluate(()=>Promise.all(Array.from(document.images).filter(i=>!i.complete).map(i=>new Promise(r=>{i.onload=r;i.onerror=r}))))`. Then screenshot.', constraints:'Wait for all images. Screenshot only after.', expectedOutput:'All images loaded → stable screenshot. Screenshot before load → broken images visible.', check:'`networkidle`: waits until no requests for 500ms. Images: check `img.complete`. Fonts: `document.fonts.ready`. Background images: harder — wait for networkidle.' },
    { id:38, level:4, title:'Visual A/B Testing Verification', scenario:'Two UI variants are served. Visually verify both look correct and are visually distinct.', objective:'Variant A: control (existing UI). Variant B: new UI. Take screenshots of both. Verify they look different from each other. Also verify each looks correct against their own baseline.', constraints:'Two variants. Different from each other. Each correct.', expectedOutput:'A-baseline matches A. B-baseline matches B. A and B are visually different (the experiment is showing different UIs).', check:'Distinctness: compare A and B snapshots — they should differ. Correctness: each matches its own baseline. Regression: neither should match the OTHER\'s baseline (they are different on purpose).' },
    { id:39, level:4, title:'Visual Testing for Charts', scenario:'A data visualization chart must match its baseline (with seeded data).', objective:'Seed the chart with fixed data (via mock). Wait for chart render. Take screenshot. Compare to baseline.', constraints:'Fixed data via mock. Wait for render. Screenshot.', expectedOutput:'Chart with seeded data: identical screenshot every run.', check:'Chart render wait: `page.waitForSelector(".chart-ready")` or wait for animation to complete. Fixed data: mock the data API with a stable response. Randomized data → mask the chart area.' },
    { id:40, level:4, title:'Visual Testing CI/CD Integration', scenario:'Integrate visual testing into a GitLab CI/CD pipeline with merge request integration.', objective:'`.gitlab-ci.yml`: visual test stage. On failure: upload diff artifacts. Post merge request comment with failure summary.', constraints:'GitLab CI YAML. Artifacts. MR comment.', expectedOutput:'MR: visual tests fail → CI stage fails → diff artifacts uploaded → MR comment: "3 visual regressions".', check:'GitLab artifacts: `artifacts:{when:on_failure,paths:["test-results/"]}`. MR comment: `curl` GitLab API. Status: `allow_failure:false` to block the MR on failure.' },
    { id:41, level:5, title:'Visual Testing Platform', scenario:'Build a complete visual testing platform for a large organization.', objective:'Platform: (1) Baseline storage (S3/GCS). (2) Diff generation service. (3) Approval workflow (web UI). (4) Slack notifications. (5) PR status checks. (6) Dashboard.', constraints:'All 6 components. Integration with GitHub.', expectedOutput:'PR: visual change detected → Slack notification → approval UI → approve or reject → GitHub status updated.', check:'Architecture: test run uploads diffs to S3. CI calls diff service. Web UI: review and approve. Approve: update baseline in S3. Status check: approved=pass, rejected=fail.' },
    { id:42, level:5, title:'AI-Powered Visual Diff', scenario:'Use computer vision AI to better understand visual differences and classify them.', objective:'For each diff: (1) Extract changed region. (2) Classify change type (layout/color/text/missing element). (3) Assess severity. (4) Suggest fix. (5) Estimate intentionality.', constraints:'5 AI classifications. Per-diff report.', expectedOutput:'Diff: "Button text changed from \"Submit\" to \"Send\". Type: text. Severity: low. Intentional: likely (matches copywriting ticket).', check:'Vision AI: send crop of changed region. Structured prompt: "Classify this UI change: what changed, type (layout/color/text/element), severity (low/medium/high), intentional (yes/no/unclear)". Parse JSON response.' },
    { id:43, level:5, title:'Visual Testing for Responsive Breakpoints', scenario:'An app has 8 breakpoints. Visual testing must cover all.', objective:'8 viewport sizes. 50 components. 400 total snapshots (8 × 50). Run in parallel. Fail fast on regression.', constraints:'400 snapshots. Parallel. Fail fast.', expectedOutput:'400 snapshots. Parallel: 40 workers, 10s total. Single regression: fail immediately.', check:'Projects: one per breakpoint. Or: parameterized tests with `for(const viewport of viewports)`. Parallelism: 8 projects × 5 workers each = 40 parallel. Fail fast: no retries, `failOnFlake:false`.' },
    { id:44, level:5, title:'Visual Testing for Theming', scenario:'A white-label product has 20 custom themes. Each must be visually tested.', objective:'20 themes × 50 components = 1000 snapshots. Load each theme via CSS variable override. Screenshot each component per theme.', constraints:'20 themes. Per-theme snapshots. CSS variable override.', expectedOutput:'1000 snapshots. Theme A changes primary color → only Theme A snapshots fail.', check:'Theme loading: `page.addStyleTag({content:":root{--primary:#ff0000;}"})`. Or: `page.addInitScript(()=>document.documentElement.setAttribute("data-theme","dark"))`. One project per theme.' },
    { id:45, level:5, title:'Visual Testing with Design Tokens', scenario:'Verify the UI correctly applies design tokens (spacing, colors, typography).', objective:'For each design token: verify its visual application. E.g., `--spacing-4: 16px` → verify an element that uses it has 16px margin.', constraints:'Token enumeration. Visual verification per token.', expectedOutput:'Token `--color-primary: #0070f3` → button background should be #0070f3. Verify via screenshot and CSS inspection.', check:'Two approaches: (1) visual screenshot comparison (holistic). (2) CSS value inspection via `getComputedStyle` (precise). Combine: screenshot for overall look, CSS for specific token verification.' },
    { id:46, level:5, title:'Cross-Browser Visual Normalization', scenario:'Different browsers render text slightly differently. Normalize differences for comparison.', objective:'Build a visual normalization process: (1) Take screenshots on all browsers. (2) Detect browser-specific differences. (3) Create normalized baselines. (4) Compare to normalized baseline on each browser.', constraints:'All 3 browsers. Normalization algorithm. Normalized baselines.', expectedOutput:'Chrome baseline: includes Chrome rendering quirks. Firefox test vs Firefox baseline: passes despite being different from Chrome baseline.', check:'Each browser has its OWN baseline. Cross-browser comparison: structural (layout, not pixel-perfect). Use `allowedMismatchedPixels` or compare element positions (getBoundingClientRect) instead of screenshots.' },
    { id:47, level:5, title:'Visual Testing for User Flows', scenario:'Capture the visual state at each step of a multi-step checkout flow.', objective:'Step 1: cart → cart.png. Step 2: shipping → shipping.png. Step 3: payment → payment.png. Step 4: confirmation → confirmation.png. Each step compared to its baseline.', constraints:'4-step flow. Screenshot after each step. 4 baselines.', expectedOutput:'checkout flow: 4 screenshots, all matching baselines. UI regression in step 2 → shipping.png fails.', check:'Flow testing: navigate each step, take screenshot, continue. Teardown: cleanup test order. Advantage: catches step-specific regressions, not just end state.' },
    { id:48, level:5, title:'Visual Testing Observability', scenario:'Monitor visual test performance, flakiness rates, and coverage over time.', objective:'Track: (1) test duration per snapshot. (2) flakiness rate per snapshot. (3) diff pixel count over time. (4) coverage (% of components with visual tests).', constraints:'All 4 metrics. Historical tracking. Dashboard.', expectedOutput:'Dashboard shows: avg screenshot time 1.2s. Flakiest snapshot: "price-label" (30% flaky). Coverage: 72%.', check:'Storage: time-series database (InfluxDB) or JSON files. Metrics: captured in custom reporter. Dashboard: Grafana or custom HTML. Trends: plot over time to identify regressions or improvements.' },
    { id:49, level:5, title:'Automated Visual Regression Triage', scenario:'After a deployment, automatically triage which visual regressions are critical vs minor.', objective:'Critical: regressions in core user flows (login, checkout, key CTAs). Minor: regressions in footer, sidebar, non-critical UI. Alert team immediately for critical, queue minor for review.', constraints:'Criticality classification. Critical alert. Minor queue.', expectedOutput:'Critical: Slack alert immediately. Minor: added to review queue. Dashboard: critical count, minor count.', check:'Classification: map test names/components to criticality tiers. `{critical:["login","checkout","hero"],minor:["footer","sidebar"]}`. Filter regressions by tier. Alert: webhook to Slack for critical.' },
    { id:50, level:5, title:'Full Visual Testing Framework', scenario:'Build a production-grade visual testing framework for an enterprise application.', objective:'Build: (1) Multi-browser, multi-viewport, multi-theme coverage. (2) AI-powered diff classification. (3) Approval workflow. (4) Baseline management (S3). (5) CI/CD integration. (6) Design token verification. (7) Dashboard and observability.', constraints:'All 7 components. npm package. Team workflow.', expectedOutput:'`import {VisualTest} from "@company/visual-test"`. `VisualTest.withThemes().withBreakpoints().withApproval().run()`.', check:'Fluent builder. Core: Playwright toHaveScreenshot. AI: vision API for diff classification. Storage: S3 for baselines. Approval: web UI. CI: GitHub Actions integration. Dashboard: real-time.' },
  ],

  pom: [
    { id:1, level:1, title:'First Page Object', scenario:'Create a Page Object for the login page.', objective:'Create `LoginPage` class with: `url="/login"`, `emailInput=page.getByLabel("Email")`, `passwordInput=page.getByLabel("Password")`, `submitButton=page.getByRole("button",{name:"Sign in"})`. Method: `goto()`.', constraints:'Class with three locators. goto method.', expectedOutput:'`const login = new LoginPage(page)`. `login.goto()`. `login.emailInput.fill("user@example.com")`.', check:'Page Object: class that wraps locators for a page. Constructor: `constructor(page){this.page=page}`. Locators: properties on the class. goto: `this.page.goto(this.url)`. Avoids duplicating locators.' },
    { id:2, level:1, title:'Actions in Page Objects', scenario:'Add action methods to the LoginPage that encapsulate user flows.', objective:'Method `login(email,password)`: fills email, fills password, clicks submit. Method `expectError(message)`: asserts error text. Use both in a test.', constraints:'login() method. expectError() method. Use in test.', expectedOutput:'`loginPage.login("user@example.com","wrongpassword")`. `loginPage.expectError("Invalid credentials")`.', check:'Action method: encapsulates a multi-step interaction. `async login(email,password){await this.emailInput.fill(email);await this.passwordInput.fill(password);await this.submitButton.click();}`. Returns void or navigates.' },
    { id:3, level:1, title:'Page Object Composition', scenario:'After login, the user lands on the Dashboard. Create a DashboardPage.', objective:'LoginPage.login() returns a DashboardPage. `const dashboard = await loginPage.login(email,password)`. `await dashboard.expectWelcomeMessage("Alice")`.', constraints:'LoginPage returns DashboardPage. Composition.', expectedOutput:'`const dashboard = await loginPage.login(email,password)`. dashboard is a DashboardPage with dashboard locators.', check:'Method return type: `async login(email,password):Promise<DashboardPage>{...;return new DashboardPage(this.page);}`. Chains page flows naturally. TypeScript: `: Promise<DashboardPage>` return type.' },
    { id:4, level:1, title:'Organizing Page Objects', scenario:'A project has 10 pages. Organize the Page Object classes in a clean directory structure.', objective:'Directory: `pages/`. Files: `LoginPage.ts`, `DashboardPage.ts`, `ProductPage.ts`. Index file: `pages/index.ts` exports all. Tests import from `../pages`.', constraints:'Directory structure. Index export. Clean import.', expectedOutput:'`import {LoginPage,DashboardPage} from "../pages"`. Clean, single import for all POs.', check:'Structure: `pages/LoginPage.ts`. `pages/index.ts`: `export {LoginPage} from "./LoginPage"`. Test: `import {LoginPage} from "../pages"`. Or barrel: `export * from "./LoginPage"` etc.' },
    { id:5, level:1, title:'Locator Strategies in POM', scenario:'Use robust locator strategies in Page Object locators.', objective:'Prefer: `getByRole`, `getByLabel`, `getByTestId`, `getByText`. Avoid: CSS selectors that depend on implementation details.', constraints:'Four preferred strategies. Explain why each is preferred.', expectedOutput:'`getByRole("button",{name:"Submit"})`: role + name. `getByLabel("Email")`: form label. `getByTestId("submit-btn")`: test-specific. All resilient to refactoring.', check:'Priority: `getByRole` (semantic), `getByLabel` (form), `getByTestId` (test-stable), `getByText` (last resort). Avoid: `.submit-button` (CSS), `nth-child(2)` (fragile). Reason: semantic locators don\'t break on CSS changes.' },
    { id:6, level:1, title:'POM with TypeScript', scenario:'Add TypeScript types to a Page Object for better IDE support.', objective:'Properties: typed as `Locator`. Methods: typed with async return types. Constructor: `private page: Page`. Import `Locator` and `Page` from `@playwright/test`.', constraints:'Locator type. Page type. Async method types.', expectedOutput:'`emailInput: Locator`. `async login(email: string, password: string): Promise<void>`. IDE provides autocomplete.', check:'Types: `import {Page,Locator} from "@playwright/test"`. Class: `class LoginPage { private page: Page; emailInput: Locator; constructor(page:Page){this.page=page;this.emailInput=page.getByLabel("Email");}}`.' },
    { id:7, level:1, title:'Reusable Assertions in POM', scenario:'Add assertion methods to Page Objects to keep test code clean.', objective:'`async expectLoggedIn(): Promise<void>`. `async expectErrorMessage(text: string): Promise<void>`. `async expectTitle(text: string): Promise<void>`. All using `expect` internally.', constraints:'Three assertion methods. expect inside POM.', expectedOutput:'`await dashboardPage.expectLoggedIn()`. Much cleaner than raw assertions in tests.', check:'Assertion methods: wrap `expect` calls. `async expectLoggedIn(){await expect(this.welcomeMsg).toBeVisible();}`. Tests read like: "expect to be logged in". Much more readable than bare assertions.' },
    { id:8, level:1, title:'Navigation Methods', scenario:'A Page Object should handle navigation to its page.', objective:'`async goto(params={})`: navigates to the page with optional query params. `async isOnPage()`: returns true if the current URL matches the page URL. Use both in tests.', constraints:'goto with params. isOnPage check.', expectedOutput:'`productPage.goto({id:123})` → navigates to `/products/123`. `productPage.isOnPage()` → true.', check:'goto: `await this.page.goto(this.url+buildQuery(params))`. isOnPage: `return this.page.url().includes(this.url)`. Or: `expect(this.page).toHaveURL(new RegExp(this.url))`.' },
    { id:9, level:1, title:'Base Page Class', scenario:'All Page Objects share common functionality. Extract it to a BasePage class.', objective:'`BasePage` class: `page`, `goto(url)`, `waitForLoad()`, `expectTitle(text)`. `LoginPage` and `DashboardPage` extend `BasePage`.', constraints:'BasePage with three methods. Two child classes.', expectedOutput:'LoginPage: `extends BasePage`. Inherits: `page`, `goto()`, `waitForLoad()`, `expectTitle()`.', check:'`class BasePage { constructor(protected page:Page){} async goto(url:string){await this.page.goto(url);} }`. `class LoginPage extends BasePage { constructor(page:Page){super(page);}...}`. Avoids code duplication.' },
    { id:10, level:1, title:'Using POMs in Tests', scenario:'Write a complete test using only Page Object methods (no raw locators in the test).', objective:'Test: login, navigate to products, add to cart, checkout. All actions via POM methods. No `page.locator` or `page.fill` directly in the test function.', constraints:'All actions via POM. No raw locators in test.', expectedOutput:'Test body: `loginPage.login(...)`. `productPage.addToCart(1)`. `cartPage.checkout()`. No direct locator calls.', check:'Clean test: all locator and navigation logic in POMs. Test describes what to do, not how. Benefits: test is readable, locator changes only require POM updates.' },
    { id:11, level:2, title:'POM with Fixtures', scenario:'Integrate Page Objects with Playwright fixtures for clean test setup.', objective:'`test.extend({loginPage:async({page},use)=>use(new LoginPage(page)),dashboardPage:async({page},use)=>use(new DashboardPage(page))})`. Tests: `test("...",async({loginPage,dashboardPage})=>{...})`.', constraints:'Two POM fixtures. Use in test.', expectedOutput:'`test("login",async({loginPage,dashboardPage})=>{ await loginPage.goto(); await loginPage.login(email,pass); await dashboardPage.expectWelcomeMessage("Alice"); })`.', check:'POM as fixture: `async({page},use)=>{await use(new LoginPage(page))}`. Tests get clean POM instances without `new LoginPage(page)` boilerplate. Composable with other fixtures.' },
    { id:12, level:2, title:'Component Objects', scenario:'A navigation bar appears on every page. Create a NavigationBar component object.', objective:'`NavigationBar` class: not a full page, just the nav. Locators: `homeLink`, `loginLink`, `cartBadge`. Methods: `clickHome()`, `getCartCount()`. Compose into page objects.', constraints:'Component object. Compose into pages.', expectedOutput:'`dashboardPage.nav.clickHome()`. `dashboardPage.nav.getCartCount()` returns 3.', check:'Component Object: a POM for a reusable UI component. Composed into pages: `class DashboardPage { nav=new NavBar(this.page); ... }`. Tests access: `page.nav.method()`. Don\'t duplicate locators.' },
    { id:13, level:2, title:'POM with Dynamic Locators', scenario:'A product list has items that need to be selected by product name.', objective:'`productListPage.getProduct("MacBook Pro")` returns a locator for that product. `productListPage.addToCart("MacBook Pro")` clicks add-to-cart for that product.', constraints:'Parameterized locator. Dynamic selection.', expectedOutput:'`productListPage.getProduct("MacBook Pro")` → locator. `addToCart("MacBook Pro")` → clicks the correct button.', check:'Dynamic locator: `getProduct(name){return this.page.getByText(name).locator("..").getByRole("button",{name:"Add to cart"})}`. Or: `this.page.locator(`[data-product="${name}"]`)`.' },
    { id:14, level:2, title:'POM for Tables', scenario:'A data table needs robust methods for reading and interacting.', objective:'`DataTablePage`: `getRowCount()`, `getCell(row,col)`, `sortByColumn(name)`, `filterBy(field,value)`, `getRowByText(text)`. Each wraps the table locators.', constraints:'Five methods. Table interactions.', expectedOutput:'`dataTable.getRowCount()` returns 20. `dataTable.getCell(1,2)` returns "Alice". `dataTable.sortByColumn("Name")` clicks the sort header.', check:'Table locators: `this.rows=page.locator("table tbody tr")`. `getRowCount():Promise<number>{return this.rows.count()}`. `getCell(r,c):Locator{return this.rows.nth(r).locator("td").nth(c)}`.' },
    { id:15, level:2, title:'POM for Forms', scenario:'A registration form has validation. Create a FormPage with validation helpers.', objective:'`RegistrationPage`: `fill(data)`, `submit()`, `getFieldError(field)`, `isSubmitEnabled()`. `fill(data)` accepts an object and fills all fields.', constraints:'fill with object. getFieldError. isSubmitEnabled.', expectedOutput:'`registrationPage.fill({name:"Alice",email:"alice@example.com"})`. `registrationPage.getFieldError("email")` returns "Invalid email".', check:'`fill(data){for(const [field,value] of Object.entries(data)){await this.page.getByLabel(field).fill(String(value));}}`. `getFieldError(field){return this.page.locator(`[data-field="${field}"] .error`).textContent()}`. ' },
    { id:16, level:2, title:'POM Inheritance vs Composition', scenario:'Multiple pages share a header. Implement this with both inheritance and composition, then compare.', objective:'Inheritance: `ProductPage extends BasePage`. BasePage has `header` methods. Composition: `ProductPage` has `header:HeaderComponent`. Compare DX.', constraints:'Both approaches. Same functionality. Comparison.', expectedOutput:'Both work. Composition preferred: more flexible, avoids inheritance issues. Inheritance: simpler for small projects.', check:'Composition: `class ProductPage { header=new Header(this.page); product=page.getByTestId("product") }`. Inheritance: `class ProductPage extends BasePage`. Composition wins: looser coupling, easier to change.' },
    { id:17, level:2, title:'POM for Modal Dialogs', scenario:'A confirmation modal appears after clicking delete. Create a ModalComponent.', objective:'`ModalComponent`: `isVisible()`, `getTitle()`, `confirm()`, `cancel()`. Compose into the page that triggers it.', constraints:'Modal component. isVisible, getTitle, confirm, cancel.', expectedOutput:'`await modal.isVisible()` true. `modal.getTitle()` = "Confirm Delete". `modal.confirm()` clicks Yes.', check:'`class Modal { locator=this.page.getByRole("dialog"); isVisible():Promise<boolean>{return this.locator.isVisible()} confirm(){return this.locator.getByRole("button",{name:"Yes"}).click()} }`.' },
    { id:18, level:2, title:'POM for SPA Navigation', scenario:'A SPA navigates without full page loads. POM must handle client-side routing.', objective:'After a `click()` that triggers client-side navigation, wait for the new page content. POM method: `async navigateToProduct(id)`. Waits for: the product heading to appear.', constraints:'SPA navigation. Wait for new content.', expectedOutput:'`productPage.navigateToProduct(1)` clicks the link, waits for `h1.product-name` to appear. No full page load.', check:'SPA navigation: `await this.page.getByText("Product 1").click()`. No full page reload. Wait: `await this.page.waitForSelector("h1.product-name")` or `expect(heading).toBeVisible()`. Next page is the same Page object.' },
    { id:19, level:2, title:'POM State Verification', scenario:'Page Objects should verify they are in the expected state before acting.', objective:'`loginPage.goto()` method: after navigation, assert `expect(page).toHaveURL("/login")`. This catches incorrect navigation early.', constraints:'URL assertion after goto. State verification.', expectedOutput:'goto() navigates and asserts URL. If URL is wrong: test fails with clear message at the POM level.', check:'State verification in goto: `async goto(){await this.page.goto(this.url);await expect(this.page).toHaveURL(new RegExp(this.url));}`. Catches: wrong URL, redirect, 404. Fail fast with clear error.' },
    { id:20, level:2, title:'POM for API-Seeded Pages', scenario:'A page requires API setup (create test data) before navigation.', objective:'`ProductPage.goto(productId)`: checks if product exists via API, creates it if not, then navigates. Encapsulates the setup.', constraints:'API call in goto. Create if not exists.', expectedOutput:'`productPage.goto(1)`: checks API, creates if missing, navigates to /products/1.', check:'`async goto(id){const exists=await this.api.productExists(id);if(!exists)await this.api.createProduct(id);await this.page.goto("/products/"+id);}`. Setup encapsulated in POM.' },
    { id:21, level:3, title:'POM Code Generation', scenario:'Automatically generate Page Object boilerplate from a running page.', objective:'Script: navigate to a URL. Find all interactive elements (inputs, buttons, links). Generate a Page Object class with locators for each.', constraints:'Element discovery. Locator generation. TypeScript class output.', expectedOutput:'Running against /login → generates LoginPage with emailInput, passwordInput, submitButton, forgotPasswordLink.', check:'Discovery: `page.$$eval("input,button,a",els=>els.map(el=>({tag:el.tagName,id:el.id,name:el.getAttribute("name"),text:el.textContent})))`. Generate: template string TypeScript class with locators.' },
    { id:22, level:3, title:'POM Testing (Testing Your Tests)', scenario:'Verify that Page Objects work correctly by testing them in isolation.', objective:'Unit test for `LoginPage.login()`: mock the page object, call login, verify fill and click were called in the correct order with correct arguments.', constraints:'POM unit test. Mock page. Verify calls.', expectedOutput:'`loginPage.login("user@example.com","pass")` → `emailInput.fill("user@example.com")` called. `passwordInput.fill("pass")` called. `submitButton.click()` called.', check:'Test your POM: create a mock page with jest.fn() or sinon. Call the method. Assert the correct locator methods were called. Catch: POM method calls wrong locator or wrong order.' },
    { id:23, level:3, title:'POM for Multi-Step Wizards', scenario:'A 4-step registration wizard must be encapsulated in a Page Object.', objective:'`RegistrationWizardPage`: `step1(personalInfo)`, `step2(addressInfo)`, `step3(payment)`, `step4(confirm)`, `complete()`. Each method fills and proceeds.', constraints:'Four step methods. complete() method.', expectedOutput:'`wizard.step1({name:"Alice",dob:"1990-01-01"}).step2({...}).step3({...}).step4(true).complete()`.', check:'Fluent interface: each step method returns `this` or the wizard object. `complete()`: final assertion. Internally: fill fields, click Next, wait for next step to appear.' },
    { id:24, level:3, title:'POM for Infinite Scroll', scenario:'A feed page uses infinite scroll. POM must handle loading more items.', objective:'`FeedPage`: `getItemCount()`, `scrollToBottom()`, `waitForMoreItems(initialCount)`, `loadAllItems(maxItems)`. loadAllItems: scrolls until maxItems loaded or no more.', constraints:'Scroll to bottom. Wait for more. Load all.', expectedOutput:'`feedPage.loadAllItems(100)` scrolls until 100 items loaded. `getItemCount()` returns 100.', check:'`scrollToBottom(){return this.page.evaluate(()=>window.scrollTo(0,document.body.scrollHeight))}`. `waitForMoreItems(initial){return this.page.waitForFunction(count=>document.querySelectorAll(".item").length>count,initial)}`.' },
    { id:25, level:3, title:'POM Factory Pattern', scenario:'Create a factory that returns the correct Page Object based on the current URL.', objective:'`PageFactory.create(page)`: reads the current URL, returns the appropriate Page Object class.', constraints:'URL-based factory. Returns correct POM.', expectedOutput:'Current URL: /login → returns LoginPage. /dashboard → DashboardPage. Unknown → throws.', check:'`static create(page){const url=page.url();if(url.includes("/login"))return new LoginPage(page);if(url.includes("/dashboard"))return new DashboardPage(page);throw new Error("Unknown page: "+url)}`.' },
    { id:26, level:3, title:'POM for Complex Authentication', scenario:'A multi-factor authentication flow (password + TOTP) needs a POM.', objective:'`AuthPage`: `enterPassword(pass)`, `enterTOTP(code)`, `generateTOTP(secret)`, `login(email,pass,secret)`. login() orchestrates the full flow.', constraints:'MFA flow. TOTP generation. Full login method.', expectedOutput:'`authPage.login("alice@example.com","pass","JBSWY3DPEHPK3PXP")` completes both MFA steps.', check:'TOTP generation: use `otplib` or `totp` npm package. `generateTOTP(secret)`: `totp.generate(secret)`. Full flow: `enterPassword`, wait for OTP prompt, `enterTOTP(generateTOTP(secret))`.' },
    { id:27, level:3, title:'POM Versioning', scenario:'A POM needs to support two versions of the UI (old and new).', objective:'`LoginPageV1` and `LoginPageV2`: same API, different locators. A `LoginPageFactory` returns the correct version based on an environment variable.', constraints:'Two versions. Same API. Factory selection.', expectedOutput:'`LEGACY=true` → LoginPageV1. Otherwise → LoginPageV2. Tests use the same login() method on both.', check:'Factory: `const isLegacy=process.env.LEGACY==="true"; return isLegacy?new LoginPageV1(page):new LoginPageV2(page)`. Tests: use the interface, not the class directly. Version-agnostic tests.' },
    { id:28, level:3, title:'POM for Real-Time Updates', scenario:'A dashboard updates in real-time via WebSocket. POM must handle live data.', objective:'`DashboardPage.waitForMetricUpdate(name,expectedValue,timeout)`: waits until the named metric displays the expected value.', constraints:'Real-time wait. Metric name. Value assertion.', expectedOutput:'`dashboard.waitForMetricUpdate("active-users",150,10000)` waits up to 10s for the metric to show 150.', check:'`waitForMetricUpdate(name,value,timeout){return expect(this.page.getByTestId("metric-"+name)).toHaveText(String(value),{timeout})}`. Playwright auto-waits on assertions.' },
    { id:29, level:3, title:'POM Documentation', scenario:'A team of 5 maintains a POM library. Document all Page Objects with JSDoc.', objective:'Each POM method: `@param`, `@returns`, `@throws`, `@example`. Generate API documentation from JSDoc.', constraints:'JSDoc on all methods. Documentation generation.', expectedOutput:'Generated doc: `LoginPage.login(email,password)`: Logs in with the given credentials. @param email - User email. @param password - User password. @returns DashboardPage.', check:'JSDoc: `/** @param {string} email - User email @returns {Promise<DashboardPage>} */`. Generate: `npx typedoc --out docs src/pages`. Or: VSCode hover shows JSDoc.' },
    { id:30, level:3, title:'POM Performance', scenario:'Slow POM initialization (many locators defined in constructor) slows down tests.', objective:'Compare: (1) locators in constructor (eager). (2) locators as getters (lazy, defined at access time). Measure initialization time difference.', constraints:'Eager vs lazy. Timing comparison.', expectedOutput:'Eager: 10 locators defined at construction (fast — locators are just objects, no I/O). Lazy: defined on first access. Minimal difference — locators are queries, not DOM operations.', check:'Playwright locators are lazy — they don\'t touch the DOM until an action or assertion. Defining them in the constructor is fine. Actual performance: minimize `page.locator` calls in loops.' },
    { id:31, level:4, title:'POM as an Abstraction Layer', scenario:'The app is being redesigned. POM insulates tests from UI changes.', objective:'Change: login form fields renamed. Without POM: 50 tests fail. With POM: only LoginPage locators updated. All 50 tests continue to pass.', constraints:'Simulate field rename. Update POM only. Tests pass.', expectedOutput:'LoginPage: `emailInput = page.getByLabel("E-mail address")` (was "Email"). All 50 tests: no changes needed, all pass.', check:'POM abstraction value: single point of change for UI structure. Test resilience: tests don\'t break on locator changes. Measure: % of tests requiring changes for a given UI change.' },
    { id:32, level:4, title:'POM with Backend Integration', scenario:'A POM that can perform both UI actions and direct API calls for setup/teardown.', objective:'`UserManagementPage`: `createUser(data)` — via API directly. `verifyUserInUI(email)` — via browser. `deleteUser(id)` — via API. Hybrid POM for efficiency.', constraints:'API in POM. UI in POM. Hybrid.', expectedOutput:'`userMgmt.createUser({email:"alice@example.com"})` — API POST. `userMgmt.verifyUserInUI("alice@example.com")` — UI assertion. Faster setup, UI-only verification.', check:'`constructor(page:Page,apiClient:APIClient){...}`. API methods: `async createUser(data){return this.apiClient.post("/users",data)}`. UI methods: `async verifyUserInUI(email){await expect(this.page.getByText(email)).toBeVisible()}`.' },
    { id:33, level:4, title:'Shared POM Library', scenario:'Multiple projects need the same Page Objects. Publish them as an npm package.', objective:'Package: `@company/page-objects`. Contains: `LoginPage`, `DashboardPage`, common components. Consumers: `import {LoginPage} from "@company/page-objects"`. Version with semver.', constraints:'npm package. Published. Versioned.', expectedOutput:'`npm install @company/page-objects`. `import {LoginPage} from "@company/page-objects"`. All teams share the same tested POMs.', check:'Package: `package.json` with `main` and `types` fields. TypeScript: compile to JS + .d.ts. Publish: npm publish (private registry). Versioning: PATCH for locator fixes, MINOR for new pages, MAJOR for breaking changes.' },
    { id:34, level:4, title:'POM with Retry Logic', scenario:'An element is intermittently slow to appear. Add retry logic to the POM method.', objective:'`async clickWhenReady(locator,maxRetries=3)`: retries the click if the element is not visible. Uses Playwright\'s built-in auto-waiting — no need to add manual retry.', constraints:'Explain Playwright auto-waiting. Manual retry when auto-wait is insufficient.', expectedOutput:'Playwright auto-waits on most actions. Manual retry: for cases where the element appears after a dynamic delay not covered by auto-wait.', check:'Playwright already retries: `click`, `fill`, assertions — all auto-wait for the element. Manual retry is rarely needed. Use: `waitForSelector` for precise control. Manual retry: true instability, not timing.' },
    { id:35, level:4, title:'POM Anti-Patterns', scenario:'Identify and fix anti-patterns in a poorly written POM.', objective:'Anti-patterns: (1) Raw CSS selectors. (2) Assertions in action methods. (3) Hardcoded waits (`waitForTimeout`). (4) Too many responsibilities per class. Fix all.', constraints:'Four anti-patterns. Fix each.', expectedOutput:'Fixed: getByRole for locators. Assertions in separate methods. No waits. Split into smaller classes.', check:'Anti-patterns: `page.locator(".btn-primary")` → `page.getByRole("button",{name:"Submit"})`. Assertion in login(): remove — separate `expectLoggedIn()`. `waitForTimeout(2000)` → `expect(locator).toBeVisible()`. Large class → split.' },
    { id:36, level:4, title:'POM for i18n Testing', scenario:'The app is in 3 languages. POM must work for all languages.', objective:'POM locators use `data-testid` (language-agnostic) instead of visible text. For text assertions: POM accepts the expected text as a parameter (or reads from i18n config).', constraints:'testid-based locators. i18n-safe assertions.', expectedOutput:'`loginPage.submitButton`: `getByTestId("submit")` — works in all languages. `expectTitle(i18n.title)`: passes the translated string.', check:'i18n-safe locators: `getByTestId` (never changes). Avoid `getByText` for text that gets translated. Assertions: `expect(heading).toHaveText(expectedText)` where `expectedText` comes from i18n config.' },
    { id:37, level:4, title:'POM Performance Monitoring', scenario:'Measure how long each POM action takes.', objective:'Wrap each POM method with timing: log start, end, and duration. Flag methods taking > 1s. Integrate with the test report.', constraints:'Timing wrapper. 1s threshold. Report integration.', expectedOutput:'`login()` took 1.8s: flagged. `expectLoggedIn()` took 0.2s: OK. Report shows timing per POM method.', check:'Wrapper: `async _timed(name,fn){const t=Date.now();await fn();const ms=Date.now()-t;if(ms>1000)console.warn("Slow POM:",name,ms+"ms");}`. Call: `return this._timed("login",()=>this._login(email,pass))`.' },
    { id:38, level:4, title:'POM Dependency Injection', scenario:'Page Objects should be injectable for testability.', objective:'`LoginPage` constructor takes `page: Page` and optional `locatorResolver: LocatorResolver`. In tests: use the default resolver. In unit tests: inject a mock resolver.', constraints:'DI constructor. Default and mock resolver.', expectedOutput:'Production test: `new LoginPage(page)`. Unit test: `new LoginPage(mockPage,mockResolver)`.', check:'DI: `constructor(page:Page,resolver:LocatorResolver=defaultResolver)`. `defaultResolver`: `(name)=>page.getByTestId(name)`. `mockResolver`: `(name)=>mockLocator`. Enables testing the POM in isolation.' },
    { id:39, level:4, title:'Fluent POM Builder', scenario:'Build a fluent POM where all action methods can be chained.', objective:'`loginPage.goto().fill("email","user@example.com").fill("password","pass").submit()`. All methods return `this` (synchronously) and collect actions. `.run()` executes them all.', constraints:'Fluent interface. Collect then execute.', expectedOutput:'Chain: `loginPage.fill("email","a@b.com").fill("password","pass").submit().run()`. All actions execute in order.', check:'Builder: `fill(label,value){this.actions.push(()=>this.page.getByLabel(label).fill(value));return this;}`. `run(){for(const a of this.actions)await a();return this;}`. Return `this` for chaining.' },
    { id:40, level:4, title:'POM Test Coverage Analysis', scenario:'Identify which POM methods are never used in any test.', objective:'Instrument POM methods to track calls. After suite: report unused methods. Consider removing them.', constraints:'Usage tracking. Unused method report.', expectedOutput:'`loginPage.forgotPassword()` never called. Consider: is this feature tested anywhere? If not, add a test or remove the method.', check:'Tracking: `class LoginPage { #usedMethods=new Set(); login(){this.#usedMethods.add("login");...} }`. After suite: compare `#usedMethods` to all method names. Report unused. Helps clean dead code.' },
    { id:41, level:5, title:'POM Framework Design', scenario:'Design a complete POM framework for a large e-commerce application.', objective:'Framework: (1) BasePage and BaseComponent. (2) Auto-generated locators. (3) Composition helpers. (4) Fixtures integration. (5) Documentation generation. (6) Test coverage tracking.', constraints:'All 6 components. Published npm package.', expectedOutput:'`import {LoginPage,ProductPage} from "@company/poms"`. All pages tested. Coverage > 80%.', check:'Monorepo: `packages/pages/*` for each domain. `packages/tools/*` for generators. CI: generate docs, check coverage, publish on merge. Quality: lint POM patterns (no raw CSS selectors).' },
    { id:42, level:5, title:'Self-Healing POM', scenario:'Locators in the POM break when the UI changes. Build a self-healing mechanism.', objective:'When a locator fails, try alternatives (different attribute, parent/child approach). If an alternative works, log a warning and use it. Flag for manual review.', constraints:'Alternative locator strategies. Warning log. Manual review flag.', expectedOutput:'Locator `getByTestId("submit")` fails. Try: `getByRole("button",{name:"Submit"})`. Works → use it. Warning: "Locator fallback used for submit button. Review needed."', check:'Self-healing: `try{return primary;}catch{const alt=fallbackLocators.find(l=>l.isVisible());if(alt){warn("fallback");return alt;}throw originalError;}`. Fallback list per element. Alert on fallback.' },
    { id:43, level:5, title:'POM Smart Waiting', scenario:'Build intelligent wait strategies into POMs.', objective:'`SmartWait` mixin: `waitForStable(locator)` — waits until the element stops moving (bounding box stable). `waitForVisible(locator)` — waits for visibility. `waitForNetwork(locator)` — waits for associated API call.', constraints:'Three smart wait strategies. Mixin pattern.', expectedOutput:'`loginPage.waitForStable(button).click()` — no more clicks during animation. `waitForNetwork("submit")` — waits for the form submission API call.', check:'Stable: poll `boundingBox()` until two consecutive calls return the same values. Network: set up `page.waitForResponse` before the action, await it after. Mixin: `Object.assign(pom,SmartWait)`.' },
    { id:44, level:5, title:'POM for Multi-Tenant Testing', scenario:'A multi-tenant SaaS has different UIs per tenant. POM must adapt.', objective:'`TenantALoginPage extends LoginPage`: overrides locators for Tenant A\'s custom login UI. `TenantBLoginPage extends LoginPage`: overrides for Tenant B. `LoginPageFactory`: returns the correct one based on tenant.', constraints:'Two tenant POMs. Factory. Same test code.', expectedOutput:'`LoginPageFactory.create(page,"tenantA")` → TenantALoginPage. `LoginPageFactory.create(page,"tenantB")` → TenantBLoginPage. Tests unchanged.', check:'Each tenant subclass: override only what\'s different. Shared: methods that work the same. Factory: reads `TENANT` env var or takes a parameter. Tests: use the factory, not the class directly.' },
    { id:45, level:5, title:'POM as DSL', scenario:'Build a domain-specific language (DSL) on top of POM for non-technical test authoring.', objective:'DSL: `login.with(email,password).then.navigate.to("products").and.add.product("MacBook Pro").to.cart`. Readable by non-engineers.', constraints:'Fluent DSL. Readable by non-engineers.', expectedOutput:'`user.login(email,password).then.browses("products").and.adds("MacBook Pro").to.cart.and.checks.out()`. Readable, chainable.', check:'DSL: fluent builder where each term returns an object with the next valid terms. `login.with(email,pass)` → `{then:{navigate:{to:fn}}}`. Wraps POM methods. Purpose: acceptance testing readable by POs.' },
    { id:46, level:5, title:'POM Mutation Testing', scenario:'Are the POM methods actually tested? Mutation testing verifies test quality.', objective:'Mutate POM methods (change locator, skip a step). Run tests. If tests still pass: they\'re not adequately testing the POM behavior.', constraints:'Mutations: 3 types. Run after each. Report survivors.', expectedOutput:'Mutation: skip `submitButton.click()`. Test: login() completes but no form submitted. Test should fail (login doesn\'t work). If it passes: test doesn\'t verify login actually happened.', check:'Mutations: (1) remove a step. (2) change a locator to wrong one. (3) skip an assertion. Run test suite. Surviving mutations = untested behavior. Fix: add assertions that catch the mutations.' },
    { id:47, level:5, title:'POM for Accessibility', scenario:'Build a POM layer specifically for accessibility testing.', objective:'`A11yPage` mixin: `checkA11y()` — runs axe-core. `getFocusOrder()` — tabs through and records focus order. `checkColorContrast()` — verifies contrast ratios. All composable into page objects.', constraints:'Three a11y methods. Mixin. Composable.', expectedOutput:'`loginPage.checkA11y()` — no violations. `loginPage.getFocusOrder()` — [email,password,submit]. Correct order.', check:'`checkA11y(){const r=await new AxeBuilder({page}).analyze();expect(r.violations).toHaveLength(0);}`. `getFocusOrder(){const order=[];while(!focusCycled){order.push(activeElement.name);page.keyboard.press("Tab");}}`. Mixin: `Object.assign(page,a11yMixins)`.' },
    { id:48, level:5, title:'POM for Visual Testing', scenario:'Integrate visual testing directly into Page Objects.', objective:'`VisualPage` mixin: `expectSnapshot(name,options)` — calls `toHaveScreenshot`. Composable into all pages. `productPage.expectSnapshot("product-detail.png",{mask:[page.locator(".price")]})`.', constraints:'Visual mixin. toHaveScreenshot wrapper. Mask support.', expectedOutput:'`productPage.expectSnapshot("product.png")` — takes screenshot, compares to baseline. mask param: dynamic content masked.', check:'Mixin: `expectSnapshot(name,opts){return expect(this.page).toHaveScreenshot(name,opts)}`. Composable: `class ProductPage extends VisualPage`. Or: `Object.assign(productPage,visualMixins)`. Option: `{mask:[...]}` passed through.' },
    { id:49, level:5, title:'POM Generation from OpenAPI', scenario:'Generate Page Objects from an OpenAPI spec for API-backed pages.', objective:'OpenAPI spec describes entities (User, Product, Order). Generator: creates CRUD Page Objects for each (UserListPage, UserDetailPage, UserFormPage).', constraints:'OpenAPI parsing. Three POM types per entity. TypeScript output.', expectedOutput:'From OpenAPI: `UserListPage` with `getUsers()`, `search(query)`. `UserDetailPage` with `getUser()`, `deleteUser()`. `UserFormPage` with `fill(user)`, `submit()`.', check:'Generator: parse OpenAPI entities. For each: generate list, detail, form POM. List: table methods. Detail: display assertions. Form: fill methods matching schema fields. Template-based generation.' },
    { id:50, level:5, title:'Full POM Architecture', scenario:'Build a complete Page Object Model architecture for an enterprise application.', objective:'Build: (1) BasePage + BaseComponent hierarchy. (2) Component library (nav, table, modal, form). (3) Page library (all app pages). (4) Self-healing locators. (5) Fixture integration. (6) Documentation. (7) Test coverage analysis.', constraints:'All 7 components. Monorepo. CI integration.', expectedOutput:'`import {LoginPage,ProductTable,Modal} from "@company/poms"`. Tests: clean, readable. CI: coverage > 80%, docs auto-generated.', check:'Monorepo: `packages/pages`, `packages/components`, `packages/tools`. CI: generate docs, coverage check, lint, publish. Each POM: unit tested, documented, covered.' },
  ],

  auth: [
    { id:1, level:1, title:'Login Once, Reuse State', scenario:'Tests should not log in before every test. Save the auth state and reuse it.', objective:'`test.setup("authenticate",async({page})=>{ await page.goto("/login"); ...fill and submit... await page.context().storageState({path:"auth.json"}); })`. Other tests: `use.storageState:"auth.json"`.', constraints:'Setup project. Save storageState. Other tests use it.', expectedOutput:'Login happens once. All other tests start already logged in. 10x faster suite.', check:'`storageState({path})`: saves cookies and localStorage. `newContext({storageState:"auth.json"})`: loads them. Tests start with a pre-authenticated session. No repeated logins.' },
    { id:2, level:1, title:'storageState Basics', scenario:'Understand what storageState saves and how to use it.', objective:'After login: `const state = await context.storageState()`. Log `state.cookies` and `state.origins`. Save to file: `storageState({path:"auth.json"})`. Load: `browser.newContext({storageState:"auth.json"})`.', constraints:'Log cookies and origins. Save. Load. Verify.', expectedOutput:'state.cookies: [{name:"session",value:"...",domain:"example.com",...}]. state.origins: [{origin:"https://example.com",localStorage:[...]}].', check:'`storageState`: `{cookies:[{name,value,domain,path,expires,httpOnly,secure,sameSite}],origins:[{origin,localStorage:[{name,value}]}]}`. Captures all browser state.' },
    { id:3, level:1, title:'Basic Auth (HTTP Basic Authentication)', scenario:'A page uses HTTP Basic Authentication.', objective:'`browser.newContext({httpCredentials:{username:"admin",password:"secret"}})`. Navigate to the protected page. Verify access.', constraints:'httpCredentials option. Protected page.', expectedOutput:'Without credentials: 401 prompt. With credentials: page loads.', check:'`httpCredentials:{username,password}`: handles HTTP 401 challenges automatically. The browser sends `Authorization: Basic base64(user:pass)`. Works for any HTTP Basic Auth prompt.' },
    { id:4, level:1, title:'Cookie Authentication', scenario:'Set an auth cookie to authenticate without going through the login UI.', objective:'`context.addCookies([{name:"session",value:"test-token",domain:"example.com",path:"/",httpOnly:true}])`. Navigate to a protected page. Verify access.', constraints:'addCookies. Protected page verification.', expectedOutput:'Cookie set directly. Protected page accessible without UI login.', check:'`context.addCookies(cookies)`: sets cookies directly. `cookie`: `{name,value,domain,path,expires?,httpOnly?,secure?,sameSite?}`. `domain`: must match the page domain. Alternative: `page.evaluate(()=>document.cookie="...")`.' },
    { id:5, level:1, title:'Token-Based Auth', scenario:'The app uses a JWT token stored in localStorage.', objective:'After login: get the JWT from the API response. Store in localStorage: `page.evaluate(([token])=>localStorage.setItem("auth_token",token),[token])`. Navigate to a protected page.', constraints:'Get JWT. Set in localStorage. Protected page.', expectedOutput:'JWT set in localStorage. App reads it for authenticated requests. Protected page accessible.', check:'`page.evaluate((token)=>localStorage.setItem("auth_token",token),token)`: sets localStorage. Or: `addInitScript(([t])=>localStorage.setItem("auth_token",t),[token])`: runs before page script.' },
    { id:6, level:1, title:'Multi-Role Authentication', scenario:'Tests need admin and regular user accounts.', objective:'Two setup tests: `auth.setup.ts` creates `admin-auth.json` and `user-auth.json`. Two projects: admin tests (use admin-auth), user tests (use user-auth).', constraints:'Two setup tests. Two auth files. Two projects.', expectedOutput:'Admin tests: full access. User tests: restricted access. No UI login in either.', check:'Admin setup: `page.goto("/login");fill("admin@example.com","adminpass");save("admin-auth.json")`. User setup: same with user credentials. Projects: `{name:"admin",use:{storageState:"admin-auth.json"}}`.' },
    { id:7, level:1, title:'Auth Verification', scenario:'Verify the auth state is working correctly before running tests.', objective:'In a beforeEach or fixture: `page.goto("/protected")`. `expect(page).toHaveURL("/protected")` — not redirected to login. Fail fast if auth is broken.', constraints:'Protected page check. URL assertion. Fail fast.', expectedOutput:'If auth works: URL stays at /protected. If auth broken: redirected to /login → test fails immediately.', check:'Auth check: `await page.goto("/protected")`. `await expect(page).toHaveURL(/protected/)`. If redirected to /login: assertion fails with clear message. Add as afterEach check.' },
    { id:8, level:1, title:'Auth State Refresh', scenario:'Auth state expires after 1 hour. Tests that run long need to refresh the token.', objective:'Check token expiry before each test. If expired (< 5 min remaining): re-login and refresh the state file. Otherwise: use existing state.', constraints:'Expiry check. Conditional re-login. Refresh state file.', expectedOutput:'Token expiring soon → re-login → new state saved. Token valid → use existing state.', check:'JWT expiry: `const {exp}=jwt.decode(token)`. `const expiresAt=exp*1000`. `if(Date.now()>expiresAt-300000)await reLogin()`. Store new state. `reLogin`: `page.goto("/login");...;context.storageState({path})`.' },
    { id:9, level:1, title:'Logout Testing', scenario:'Test that logout correctly clears authentication state.', objective:'Login. Verify protected page accessible. Click logout. Verify redirected to login page. Verify protected page no longer accessible.', constraints:'Login. Logout. Verify before and after.', expectedOutput:'Before logout: /protected accessible. After logout: redirected to /login.', check:'Logout test: verify session is cleared. After logout: cookies cleared, localStorage cleared, redirect to login. Try: navigate to protected page → redirected. Assert: no session cookie.' },
    { id:10, level:1, title:'Auth in API Tests', scenario:'API tests need authentication headers.', objective:'In config: `use:{extraHTTPHeaders:{"Authorization":"Bearer "+process.env.API_TOKEN}}`. All API request fixture calls get the auth header automatically.', constraints:'extraHTTPHeaders in config. API_TOKEN env var.', expectedOutput:'All API requests in tests have the Authorization header. No need to set it per-test.', check:'`extraHTTPHeaders`: applies to ALL requests from the context (browser and API request fixture). For the `request` fixture specifically: set in `use.extraHTTPHeaders` or in the APIRequestContext options.' },
    { id:11, level:2, title:'OAuth2 Login Flow', scenario:'The app uses OAuth2 for authentication (e.g., Google OAuth).', objective:'Approach 1: UI flow — go through the OAuth provider\'s login page. Approach 2: API approach — exchange credentials directly for a token. Approach 2 is faster.', constraints:'Both approaches. API approach implemented.', expectedOutput:'API approach: POST to OAuth token endpoint → get token → set in storageState. No UI interaction with OAuth provider.', check:'API token: `POST /oauth/token {grant_type:"password",username,password,client_id,client_secret}` → `{access_token}`. Store in cookies/localStorage. Avoids OAuth UI login page.' },
    { id:12, level:2, title:'Session-Based Auth Testing', scenario:'The app uses server-side sessions (session cookie).', objective:'Login via API: `request.post("/api/login",{data:{email,password}})`. Extract the `Set-Cookie` header. Set the cookie in the browser context.', constraints:'API login. Extract cookie. Set in context.', expectedOutput:'API login → Set-Cookie: session=abc. Set cookie in browser context. Navigate to protected page → accessible.', check:'Extract cookie: `const setCookieHeader=loginResponse.headers()["set-cookie"]`. Parse: `const sessionValue=setCookieHeader.split(";")[0].split("=")[1]`. Set: `context.addCookies([{name:"session",value,...}])`.' },
    { id:13, level:2, title:'Mock Authentication', scenario:'Tests should bypass the real auth server in isolated environments.', objective:'Intercept the login request: `page.route("/api/auth",route=>route.fulfill({json:{token:"mock-jwt",user:{id:1,role:"admin"}}}))`. Tests authenticate against the mock.', constraints:'Mock login endpoint. Mock token. Protected page.', expectedOutput:'Login request intercepted. Mock token returned. App authenticates with mock token.', check:'Mock auth: intercept login endpoint, return fake token. The app stores the token and makes authenticated requests. Those requests also need mocking (or point to a real API that accepts the mock token).' },
    { id:14, level:2, title:'Auth State Isolation Between Tests', scenario:'Test A logs out. Test B still needs to be logged in. Ensure isolation.', objective:'Each test gets its own context (default in Playwright). Auth state loaded from file per context. Logout in test A only affects test A\'s context.', constraints:'Context isolation demonstration. Logout in one test. Other test unaffected.', expectedOutput:'Test A logs out. Test B: still logged in (its own context loaded from auth.json).', check:'Default: each test gets a new BrowserContext. `storageState` is loaded fresh for each context. Logout in one context: clears cookies in that context only. Other contexts: unaffected.' },
    { id:15, level:2, title:'Auth for Different Environments', scenario:'Auth credentials differ between dev, staging, and prod.', objective:'Auth credentials from env vars: `process.env.AUTH_USER`, `process.env.AUTH_PASS`. Setup test uses env-var credentials. `auth.json` is environment-specific.', constraints:'Env vars for credentials. Environment-specific auth.', expectedOutput:'Dev run: uses dev credentials. Staging run: uses staging credentials. Same test code.', check:'Credential env vars: `AUTH_USER` and `AUTH_PASS`. Setup: `page.fill("#email",process.env.AUTH_USER!)`. `auth.json`: different per environment (generated in CI per environment).' },
    { id:16, level:2, title:'SAML/SSO Authentication', scenario:'Enterprise SSO (SAML) authentication for a corporate app.', objective:'SAML flow: redirect to IdP, login with corp credentials, redirect back with assertion. Automate with Playwright by intercepting the SAML assertion or using API to get a token.', constraints:'SAML flow. API bypass.', expectedOutput:'API bypass: POST to SAML endpoint with credentials → get assertion → post to SP → get session. Browser context: set session cookie.', check:'SAML bypass: `POST /api/saml/sso {username,password}` → `{sessionCookie}`. Set cookie: `context.addCookies([...])`. Many IdPs block automation — check if there\'s an API endpoint that handles SAML without a browser.' },
    { id:17, level:2, title:'Auth Fixture Design', scenario:'Design a clean auth fixture that handles all authentication concerns.', objective:'`auth` fixture: loads storageState, verifies it\'s valid, refreshes if expired. `adminAuth` and `userAuth` extend it with role-specific states.', constraints:'Base auth fixture. Two role fixtures. Validity check.', expectedOutput:'`test("admin test",async({adminAuth})=>{...})`. Auth loaded, verified, refreshed if needed. Clean and composable.', check:'`auth` fixture: `async({browser},use)=>{const ctx=await browser.newContext({storageState});const page=await ctx.newPage();if(!await isValid(page))await refresh();await use(ctx);}`. Role: override storageState path.' },
    { id:18, level:2, title:'Parallel Auth Setup', scenario:'Setting up auth for 10 user roles takes 10 minutes sequentially. Parallelize it.', objective:'In global-setup: `await Promise.all(roles.map(role=>setupAuth(role)))`. All 10 auth files generated in parallel.', constraints:'Parallel setup. 10 roles. Promise.all.', expectedOutput:'Sequential: 10 minutes. Parallel: ~1 minute (10 logins in parallel).', check:'Global setup: `const browser=await chromium.launch()`. `await Promise.all(roles.map(async role=>{const ctx=await browser.newContext();const page=await ctx.newPage();await login(page,role);await ctx.storageState({path:authPath(role)});}))`. ' },
    { id:19, level:2, title:'Auth Expiry Simulation', scenario:'Test how the app handles expired authentication.', objective:'Set an expired JWT or expired cookie. Navigate to a protected page. Verify the app shows an appropriate "Session expired" message and redirects to login.', constraints:'Expired token/cookie. Protected page. Error handling.', expectedOutput:'Expired session → app shows "Session expired. Please log in again." → redirected to login.', check:'Expired JWT: create with `exp:Math.floor(Date.now()/1000)-60` (1 minute ago). Set in localStorage. Navigate to protected page. App should detect expired token and handle gracefully.' },
    { id:20, level:2, title:'Remember Me Testing', scenario:'Test that "Remember Me" keeps the user logged in after closing the browser.', objective:'Login with "Remember Me" checked. Close context (simulates browser close). Create new context with saved cookies. Navigate to protected page. Verify still logged in.', constraints:'Remember Me. Close context. New context. Verify.', expectedOutput:'Remember Me: persistent cookie (no expiry). Close and reopen: still logged in.', check:'Remember Me: sets a persistent cookie (with expires date in the future). Without: session cookie (expires on browser close). Test: save cookies, create new context, load cookies, verify auth.' },
    { id:21, level:3, title:'Multi-Factor Authentication Automation', scenario:'Automate a 2FA login flow (TOTP).', objective:'Login with email/password. Capture the 2FA challenge. Generate TOTP code from the secret. Enter the code. Verify successful login.', constraints:'TOTP generation. Enter 2FA code. Verify login.', expectedOutput:'`totp.generate(secret)` → "123456". Enter in 2FA field. Submit. Logged in.', check:'TOTP: use `@otplib/preset-default` or `totp` package. `totp.generate(base32Secret)`: current TOTP code. Enter in the 2FA input. Must match the server\'s TOTP (same shared secret). Valid for 30s.' },
    { id:22, level:3, title:'Biometric Auth Testing', scenario:'The app has biometric (fingerprint/Face ID) for mobile. Test in an automated environment.', objective:'Mock the biometric response: use `page.evaluate` to override the WebAuthn/biometric API. Or: configure a WebAuthn virtual authenticator.', constraints:'WebAuthn virtual authenticator. Mock biometric response.', expectedOutput:'Virtual authenticator registered. Login with biometric: authenticator provides the response. App logs in.', check:'`context.on("page",async page=>{const client=await page.context().newCDPSession(page);await client.send("WebAuthn.enable");await client.send("WebAuthn.addVirtualAuthenticator",{...});})`. CDP: Chromium only.' },
    { id:23, level:3, title:'Auth State in CI/CD', scenario:'CI/CD needs stable auth without interactive login.', objective:'Strategy: (1) Store auth credentials as CI secrets. (2) Generate auth.json in setup. (3) Cache auth.json between CI runs (when not expired). (4) Rotate credentials securely.', constraints:'CI secrets. Cache strategy. Rotation.', expectedOutput:'CI: credentials from secrets → login → auth.json generated → cached. Next run: reuse cache if < 1h old.', check:'CI cache: `key:playwright-auth-${{hashFiles("playwright.config.ts")}}`. Cache auth.json. Invalidate: any config change. Always regenerate if cache miss. Credentials: GitHub/GitLab secrets.' },
    { id:24, level:3, title:'Auth Load Testing', scenario:'Verify the auth system handles many concurrent logins.', objective:'10 parallel setup tests, each creating a different user and saving auth. Measure: total time, success rate.', constraints:'10 concurrent logins. Timing. Success rate.', expectedOutput:'10 concurrent logins: all succeed in < 30s. Sequential: 50s. Speedup: 1.7x.', check:'Parallelism: `Promise.all(users.map(async user=>{const ctx=await browser.newContext();const page=await ctx.newPage();await login(page,user);await ctx.storageState({path:authPath(user)});}))`. Success: no 429 rate limiting.' },
    { id:25, level:3, title:'Auth Token Inspection', scenario:'Decode and verify the JWT token for claims.', objective:'After login: `const token=await page.evaluate(()=>localStorage.getItem("auth_token"))`. Decode: `jwt.decode(token)`. Verify: `{sub:"user-id",role:"admin",exp:...}`. Assert correct claims.', constraints:'Get JWT. Decode. Assert claims.', expectedOutput:'JWT decoded: {sub:"user-123",role:"admin",exp:1705363200}. All claims correct.', check:'`jwt.decode(token)`: decodes without verification (no secret). `jwt.verify(token,secret)`: verifies signature. For tests: decode and check claims (sub, role, exp). Don\'t verify signature unless testing auth security.' },
    { id:26, level:3, title:'Auth State Persistence Testing', scenario:'Auth state must survive page refreshes and back/forward navigation.', objective:'Login. Refresh page. Verify still logged in. Navigate away. Navigate back. Verify still logged in.', constraints:'Refresh. Navigate away/back. Verify auth.', expectedOutput:'All navigation events: user stays logged in. Persistent cookie or localStorage-based auth.', check:'Persistence types: session cookie (cleared on browser close), persistent cookie (survives close), localStorage (survives close). Test: reload → check session. Navigate → check session. Close/reopen → check only for persistent.' },
    { id:27, level:3, title:'Cross-Domain Auth', scenario:'Auth state must work across subdomains (e.g., app.example.com and api.example.com).', objective:'Login on app.example.com. Verify the auth cookie is accessible on api.example.com. Check cookie `domain` attribute.', constraints:'Cross-subdomain cookie. Domain attribute.', expectedOutput:'Cookie domain: `.example.com` (leading dot → accessible on all subdomains). Both app and api subdomains authenticated.', check:'Cookie domain: `.example.com` (with dot) → shared across subdomains. `example.com` (no dot) → only the exact domain. Verify: `context.cookies("https://api.example.com")` returns the auth cookie.' },
    { id:28, level:3, title:'Auth State Migration', scenario:'The app is migrating from cookie auth to JWT. Both must work during the migration.', objective:'Test both auth methods work: (1) Set old cookie → verify access. (2) Set new JWT → verify access. (3) Both set → verify JWT takes precedence.', constraints:'Two auth methods. Precedence test.', expectedOutput:'Cookie: access granted. JWT: access granted. Both: JWT takes precedence.', check:'Migration testing: ensure old and new auth coexist. Precedence: app logic decides which to use when both present. Test explicitly. Document: when migration is complete, cookie auth can be removed.' },
    { id:29, level:3, title:'Permission-Based Testing', scenario:'Different roles have different permissions. Test permission boundaries.', objective:'Admin: can access /admin. User: cannot access /admin (403). Guest: redirected to login. Test each.', constraints:'Three roles. Three outcomes. Permission assertions.', expectedOutput:'Admin → /admin: 200. User → /admin: 403 error page. Guest → /admin: redirect to /login.', check:'Permission tests: positive (access granted) and negative (access denied). Negative: verify correct error (403, not 404). Verify error message is user-friendly. Test boundary: just-below and at-permission level.' },
    { id:30, level:3, title:'Auth Logging', scenario:'Log all authentication events during tests for debugging.', objective:'`page.on("request",req=>{ if(req.url().includes("/auth")) log(req.url(),req.method(),req.postData()) })`. Log auth responses too.', constraints:'Request listener for /auth paths. Log method and body (masking password).', expectedOutput:'Login: "POST /api/auth {email:user@example.com,password:***}"', check:'Mask password: `JSON.stringify({...data,password:"***"})`. Log: helps debug auth failures in CI. Alert: never log actual passwords. Mask before logging.' },
    { id:31, level:4, title:'Auth State as Test Data', scenario:'Auth state should be version-controlled test data, not generated at test time.', objective:'Commit `auth.json` files (with test-user credentials) to git. Tests use them directly. No setup step. Tradeoffs: simpler but credentials visible in git.', constraints:'Committed auth.json. Tradeoffs analysis.', expectedOutput:'Test starts with pre-committed auth.json. No login step. Tradeoff: test credentials in git (acceptable for test-only accounts).', check:'Committed auth: simplest approach. Only for test-only accounts (never real credentials). Rotate regularly. Encrypt with git-crypt or secret management. Tradeoff: vs. generated auth (always fresh).' },
    { id:32, level:4, title:'Impersonation Testing', scenario:'An admin feature allows impersonating any user. Test it.', objective:'Login as admin. Navigate to /admin/users/123/impersonate. Verify now acting as user 123. Perform actions as user 123. Return to admin via "Stop impersonating". Verify admin session restored.', constraints:'Impersonation. Actions as impersonated user. Return.', expectedOutput:'Admin impersonates user → has user\'s permissions. Stop impersonating → admin permissions restored.', check:'Impersonation: checks correct permission scope during impersonation. After return: admin cookies/token restored. Verify: no admin actions possible while impersonating (if restricted).' },
    { id:33, level:4, title:'Auth Security Testing', scenario:'Test for common authentication security issues.', objective:'(1) Brute force protection: 5+ failed logins → locked. (2) Account enumeration: invalid user vs invalid password → same error. (3) SQL injection in login. (4) CSRF token validation.', constraints:'Four security tests.', expectedOutput:'(1) 6th attempt: account locked. (2) Both return "Invalid credentials". (3) SQL injection: rejected. (4) No CSRF token: rejected.', check:'Security tests: probe for vulnerabilities. Report: which security controls are working. (1): verify lockout. (2): same error for both. (3): app returns 400, not 200 with data. (4): remove CSRF token, verify rejection.' },
    { id:34, level:4, title:'Refresh Token Testing', scenario:'JWT access tokens expire in 15 minutes. Refresh tokens extend the session.', objective:'Login: get access_token (15min) and refresh_token (7 days). Simulate access_token expiry: `page.evaluate(()=>localStorage.setItem("expires","0"))`. Trigger an API call. App should auto-refresh.', constraints:'Simulate expiry. Trigger auto-refresh. Verify new token.', expectedOutput:'Simulated expiry → app makes POST /api/refresh → new access_token → API call succeeds.', check:'Auto-refresh: app checks expiry before API calls. If expired: POST /api/refresh with refresh_token → new access_token. Test: verify the refresh request is made and the subsequent API call uses the new token.' },
    { id:35, level:4, title:'Auth State Synchronization', scenario:'Multiple tabs must share auth state (login in one tab → all tabs are logged in).', objective:'Page 1: login. Page 2 (same context): navigate to protected page. Verify page 2 also sees the auth state.', constraints:'Two pages, same context. Shared auth.', expectedOutput:'Login on page 1 → page 2 can access protected content. Same context = shared cookies.', check:'Same context = shared cookies and localStorage. `const page2=await context.newPage()`. After login on page1: page2 shares the session cookie. Tabs in a real browser work the same way.' },
    { id:36, level:4, title:'Auth Performance', scenario:'Auth setup is the bottleneck in the test suite. Optimize it.', objective:'(1) API login (not UI): much faster. (2) Cache auth.json: reuse between test runs. (3) Worker-scoped auth: one login per worker (not per test).', constraints:'All three optimizations. Measure before/after.', expectedOutput:'UI login: 3s. API login: 200ms. Cached: 0ms (file load). Worker-scoped: 1 login per worker.', check:'API login: `request.post("/api/login",{data:{email,password}})`. Extract token. Set in context. Much faster than UI. Cache: `if(fs.existsSync("auth.json")&&!isExpired)loadCache()`. Worker scope: `{scope:"worker"}` fixture.' },
    { id:37, level:4, title:'Delegated Auth Testing', scenario:'Service-to-service auth (machine-to-machine) must be tested.', objective:'Generate a client credentials token (OAuth2 M2M): `POST /oauth/token {grant_type:"client_credentials",client_id,client_secret}`. Use the token for API calls. Verify service has correct scopes.', constraints:'Client credentials flow. Scopes. Service API calls.', expectedOutput:'M2M token received with scopes ["read:users","write:orders"]. API calls with this token succeed for allowed scopes, fail for others.', check:'Client credentials: no user involved. Token represents the service. Scopes: `read:users` allows GET /users, `write:orders` allows POST /orders. Verify 403 for out-of-scope operations.' },
    { id:38, level:4, title:'Auth State Debugging', scenario:'Auth tests are failing in CI but passing locally. Debug the difference.', objective:'CI: log the full auth state (cookies, localStorage) after setup. Compare to local. Identify the difference (domain mismatch, expired state, different credentials).', constraints:'Full state logging. Local vs CI comparison.', expectedOutput:'CI cookies: domain "localhost". Local: domain "example.com". Mismatch: auth.json from local cannot be used in CI.', check:'Debug auth: `console.log(JSON.stringify(await context.storageState()))`. Compare cookies: domain, path, secure, httpOnly flags. Common CI issue: wrong domain in saved cookies.' },
    { id:39, level:4, title:'Passwordless Auth Testing', scenario:'The app uses magic links for passwordless authentication.', objective:'Submit email. Mock the email: intercept the email send API, extract the magic link. Navigate to the magic link. Verify logged in.', constraints:'Email interception. Magic link extraction. Navigation.', expectedOutput:'Submit email → intercept /api/send-magic-link → extract token → navigate to /auth/magic?token=X → logged in.', check:'Magic link: token in the link URL. Intercept: `page.route("/api/send-magic-link",async route=>{const body=await route.request().postDataJSON();const token=generateTestToken(body.email);route.fulfill({json:{success:true}})})`. Navigate to the link.' },
    { id:40, level:4, title:'Auth State for External Services', scenario:'The app integrates with Stripe, GitHub, Slack. Test OAuth flows for each.', objective:'For each external service: mock the OAuth callback. Return a fake access token. Verify the app stores it correctly and uses it for API calls.', constraints:'Three service OAuth mocks. Token storage. API call.', expectedOutput:'GitHub OAuth mock: app stores GitHub token. Subsequent GitHub API calls use the token.', check:'Mock OAuth callback: `page.route("/auth/github/callback",route=>route.fulfill({status:302,headers:{Location:"/dashboard?github_connected=true"}}))`. Also mock the token exchange endpoint.' },
    { id:41, level:5, title:'Auth Framework Design', scenario:'Design a complete authentication testing framework.', objective:'Build: (1) Multi-role auth manager. (2) Token lifecycle management. (3) Security test suite. (4) Auth state inspector. (5) Performance monitoring. (6) CI/CD integration.', constraints:'All 6 components. npm package.', expectedOutput:'`import {AuthTest} from "@company/auth-test"`. `AuthTest.asAdmin().onPage("/admin").expectAccess()`. Fluent, readable.', check:'Core: role-based storageState management. Token: expiry tracking, auto-refresh. Security: brute force, enumeration, CSRF. Inspector: decode JWT, log cookies. CI: secrets management.' },
    { id:42, level:5, title:'Zero-Trust Auth Testing', scenario:'Test a zero-trust architecture where every request is re-authenticated.', objective:'Each API request: verify it includes a valid token. No implicit trust. Test: token valid → access. Token missing → 401. Token for wrong scope → 403. Token from different user → 403.', constraints:'Four authentication scenarios. All API requests.', expectedOutput:'Valid: 200. Missing: 401. Wrong scope: 403. Wrong user: 403. Zero-trust: each scenario tested.', check:'Zero-trust: no session cookies, every request authenticated. Token: short-lived JWT. Test: use `page.on("request")` to verify every API request has the Authorization header. Scope and user isolation.' },
    { id:43, level:5, title:'Auth State Attack Simulation', scenario:'Simulate common session attacks and verify the app is protected.', objective:'(1) Session fixation: set a known session ID before login, verify it changes after login. (2) Session hijacking: steal session cookie, use in a different context. (3) CSRF: submit form without CSRF token.', constraints:'Three attack simulations. All should be blocked.', expectedOutput:'(1) Session ID changes after login. (2) Stolen session: rejected. (3) No CSRF token: 403.', check:'Security tests: deliberately try to exploit. (1) Session fixation: `context.addCookies([{name:"session",value:"known"}])`, login, check if value changed. (2) Steal cookie, use in new incognito context. (3) Remove CSRF token from form.' },
    { id:44, level:5, title:'Federated Identity Testing', scenario:'The app supports multiple identity providers (Google, Microsoft, GitHub). Test all.', objective:'For each IdP: mock the OAuth flow. Verify the app handles the callback correctly. Verify the correct user profile is created/linked.', constraints:'Three IdP mocks. Profile creation. Account linking.', expectedOutput:'Google login → creates profile with Google photo/name. GitHub login → links GitHub repo access. Microsoft login → uses corporate email.', check:'IdP mock: intercept the OAuth callback URL. Return fake id_token with the provider\'s user claims. Verify: app creates user with correct attributes. Link: if user exists, link new IdP. Test both cases.' },
    { id:45, level:5, title:'Auth Compliance Testing', scenario:'GDPR and HIPAA require specific auth behaviors. Test compliance.', objective:'(1) Right to be forgotten: delete user, verify session invalidated. (2) Audit log: all auth events logged. (3) Session timeout: after 30min inactive, session expires. (4) Password policy: enforced.', constraints:'Four compliance checks.', expectedOutput:'(1) Deleted user → existing session rejected. (2) Audit log has login, logout, and failure events. (3) After 30min: session expired. (4) Weak password: rejected.', check:'Compliance testing: verify specific behaviors required by regulations. (1) Verify 401 after deletion. (2) Check audit API. (3) Simulate time with `page.clock`. (4) Test password validation.' },
    { id:46, level:5, title:'Auth State Chaos Testing', scenario:'Auth infrastructure is degraded. Test graceful degradation.', objective:'Scenarios: (1) Auth service down. (2) Slow auth service (5s). (3) Auth service intermittently failing. (4) Cache miss. All should have graceful UX.', constraints:'Four chaos scenarios. Graceful handling.', expectedOutput:'(1) "Service unavailable, try later". (2) Loading indicator during 5s wait. (3) Retry with user feedback. (4) Re-authentication prompt.', check:'Mock: `page.route("/api/auth",route=>chaos(route))`. Chaos: abort (down), delay (slow), alternating (intermittent). Assert: app handles each without crashing, shows helpful message.' },
    { id:47, level:5, title:'Distributed Session Testing', scenario:'The app runs on 3 servers. Auth state must be consistent across all servers.', objective:'Login on server A. Navigate to server B (via load balancer). Verify still logged in. Logout on server C. Verify logged out on server A.', constraints:'Multi-server simulation. Cross-server auth. Cross-server logout.', expectedOutput:'Login on A → access B: logged in. Logout on C → check A: logged out.', check:'Distributed sessions: shared session store (Redis, DynamoDB). Test: force requests to specific servers via routing headers. Cross-server logout: verify session store updated. Key: session store is the truth, not local memory.' },
    { id:48, level:5, title:'Auth Test Matrix', scenario:'Test all combinations of: 3 auth methods × 4 roles × 3 environments.', objective:'Matrix: 36 combinations. For each: verify auth works, correct permissions applied. Run in parallel.', constraints:'Matrix generation. 36 tests. Parallel. All pass.', expectedOutput:'All 36 combinations: auth successful, correct permissions. Failures: report which combination failed and why.', check:'Matrix: `authMethods.flatMap(m=>roles.flatMap(r=>environments.map(e=>({method:m,role:r,env:e}))))`. Playwright project per environment. Test parameterized over auth method and role.' },
    { id:49, level:5, title:'Auth API Contract Testing', scenario:'The auth service has a contract. Test that it is honored.', objective:'Consumer: defines expected auth API behavior. Auth service: must fulfill the contract. Run contract tests on every deployment. Fail if contract broken.', constraints:'Auth API contract. Consumer pact. Provider verification.', expectedOutput:'Consumer expects: POST /login → 200 {token,expiresIn}. Auth service: verified to return this. Deploy: contract tests in CI gate.', check:'Pact: consumer defines expected interactions. Provider verifies. `POST /login {email,password}` → `{token:string,expiresIn:number}`. Any change to this contract: fails the consumer tests.' },
    { id:50, level:5, title:'Full Auth Testing System', scenario:'Build a complete authentication testing system for enterprise applications.', objective:'Build: (1) Multi-IdP support. (2) Role-based access verification. (3) Token lifecycle testing. (4) Security attack simulation. (5) Compliance validation. (6) Performance benchmarking. (7) CI/CD integration.', constraints:'All 7 components. Composable. Documented.', expectedOutput:'`import {AuthTestSystem} from "@company/auth-test"`. `AuthTestSystem.role("admin").withMFA().on("staging").run()`.', check:'Fluent builder. Core: storageState management. IdP: multiple OAuth mocks. Security: attack suite. Compliance: GDPR/HIPAA checks. Performance: auth timing budgets. CI: secrets, caching, reporting.' },
  ],

  parallel: [
    { id:1, level:1, title:'Workers Configuration', scenario:'Run tests in parallel by configuring multiple workers.', objective:'In config: `workers:4`. Run the test suite. Observe 4 tests running simultaneously. Compare execution time vs `workers:1`.', constraints:'workers:4. Observe parallel execution. Time comparison.', expectedOutput:'4 tests: run simultaneously. Total time ≈ time of slowest test (not sum). workers:1: sequential. workers:4: ~4x faster.', check:'`workers:N`: N parallel worker processes. Each worker runs tests independently. Default: 1 worker per file (at most). `fullyParallel:true`: also parallelizes within a file.' },
    { id:2, level:1, title:'fullyParallel Mode', scenario:'By default, tests within a file run sequentially. Enable full parallelism.', objective:'`fullyParallel:true` in config. All tests, even within the same file, run in parallel. Each test gets its own worker.', constraints:'fullyParallel:true. Verify within-file parallelism.', expectedOutput:'File with 10 tests: all run in parallel (with enough workers). No sequential ordering guarantee.', check:'`fullyParallel:true`: every test runs in its own worker. Test ordering: no guarantee. Requirement: tests must be independent (no shared state between tests in the same file).' },
    { id:3, level:1, title:'Worker Count Strategies', scenario:'Choose the optimal worker count for CI and local development.', objective:'Local: `workers:"50%"` (half of CPUs). CI: `workers:2` (limited resources). Show both configurations.', constraints:'Percentage format. Fixed count. CI vs local.', expectedOutput:'Local (8 CPUs): 4 workers. CI (4 vCPUs): 2 workers.', check:'`workers:"50%"`: percentage of available CPUs. `workers:4`: fixed. `workers:1`: serial. `process.env.CI?"2":"50%"`: conditional. Recommendation: match your CI resource limit.' },
    { id:4, level:1, title:'Test File Parallelism', scenario:'Different test files should run in parallel.', objective:'3 test files: `login.spec.ts`, `products.spec.ts`, `checkout.spec.ts`. With `workers:3`: all three run simultaneously.', constraints:'Three files. workers:3. Verify parallel execution.', expectedOutput:'All 3 files start simultaneously. Finish independently.', check:'File-level parallelism: default behavior. Each file runs in a separate worker. `workers:N`: up to N files run simultaneously. `fullyParallel:false` (default): within a file, tests run sequentially.' },
    { id:5, level:1, title:'Test.describe.configure for Parallelism', scenario:'Control parallelism at the describe level.', objective:'`test.describe.configure({mode:"parallel"})` inside a describe block. Tests in this describe run in parallel. Other describe blocks: default behavior.', constraints:'describe-level parallel. Default behavior outside.', expectedOutput:'Describe with mode:"parallel": all tests run simultaneously. Others: sequential.', check:'`test.describe.configure({mode:"parallel"})`: runs tests in the describe in parallel. `mode:"serial"`: sequential. `mode:"default"`: inherits from config. Scoped to the describe block.' },
    { id:6, level:1, title:'Serial Tests', scenario:'Some tests must run in a specific order (e.g., create → update → delete).', objective:'`test.describe.configure({mode:"serial"})`. Tests in this describe run in order: create (1), update (2), delete (3). If create fails, update and delete are skipped.', constraints:'serial mode. Order dependency. Skip on earlier failure.', expectedOutput:'create passes → update runs. update passes → delete runs. create fails → update and delete skipped.', check:'`mode:"serial"`: sequential in order. If a test fails: subsequent tests in the group are skipped. Use for stateful workflows. Avoid: prefer independent tests when possible.' },
    { id:7, level:1, title:'Parallel Tests Independence', scenario:'Parallel tests must not share state with each other.', objective:'Demonstrate: two parallel tests both modify a shared variable → race condition. Fix: each test uses its own isolated state (own user, own data).', constraints:'Demonstrate race condition. Fix with isolation.', expectedOutput:'Shared variable: random failures. Isolated state: all pass.', check:'Independence: each test creates its own data (unique email, unique product). No shared mutable state. Fixture: creates test-specific data. Cleanup: fixture teardown removes the data.' },
    { id:8, level:1, title:'Parallel Browser Contexts', scenario:'Each parallel test gets its own BrowserContext.', objective:'Log `context` in 4 parallel tests. Verify each is a different instance. Verify they don\'t share cookies or localStorage.', constraints:'Verify different contexts. Cookie isolation.', expectedOutput:'4 parallel tests: 4 different BrowserContext instances. Setting a cookie in one: doesn\'t appear in others.', check:'Default: each test gets its own BrowserContext. Browser (the process) can be shared between tests in the same worker. BrowserContext: isolated cookies, localStorage, session storage.' },
    { id:9, level:1, title:'Parallel Port Conflicts', scenario:'Parallel tests that each start a local server may use the same port → conflict.', objective:'Use dynamic port allocation: `const port=await findFreePort()`. Or: use a different port per worker (`testInfo.workerIndex`).', constraints:'Dynamic port. workerIndex-based port. No conflict.', expectedOutput:'Worker 0: port 3000. Worker 1: port 3001. Worker 2: port 3002. No conflicts.', check:'`testInfo.workerIndex`: 0-based index of the current worker. `basePort+testInfo.workerIndex`: unique port per worker. Or: `net.createServer()` on port 0 (auto-assign) → `server.address().port`.' },
    { id:10, level:1, title:'Parallel Execution Report', scenario:'View which tests ran in parallel and on which workers.', objective:'Run tests with `workers:4`. Open the HTML report. Find the "Timeline" view. Observe which tests ran simultaneously.', constraints:'HTML report. Timeline view. Worker identification.', expectedOutput:'Timeline: 4 lanes (workers). Tests shown in parallel. Longest test determines total time.', check:'HTML report timeline: shows test start/end times. `testInfo.workerIndex`: shows which worker. Worker 0: tests 1,5,9. Worker 1: tests 2,6,10. Helps identify imbalanced workers.' },
    { id:11, level:2, title:'Parallel Test Data Isolation', scenario:'Each parallel test needs its own database records without conflicting.', objective:'Test fixture: generates a unique user email with `Date.now()` suffix. Creates the user via API. Deletes after test. No conflicts between parallel tests.', constraints:'Unique email per test. Create/delete. No conflicts.', expectedOutput:'Test 1: user_1705363200000@test.com. Test 2: user_1705363200001@test.com. Both run simultaneously, no conflict.', check:'Unique identifiers: `email=${Date.now()}-${Math.random()}@test.com`. Or: UUID. Prefix: `user-${testInfo.testId}@test.com`. Teardown: delete user by ID (not by email to avoid race).' },
    { id:12, level:2, title:'Worker-Scoped Setup', scenario:'Expensive setup (database connection) should happen once per worker, not once per test.', objective:'Worker fixture with `{scope:"worker"}`: creates a DB connection on worker start. All tests in the worker reuse it. Cleanup: close connection after last test.', constraints:'Worker scope. Shared connection. Cleanup.', expectedOutput:'4 workers: 4 DB connections (one each). 10 tests per worker: each reuses its worker\'s connection.', check:'Worker scope: `[async({},use)=>{const db=await connect();await use(db);await db.close();},{scope:"worker"}]`. Created once per worker (on first test). Closed when worker finishes all tests.' },
    { id:13, level:2, title:'Parallel API Testing', scenario:'Run API tests in parallel for speed.', objective:'50 API endpoint tests. `workers:10`. Each test calls one endpoint. All 50 complete in parallel batches. Verify no 429 (rate limiting).', constraints:'50 tests. 10 workers. Rate limit awareness.', expectedOutput:'50 tests: 5 batches of 10. Total time: ~5x faster than sequential. No 429 errors.', check:'API tests: no browser, so very fast. Rate limiting: if API rate limits at 10 req/s: use `workers:10` max. Add `waitForTimeout` if needed. Or: add retry on 429 with backoff.' },
    { id:14, level:2, title:'Parallel File Upload Tests', scenario:'Tests that upload files should not conflict over the same file path.', objective:'Each test: copy the test file to a unique temp path. Upload that copy. Delete after.', constraints:'Unique temp file per test. Copy. Upload. Delete.', expectedOutput:'Test 1: uploads /tmp/test-file-1.pdf. Test 2: uploads /tmp/test-file-2.pdf. No conflict.', check:'Unique path: `path.join(os.tmpdir(),"upload-"+testInfo.testId+path.extname(file))`. Copy: `fs.copyFileSync(sourcePath,tempPath)`. Upload. Cleanup: `fs.unlinkSync(tempPath)` in fixture teardown.' },
    { id:15, level:2, title:'Parallelism with Shared Resources', scenario:'Parallel tests need a limited shared resource (only 5 DB connections available).', objective:'Connection pool with semaphore: max 5 concurrent. Tests wait for an available connection. No more than 5 tests access the DB simultaneously.', constraints:'Pool of 5. Semaphore. Wait when all busy.', expectedOutput:'5 tests: immediate access. Test 6: waits. First test finishes → test 6 gets connection.', check:'Semaphore: `let count=5;const wait=()=>new Promise(r=>{const t=setInterval(()=>{if(count>0){count--;clearInterval(t);r();}},50)})`. Fixture: `await wait();await use(db);count++;`. Worker-scoped better.' },
    { id:16, level:2, title:'Test Ordering in Parallel Mode', scenario:'Tests run in parallel but their order is non-deterministic. Verify there are no ordering dependencies.', objective:'Shuffle the test file order: `--shard=2/4` runs a subset. Run tests in different orders. Verify all combinations pass.', constraints:'Non-deterministic ordering. Sharding. Independence.', expectedOutput:'All shards pass regardless of which tests they run. No ordering dependency.', check:'`--shard=1/4`: runs 25% of tests. Different shards run different subsets in different orders. If a test only passes when run after another test: it has an ordering dependency → fix it.' },
    { id:17, level:2, title:'Parallel Visual Testing', scenario:'Visual tests run in parallel and must not interfere with each other\'s screenshots.', objective:'5 parallel visual tests. Each takes a screenshot. Snapshots named by test ID. No overwrite conflicts.', constraints:'Unique snapshot names. No overwrites. Verify isolation.', expectedOutput:'5 unique snapshots. Each test\'s snapshot is compared only to its own baseline.', check:'Unique snapshot names: `toHaveScreenshot(testInfo.testId+".png")` or just `toHaveScreenshot("test-name.png")` (name is unique per test). Playwright handles snapshot isolation per test.' },
    { id:18, level:2, title:'Load Balancing Tests Across Workers', scenario:'Some tests are much slower than others. Balance the work across workers.', objective:'Run with `workers:4`. Check if workers finish at the same time (balanced) or if some finish early (imbalanced). Investigate the slow tests.', constraints:'Timeline analysis. Balance check. Slow test identification.', expectedOutput:'Worker 0: finishes in 5min. Worker 3: finishes in 15min. Imbalanced. Slow tests: 3 checkout tests (each 3min).', check:'Imbalanced workers: some workers idle while others run slow tests. Solution: split slow test files. Or: run slow tests first (so they don\'t hold up the end). Or: more workers.' },
    { id:19, level:2, title:'Parallel Test with Unique URLs', scenario:'Parallel tests navigating to the same URL can interfere via shared state on the server.', objective:'Each test: creates its own user, logs in with that user, navigates to the profile URL. Profile is user-specific. No server-side state conflict.', constraints:'User-specific URLs. Unique per test.', expectedOutput:'Test 1: /users/1/profile. Test 2: /users/2/profile. Same URL pattern, different user data.', check:'Server-side isolation: use user-specific URLs. E.g., `/api/user/profile` where the user is identified by the auth token (not URL parameter). Each test\'s token → its own data.' },
    { id:20, level:2, title:'Detecting Parallel Test Pollution', scenario:'A test sometimes fails because another parallel test modified shared state.', objective:'Reproduce: two tests both set a global user preference. One test reads the preference set by the other. Fix: isolate preferences per test user.', constraints:'Reproduce shared state issue. Fix with isolation.', expectedOutput:'Before fix: 2/10 runs fail due to pollution. After fix: 10/10 pass.', check:'Shared state: global settings, shared database rows, shared files. Detection: run test in isolation (passes) and in parallel (fails). Fix: use test-specific data for everything.' },
    { id:21, level:3, title:'Test Sharding', scenario:'Split the test suite across multiple CI machines for faster execution.', objective:'`--shard=1/4` on machine 1. `--shard=2/4` on machine 2. `--shard=3/4` on machine 3. `--shard=4/4` on machine 4. All 4 run simultaneously.', constraints:'4 shards. 4 machines. Combine reports.', expectedOutput:'Each machine runs 25% of tests. Total time: 1/4 of single-machine time. Reports combined after.', check:'Sharding: `npx playwright test --shard=1/4`. Each shard runs tests with index `i % totalShards === shardIndex`. Reports: merge with `npx playwright merge-reports`. Each shard outputs a blob report.' },
    { id:22, level:3, title:'Merging Shard Reports', scenario:'Combine reports from 4 CI shards into one.', objective:'Each shard: `reporter:[["blob"]]`. After all shards: `npx playwright merge-reports ./all-blobs --reporter=html`. Single HTML report with all results.', constraints:'Blob reporter. Download all blobs. Merge command. HTML output.', expectedOutput:'One HTML report with all 100 tests from 4 shards.', check:'Blob reporter: `reporter:[["blob",{outputDir:"blob-report"}]]`. Download blobs from all CI workers. Merge: `npx playwright merge-reports ./blob-report --reporter=html`. ' },
    { id:23, level:3, title:'Playwright Workers and Node.js Processes', scenario:'Understand the architecture: one worker = one Node.js process.', objective:'In a test: `process.pid` — each worker has a unique PID. Worker-scoped fixtures share state within a PID. Test-scoped: new instances per test.', constraints:'Log process.pid. Multiple workers. PID comparison.', expectedOutput:'Worker 0: pid 12345. Worker 1: pid 12346. Test A and Test B in worker 0: same pid. Test C in worker 1: different pid.', check:'Workers = separate Node.js processes. No shared memory between workers. Worker-scoped fixture: shared within the same PID. Cross-worker: use files, databases, or HTTP servers to share.' },
    { id:24, level:3, title:'Cross-Worker Data Sharing', scenario:'Setup data created by Worker 1 needs to be accessible by Worker 2.', objective:'Worker 1 (setup project): creates data, writes to `test-data.json`. Worker 2 (test project): reads `test-data.json`. Workers communicate via file system.', constraints:'File-based sharing. Setup project writes. Test project reads.', expectedOutput:'Setup: creates test-data.json with product IDs. Tests: read product IDs, use in tests.', check:'Cross-worker via file: JSON file. `fs.writeFileSync("test-data.json",JSON.stringify(data))`. `const data=JSON.parse(fs.readFileSync("test-data.json","utf8"))`. Or: database, HTTP server.' },
    { id:25, level:3, title:'Parallel Performance Testing', scenario:'Run performance measurements in parallel to reduce total time.', objective:'20 performance tests (each measures one API endpoint). `workers:20`: all run simultaneously. Collect all timing results. Report p50, p95, p99 across all endpoints.', constraints:'20 parallel perf tests. Collect timings. Aggregate.', expectedOutput:'All 20 run simultaneously. Results: {endpoint,p50,p95,p99}. Total time: time of slowest endpoint.', check:'Parallel perf: measure timing in each test. Write to a shared file (with locking or unique names). Aggregate: read all files in afterAll. Or: write to a database and query in a final report step.' },
    { id:26, level:3, title:'Dynamic Worker Count', scenario:'Automatically scale workers based on available system resources.', objective:'`const workers=Math.max(1,Math.floor(os.cpus().length*0.75))`. Use 75% of CPUs. Adjust for CI: cap at CI_CONCURRENT_WORKERS env var.', constraints:'CPU-based scaling. CI cap. Min 1.', expectedOutput:'Local (8 CPUs): 6 workers. CI (4 CPUs, cap 2): 2 workers.', check:'`os.cpus().length`: number of logical CPUs. 75%: leaves some for the OS. CI cap: `parseInt(process.env.CI_CONCURRENT_WORKERS||"99")`. `workers:Math.min(cpuBased,ciCap)`.' },
    { id:27, level:3, title:'Parallel Tests with Shared Fake Timer', scenario:'Tests that manipulate time (using page.clock) must not interfere with each other.', objective:'Each parallel test manipulates `page.clock` independently. Verify one test\'s clock changes don\'t affect another.', constraints:'page.clock isolation. Parallel clock manipulation.', expectedOutput:'Test 1: sets date to Dec 25. Test 2 (same time): sets date to Jan 1. Both work correctly, no interference.', check:'`page.clock` is per-page, so it\'s isolated. Each test has its own page → its own clock. No cross-test interference. Verify: test 1\'s clock change doesn\'t affect test 2\'s date.' },
    { id:28, level:3, title:'Parallel Auth Setup', scenario:'Generate auth state for 10 roles in parallel during global setup.', objective:'`global-setup.ts`: `await Promise.all(roles.map(async role=>{ const browser=await chromium.launch(); const page=await browser.newPage(); await login(page,role); await page.context().storageState({path:authPath(role)}); await browser.close(); }))`.', constraints:'Promise.all. One browser per role. 10 auth files.', expectedOutput:'10 roles: all auth files generated in parallel. 10x faster than sequential.', check:'Global setup: runs once before all workers. Parallel setup: `Promise.all`. Each role: own browser (parallel execution). After: 10 auth files. Workers: use the auth files in their tests.' },
    { id:29, level:3, title:'Queue-Based Worker Management', scenario:'A central queue dispatches tests to workers. Workers process from the queue.', objective:'Implement a simple queue: tests pop from the queue, process, and report results. Demonstrate how Playwright\'s built-in worker system works similarly.', constraints:'Queue concept. Explain Playwright\'s model.', expectedOutput:'Playwright: test runner maintains a queue. Workers pop tests, run them, report results. Queue empty: workers idle and shut down.', check:'Playwright internal model: test runner has all tests. Workers ask for the next test. Run it. Report result. Ask for next. Repeat until done. Workers are reused across test files (unless crashed).' },
    { id:30, level:3, title:'Parallel Debug Strategies', scenario:'A test fails only in parallel. Debug without breaking parallelism.', objective:'(1) Add logging with `testInfo.workerIndex`. (2) Reproduce with `--repeat-each=10`. (3) Add `--shard` to isolate. (4) Temporarily add `test.only` to reproduce in isolation.', constraints:'All four debug strategies.', expectedOutput:'Strategy 4: test passes in isolation → parallel-specific issue. Fix: isolate test data.', check:'Debug parallel: `--workers=1` to reproduce sequentially. If it passes: race condition. Add logging with worker index to track execution. Check: shared state (file, DB, env vars). Fix: isolate.' },
    { id:31, level:4, title:'Optimal Sharding Strategy', scenario:'Determine the optimal number of shards for a 500-test suite on different CI machines.', objective:'Analyze test durations. Calculate optimal shard count: minimize total time given CI machine specs (2 CPUs, 4GB RAM per machine).', constraints:'Duration analysis. Machine specs. Optimal shard count.', expectedOutput:'500 tests, avg 10s each = 5000s. 2 CPUs per machine, 4 workers per machine. Machines needed: 5000/(2*4*10)=62. With 10 machines: 5000/(10*4*10)=12.5s total.', check:'Calculation: total_tests × avg_duration / (workers_per_machine × machine_count). Minimum time: max_test_duration (irreducible). Monitor: CI machine CPU/RAM usage during runs.' },
    { id:32, level:4, title:'Parallel Test Prioritization', scenario:'Critical tests should run first (while other workers handle the rest).', objective:'Priority queue: `critical` tests first, then `regression`, then `visual`. Implement via project ordering and `--project=critical,regression,visual`.', constraints:'Project ordering. Priority execution. Critical first.', expectedOutput:'Critical tests: start immediately. Regression: start after critical. Visual: last. Fast feedback on critical failures.', check:'Project ordering: in config, projects are executed in order (by default). `--project=critical`: runs only critical. For custom ordering: run `critical` project first in CI, then `regression`.' },
    { id:33, level:4, title:'Parallel Test Suite Maintenance', scenario:'Adding tests to a sharded suite requires rebalancing to keep execution time even.', objective:'After adding 50 new slow tests: analyze which shards run long. Rebalance: move tests between shards, or add more shards.', constraints:'Duration analysis after adding tests. Rebalancing.', expectedOutput:'Before: 4 shards, balanced. After adding 50 tests to shard 1: shard 1 takes 2x longer. Add more shards or move tests.', check:'Playwright shards by test order. To rebalance: move test files. Or: use `@playwright/test`\'s `--repeat-each` to identify the slowest tests. Or: use `--shard` with more shards.' },
    { id:34, level:4, title:'Parallel Test with Shared Database', scenario:'Parallel tests need to READ from a shared database and WRITE test data.', objective:'Reads: safe to share (read-only). Writes: use unique table rows per test (test-specific prefix). Verify no write conflicts.', constraints:'Read sharing. Write isolation. Conflict-free.', expectedOutput:'All tests read shared config. Each test writes to its own rows (unique prefix). No conflicts.', check:'Read-sharing: reads are safe to parallelize. Write isolation: unique prefix (`user_testId_email`). Cleanup: delete rows with the test\'s prefix. Transaction: wrap in a transaction if atomicity needed.' },
    { id:35, level:4, title:'Parallel Test Flakiness Analysis', scenario:'A test is flaky only when other specific tests run in parallel.', objective:'Binary search: run test X with half of the other tests. Identify which tests cause X to fail. Fix the shared state between X and the culprit.', constraints:'Binary search for culprit. Shared state identification.', expectedOutput:'Test X fails when test Y runs in parallel. Shared: both write to the same database row. Fix: unique row per test.', check:'Binary search: `--shard` to split tests. Run X with subset. Narrow down. When found: identify shared state. Fix: isolate. Prove: 10x run with both tests in parallel → no failures.' },
    { id:36, level:4, title:'Parallel Test with Network Isolation', scenario:'Tests that mock the network must not interfere with each other\'s mocks.', objective:'Parallel tests, each mocking different API endpoints. Verify one test\'s mock doesn\'t affect another.', constraints:'Parallel mocks. Verify isolation.', expectedOutput:'Test 1 mocks /api/users. Test 2 (parallel) gets real /api/users. No cross-mock pollution.', check:'`page.route` is per-page (per-context). Parallel tests have different pages → isolated mocks. `context.route`: per-context (same). `page.route` vs `context.route`: the latter affects all pages in the context.' },
    { id:37, level:4, title:'Parallel Test Reporting in Real-Time', scenario:'Report test results in real-time as they come in from parallel workers.', objective:'Custom reporter: `onTestEnd` called as each test finishes (from any worker). Display: rolling log of pass/fail. Dashboard: live update.', constraints:'onTestEnd. Real-time display. Live dashboard.', expectedOutput:'Tests finishing: "PASS: login test (worker 2, 1.2s)". "FAIL: checkout test (worker 0, 3.1s)". Live.', check:'Reporter: `onTestEnd(test,result)` receives each test as it finishes (any worker). WebSocket: push to dashboard. Dashboard: list of tests with statuses. Last-writer: sort by finish time.' },
    { id:38, level:4, title:'Worker Affinity', scenario:'Some tests must run on the same worker (they share local state like temp files).', objective:'`test.describe.configure({mode:"serial"})`: ensures the same worker handles all tests in the group. Combine with a worker fixture for shared state.', constraints:'Serial mode. Worker fixture. Shared local state.', expectedOutput:'Group of 5 tests: all on the same worker. Worker fixture: initialized once, used by all 5.', check:'`mode:"serial"`: Playwright tries to run serial tests on the same worker. Worker fixture: created once per worker. Combination: serial group + worker fixture = shared worker state within the group.' },
    { id:39, level:4, title:'Parallel Test Suite CI Pipeline', scenario:'Design a CI pipeline that maximizes parallelism for Playwright tests.', objective:'Pipeline: 4 shards × 4 workers each = 16 concurrent tests. Setup: generate auth in parallel. Matrix: shards as a CI matrix. Merge: reports after all shards.', constraints:'4 shards. 4 workers. Auth parallelism. Report merge.', expectedOutput:'Total time: 16x faster than serial. Auth: generated in parallel (10 roles × 1s each = 1s total). Tests: 16 parallel.', check:'CI matrix: `strategy.matrix.shard:[1,2,3,4]`. Step: `npx playwright test --shard=${{ matrix.shard }}/4`. Auth: a separate job that generates all auth files and caches them. Report: merge job after matrix.' },
    { id:40, level:4, title:'Parallel Test Observability', scenario:'Monitor parallel test execution: worker utilization, queue depth, completion rates.', objective:'Custom reporter: track worker utilization (busy/idle ratio). Queue depth: tests waiting vs running. Completion rate: tests/minute.', constraints:'Worker utilization. Queue depth. Completion rate.', expectedOutput:'Dashboard: 4 workers: 3 busy, 1 idle. Queue depth: 12 tests waiting. Rate: 8 tests/minute.', check:'Track: `onTestBegin(test,result)` increments busy workers. `onTestEnd` decrements. Queue depth: started - finished. Rate: `finished / elapsed_seconds * 60`. Report every 5s.' },
    { id:41, level:5, title:'Parallel Test Architecture Design', scenario:'Design a parallel testing architecture for a 10,000-test suite.', objective:'(1) Sharding across 20 machines. (2) Priority queuing (critical first). (3) Dynamic worker scaling. (4) Cross-shard data sharing. (5) Real-time dashboard. (6) Failure isolation.', constraints:'All 6 components. Capacity planning.', expectedOutput:'10,000 tests × 5s avg / 20 machines × 8 workers = 312s total. Priority: critical 100 tests done in 60s.', check:'Architecture: 20 machines × 8 workers. Priority: critical project first on all machines. Shards: `--shard=N/20`. Data: S3 for cross-shard sharing. Dashboard: WebSocket. Failures: retry on different machine.' },
    { id:42, level:5, title:'Test Parallelism Optimizer', scenario:'Automatically determine the optimal parallelism configuration.', objective:'Run tests 10 times with different worker counts (1,2,4,8,16). Plot execution time vs workers. Find the elbow point (diminishing returns). Recommend optimal.', constraints:'10 runs. Different counts. Plot. Recommend.', expectedOutput:'Workers: 1→300s. 2→155s. 4→82s. 8→48s. 16→42s. Elbow at 8: diminishing returns. Recommend: 8 workers.', check:'Plot: execution time vs workers. Amdahl\'s law: parallel portion + serial portion. Serial portion limits speedup. Elbow: marginal gain < 10%. Recommend: elbow point.' },
    { id:43, level:5, title:'Parallel Test Data Factory at Scale', scenario:'Generate unique test data for thousands of parallel tests efficiently.', objective:'Data factory: pre-generates a pool of test data before the suite runs. Each test claims a data item from the pool. After test: data returned to pool (or discarded).', constraints:'Pre-generated pool. Claim/return. Thread-safe.', expectedOutput:'Pre-generate 1000 users. Each of 1000 parallel tests claims one user. No conflicts.', check:'Pool: in-memory array (for same-worker tests) or shared file (cross-worker). Claim: atomic pop from array. Return: push back. Thread-safe: SQLite with transactions, or worker-local pools.' },
    { id:44, level:5, title:'Zero-Downtime Parallel Test Deploy', scenario:'Tests run during a rolling deployment (some servers old version, some new).', objective:'While deployment is in progress: run tests against both old and new versions in parallel. Flag any regression on the new version.', constraints:'Two version targets. Parallel. Regression detection.', expectedOutput:'Old version: all pass. New version: 3 failures. Deployment: stopped. Regression report.', check:'Two projects: `{name:"old",use:{baseURL:OLD_URL}}` and `{name:"new",use:{baseURL:NEW_URL}}`. Run both in parallel. Compare results. Regression: test that passes on old, fails on new. Alert and block.' },
    { id:45, level:5, title:'Distributed Parallel Testing', scenario:'Tests run on machines in 3 different geographic regions simultaneously.', objective:'Region 1 (US): tests against US endpoint. Region 2 (EU): EU endpoint. Region 3 (APAC): APAC endpoint. All run in parallel. Reports merged.', constraints:'3 regions. Region-specific endpoints. Parallel. Merged report.', expectedOutput:'Total time: max(region1,region2,region3) — all parallel. Report: by region and globally.', check:'CI: GitHub Actions with `runs-on:[ubuntu-latest,eu-west-1-runner,ap-southeast-1-runner]`. Each region: different `BASE_URL`. Merged report: `npx playwright merge-reports`. Per-region analysis.' },
    { id:46, level:5, title:'Adaptive Parallel Testing', scenario:'Automatically adjust parallelism based on CI machine load and test performance history.', objective:'CI monitor: CPU usage. If < 50%: increase workers. If > 90%: decrease. History: p95 test duration. Adjust: slow tests get more workers.', constraints:'CPU monitoring. Dynamic adjustment. History-based.', expectedOutput:'CI starts at 4 workers. CPU: 30% → increase to 8. CPU: 95% → decrease to 6. Stabilizes at 6.', check:'Monitor: `os.loadavg()[0]` (1-minute average). Adjust: `sendSignal("increase-workers")` or `"decrease-workers"`. Playwright: not dynamic, but can restart with new config. Alternative: pre-calculate based on history.' },
    { id:47, level:5, title:'Parallel Test Failure Analysis', scenario:'A parallel run has 50 failures. Automatically categorize and prioritize them.', objective:'Categorize failures: (1) Auth issues. (2) Network timeouts. (3) Element not found. (4) Visual regressions. (5) API errors. Prioritize by category. Group related failures.', constraints:'5 categories. Prioritization. Grouping.', expectedOutput:'Auth failures: 5 (critical, fix auth setup). Timeouts: 20 (network issue, not code bugs). Visual: 3 (review needed). Element not found: 12 (locator changes). API: 10.', check:'Categorize: parse error message. Auth: contains "login" or "401". Timeout: "timeout". Element: "not found". Visual: "screenshot". Priority: auth > element > API > visual > timeout.' },
    { id:48, level:5, title:'Parallel Test Cost Optimization', scenario:'CI costs are high due to many workers. Optimize cost without sacrificing speed.', objective:'Analyze: which tests are slow? Can slow tests be parallelized within themselves? Which tests can use a cheaper instance type?', constraints:'Cost analysis. Slow test identification. Instance optimization.', expectedOutput:'Top 10 slow tests: moved to dedicated workers. Fast tests: bin-packed. Cheaper instances for visual tests. 40% cost reduction.', check:'Cost = instance_hours × price. Reduce: less workers for fast test suites. Right-size: small instance for small suites. Spot/preemptible: for non-critical tests. Cache: auth state to reduce setup time.' },
    { id:49, level:5, title:'Parallel Test Compliance', scenario:'Regulatory compliance requires test isolation and evidence that tests did not interfere.', objective:'Generate a compliance report: for each test, evidence that it ran in isolation (own context, own data, no shared state). Verify cross-test independence.', constraints:'Per-test isolation evidence. Report generation. Cross-test independence verification.', expectedOutput:'Report: Test X — context ID: abc, user: test-user-123, data prefix: test-x-. No shared state detected.', check:'Evidence: log context ID, test data identifiers, start/end times, worker index. Report: show no overlapping data access. Verification: compare test data identifiers — no overlap.' },
    { id:50, level:5, title:'Full Parallel Testing Infrastructure', scenario:'Build a complete parallel testing infrastructure for enterprise scale.', objective:'Build: (1) Dynamic sharding. (2) Priority queuing. (3) Test data factory. (4) Real-time dashboard. (5) Cost optimizer. (6) Failure analyzer. (7) Compliance reporter.', constraints:'All 7 components. Kubernetes deployment. CI/CD integration.', expectedOutput:'Deploy: k8s job for each shard. Auto-scale: HPA based on queue depth. Dashboard: Grafana. Cost: spot instances. Report: merged and published.', check:'k8s: Job spec with `parallelism` and `completions`. Each pod: one shard. Shard discovery: `SHARD_INDEX` and `SHARD_TOTAL` env vars. Reports: emitted to S3, merged in a final step, published to GitHub Pages.' },
  ],

};
